        private static MusketDrawStartViewMetrics MeasureMusketDrawStartView(
            Transform target,
            Transform playerRoot,
            Transform playerCamera,
            Bounds targetBounds,
            bool targetTransformUnchanged,
            MusketDrawStartViewMetrics applied)
        {
