                metrics.maximumAppliedUpperTorsoAwayPitchDegrees <=
                    BatonSwingRightMaximumUpperTorsoAwayPitchDegrees + 0.1f &&
                metrics.maximumElbowFlexDifferenceDegrees <= 1f &&
                metrics.rightHandLateralSpanDifferenceMeters <= 0.14f &&
