        [MenuItem("Bellerophon/Player/Build Shotgun Muzzle Flash V4 Preview")]
        internal static void BuildShotgunMuzzleFlashV4Preview()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 assets must be built in Edit Mode.");
            }

            Directory.CreateDirectory(Path.GetFullPath(
                ShotgunMuzzleFlashV4Directory));
            Directory.CreateDirectory(Path.GetFullPath(
                ShotgunMuzzleFlashV4SampleDirectory + "/renders"));
            AssetDatabase.Refresh();

            Mesh flameMesh = CreateOrUpdateShotgunMuzzleFlashV4Mesh(
                ShotgunMuzzleFlashV4FlameMeshPath,
                CreateShotgunMuzzleFlashV4FlameMesh());
            Texture2D coreTexture = CreateOrUpdateShotgunMuzzleFlashV4Texture(
                ShotgunMuzzleFlashV4CoreTexturePath,
                CreateShotgunMuzzleFlashV4CoreTexture());
            Texture2D flameTexture = CreateOrUpdateShotgunMuzzleFlashV4Texture(
                ShotgunMuzzleFlashV4FlameTexturePath,
                CreateShotgunMuzzleFlashV4FlameTexture());
            Texture2D smokeTexture = CreateOrUpdateShotgunMuzzleFlashV4Texture(
                ShotgunMuzzleFlashV4SmokeTexturePath,
                CreateShotgunMuzzleFlashV4SmokeTexture());

            Material coreMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleFlashV4CoreMaterialPath,
                true,
                coreTexture,
                new Color(3.4f, 1.60f, 0.30f, 0.90f),
                new Color(7.2f, 3.0f, 0.48f, 1f));
            Material volumeMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleFlashV4VolumeMaterialPath,
                true,
                null,
                new Color(1.8f, 0.48f, 0.05f, 0.08f),
                new Color(3.0f, 0.82f, 0.10f, 1f));
            if (volumeMaterial.HasProperty("_BaseMap"))
            {
                volumeMaterial.SetTexture("_BaseMap", null);
            }

            if (volumeMaterial.HasProperty("_MainTex"))
            {
                volumeMaterial.SetTexture("_MainTex", null);
            }

            EditorUtility.SetDirty(volumeMaterial);
            Material flameMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleFlashV4FlameMaterialPath,
                true,
                flameTexture,
                new Color(3.0f, 0.95f, 0.10f, 0.82f),
                new Color(6.2f, 2.05f, 0.24f, 1f));
            Material smokeMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleFlashV4SmokeMaterialPath,
                false,
                smokeTexture,
                new Color(0.94f, 0.86f, 0.77f, 1f));
            Material sparkMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleFlashV4SparkMaterialPath,
                true,
                coreTexture,
                new Color(3.8f, 1.22f, 0.12f, 0.94f),
                new Color(7.4f, 2.5f, 0.22f, 1f));

            GameObject root = new GameObject("Shotgun_MuzzleFlash_V4");
            GameObject savedPrefab;
            try
            {
                ParticleSystem ignition =
                    CreateShotgunMuzzleFlashV4IgnitionSystem(
                        root.transform,
                        coreMaterial);
                ParticleSystem volume =
                    CreateShotgunMuzzleFlashV4VolumeSystem(
                        root.transform,
                        flameMesh,
                        volumeMaterial);
                ParticleSystem pressure =
                    CreateShotgunMuzzleFlashV4PressureSystem(
                        root.transform,
                        flameMaterial);
                ParticleSystem smoke =
                    CreateShotgunMuzzleFlashV4SmokeSystem(
                        root.transform,
                        smokeMaterial);
                ParticleSystem fragments =
                    CreateShotgunMuzzleFlashV4FragmentSystem(
                        root.transform,
                        sparkMaterial);

                GameObject lightObject = new GameObject("MuzzleLight");
                lightObject.transform.SetParent(root.transform, false);
                lightObject.transform.localPosition = Vector3.right * 0.12f;
                Light muzzleLight = lightObject.AddComponent<Light>();
                muzzleLight.type = LightType.Point;
                muzzleLight.color = new Color(1f, 0.44f, 0.10f, 1f);
                muzzleLight.range = 2.35f;
                muzzleLight.intensity = 0f;
                muzzleLight.shadows = LightShadows.None;
                muzzleLight.renderMode = LightRenderMode.Auto;
                muzzleLight.enabled = false;

                Type runtimeType = RequireMusketMuzzleFlashRuntimeType(
                    ShotgunMuzzleFlashV4RuntimeTypeName);
                MonoBehaviour controller = root.AddComponent(runtimeType)
                    as MonoBehaviour ?? throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 controller could not be added.");
                ParticleSystem[] layers =
                {
                    ignition,
                    volume,
                    pressure,
                    smoke,
                    fragments
                };
                InvokeMusketMuzzleFlashMethod(
                    controller,
                    "Configure",
                    (object)layers,
                    smoke,
                    muzzleLight,
                    ShotgunMuzzleFlashV4LightDurationSeconds,
                    ShotgunMuzzleFlashV4LightPeakIntensity);
                savedPrefab = PrefabUtility.SaveAsPrefabAsset(
                    root,
                    ShotgunMuzzleFlashV4PrefabPath);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(root);
            }

            if (savedPrefab == null)
            {
                throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 prefab could not be saved.");
            }

            AssetDatabase.SaveAssets();
            Renderer[] renderers = savedPrefab
                .GetComponentsInChildren<Renderer>(true);
            ParticleSystem[] systems = savedPrefab
                .GetComponentsInChildren<ParticleSystem>(true);
            int maximumParticles = systems.Sum(system =>
                system.main.maxParticles);
            int billboardCapacity = systems
                .Where(system => system.GetComponent<ParticleSystemRenderer>()
                    .renderMode != ParticleSystemRenderMode.Mesh)
                .Sum(system => system.main.maxParticles);
            int meshCapacity = systems
                .Where(system => system.GetComponent<ParticleSystemRenderer>()
                    .renderMode == ParticleSystemRenderMode.Mesh)
                .Sum(system => system.main.maxParticles);
            long textureBytes =
                UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(
                    coreTexture) +
                UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(
                    flameTexture) +
                UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(
                    smokeTexture);
            ShotgunMuzzleFlashV4PreviewMetrics metrics =
                new ShotgunMuzzleFlashV4PreviewMetrics
                {
                    target = ShotgunFireTargetName,
                    prefabPath = ShotgunMuzzleFlashV4PrefabPath,
                    runtimeType = ShotgunMuzzleFlashV4RuntimeTypeName,
                    visualRepresentation =
                        "Unity-native 3D flame mesh plus layered particle volume",
                    layers = systems.Select(system => system.name).ToArray(),
                    textureAssets = new[]
                    {
                        ShotgunMuzzleFlashV4CoreTexturePath,
                        ShotgunMuzzleFlashV4FlameTexturePath,
                        ShotgunMuzzleFlashV4SmokeTexturePath
                    },
                    materialAssets = new[]
                    {
                        ShotgunMuzzleFlashV4CoreMaterialPath,
                        ShotgunMuzzleFlashV4VolumeMaterialPath,
                        ShotgunMuzzleFlashV4FlameMaterialPath,
                        ShotgunMuzzleFlashV4SmokeMaterialPath,
                        ShotgunMuzzleFlashV4SparkMaterialPath
                    },
                    particleSystemCount = systems.Length,
                    maximumConfiguredParticles = maximumParticles,
                    ignitionBurstCount = systems.Single(system =>
                        string.Equals(
                            system.name,
                            "IgnitionCore",
                            StringComparison.Ordinal)).main.maxParticles,
                    volumeBurstCount = systems.Single(system =>
                        string.Equals(
                            system.name,
                            "FlameVolume3D",
                            StringComparison.Ordinal)).main.maxParticles,
                    pressureBurstCount = systems
                        .Where(system => system.name.StartsWith(
                            "PressureFlame",
                            StringComparison.Ordinal))
                        .Sum(system => system.main.maxParticles),
                    smokeBurstCount = systems.Single(system =>
                        string.Equals(
                            system.name,
                            "PowderSmokeVolume",
                            StringComparison.Ordinal)).main.maxParticles,
                    fragmentBurstCount = systems.Single(system =>
                        string.Equals(
                            system.name,
                            "HotPowderFragments",
                            StringComparison.Ordinal)).main.maxParticles,
                    pressureConeAngleDegrees =
                        ShotgunMuzzleFlashV4PressureConeAngleDegrees,
                    pressureApexRadiusMeters =
                        ShotgunMuzzleFlashV4PressureApexRadiusMeters,
                    pressureApexLengthMeters =
                        ShotgunMuzzleFlashV4PressureApexLengthMeters,
                    pressureRandomLateralSpeedMetersPerSecond =
                        ShotgunMuzzleFlashV4PressureLateralJitterSpeed,
                    closeCameraOrthographicSize =
                        ShotgunMuzzleFlashV4CloseOrthographicSize,
                    continuousPressureCone = systems.Count(system =>
                        string.Equals(
                            system.name,
                            "PressureFlameCone",
                            StringComparison.Ordinal)) == 1,
                    allExpandingLayersUseForwardCones = systems.All(system =>
                        system.shape.enabled && system.shape.angle < 90f),
                    stretchedParticlesTailAnchored = renderers
                        .Where(renderer => renderer is ParticleSystemRenderer)
                        .Cast<ParticleSystemRenderer>()
                        .Where(renderer => renderer.renderMode ==
                            ParticleSystemRenderMode.Stretch)
                        .All(renderer => Mathf.Approximately(
                            renderer.pivot.y,
                            0.5f)),
                    stretchLengthCompensated = renderers
                        .Where(renderer => renderer is ParticleSystemRenderer)
                        .Cast<ParticleSystemRenderer>()
                        .Where(renderer => renderer.renderMode ==
                            ParticleSystemRenderMode.Stretch)
                        .All(renderer =>
                            renderer.velocityScale <= 0.080001f &&
                            renderer.lengthScale <= 0.525001f),
                    maximumPressureDirectionDegrees =
                        ShotgunMuzzleFlashV4PressureConeAngleDegrees,
                    maximumFragmentDirectionDegrees = 56f,
                    flameMeshMinimumForwardMeters = flameMesh.bounds.min.z,
                    volumeLateralSpeedMetersPerSecond =
                        ShotgunMuzzleFlashV4VolumeLateralSpeed,
                    fragmentLateralSpeedMetersPerSecond =
                        ShotgunMuzzleFlashV4FragmentLateralSpeed,
                    forwardSpeedLifetimeAndMeshLengthUnchanged = true,
                    enhancedLateralFanSpread = true,
                    rendererCount = renderers.Length,
                    materialCount = renderers
                        .Select(renderer => renderer.sharedMaterial)
                        .Where(material => material != null)
                        .Distinct()
                        .Count(),
                    lightCount = savedPrefab
                        .GetComponentsInChildren<Light>(true).Length,
                    flameMeshVertices = flameMesh.vertexCount,
                    flameMeshTriangles = flameMesh.triangles.Length / 3,
                    estimatedTextureRuntimeBytes = textureBytes,
                    estimatedPeakBillboardVertices = billboardCapacity * 4,
                    estimatedPeakFlameMeshVertices =
                        meshCapacity * flameMesh.vertexCount,
                    usesThreeDimensionalFlameMesh = true,
                    usesLayeredParticleVolume = true,
                    usesSingleDominantCard = false,
                    createsObjectsPerShot = false,
                    shadowsDisabled = renderers.All(renderer =>
                        renderer.shadowCastingMode == ShadowCastingMode.Off &&
                        !renderer.receiveShadows),
                    motionVectorsDisabled = renderers.All(renderer =>
                        renderer.motionVectorGenerationMode ==
                        MotionVectorGenerationMode.ForceNoMotion),
                    compatibleCycleSeconds = ShotgunFireCycleSeconds,
                    compatibleTriggerSeconds =
                        ShotgunMuzzleFlashTriggerAbsoluteSeconds,
                    compatibleNormalizedTriggerTime =
                        ShotgunMuzzleFlashTriggerNormalizedTime,
                    previewPath = ShotgunMuzzleFlashV4PreviewPath,
                    previewAgesSeconds = Array.Empty<float>(),
                    previewViews = Array.Empty<string>(),
                    actualUnityPrefabRendered = false,
                    exactPrefabUsedForPreview = false,
                    existingShotgunFireEffectReplaced = false,
                    sceneModified = false,
                    validationPriority =
                        "1_direct_Unity_visual_review_2_numeric_support"
                };
            metrics.passedNumericChecks =
                metrics.particleSystemCount ==
                    ShotgunMuzzleFlashV4SystemCount &&
                metrics.maximumConfiguredParticles ==
                    ShotgunMuzzleFlashV4MaximumParticleCapacity &&
                metrics.ignitionBurstCount == 10 &&
                metrics.volumeBurstCount == 10 &&
                metrics.pressureBurstCount == 52 &&
                Mathf.Approximately(
                    metrics.pressureConeAngleDegrees,
                    ShotgunMuzzleFlashV4PressureConeAngleDegrees) &&
                metrics.pressureApexRadiusMeters <= 0.004001f &&
                metrics.pressureApexLengthMeters <= 0.006001f &&
                metrics.continuousPressureCone &&
                metrics.allExpandingLayersUseForwardCones &&
                metrics.stretchedParticlesTailAnchored &&
                metrics.stretchLengthCompensated &&
                metrics.maximumPressureDirectionDegrees < 90f &&
                metrics.maximumFragmentDirectionDegrees < 90f &&
                metrics.flameMeshMinimumForwardMeters >= -0.000001f &&
                metrics.smokeBurstCount == 26 &&
                metrics.fragmentBurstCount == 20 &&
                metrics.forwardSpeedLifetimeAndMeshLengthUnchanged &&
                metrics.enhancedLateralFanSpread &&
                metrics.rendererCount == ShotgunMuzzleFlashV4SystemCount &&
                metrics.materialCount == 5 &&
                metrics.lightCount == 1 &&
                metrics.usesThreeDimensionalFlameMesh &&
                metrics.usesLayeredParticleVolume &&
                !metrics.usesSingleDominantCard &&
                !metrics.createsObjectsPerShot &&
                metrics.shadowsDisabled &&
                metrics.motionVectorsDisabled;
            WriteJson(ShotgunMuzzleFlashV4MetricsPath, metrics);
            Debug.Log(
                "[ShotgunMuzzleFlashV4] Built exact preview/runtime prefab. " +
                "Systems=" + metrics.particleSystemCount +
                ", Capacity=" + metrics.maximumConfiguredParticles +
                ", 3DFlameVertices=" + metrics.flameMeshVertices +
                ", SceneChanged=False.");
        }

        [MenuItem("Bellerophon/Player/Capture Shotgun Muzzle Flash V4 Preview")]
        internal static void CaptureShotgunMuzzleFlashV4Preview()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 preview must be captured in Edit Mode.");
            }

            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp must be clean before the temporary V4 preview.");
            }

            ShotgunMuzzleFlashV4PreviewMetrics metrics =
                ReadJson<ShotgunMuzzleFlashV4PreviewMetrics>(
                    ShotgunMuzzleFlashV4MetricsPath);
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 support checks did not pass.");
            }

            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunMuzzleFlashV4PrefabPath) ??
                throw new FileNotFoundException(
                    "Shotgun muzzle flash V4 prefab is missing.",
                    Path.GetFullPath(ShotgunMuzzleFlashV4PrefabPath));
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunFireTargetName);
            Transform rightHand = FindRequired(target, RightHandPath);
            Transform item = rightHand.Find(ShotgunHandInstanceName) ??
                throw new InvalidOperationException(
                    ShotgunFireTargetName +
                    " has no right-hand Shotgun instance.");
            Transform existingEffect = item.Find(ShotgunMuzzleFlashRootName) ??
                throw new InvalidOperationException(
                    "The current Shotgun_Fire muzzle anchor could not be found.");
            Animator animator = RequireAnimator(target);
            ShotgunAnimationSpec fireSpec = GetShotgunAnimationSpecs()
                .Single(value => string.Equals(
                    value.TargetName,
                    ShotgunFireTargetName,
                    StringComparison.Ordinal));
            SampleAnimator(
                animator,
                fireSpec.StateName,
                ShotgunMuzzleFlashTriggerNormalizedTime);
            GameObject preview = null;
            float[] ages = { 0.018f, 0.045f, 0.085f, 0.145f, 0.32f, 0.62f };
            List<List<byte[]>> rows = new List<List<byte[]>>
            {
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>()
            };
            try
            {
                preview = PrefabUtility.InstantiatePrefab(
                    prefab) as GameObject ?? throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 preview instance could not be created.");
                preview.name = "Shotgun_MuzzleFlash_V4_Preview";
                preview.transform.SetPositionAndRotation(
                    existingEffect.position,
                    existingEffect.rotation);
                preview.transform.localScale = existingEffect.lossyScale;
                SetShotgunMuzzleFlashV4PreviewHideFlags(preview.transform);

                Type runtimeType = RequireMusketMuzzleFlashRuntimeType(
                    ShotgunMuzzleFlashV4RuntimeTypeName);
                MonoBehaviour controller = preview.GetComponent(runtimeType)
                    as MonoBehaviour ?? throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 preview controller is missing.");
                ParticleSystem[] systems = preview
                    .GetComponentsInChildren<ParticleSystem>(true);
                Light muzzleLight = preview
                    .GetComponentInChildren<Light>(true);

                using (CaptureEnvironment environment =
                       new CaptureEnvironment(
                           target,
                           preview.transform,
                           existingEffect))
                {
                    foreach (float age in ages)
                    {
                        InvokeMusketMuzzleFlashMethod(
                            controller,
                            "PlayEffect");
                        foreach (ParticleSystem system in systems)
                        {
                            system.Simulate(age, true, true, false);
                        }

                        if (muzzleLight != null)
                        {
                            float lightWeight = Mathf.Clamp01(
                                1f - age /
                                ShotgunMuzzleFlashV4LightDurationSeconds);
                            muzzleLight.intensity =
                                ShotgunMuzzleFlashV4LightPeakIntensity *
                                lightWeight * lightWeight;
                            muzzleLight.enabled = lightWeight > 0f;
                        }

                        Vector3 muzzleCenter = preview.transform.position +
                            preview.transform.right * 0.38f;
                        environment.ConfigureView(
                            target,
                            muzzleCenter,
                            ShotgunMuzzleFlashV4CloseOrthographicSize);
                        rows[0].Add(environment.CaptureFront());
                        rows[1].Add(environment.CaptureSide());
                        rows[2].Add(environment.CaptureOblique(
                            target,
                            muzzleCenter,
                            target.forward + target.right * 0.65f +
                                target.up * 0.16f,
                            ShotgunMuzzleFlashV4CloseOrthographicSize));
                        environment.ConfigureView(
                            target,
                            target.position + target.up * 0.95f,
                            1.28f);
                        rows[3].Add(environment.CaptureFront());
                    }
                }

                ComposeRows(rows, ShotgunMuzzleFlashV4PreviewPath);
                metrics.previewAgesSeconds = ages;
                metrics.previewViews = new[]
                {
                    "front_close",
                    "side_close",
                    "oblique_close",
                    "shotgun_fire_full_context"
                };
                metrics.actualUnityPrefabRendered = true;
                metrics.exactPrefabUsedForPreview = true;
                metrics.existingShotgunFireEffectReplaced = false;
                metrics.sceneModified = false;
                metrics.previewPath = ShotgunMuzzleFlashV4PreviewPath;
                metrics.passedNumericChecks =
                    metrics.passedNumericChecks &&
                    rows.All(row => row.Count == ages.Length) &&
                    File.Exists(Path.GetFullPath(
                        ShotgunMuzzleFlashV4PreviewPath));
                WriteJson(ShotgunMuzzleFlashV4MetricsPath, metrics);
            }
            finally
            {
                if (preview != null)
                {
                    UnityEngine.Object.DestroyImmediate(preview);
                }

                animator.Rebind();
                animator.Update(0f);
            }

            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "The temporary Shotgun V4 preview unexpectedly dirtied CargoRunMvp.");
            }

            Debug.Log(
                "[ShotgunMuzzleFlashV4] Captured the exact final prefab once " +
                "at the current Shotgun_Fire muzzle anchor without saving or " +
                "replacing the scene effect. Path=" +
                Path.GetFullPath(ShotgunMuzzleFlashV4PreviewPath) + ".");
        }

        [MenuItem("Bellerophon/Player/Apply Shotgun Muzzle Flash V4 To Shotgun Fire")]
        internal static void ApplyShotgunMuzzleFlashV4ToShotgunFire()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 must be applied in Edit Mode.");
            }

            ShotgunMuzzleFlashV4PreviewMetrics metrics =
                ReadJson<ShotgunMuzzleFlashV4PreviewMetrics>(
                    ShotgunMuzzleFlashV4MetricsPath);
            if (!metrics.passedNumericChecks ||
                !metrics.actualUnityPrefabRendered ||
                !metrics.exactPrefabUsedForPreview)
            {
                throw new InvalidOperationException(
                    "The approved Shotgun muzzle flash V4 prefab did not pass its preview checks.");
            }

            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunMuzzleFlashV4PrefabPath) ??
                throw new FileNotFoundException(
                    "Shotgun muzzle flash V4 prefab is missing.",
                    Path.GetFullPath(ShotgunMuzzleFlashV4PrefabPath));
            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunFireTargetName);
            Transform rightHand = FindRequired(target, RightHandPath);
            Transform item = rightHand.Find(ShotgunHandInstanceName) ??
                throw new InvalidOperationException(
                    ShotgunFireTargetName +
                    " has no right-hand Shotgun instance.");
            Transform existingEffect = item.Find(ShotgunMuzzleFlashRootName) ??
                throw new InvalidOperationException(
                    "The current Shotgun_Fire muzzle anchor could not be found.");
            Vector3 anchorLocalPosition = existingEffect.localPosition;
            Quaternion anchorLocalRotation = existingEffect.localRotation;
            Vector3 anchorLocalScale = existingEffect.localScale;

            ShotgunAnimationSpec fireSpec = GetShotgunAnimationSpecs()
                .Single(value => string.Equals(
                    value.TargetName,
                    ShotgunFireTargetName,
                    StringComparison.Ordinal));
            AnimationClip derived = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ShotgunFireThreeSecondClipPath) ??
                throw new FileNotFoundException(
                    "Shotgun_Fire three-second clip is missing.",
                    Path.GetFullPath(ShotgunFireThreeSecondClipPath));
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    fireSpec.ControllerPath) ??
                throw new FileNotFoundException(
                    fireSpec.ControllerPath,
                    Path.GetFullPath(fireSpec.ControllerPath));
            AnimatorState state = RequireControllerState(
                controller,
                fireSpec.StateName);
            if (state.motion != derived ||
                Mathf.Abs(state.speed - 1f) > 0.0001f ||
                Mathf.Abs(derived.length - ShotgunFireCycleSeconds) > 0.0001f)
            {
                throw new InvalidOperationException(
                    "Shotgun_Fire three-second animation connection changed before V4 apply.");
            }

            ConfigureShotgunMuzzleFlashV4StateBehaviour(state);
            UnityEngine.Object.DestroyImmediate(existingEffect.gameObject);
            GameObject effectObject = PrefabUtility.InstantiatePrefab(
                prefab,
                item) as GameObject ?? throw new InvalidOperationException(
                "Shotgun muzzle flash V4 prefab could not be instantiated.");
            effectObject.name = ShotgunMuzzleFlashRootName;
            effectObject.transform.localPosition = anchorLocalPosition;
            effectObject.transform.localRotation = anchorLocalRotation;
            effectObject.transform.localScale = anchorLocalScale;

            Type runtimeType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashV4RuntimeTypeName);
            MonoBehaviour effect = effectObject.GetComponent(runtimeType)
                as MonoBehaviour ?? throw new InvalidOperationException(
                "Shotgun muzzle flash V4 runtime component is missing.");
            Animator animator = RequireAnimator(target);
            animator.runtimeAnimatorController = controller;
            animator.speed = 1f;
            animator.applyRootMotion = false;
            EditorUtility.SetDirty(effect);
            EditorUtility.SetDirty(effectObject);
            EditorUtility.SetDirty(animator);
            EditorUtility.SetDirty(state);
            EditorUtility.SetDirty(controller);
            EditorSceneManager.MarkSceneDirty(scene);
            AssetDatabase.SaveAssets();
            if (!EditorSceneManager.SaveScene(scene))
            {
                throw new InvalidOperationException(
                    "CargoRunMvp could not be saved after Shotgun muzzle flash V4 apply.");
            }

            Type behaviourType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashV4BehaviourTypeName);
            Type previousBehaviourType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashBehaviourTypeName);
            StateMachineBehaviour[] behaviours = state.behaviours;
            StateMachineBehaviour[] v4Behaviours = behaviours
                .Where(value =>
                    value != null && behaviourType.IsInstanceOfType(value))
                .ToArray();
            int previousBehaviourCount = behaviours.Count(value =>
                value != null && previousBehaviourType.IsInstanceOfType(value));
            float triggerTime = v4Behaviours.Length == 1
                ? ReadMusketMuzzleFlashProperty<float>(
                    v4Behaviours[0],
                    "NormalizedTriggerTime")
                : -1f;
            ParticleSystem[] systems = effectObject
                .GetComponentsInChildren<ParticleSystem>(true);
            Renderer[] renderers = effectObject
                .GetComponentsInChildren<Renderer>(true);
            int maximumParticles = systems.Sum(system =>
                system.main.maxParticles);
            bool passed =
                v4Behaviours.Length == 1 &&
                previousBehaviourCount == 0 &&
                Mathf.Abs(triggerTime -
                    ShotgunMuzzleFlashTriggerNormalizedTime) <= 0.0001f &&
                systems.Length == ShotgunMuzzleFlashV4SystemCount &&
                renderers.Length == ShotgunMuzzleFlashV4SystemCount &&
                maximumParticles ==
                    ShotgunMuzzleFlashV4MaximumParticleCapacity &&
                effectObject.GetComponentsInChildren<Light>(true).Length == 1 &&
                Vector3.Distance(
                    effectObject.transform.localPosition,
                    anchorLocalPosition) <= PositionTolerance &&
                Quaternion.Angle(
                    effectObject.transform.localRotation,
                    anchorLocalRotation) <= RotationTolerance;
            if (!passed)
            {
                throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 apply support checks failed. " +
                    "V4Behaviours=" + v4Behaviours.Length +
                    ", PreviousBehaviours=" + previousBehaviourCount +
                    ", Trigger=" + Num(triggerTime) +
                    ", Systems=" + systems.Length +
                    ", Renderers=" + renderers.Length +
                    ", Capacity=" + maximumParticles + ".");
            }

            Debug.Log(
                "[ShotgunMuzzleFlashV4] Approved exact prefab replaced the " +
                "previous Shotgun_Fire effect at the unchanged muzzle anchor. " +
                "TriggerSeconds=" + Num(ShotgunMuzzleFlashTriggerAbsoluteSeconds) +
                ", TriggerNormalized=" + Num(triggerTime) +
                ", Systems=" + systems.Length +
                ", Capacity=" + maximumParticles +
                ", SceneChanged=True.");
        }

        [MenuItem("Bellerophon/Player/Capture Shotgun Muzzle Flash V4 Applied Review")]
        internal static void CaptureShotgunMuzzleFlashV4AppliedReview()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun muzzle flash V4 applied review must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp must be clean before the V4 applied review.");
            }

            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunFireTargetName);
            Transform rightHand = FindRequired(target, RightHandPath);
            Transform item = rightHand.Find(ShotgunHandInstanceName) ??
                throw new InvalidOperationException(
                    ShotgunFireTargetName +
                    " has no right-hand Shotgun instance.");
            Transform effectRoot = item.Find(ShotgunMuzzleFlashRootName) ??
                throw new InvalidOperationException(
                    "The applied Shotgun muzzle flash could not be found.");
            Type runtimeType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashV4RuntimeTypeName);
            MonoBehaviour effect = effectRoot.GetComponent(runtimeType)
                as MonoBehaviour ?? throw new InvalidOperationException(
                "The applied Shotgun muzzle flash is not the approved V4 prefab.");
            Animator animator = RequireAnimator(target);
            ShotgunAnimationSpec fireSpec = GetShotgunAnimationSpecs()
                .Single(value => string.Equals(
                    value.TargetName,
                    ShotgunFireTargetName,
                    StringComparison.Ordinal));
            AnimatorController controller = animator.runtimeAnimatorController
                as AnimatorController ?? throw new InvalidOperationException(
                "Shotgun_Fire does not use its editable AnimatorController.");
            AnimatorState state = RequireControllerState(
                controller,
                fireSpec.StateName);
            Type behaviourType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashV4BehaviourTypeName);
            StateMachineBehaviour[] v4Behaviours = state.behaviours
                .Where(value =>
                    value != null && behaviourType.IsInstanceOfType(value))
                .ToArray();
            if (v4Behaviours.Length != 1 ||
                Mathf.Abs(ReadMusketMuzzleFlashProperty<float>(
                    v4Behaviours[0],
                    "NormalizedTriggerTime") -
                    ShotgunMuzzleFlashTriggerNormalizedTime) > 0.0001f)
            {
                throw new InvalidOperationException(
                    "Shotgun_Fire does not have the approved V4 0.15-second trigger.");
            }

            SampleAnimator(
                animator,
                fireSpec.StateName,
                ShotgunMuzzleFlashTriggerNormalizedTime);
            ParticleSystem[] systems = effectRoot
                .GetComponentsInChildren<ParticleSystem>(true);
            if (systems.Length != ShotgunMuzzleFlashV4SystemCount ||
                systems.Sum(system => system.main.maxParticles) !=
                    ShotgunMuzzleFlashV4MaximumParticleCapacity)
            {
                throw new InvalidOperationException(
                    "The applied V4 particle configuration no longer matches the approved prefab.");
            }

            Light muzzleLight = effectRoot.GetComponentInChildren<Light>(true);
            float[] ages = { 0.018f, 0.045f, 0.085f, 0.145f, 0.32f, 0.62f };
            List<List<byte[]>> rows = new List<List<byte[]>>
            {
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>()
            };
            try
            {
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    foreach (float age in ages)
                    {
                        InvokeMusketMuzzleFlashMethod(effect, "PlayEffect");
                        foreach (ParticleSystem system in systems)
                        {
                            system.Simulate(age, true, true, false);
                        }

                        if (muzzleLight != null)
                        {
                            float lightWeight = Mathf.Clamp01(
                                1f - age /
                                ShotgunMuzzleFlashV4LightDurationSeconds);
                            muzzleLight.intensity =
                                ShotgunMuzzleFlashV4LightPeakIntensity *
                                lightWeight * lightWeight;
                            muzzleLight.enabled = lightWeight > 0f;
                        }

                        Vector3 muzzleCenter = effectRoot.position +
                            effectRoot.right * 0.38f;
                        environment.ConfigureView(
                            target,
                            muzzleCenter,
                            ShotgunMuzzleFlashV4CloseOrthographicSize);
                        rows[0].Add(environment.CaptureFront());
                        rows[1].Add(environment.CaptureSide());
                        rows[2].Add(environment.CaptureOblique(
                            target,
                            muzzleCenter,
                            target.forward + target.right * 0.65f +
                                target.up * 0.16f,
                            ShotgunMuzzleFlashV4CloseOrthographicSize));
                        environment.ConfigureView(
                            target,
                            target.position + target.up * 0.95f,
                            1.28f);
                        rows[3].Add(environment.CaptureFront());
                    }
                }

                ComposeRowsBesideReference(
                    rows,
                    ShotgunMuzzleFlashV4PreviewPath,
                    ShotgunMuzzleFlashV4AppliedReviewPath);
                AssetDatabase.ImportAsset(
                    ShotgunMuzzleFlashV4AppliedReviewPath,
                    ImportAssetOptions.ForceSynchronousImport);
            }
            finally
            {
                foreach (ParticleSystem system in systems)
                {
                    system.Stop(
                        true,
                        ParticleSystemStopBehavior.StopEmittingAndClear);
                }

                if (muzzleLight != null)
                {
                    muzzleLight.intensity = 0f;
                    muzzleLight.enabled = false;
                }

                animator.Rebind();
                animator.Update(0f);
            }

            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "The V4 applied review unexpectedly dirtied CargoRunMvp.");
            }

            if (!File.Exists(Path.GetFullPath(
                    ShotgunMuzzleFlashV4AppliedReviewPath)))
            {
                throw new InvalidOperationException(
                    "The V4 applied comparison image was not created.");
            }

            Debug.Log(
                "[ShotgunMuzzleFlashV4] One final side-by-side review was " +
                "captured from the applied Shotgun_Fire object. Left=approved " +
                "reference, Right=applied scene object, Path=" +
                Path.GetFullPath(ShotgunMuzzleFlashV4AppliedReviewPath) + ".");
        }

        private static void ConfigureShotgunMuzzleFlashV4StateBehaviour(
            AnimatorState state)
        {
            Type previousType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashBehaviourTypeName);
            foreach (StateMachineBehaviour previous in state.behaviours
                         .Where(value =>
                             value != null && previousType.IsInstanceOfType(value))
                         .ToArray())
            {
                UnityEngine.Object.DestroyImmediate(previous, true);
            }

            Type behaviourType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashV4BehaviourTypeName);
            StateMachineBehaviour[] behaviours = state.behaviours
                .Where(value =>
                    value != null && behaviourType.IsInstanceOfType(value))
                .ToArray();
            StateMachineBehaviour behaviour = behaviours.FirstOrDefault();
            if (behaviour == null)
            {
                behaviour = state.AddStateMachineBehaviour(behaviourType);
            }

            foreach (StateMachineBehaviour duplicate in behaviours.Skip(1))
            {
                UnityEngine.Object.DestroyImmediate(duplicate, true);
            }

            InvokeMusketMuzzleFlashMethod(
                behaviour,
                "Configure",
                ShotgunMuzzleFlashTriggerNormalizedTime);
            EditorUtility.SetDirty(behaviour);
        }

        private static void SetShotgunMuzzleFlashV4PreviewHideFlags(
            Transform root)
        {
            foreach (Transform transform in root
                         .GetComponentsInChildren<Transform>(true))
            {
                transform.gameObject.hideFlags = HideFlags.HideAndDontSave;
            }
        }

        private static Mesh CreateOrUpdateShotgunMuzzleFlashV4Mesh(
            string path,
            Mesh generated)
        {
            Mesh existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, path);
                return generated;
            }

            EditorUtility.CopySerialized(generated, existing);
            UnityEngine.Object.DestroyImmediate(generated);
            EditorUtility.SetDirty(existing);
            return existing;
        }

        private static Mesh CreateShotgunMuzzleFlashV4FlameMesh()
        {
            const int sides = 24;
            float[] ringZ = { 0.012f, 0.085f, 0.18f, 0.32f, 0.46f };
            float[] ringRadius = { 0.012f, 0.065f, 0.14f, 0.23f, 0.12f };
            List<Vector3> vertices = new List<Vector3>
            {
                Vector3.zero
            };
            List<Vector2> uvs = new List<Vector2>
            {
                new Vector2(0.5f, 0f)
            };
            for (int ring = 0; ring < ringZ.Length; ring++)
            {
                for (int side = 0; side < sides; side++)
                {
                    float angle = side * Mathf.PI * 2f / sides;
                    float irregular = 1f +
                        0.16f * Mathf.Sin(side * 2.7f + ring * 1.9f) +
                        0.08f * Mathf.Cos(side * 4.1f - ring * 0.8f);
                    vertices.Add(new Vector3(
                        Mathf.Cos(angle) * ringRadius[ring] * irregular,
                        Mathf.Sin(angle) * ringRadius[ring] * irregular,
                        ringZ[ring]));
                    uvs.Add(new Vector2(
                        side / (float)sides,
                        (ring + 1f) / (ringZ.Length + 1f)));
                }
            }

            int tipIndex = vertices.Count;
            vertices.Add(new Vector3(0.014f, -0.010f, 0.60f));
            uvs.Add(new Vector2(0.5f, 1f));
            List<int> triangles = new List<int>();
            for (int side = 0; side < sides; side++)
            {
                int next = (side + 1) % sides;
                triangles.Add(0);
                triangles.Add(1 + next);
                triangles.Add(1 + side);
                for (int ring = 0; ring < ringZ.Length - 1; ring++)
                {
                    int current = 1 + ring * sides + side;
                    int currentNext = 1 + ring * sides + next;
                    int following = current + sides;
                    int followingNext = currentNext + sides;
                    triangles.Add(current);
                    triangles.Add(currentNext);
                    triangles.Add(followingNext);
                    triangles.Add(current);
                    triangles.Add(followingNext);
                    triangles.Add(following);
                }

                int last = 1 + (ringZ.Length - 1) * sides + side;
                int lastNext = 1 + (ringZ.Length - 1) * sides + next;
                triangles.Add(last);
                triangles.Add(lastNext);
                triangles.Add(tipIndex);
            }

            Mesh mesh = new Mesh
            {
                name = "ShotgunMuzzleFlameVolume"
            };
            mesh.SetVertices(vertices);
            mesh.SetUVs(0, uvs);
            mesh.SetTriangles(triangles, 0);
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Texture2D CreateOrUpdateShotgunMuzzleFlashV4Texture(
            string path,
            Texture2D generated)
        {
            Texture2D existing = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, path);
                return generated;
            }

            EditorUtility.CopySerialized(generated, existing);
            UnityEngine.Object.DestroyImmediate(generated);
            EditorUtility.SetDirty(existing);
            return existing;
        }

        private static Texture2D CreateShotgunMuzzleFlashV4CoreTexture()
        {
            const int tileSize = 64;
            const int textureSize = tileSize * 2;
            Texture2D texture = CreateShotgunMuzzleFlashV4Texture(
                textureSize,
                "ShotgunMuzzleCoreAtlas");
            Color[] pixels = new Color[textureSize * textureSize];
            for (int tileY = 0; tileY < 2; tileY++)
            {
                for (int tileX = 0; tileX < 2; tileX++)
                {
                    int variant = tileY * 2 + tileX;
                    for (int y = 0; y < tileSize; y++)
                    {
                        for (int x = 0; x < tileSize; x++)
                        {
                            float px = ((x + 0.5f) / tileSize) * 2f - 1f;
                            float py = ((y + 0.5f) / tileSize) * 2f - 1f;
                            float radius = Mathf.Sqrt(px * px + py * py);
                            float envelope = Mathf.Exp(
                                -radius * radius *
                                (2.6f + variant * 0.12f));
                            envelope *= 1f - Mathf.SmoothStep(
                                0.72f,
                                1.08f,
                                radius);
                            float core = 1f - Mathf.SmoothStep(
                                0.02f,
                                0.42f,
                                radius);
                            float alpha = Mathf.Clamp01(
                                envelope * (0.78f + core * 0.22f));
                            int pixelX = tileX * tileSize + x;
                            int pixelY = tileY * tileSize + y;
                            pixels[pixelY * textureSize + pixelX] =
                                new Color(1f, 0.94f + core * 0.06f,
                                    0.72f + core * 0.28f, alpha);
                        }
                    }
                }
            }

            texture.SetPixels(pixels);
            texture.Apply(false, false);
            return texture;
        }

        private static Texture2D CreateShotgunMuzzleFlashV4FlameTexture()
        {
            const int tileSize = 96;
            const int textureSize = tileSize * 2;
            Texture2D texture = CreateShotgunMuzzleFlashV4Texture(
                textureSize,
                "ShotgunMuzzleFlameAtlas");
            Color[] pixels = new Color[textureSize * textureSize];
            for (int tileY = 0; tileY < 2; tileY++)
            {
                for (int tileX = 0; tileX < 2; tileX++)
                {
                    int variant = tileY * 2 + tileX;
                    float tilt = (variant - 1.5f) * 0.10f;
                    for (int y = 0; y < tileSize; y++)
                    {
                        for (int x = 0; x < tileSize; x++)
                        {
                            float px = ((x + 0.5f) / tileSize) * 2f - 1f;
                            float py = ((y + 0.5f) / tileSize) * 2f - 1f;
                            float shiftedX = px - py * tilt;
                            float centeredY = py + 0.10f;
                            float radius = Mathf.Sqrt(
                                shiftedX * shiftedX / 0.78f +
                                centeredY * centeredY / 0.92f);
                            float density = Mathf.Exp(
                                -radius * radius * 2.4f);
                            float lobeX = shiftedX -
                                0.24f * Mathf.Sin(variant * 1.7f + py * 2.4f);
                            float lobeY = py - 0.28f;
                            float lobe = Mathf.Exp(-(
                                lobeX * lobeX / 0.16f +
                                lobeY * lobeY / 0.28f) * 1.6f);
                            density = Mathf.Max(density, lobe * 0.82f);
                            float turbulence = Mathf.Clamp01(
                                0.76f +
                                0.17f * Mathf.Sin(
                                    shiftedX * 11f + py * 6f + variant) +
                                0.11f * Mathf.Cos(
                                    shiftedX * 5f - py * 14f - variant));
                            float alpha = Mathf.Clamp01(
                                density * turbulence *
                                (1f - Mathf.SmoothStep(0.70f, 1.08f, radius)));
                            alpha = Mathf.Pow(alpha, 1.18f);
                            float hot = 1f - Mathf.SmoothStep(
                                0.05f,
                                0.52f,
                                Mathf.Abs(shiftedX));
                            int pixelX = tileX * tileSize + x;
                            int pixelY = tileY * tileSize + y;
                            pixels[pixelY * textureSize + pixelX] =
                                new Color(1f, 0.78f + hot * 0.22f,
                                    0.18f + hot * 0.60f, alpha);
                        }
                    }
                }
            }

            texture.SetPixels(pixels);
            texture.Apply(false, false);
            return texture;
        }

        private static Texture2D CreateShotgunMuzzleFlashV4SmokeTexture()
        {
            const int tileSize = 96;
            const int textureSize = tileSize * 2;
            Texture2D texture = CreateShotgunMuzzleFlashV4Texture(
                textureSize,
                "ShotgunMuzzleSmokeAtlas");
            Color[] pixels = new Color[textureSize * textureSize];
            for (int tileY = 0; tileY < 2; tileY++)
            {
                for (int tileX = 0; tileX < 2; tileX++)
                {
                    int variant = tileY * 2 + tileX;
                    for (int y = 0; y < tileSize; y++)
                    {
                        for (int x = 0; x < tileSize; x++)
                        {
                            float px = ((x + 0.5f) / tileSize) * 2f - 1f;
                            float py = ((y + 0.5f) / tileSize) * 2f - 1f;
                            float warpedX = px + 0.10f * Mathf.Sin(
                                py * 4.7f + variant * 1.1f);
                            float warpedY = py + 0.09f * Mathf.Cos(
                                px * 5.2f - variant * 0.8f);
                            float radius = Mathf.Sqrt(
                                warpedX * warpedX + warpedY * warpedY);
                            float cellular = Mathf.Clamp01(
                                0.64f +
                                0.20f * Mathf.Sin(
                                    warpedX * 7.1f + warpedY * 3.9f) +
                                0.16f * Mathf.Cos(
                                    warpedX * 3.7f - warpedY * 8.3f));
                            float envelope = 1f - Mathf.SmoothStep(
                                0.52f,
                                1.08f,
                                radius);
                            float alpha = Mathf.Pow(
                                Mathf.Clamp01(envelope * cellular),
                                1.2f) * 0.86f;
                            float warmth = Mathf.Clamp01(1f - radius);
                            int pixelX = tileX * tileSize + x;
                            int pixelY = tileY * tileSize + y;
                            pixels[pixelY * textureSize + pixelX] =
                                new Color(0.64f + warmth * 0.16f,
                                    0.62f + warmth * 0.12f,
                                    0.60f + warmth * 0.08f, alpha);
                        }
                    }
                }
            }

            texture.SetPixels(pixels);
            texture.Apply(false, false);
            return texture;
        }

        private static Texture2D CreateShotgunMuzzleFlashV4Texture(
            int size,
            string name)
        {
            return new Texture2D(
                size,
                size,
                TextureFormat.RGBA32,
                false,
                true)
            {
                name = name,
                wrapMode = TextureWrapMode.Clamp,
                filterMode = FilterMode.Bilinear,
                anisoLevel = 0
            };
        }

