        private static ParticleSystem CreateShotgunMuzzleFlashV4ParticleSystem(
            Transform parent,
            string name,
            Mesh mesh,
            Material material,
            ParticleSystemRenderMode renderMode,
            uint randomSeed,
            short burstCount)
        {
            GameObject item = new GameObject(name);
            item.transform.SetParent(parent, false);
            item.transform.localRotation = Quaternion.Euler(0f, 90f, 0f);
            ParticleSystem system = item.AddComponent<ParticleSystem>();
            system.useAutoRandomSeed = false;
            system.randomSeed = randomSeed;
            ParticleSystem.MainModule main = system.main;
            main.loop = false;
            main.playOnAwake = false;
            main.simulationSpace = ParticleSystemSimulationSpace.Local;
            main.scalingMode = ParticleSystemScalingMode.Local;
            main.maxParticles = burstCount;
            ParticleSystem.EmissionModule emission = system.emission;
            emission.enabled = true;
            emission.rateOverTime = 0f;
            emission.SetBursts(new[]
            {
                new ParticleSystem.Burst(0f, burstCount)
            });
            ParticleSystemRenderer renderer =
                item.GetComponent<ParticleSystemRenderer>();
            renderer.renderMode = renderMode;
            renderer.alignment = renderMode == ParticleSystemRenderMode.Mesh
                ? ParticleSystemRenderSpace.Local
                : ParticleSystemRenderSpace.View;
            renderer.mesh = renderMode == ParticleSystemRenderMode.Mesh
                ? mesh
                : null;
            renderer.sharedMaterial = material;
            renderer.sortMode = renderMode == ParticleSystemRenderMode.Mesh
                ? ParticleSystemSortMode.None
                : ParticleSystemSortMode.Distance;
            renderer.normalDirection = renderMode == ParticleSystemRenderMode.Mesh
                ? 1f
                : 0.45f;
            renderer.cameraVelocityScale = 0f;
            bool pressureFlame = name.StartsWith(
                "PressureFlame",
                StringComparison.Ordinal);
            if (renderMode == ParticleSystemRenderMode.Stretch)
            {
                renderer.pivot = new Vector3(0f, 0.5f, 0f);
            }

            renderer.velocityScale = renderMode == ParticleSystemRenderMode.Stretch
                ? pressureFlame
                    ? 0.08f
                    : 0.06f
                : 0f;
            renderer.lengthScale =
                string.Equals(name, "HotPowderFragments", StringComparison.Ordinal)
                    ? 0.46f
                    : renderMode == ParticleSystemRenderMode.Stretch
                        ? pressureFlame
                            ? 0.525f
                            : 0.50f
                        : 1f;
            renderer.minParticleSize = 0f;
            renderer.maxParticleSize = 0.75f;
            renderer.sortingOrder = string.Equals(
                    name,
                    "IgnitionCore",
                    StringComparison.Ordinal)
                ? 5
                : string.Equals(
                    name,
                    "HotPowderFragments",
                    StringComparison.Ordinal)
                    ? 6
                    : pressureFlame
                        ? 4
                        : string.Equals(
                            name,
                            "FlameVolume3D",
                            StringComparison.Ordinal)
                            ? 3
                            : 1;
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            renderer.motionVectorGenerationMode =
                MotionVectorGenerationMode.ForceNoMotion;
            renderer.lightProbeUsage = LightProbeUsage.Off;
            renderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
            renderer.allowOcclusionWhenDynamic = false;
            system.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
            return system;
        }

        private static void ConfigureShotgunMuzzleFlashV4LateralVelocity(
            ParticleSystem system,
            float maximumSpeed)
        {
            ParticleSystem.VelocityOverLifetimeModule velocity =
                system.velocityOverLifetime;
            velocity.enabled = true;
            velocity.space = ParticleSystemSimulationSpace.Local;
            velocity.x = new ParticleSystem.MinMaxCurve(
                -maximumSpeed,
                maximumSpeed);
            velocity.y = new ParticleSystem.MinMaxCurve(
                -maximumSpeed,
                maximumSpeed);
            velocity.z = new ParticleSystem.MinMaxCurve(0f, 0f);
        }

        private static void ConfigureShotgunMuzzleFlashV4Size(
            ParticleSystem system,
            float start,
            float peak,
            float end)
        {
            ParticleSystem.SizeOverLifetimeModule size =
                system.sizeOverLifetime;
            size.enabled = true;
            size.size = new ParticleSystem.MinMaxCurve(
                1f,
                new AnimationCurve(
                    new Keyframe(0f, start),
                    new Keyframe(0.28f, peak),
                    new Keyframe(1f, end)));
        }

        [MenuItem("Bellerophon/Player/Apply Shotgun Fire Muzzle Flash And Three Second Cycle")]
        internal static void ApplyShotgunFireMuzzleFlashAndThreeSecondCycle()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun Fire VFX and timing must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunFireTargetName);
            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(value => string.Equals(
                    value.TargetName,
                    ShotgunFireTargetName,
                    StringComparison.Ordinal));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ?? throw new FileNotFoundException(
                "Unity shotgun FBX is missing.",
                Path.GetFullPath(ShotgunAssetPath));
            string shotgunHashBefore = HashFile(ShotgunAssetPath);
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);

            CreateOrUpdateShotgunMuzzleFlashTransparentTexture();
            ConfigureShotgunMuzzleFlashTextureImporter(
                ShotgunMuzzleFlashTexturePath);
            ConfigureShotgunMuzzleFlashTextureImporter(
                ShotgunMuzzleFlashRuntimeTexturePath);
            Texture2D texture = AssetDatabase.LoadAssetAtPath<Texture2D>(
                ShotgunMuzzleFlashRuntimeTexturePath) ??
                throw new FileNotFoundException(
                    "Transparent runtime Shotgun muzzle flash texture is missing.",
                    Path.GetFullPath(ShotgunMuzzleFlashRuntimeTexturePath));
            ReadPngDimensions(
                ShotgunMuzzleFlashTexturePath,
                out int sourceWidth,
                out int sourceHeight);
            float effectLength = analysis.Geometry.SourceLength * 0.85f;
            float effectHeight = effectLength * sourceHeight / sourceWidth;
            Mesh mesh = CreateOrUpdateShotgunMuzzleFlashMesh(
                effectLength,
                effectHeight);
            Material material = CreateOrUpdateShotgunMuzzleFlashMaterial(texture);
            GameObject prefab = CreateOrUpdateShotgunMuzzleFlashPrefab(
                mesh,
                material);

            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ShotgunFireCorrectedClipPath) ??
                throw new FileNotFoundException(
                    "Current corrected Shotgun Fire clip is missing.",
                    Path.GetFullPath(ShotgunFireCorrectedClipPath));
            string sourceHashBefore = HashFile(ShotgunFireCorrectedClipPath);
            AnimationClip derived = CreateOrUpdateUniformlyRetimedClip(
                source,
                ShotgunFireThreeSecondClipPath,
                ShotgunFireCycleSeconds,
                out float maximumNormalizedValueError,
                out int totalFloatKeys);

            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    spec.ControllerPath) ?? throw new FileNotFoundException(
                    spec.ControllerPath,
                    Path.GetFullPath(spec.ControllerPath));
            AnimatorState state = RequireControllerState(
                controller,
                spec.StateName);
            state.motion = derived;
            state.speed = 1f;
            ConfigureShotgunMuzzleFlashStateBehaviour(state);
            EditorUtility.SetDirty(state);
            EditorUtility.SetDirty(controller);

            Transform rightHand = FindRequired(target, RightHandPath);
            Transform item = rightHand.Find(ShotgunHandInstanceName) ??
                throw new InvalidOperationException(
                    ShotgunFireTargetName + " has no right-hand Shotgun instance.");
            Transform existingEffect = item.Find(ShotgunMuzzleFlashRootName);
            if (existingEffect != null)
            {
                UnityEngine.Object.DestroyImmediate(existingEffect.gameObject);
            }

            GameObject effectObject = PrefabUtility.InstantiatePrefab(
                prefab,
                item) as GameObject ?? throw new InvalidOperationException(
                "Shotgun muzzle flash prefab could not be instantiated.");
            effectObject.name = ShotgunMuzzleFlashRootName;
            Vector3 muzzleAxis = analysis.Geometry.StockToMuzzleAxis.normalized;
            effectObject.transform.localPosition =
                analysis.Geometry.LocalMuzzlePoint;
            effectObject.transform.localRotation =
                Quaternion.FromToRotation(Vector3.right, muzzleAxis);
            effectObject.transform.localScale = Vector3.one;
            MonoBehaviour effect = effectObject.GetComponent(
                RequireMusketMuzzleFlashRuntimeType(
                    ShotgunMuzzleFlashRuntimeTypeName)) as MonoBehaviour ??
                throw new InvalidOperationException(
                    "Shotgun muzzle flash runtime component is missing.");
            Renderer visualRenderer = effectObject.GetComponent<Renderer>() ??
                throw new InvalidOperationException(
                    "Shotgun muzzle flash renderer is missing.");
            InvokeMusketMuzzleFlashMethod(
                effect,
                "Configure",
                visualRenderer,
                ShotgunMuzzleFlashHotDurationSeconds,
                ShotgunMuzzleFlashTotalDurationSeconds);

            Animator animator = RequireAnimator(target);
            animator.runtimeAnimatorController = controller;
            animator.speed = 1f;
            animator.applyRootMotion = false;
            EditorUtility.SetDirty(animator);
            EditorUtility.SetDirty(effectObject);
            EditorSceneManager.MarkSceneDirty(scene);
            AssetDatabase.SaveAssets();
            if (!EditorSceneManager.SaveScene(scene))
            {
                throw new InvalidOperationException(
                    "CargoRunMvp could not be saved after Shotgun Fire apply.");
            }

            TextureImporter importer = AssetImporter.GetAtPath(
                ShotgunMuzzleFlashRuntimeTexturePath) as TextureImporter ??
                throw new InvalidOperationException(
                    "Shotgun muzzle flash texture importer is unavailable.");
            TextureImporterPlatformSettings standalone =
                importer.GetPlatformTextureSettings("Standalone");
            StateMachineBehaviour[] behaviours = state.behaviours
                .Where(value => value != null &&
                    RequireMusketMuzzleFlashRuntimeType(
                        ShotgunMuzzleFlashBehaviourTypeName)
                        .IsInstanceOfType(value))
                .ToArray();
            float triggerTime = behaviours.Length == 1
                ? ReadMusketMuzzleFlashProperty<float>(
                    behaviours[0],
                    "NormalizedTriggerTime")
                : -1f;
            Renderer[] renderers = effectObject
                .GetComponentsInChildren<Renderer>(true);
            ShotgunMuzzleFlashApplicationMetrics metrics =
                new ShotgunMuzzleFlashApplicationMetrics
                {
                    target = ShotgunFireTargetName,
                    approvedSample =
                        "artSample/shotgun_muzzle_flash/renders/01_realistic_shotgun_muzzle_flash.png",
                    sampleApprovalStatus = "approved_by_user",
                    shotgunAssetPath = ShotgunAssetPath,
                    shotgunAssetHashBefore = shotgunHashBefore,
                    shotgunAssetHashAfter = HashFile(ShotgunAssetPath),
                    sourceTexturePath = ShotgunMuzzleFlashTexturePath,
                    runtimeTexturePath =
                        ShotgunMuzzleFlashRuntimeTexturePath,
                    sourceTextureWidth = sourceWidth,
                    sourceTextureHeight = sourceHeight,
                    sourceTextureFileBytes = new FileInfo(
                        Path.GetFullPath(ShotgunMuzzleFlashTexturePath)).Length,
                    sourceRawRgbaBytes = (long)sourceWidth * sourceHeight * 4L,
                    importedTextureWidth = texture.width,
                    importedTextureHeight = texture.height,
                    importedTextureRuntimeBytes =
                        UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(
                            texture),
                    importedTextureMaxSize = standalone.maxTextureSize,
                    importedTextureCompression =
                        importer.textureCompression + "/" + standalone.format,
                    sourceClipPath = ShotgunFireCorrectedClipPath,
                    sourceClipHashBefore = sourceHashBefore,
                    sourceClipHashAfter = HashFile(
                        ShotgunFireCorrectedClipPath),
                    derivedClipPath = ShotgunFireThreeSecondClipPath,
                    sourceDurationSeconds = source.length,
                    derivedDurationSeconds = derived.length,
                    uniformTimeScale = ShotgunFireCycleSeconds / source.length,
                    floatCurveBindings =
                        AnimationUtility.GetCurveBindings(source).Length,
                    totalFloatKeys = totalFloatKeys,
                    maximumNormalizedCurveValueError =
                        maximumNormalizedValueError,
                    sourceCurveValuesUnchanged =
                        string.Equals(
                            sourceHashBefore,
                            HashFile(ShotgunFireCorrectedClipPath),
                            StringComparison.OrdinalIgnoreCase),
                    controllerPath = spec.ControllerPath,
                    stateName = spec.StateName,
                    stateSpeed = state.speed,
                    normalizedTriggerTime = triggerTime,
                    effectPath = AnimationUtility.CalculateTransformPath(
                        effectObject.transform,
                        target),
                    muzzleLocalPosition = effectObject.transform.localPosition,
                    muzzleLocalAxis =
                        effectObject.transform.localRotation * Vector3.right,
                    muzzleAnchorErrorMeters = Vector3.Distance(
                        effectObject.transform.localPosition,
                        analysis.Geometry.LocalMuzzlePoint),
                    muzzleDirectionErrorDegrees = Vector3.Angle(
                        effectObject.transform.localRotation * Vector3.right,
                        muzzleAxis),
                    rendererCount = renderers.Length,
                    materialCount = renderers
                        .Select(value => value.sharedMaterial)
                        .Where(value => value != null)
                        .Distinct()
                        .Count(),
                    meshVertexCount = mesh.vertexCount,
                    meshTriangleCount = mesh.triangles.Length / 3,
                    particleSystemCount = effectObject
                        .GetComponentsInChildren<ParticleSystem>(true).Length,
                    lightCount = effectObject
                        .GetComponentsInChildren<Light>(true).Length,
                    createsObjectsPerShot = false,
                    rendererReused = true,
                    mipMapsDisabled = !importer.mipmapEnabled,
                    shadowsDisabled = renderers.All(value =>
                        value.shadowCastingMode == ShadowCastingMode.Off &&
                        !value.receiveShadows),
                    motionVectorsDisabled = renderers.All(value =>
                        value.motionVectorGenerationMode ==
                        MotionVectorGenerationMode.ForceNoMotion),
                    presentationMatteRemovedOffline = true,
                    sourceEffectPixelsReused = true,
                    detectedCheckerVerticalPeriodPixels =
                        shotgunMuzzleFlashDetectedCheckerPeriod,
                    warmupFramesPerCondition =
                        ShotgunMuzzleFlashWarmupFrames,
                    sampleFramesPerCondition =
                        ShotgunMuzzleFlashSampleFrames,
                    performanceConditions = Array.Empty<
                        ShotgunMuzzleFlashConditionMetrics>(),
                    actualPlayModeObserved = false,
                    naturalLoopsObserved = 0,
                    naturalEmissionsObserved = 0,
                    finalReviewPath = ShotgunMuzzleFlashFinalReviewPath,
                    finalReviewExists = false,
                    performanceSafe = false,
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                string.Equals(
                    metrics.shotgunAssetHashBefore,
                    metrics.shotgunAssetHashAfter,
                    StringComparison.OrdinalIgnoreCase) &&
                metrics.sourceCurveValuesUnchanged &&
                Mathf.Abs(metrics.derivedDurationSeconds -
                    ShotgunFireCycleSeconds) <= 0.0001f &&
                metrics.maximumNormalizedCurveValueError <= 0.0001f &&
                Mathf.Abs(metrics.stateSpeed - 1f) <= 0.0001f &&
                behaviours.Length == 1 &&
                Mathf.Abs(metrics.normalizedTriggerTime -
                    ShotgunMuzzleFlashTriggerNormalizedTime) <= 0.0001f &&
                metrics.muzzleAnchorErrorMeters <= PositionTolerance &&
                metrics.muzzleDirectionErrorDegrees <= RotationTolerance &&
                metrics.rendererCount == 1 &&
                metrics.materialCount == 1 &&
                metrics.meshVertexCount == 4 &&
                metrics.meshTriangleCount == 2 &&
                metrics.particleSystemCount == 0 &&
                metrics.lightCount == 0 &&
                !metrics.createsObjectsPerShot &&
                metrics.rendererReused &&
                metrics.mipMapsDisabled &&
                metrics.shadowsDisabled &&
                metrics.motionVectorsDisabled &&
                metrics.presentationMatteRemovedOffline &&
                metrics.sourceEffectPixelsReused;
            WriteJson(ShotgunMuzzleFlashApplicationMetricsPath, metrics);
            SessionState.EraseInt(ShotgunMuzzleFlashCaptureStageKey);
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun Fire VFX/timing support checks failed. " +
                    JsonUtility.ToJson(metrics));
            }

            Debug.Log(
                "[PlayerShotgunMuzzleFlash] Approved sample applied at the detected muzzle as one reused 4-vertex/2-triangle renderer. " +
                "The exact existing fire curves were uniformly retimed from " +
                Num(source.length) + "s to " + Num(derived.length) +
                "s at Animator speed 1. SceneChanged=True.");
        }

        [MenuItem("Bellerophon/Player/Apply Shotgun Fire Volumetric Muzzle Flash")]
        internal static void ApplyShotgunFireVolumetricMuzzleFlash()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun volumetric muzzle flash must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunFireTargetName);
            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(value => string.Equals(
                    value.TargetName,
                    ShotgunFireTargetName,
                    StringComparison.Ordinal));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ?? throw new FileNotFoundException(
                "Unity shotgun FBX is missing.",
                Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            string shotgunHashBefore = HashFile(ShotgunAssetPath);

            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ShotgunFireCorrectedClipPath) ??
                throw new FileNotFoundException(
                    "Current corrected Shotgun Fire clip is missing.",
                    Path.GetFullPath(ShotgunFireCorrectedClipPath));
            AnimationClip derived = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ShotgunFireThreeSecondClipPath) ??
                throw new FileNotFoundException(
                    "Existing three-second Shotgun Fire clip is missing.",
                    Path.GetFullPath(ShotgunFireThreeSecondClipPath));
            string sourceHashBefore = HashFile(ShotgunFireCorrectedClipPath);
            string derivedHashBefore = HashFile(ShotgunFireThreeSecondClipPath);

            string approvedSampleHash = HashFile(
                ShotgunMuzzleFlashApprovedSamplePath);
            string sourceTextureHash = HashFile(
                ShotgunMuzzleFlashTexturePath);
            if (!string.Equals(
                    approvedSampleHash,
                    sourceTextureHash,
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Unity Shotgun muzzle flash V2 source is not an exact copy of the approved sample.");
            }

            CreateOrUpdateShotgunMuzzleFlashTransparentTexture();
            ConfigureShotgunMuzzleFlashTextureImporter(
                ShotgunMuzzleFlashTexturePath);
            ConfigureShotgunMuzzleFlashTextureImporter(
                ShotgunMuzzleFlashRuntimeTexturePath);

            Texture2D texture = AssetDatabase.LoadAssetAtPath<Texture2D>(
                ShotgunMuzzleFlashRuntimeTexturePath) ??
                throw new FileNotFoundException(
                    "Approved Shotgun muzzle flash runtime texture is missing.",
                    Path.GetFullPath(ShotgunMuzzleFlashRuntimeTexturePath));
            ReadPngDimensions(
                ShotgunMuzzleFlashTexturePath,
                out int sourceWidth,
                out int sourceHeight);
            float baselineLength = analysis.Geometry.SourceLength * 0.85f;
            float baselineHeight =
                baselineLength * sourceHeight / sourceWidth;
            Mesh particleMesh = AssetDatabase.LoadAssetAtPath<Mesh>(
                MusketMuzzleFlashMeshPath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference particle mesh is missing.",
                    Path.GetFullPath(MusketMuzzleFlashMeshPath));
            Mesh smokeMesh = AssetDatabase.LoadAssetAtPath<Mesh>(
                MusketMuzzleSmokeMeshPath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference smoke mesh is missing.",
                    Path.GetFullPath(MusketMuzzleSmokeMeshPath));
            Texture2D flameMask = AssetDatabase.LoadAssetAtPath<Texture2D>(
                MusketMuzzleFlameTexturePath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference flame mask is missing.",
                    Path.GetFullPath(MusketMuzzleFlameTexturePath));
            Texture2D smokeMask = AssetDatabase.LoadAssetAtPath<Texture2D>(
                MusketMuzzleSmokeTexturePath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference smoke mask is missing.",
                    Path.GetFullPath(MusketMuzzleSmokeTexturePath));
            Material bloomMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleBloomMaterialPath,
                false,
                flameMask,
                new Color(1.8f, 1.8f, 1.8f, 1f));
            Material hotGasMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleHotGasMaterialPath,
                true,
                flameMask,
                new Color(3.8f, 1.15f, 0.12f, 1f),
                new Color(8.5f, 2.4f, 0.12f, 1f));
            Material smokeMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleSmokeMaterialPath,
                false,
                smokeMask,
                new Color(0.82f, 0.76f, 0.70f, 1f));
            GameObject prefab = CreateOrUpdateShotgunMuzzleFlashPrefab(
                particleMesh,
                smokeMesh,
                bloomMaterial,
                hotGasMaterial,
                smokeMaterial);

            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    spec.ControllerPath) ?? throw new FileNotFoundException(
                    spec.ControllerPath,
                    Path.GetFullPath(spec.ControllerPath));
            AnimatorState state = RequireControllerState(
                controller,
                spec.StateName);
            if (state.motion != derived ||
                Mathf.Abs(state.speed - 1f) > 0.0001f ||
                Mathf.Abs(derived.length - ShotgunFireCycleSeconds) > 0.0001f)
            {
                throw new InvalidOperationException(
                    "Shotgun_Fire three-second animation connection changed before VFX-only apply.");
            }

            ConfigureShotgunMuzzleFlashStateBehaviour(state);
            EditorUtility.SetDirty(state);
            EditorUtility.SetDirty(controller);

            Transform rightHand = FindRequired(target, RightHandPath);
            Transform item = rightHand.Find(ShotgunHandInstanceName) ??
                throw new InvalidOperationException(
                    ShotgunFireTargetName +
                    " has no right-hand Shotgun instance.");
            Transform existingEffect = item.Find(ShotgunMuzzleFlashRootName);
            if (existingEffect != null)
            {
                UnityEngine.Object.DestroyImmediate(existingEffect.gameObject);
            }

            GameObject effectObject = PrefabUtility.InstantiatePrefab(
                prefab,
                item) as GameObject ?? throw new InvalidOperationException(
                "Shotgun volumetric muzzle flash prefab could not be instantiated.");
            effectObject.name = ShotgunMuzzleFlashRootName;
            Vector3 muzzleAxis = analysis.Geometry.StockToMuzzleAxis.normalized;
            effectObject.transform.localPosition =
                analysis.Geometry.LocalMuzzlePoint;
            effectObject.transform.localRotation =
                Quaternion.FromToRotation(Vector3.right, muzzleAxis);
            effectObject.transform.localScale = Vector3.one;
            MonoBehaviour effect = effectObject.GetComponent(
                RequireMusketMuzzleFlashRuntimeType(
                    ShotgunMuzzleFlashRuntimeTypeName)) as MonoBehaviour ??
                throw new InvalidOperationException(
                    "Shotgun volumetric muzzle flash runtime component is missing.");
            Renderer visualRenderer = effectObject
                .GetComponentsInChildren<ParticleSystemRenderer>(true)
                .SingleOrDefault(value => string.Equals(
                    value.gameObject.name,
                    "FlashCore",
                    StringComparison.Ordinal)) ??
                throw new InvalidOperationException(
                    "Shotgun Musket-style flash core renderer is missing.");
            Vector3 initialScaleRatio = new Vector3(0.65f, 0.55f, 0.55f);
            InvokeMusketMuzzleFlashMethod(
                effect,
                "ConfigureVolume",
                visualRenderer,
                ShotgunMuzzleFlashHotDurationSeconds,
                ShotgunMuzzleFlashTotalDurationSeconds,
                ShotgunMuzzleFlashExpansionDurationSeconds,
                initialScaleRatio);
            ParticleSystem[] particleSystems = effectObject
                .GetComponentsInChildren<ParticleSystem>(true);
            ParticleSystem hotGas = particleSystems.Single(value =>
                string.Equals(
                    value.gameObject.name,
                    "HotGasVolume",
                    StringComparison.Ordinal));
            ParticleSystem smoke = particleSystems.Single(value =>
                string.Equals(
                    value.gameObject.name,
                    "SmokeVolume",
                    StringComparison.Ordinal));
            ParticleSystem embers = particleSystems.Single(value =>
                string.Equals(
                    value.gameObject.name,
                    "PowderEmbers",
                    StringComparison.Ordinal));
            Light muzzleLight = effectObject
                .GetComponentsInChildren<Light>(true)
                .SingleOrDefault() ?? throw new InvalidOperationException(
                    "Shotgun Musket-style capped muzzle light is missing.");
            InvokeMusketMuzzleFlashMethod(
                effect,
                "ConfigureLayers",
                null,
                hotGas,
                smoke,
                embers,
                muzzleLight,
                ShotgunMuzzleFlashLightDurationSeconds,
                ShotgunMuzzleFlashLightPeakIntensity);

            EditorUtility.SetDirty(effectObject);
            EditorSceneManager.MarkSceneDirty(scene);
            AssetDatabase.SaveAssets();
            if (!EditorSceneManager.SaveScene(scene))
            {
                throw new InvalidOperationException(
                    "CargoRunMvp could not be saved after volumetric Shotgun muzzle flash apply.");
            }

            TextureImporter importer = AssetImporter.GetAtPath(
                ShotgunMuzzleFlashRuntimeTexturePath) as TextureImporter ??
                throw new InvalidOperationException(
                    "Shotgun muzzle flash texture importer is unavailable.");
            TextureImporterPlatformSettings standalone =
                importer.GetPlatformTextureSettings("Standalone");
            Type behaviourType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashBehaviourTypeName);
            StateMachineBehaviour[] behaviours = state.behaviours
                .Where(value => value != null &&
                    behaviourType.IsInstanceOfType(value))
                .ToArray();
            float triggerTime = behaviours.Length == 1
                ? ReadMusketMuzzleFlashProperty<float>(
                    behaviours[0],
                    "NormalizedTriggerTime")
                : -1f;
            Renderer[] renderers = effectObject
                .GetComponentsInChildren<Renderer>(true);
            Vector3 configuredFullLocalScale =
                ReadMusketMuzzleFlashProperty<Vector3>(
                    effect,
                    "FullLocalScale");
            ShotgunMuzzleFlashApplicationMetrics metrics =
                new ShotgunMuzzleFlashApplicationMetrics
                {
                    target = ShotgunFireTargetName,
                    approvedSample = ShotgunMuzzleFlashApprovedSamplePath,
                    approvedSampleHash = approvedSampleHash,
                    sampleApprovalStatus = "approved_by_user",
                    shotgunAssetPath = ShotgunAssetPath,
                    shotgunAssetHashBefore = shotgunHashBefore,
                    shotgunAssetHashAfter = HashFile(ShotgunAssetPath),
                    sourceTexturePath = ShotgunMuzzleFlashTexturePath,
                    sourceTextureHash = sourceTextureHash,
                    runtimeTexturePath =
                        ShotgunMuzzleFlashRuntimeTexturePath,
                    sourceTextureWidth = sourceWidth,
                    sourceTextureHeight = sourceHeight,
                    sourceTextureFileBytes = new FileInfo(
                        Path.GetFullPath(ShotgunMuzzleFlashTexturePath)).Length,
                    sourceRawRgbaBytes = (long)sourceWidth * sourceHeight * 4L,
                    importedTextureWidth = texture.width,
                    importedTextureHeight = texture.height,
                    importedTextureRuntimeBytes =
                        UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(
                            texture),
                    importedTextureMaxSize = standalone.maxTextureSize,
                    importedTextureCompression =
                        importer.textureCompression + "/" + standalone.format,
                    sourceClipPath = ShotgunFireCorrectedClipPath,
                    sourceClipHashBefore = sourceHashBefore,
                    sourceClipHashAfter = HashFile(
                        ShotgunFireCorrectedClipPath),
                    derivedClipPath = ShotgunFireThreeSecondClipPath,
                    derivedClipHashBefore = derivedHashBefore,
                    derivedClipHashAfter = HashFile(
                        ShotgunFireThreeSecondClipPath),
                    sourceDurationSeconds = source.length,
                    derivedDurationSeconds = derived.length,
                    uniformTimeScale = derived.length / source.length,
                    floatCurveBindings =
                        AnimationUtility.GetCurveBindings(derived).Length,
                    totalFloatKeys = AnimationUtility
                        .GetCurveBindings(derived)
                        .Sum(binding => AnimationUtility
                            .GetEditorCurve(derived, binding).length),
                    maximumNormalizedCurveValueError =
                        CalculateMaximumNormalizedCurveValueError(
                            source,
                            derived),
                    sourceCurveValuesUnchanged =
                        string.Equals(
                            sourceHashBefore,
                            HashFile(ShotgunFireCorrectedClipPath),
                            StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(
                            derivedHashBefore,
                            HashFile(ShotgunFireThreeSecondClipPath),
                            StringComparison.OrdinalIgnoreCase),
                    controllerPath = spec.ControllerPath,
                    stateName = spec.StateName,
                    stateSpeed = state.speed,
                    triggerAbsoluteSeconds = triggerTime * derived.length,
                    normalizedTriggerTime = triggerTime,
                    visualRepresentation =
                        "musket_style_layered_soft_billboards_without_dominant_card",
                    usesMusketStyleLayeredSoftBillboards = true,
                    usesSingleDominantCard = false,
                    flashBurstCount = ShotgunMuzzleFlashFlashBurstCount,
                    hotGasBurstCount = ShotgunMuzzleFlashHotGasBurstCount,
                    smokeBurstCount = ShotgunMuzzleFlashSmokeBurstCount,
                    emberBurstCount = ShotgunMuzzleFlashEmberBurstCount,
                    maximumConfiguredParticles =
                        ReadMusketMuzzleFlashProperty<int>(
                            effect,
                            "MaximumConfiguredParticles"),
                    hasCappedShortMuzzleLight = muzzleLight != null &&
                        muzzleLight.shadows == LightShadows.None &&
                        muzzleLight.range <= 2.1f,
                    approvedTextureExcludedFromRuntimeCard = renderers.All(
                        value => value.sharedMaterial != null &&
                            !string.Equals(
                                AssetDatabase.GetAssetPath(
                                    value.sharedMaterial),
                                ShotgunMuzzleFlashMaterialPath,
                                StringComparison.Ordinal)),
                    requestedVisualScale = 0f,
                    baselineLengthMeters = baselineLength,
                    baselineHeightMeters = baselineHeight,
                    appliedLengthMeters = 0f,
                    appliedHeightMeters = 0f,
                    appliedDepthMeters = 0f,
                    measuredLengthScale = 0f,
                    measuredHeightScale = 0f,
                    expansionDurationSeconds =
                        ReadMusketMuzzleFlashProperty<float>(
                            effect,
                            "ExpansionDurationSeconds"),
                    initialScaleRatio =
                        ReadMusketMuzzleFlashProperty<Vector3>(
                            effect,
                            "InitialScaleRatio"),
                    configuredFullLocalScale = configuredFullLocalScale,
                    expandsFromMuzzle = initialScaleRatio.x < 1f,
                    usesCameraBillboarding =
                        ReadMusketMuzzleFlashProperty<bool>(
                            effect,
                            "UsesCameraBillboarding"),
                    effectPath = AnimationUtility.CalculateTransformPath(
                        effectObject.transform,
                        target),
                    muzzleLocalPosition = effectObject.transform.localPosition,
                    muzzleLocalAxis =
                        effectObject.transform.localRotation * Vector3.right,
                    muzzleAnchorErrorMeters = Vector3.Distance(
                        effectObject.transform.localPosition,
                        analysis.Geometry.LocalMuzzlePoint),
                    muzzleDirectionErrorDegrees = Vector3.Angle(
                        effectObject.transform.localRotation * Vector3.right,
                        muzzleAxis),
                    rendererCount = renderers.Length,
                    materialCount = renderers
                        .Select(value => value.sharedMaterial)
                        .Where(value => value != null)
                        .Distinct()
                        .Count(),
                    meshVertexCount = particleMesh.vertexCount,
                    meshTriangleCount = particleMesh.triangles.Length / 3,
                    particleSystemCount = effectObject
                        .GetComponentsInChildren<ParticleSystem>(true).Length,
                    lightCount = effectObject
                        .GetComponentsInChildren<Light>(true).Length,
                    createsObjectsPerShot = false,
                    rendererReused = true,
                    mipMapsDisabled = !importer.mipmapEnabled,
                    shadowsDisabled = renderers.All(value =>
                        value.shadowCastingMode == ShadowCastingMode.Off &&
                        !value.receiveShadows),
                    motionVectorsDisabled = renderers.All(value =>
                        value.motionVectorGenerationMode ==
                        MotionVectorGenerationMode.ForceNoMotion),
                    presentationMatteRemovedOffline = string.Equals(
                        shotgunMuzzleFlashTransparencyPreparation,
                        "checker_matte_removed",
                        StringComparison.Ordinal),
                    transparencyPreparation =
                        shotgunMuzzleFlashTransparencyPreparation,
                    runtimeTransparencyPrepared = true,
                    sourceEffectPixelsReused = false,
                    detectedCheckerVerticalPeriodPixels =
                        shotgunMuzzleFlashDetectedCheckerPeriod,
                    warmupFramesPerCondition =
                        ShotgunMuzzleFlashWarmupFrames,
                    sampleFramesPerCondition =
                        ShotgunMuzzleFlashSampleFrames,
                    performanceConditions = Array.Empty<
                        ShotgunMuzzleFlashConditionMetrics>(),
                    actualPlayModeObserved = false,
                    naturalLoopsObserved = 0,
                    naturalEmissionsObserved = 0,
                    finalReviewPath = ShotgunMuzzleFlashFinalReviewPath,
                    finalReviewExists = false,
                    performanceSafe = false,
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                ShotgunVolumetricMuzzleFlashStaticMetricsPass(metrics) &&
                behaviours.Length == 1;
            WriteJson(ShotgunMuzzleFlashApplicationMetricsPath, metrics);
            SessionState.EraseInt(ShotgunMuzzleFlashCaptureStageKey);
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Volumetric Shotgun muzzle flash support checks failed. " +
                    JsonUtility.ToJson(metrics));
            }

            Debug.Log(
                "[PlayerShotgunMuzzleFlash] Replaced the dominant crossed-card burst with the Musket's four-layer soft-particle architecture, widened for Shotgun dispersion and backed by one capped unshadowed light. " +
                "Trigger=" + Num(metrics.triggerAbsoluteSeconds) +
                "s, Expansion=" + Num(metrics.expansionDurationSeconds) +
                "s, Systems=" + metrics.particleSystemCount +
                ", MaxParticles=" + metrics.maximumConfiguredParticles +
                ", AnimationClipsChanged=False, SceneChanged=True.");
        }

        private static bool ShotgunVolumetricMuzzleFlashStaticMetricsPass(
            ShotgunMuzzleFlashApplicationMetrics metrics)
        {
            return string.Equals(
                       metrics.shotgunAssetHashBefore,
                       metrics.shotgunAssetHashAfter,
                       StringComparison.OrdinalIgnoreCase) &&
                   string.Equals(
                       metrics.sourceClipHashBefore,
                       metrics.sourceClipHashAfter,
                       StringComparison.OrdinalIgnoreCase) &&
                   string.Equals(
                       metrics.derivedClipHashBefore,
                   metrics.derivedClipHashAfter,
                       StringComparison.OrdinalIgnoreCase) &&
                   metrics.sourceCurveValuesUnchanged &&
                   metrics.maximumNormalizedCurveValueError <= 0.0001f &&
                   Mathf.Abs(metrics.derivedDurationSeconds -
                       ShotgunFireCycleSeconds) <= 0.0001f &&
                   Mathf.Abs(metrics.stateSpeed - 1f) <= 0.0001f &&
                   Mathf.Abs(metrics.triggerAbsoluteSeconds -
                       ShotgunMuzzleFlashTriggerAbsoluteSeconds) <= 0.0001f &&
                   Mathf.Abs(metrics.normalizedTriggerTime -
                       ShotgunMuzzleFlashTriggerNormalizedTime) <= 0.0001f &&
                    metrics.usesMusketStyleLayeredSoftBillboards &&
                    !metrics.usesSingleDominantCard &&
                    metrics.flashBurstCount ==
                        ShotgunMuzzleFlashFlashBurstCount &&
                    metrics.hotGasBurstCount ==
                        ShotgunMuzzleFlashHotGasBurstCount &&
                    metrics.smokeBurstCount ==
                        ShotgunMuzzleFlashSmokeBurstCount &&
                    metrics.emberBurstCount ==
                        ShotgunMuzzleFlashEmberBurstCount &&
                    metrics.maximumConfiguredParticles ==
                        ShotgunMuzzleFlashMaximumParticleCapacity &&
                    metrics.hasCappedShortMuzzleLight &&
                    metrics.approvedTextureExcludedFromRuntimeCard &&
                    Vector3.Distance(
                        metrics.configuredFullLocalScale,
                        Vector3.one) <= 0.001f &&
                   metrics.expandsFromMuzzle &&
                   metrics.usesCameraBillboarding &&
                   metrics.muzzleAnchorErrorMeters <= PositionTolerance &&
                   metrics.muzzleDirectionErrorDegrees <= RotationTolerance &&
                   metrics.rendererCount == ShotgunMuzzleFlashSystemCount &&
                   metrics.materialCount == 3 &&
                   metrics.particleSystemCount ==
                       ShotgunMuzzleFlashSystemCount &&
                   metrics.lightCount == 1 &&
                   !metrics.createsObjectsPerShot &&
                   metrics.rendererReused &&
                   metrics.shadowsDisabled &&
                   metrics.motionVectorsDisabled &&
                   metrics.runtimeTransparencyPrepared &&
                   !metrics.sourceEffectPixelsReused;
        }

        private static void ConfigureShotgunMuzzleFlashTextureImporter(
            string texturePath)
        {
            TextureImporter importer = AssetImporter.GetAtPath(
                texturePath) as TextureImporter ??
                throw new InvalidOperationException(
                    "Shotgun muzzle flash texture importer is unavailable: " +
                    texturePath + ".");
            importer.textureType = TextureImporterType.Default;
            importer.sRGBTexture = true;
            importer.alphaIsTransparency = true;
            importer.mipmapEnabled = false;
            importer.npotScale = TextureImporterNPOTScale.None;
            importer.wrapMode = TextureWrapMode.Clamp;
            importer.filterMode = FilterMode.Bilinear;
            importer.anisoLevel = 0;
            importer.maxTextureSize = ShotgunMuzzleFlashTextureMaxSize;
            importer.textureCompression = TextureImporterCompression.CompressedHQ;
            importer.compressionQuality = 90;
            TextureImporterPlatformSettings standalone =
                importer.GetPlatformTextureSettings("Standalone");
            standalone.name = "Standalone";
            standalone.overridden = true;
            standalone.maxTextureSize = ShotgunMuzzleFlashTextureMaxSize;
            standalone.format = TextureImporterFormat.BC7;
            standalone.textureCompression =
                TextureImporterCompression.CompressedHQ;
            standalone.compressionQuality = 90;
            importer.SetPlatformTextureSettings(standalone);
            importer.SaveAndReimport();
        }

        private static void CreateOrUpdateShotgunMuzzleFlashTransparentTexture()
        {
            Texture2D source = new Texture2D(
                2,
                2,
                TextureFormat.RGBA32,
                false);
            Texture2D output = null;
            try
            {
                if (!source.LoadImage(File.ReadAllBytes(
                        Path.GetFullPath(ShotgunMuzzleFlashTexturePath))))
                {
                    throw new InvalidOperationException(
                        "Approved Shotgun muzzle flash source could not be decoded.");
                }

                output = new Texture2D(
                    source.width,
                    source.height,
                    TextureFormat.RGBA32,
                    false,
                    false);
                Color[] sourcePixels = source.GetPixels();
                Color[] outputPixels = new Color[sourcePixels.Length];
                int transparentPixelCount = sourcePixels.Count(value =>
                    value.a <= 0.01f);
                bool sourceHasUsableAlpha = transparentPixelCount >=
                    sourcePixels.Length / 20;
                if (sourceHasUsableAlpha)
                {
                    Array.Copy(
                        sourcePixels,
                        outputPixels,
                        sourcePixels.Length);
                    shotgunMuzzleFlashDetectedCheckerPeriod = 0;
                    shotgunMuzzleFlashTransparencyPreparation =
                        "source_alpha_preserved";
                }
                else
                {
                    int checkerPeriod = DetectShotgunCheckerVerticalPeriod(
                        sourcePixels,
                        source.width,
                        source.height);
                    shotgunMuzzleFlashDetectedCheckerPeriod = checkerPeriod;
                    shotgunMuzzleFlashTransparencyPreparation =
                        "checker_matte_removed";
                    float[] matteAlpha = new float[sourcePixels.Length];
                    float[] highlightDifference = new float[
                        sourcePixels.Length];
                    for (int y = 0; y < source.height; y++)
                    {
                        for (int x = 0; x < source.width; x++)
                        {
                            int index = y * source.width + x;
                            Color value = sourcePixels[index];
                            int backgroundY = y % checkerPeriod;
                            Color background = sourcePixels[
                                backgroundY * source.width + x];
                            float redAlpha = Mathf.Max(
                                0f,
                                (background.r - value.r) /
                                Mathf.Max(0.001f, background.r));
                            float greenAlpha = Mathf.Max(
                                0f,
                                (background.g - value.g) /
                                Mathf.Max(0.001f, background.g));
                            float blueAlpha = Mathf.Max(
                                0f,
                                (background.b - value.b) /
                                Mathf.Max(0.001f, background.b));
                            highlightDifference[index] = Mathf.Max(
                                value.r - background.r,
                                Mathf.Max(
                                    value.g - background.g,
                                    value.b - background.b));
                            float alpha = Mathf.Clamp01(
                                Mathf.Max(
                                    redAlpha,
                                    Mathf.Max(greenAlpha, blueAlpha)));
                            matteAlpha[index] = Mathf.InverseLerp(
                                0.025f,
                                1f,
                                alpha) * value.a;
                        }
                    }

                    for (int y = 0; y < source.height; y++)
                    {
                        for (int x = 0; x < source.width; x++)
                        {
                            int index = y * source.width + x;
                            Color value = sourcePixels[index];
                            int backgroundY = y % checkerPeriod;
                            Color background = sourcePixels[
                                backgroundY * source.width + x];
                            float normalizedX = x /
                                Mathf.Max(1f, source.width - 1f);
                            float coreProgress = Mathf.InverseLerp(
                                0f,
                                0.35f,
                                normalizedX);
                            float coreHalfHeight = Mathf.Lerp(
                                source.height * 0.018f,
                                source.height * 0.11f,
                                coreProgress);
                            float centerDistance = Mathf.Abs(
                                y - (source.height - 1f) * 0.5f);
                            float coreVerticalSupport = 1f -
                                Mathf.InverseLerp(
                                    coreHalfHeight * 0.72f,
                                    coreHalfHeight,
                                    centerDistance);
                            float coreForwardSupport = 1f -
                                Mathf.InverseLerp(
                                    0.38f,
                                    0.5f,
                                    normalizedX);
                            float coreSupport = coreVerticalSupport *
                                coreForwardSupport;
                            float highlightAlpha = Mathf.InverseLerp(
                                0.02f,
                                0.075f,
                                highlightDifference[index]) *
                                coreSupport;
                            float brightness = Mathf.Max(
                                value.r,
                                Mathf.Max(value.g, value.b));
                            float coreAlpha = Mathf.InverseLerp(
                                0.94f,
                                0.995f,
                                brightness) * coreSupport * 0.92f;
                            float alpha = Mathf.Clamp01(Mathf.Max(
                                matteAlpha[index],
                                Mathf.Max(highlightAlpha, coreAlpha)));
                            if (alpha <= 0.001f)
                            {
                                outputPixels[index] = Color.clear;
                                continue;
                            }

                            float inverseAlpha = 1f - alpha;
                            outputPixels[index] = new Color(
                                Mathf.Clamp01(
                                    (value.r - background.r * inverseAlpha) /
                                    alpha),
                                Mathf.Clamp01(
                                    (value.g - background.g * inverseAlpha) /
                                    alpha),
                                Mathf.Clamp01(
                                    (value.b - background.b * inverseAlpha) /
                                    alpha),
                                alpha);
                        }
                    }
                }

                output.SetPixels(outputPixels);
                output.Apply(false, false);
                File.WriteAllBytes(
                    Path.GetFullPath(ShotgunMuzzleFlashRuntimeTexturePath),
                    output.EncodeToPNG());
                AssetDatabase.ImportAsset(
                    ShotgunMuzzleFlashRuntimeTexturePath,
                    ImportAssetOptions.ForceSynchronousImport |
                    ImportAssetOptions.ForceUpdate);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(source);
                if (output != null)
                {
                    UnityEngine.Object.DestroyImmediate(output);
                }
            }
        }

        private static int DetectShotgunCheckerVerticalPeriod(
            IReadOnlyList<Color> pixels,
            int width,
            int height)
        {
            int bestPeriod = 128;
            double bestError = double.PositiveInfinity;
            int maximumPeriod = Mathf.Min(180, height / 4);
            for (int period = 96; period <= maximumPeriod; period++)
            {
                double error = 0d;
                int samples = 0;
                int comparisonRows = Mathf.Min(72, height - period);
                for (int y = 8; y < comparisonRows; y += 4)
                {
                    for (int x = 8; x < width - 8; x += 8)
                    {
                        Color first = pixels[y * width + x];
                        Color second = pixels[(y + period) * width + x];
                        error += Mathf.Abs(first.r - second.r) +
                                 Mathf.Abs(first.g - second.g) +
                                 Mathf.Abs(first.b - second.b);
                        samples++;
                    }
                }

                if (samples > 0 && error / samples < bestError)
                {
                    bestError = error / samples;
                    bestPeriod = period;
                }
            }

            return bestPeriod;
        }

        private static void ReadPngDimensions(
            string assetPath,
            out int width,
            out int height)
        {
            byte[] bytes = File.ReadAllBytes(Path.GetFullPath(assetPath));
            if (bytes.Length < 24 ||
                bytes[0] != 137 || bytes[1] != 80 ||
                bytes[2] != 78 || bytes[3] != 71)
            {
                throw new InvalidOperationException(
                    assetPath + " is not a readable PNG.");
            }

            width = (bytes[16] << 24) | (bytes[17] << 16) |
                    (bytes[18] << 8) | bytes[19];
            height = (bytes[20] << 24) | (bytes[21] << 16) |
                     (bytes[22] << 8) | bytes[23];
        }

        private static Mesh CreateOrUpdateShotgunMuzzleFlashMesh(
            float length,
            float height)
        {
            Mesh generated = new Mesh
            {
                name = "ShotgunMuzzleFlashCrossVolume"
            };
            List<Vector3> vertices = new List<Vector3>();
            List<Vector2> uvs = new List<Vector2>();
            List<int> triangles = new List<int>();
            const int planeCount = 4;
            float halfHeight = height * 0.5f;
            for (int plane = 0; plane < planeCount; plane++)
            {
                float angle = plane * Mathf.PI / planeCount;
                Vector3 radial = new Vector3(
                    0f,
                    Mathf.Cos(angle),
                    Mathf.Sin(angle)) * halfHeight;
                int first = vertices.Count;
                vertices.Add(-radial);
                vertices.Add(radial);
                vertices.Add(Vector3.right * length + radial);
                vertices.Add(Vector3.right * length - radial);
                uvs.Add(new Vector2(0f, 0f));
                uvs.Add(new Vector2(0f, 1f));
                uvs.Add(new Vector2(1f, 1f));
                uvs.Add(new Vector2(1f, 0f));
                triangles.Add(first);
                triangles.Add(first + 1);
                triangles.Add(first + 2);
                triangles.Add(first);
                triangles.Add(first + 2);
                triangles.Add(first + 3);
            }

            generated.SetVertices(vertices);
            generated.SetUVs(0, uvs);
            generated.SetTriangles(triangles, 0);
            generated.RecalculateNormals();
            generated.RecalculateTangents();
            generated.RecalculateBounds();
            return CreateOrUpdateMusketMuzzleMesh(
                ShotgunMuzzleFlashMeshPath,
                generated);
        }

        private static Material CreateOrUpdateShotgunMuzzleFlashMaterial(
            Texture2D texture)
        {
            Shader shader =
                Shader.Find("Bellerophon/VFX/ShotgunMuzzleFlashUnlit") ??
                Shader.Find("Universal Render Pipeline/Unlit") ??
                Shader.Find("Unlit/Transparent") ??
                Shader.Find("Unlit/Texture");
            if (shader == null)
            {
                throw new InvalidOperationException(
                    "No non-particle Unlit shader is available for the approved Shotgun burst texture.");
            }

            Material material = AssetDatabase.LoadAssetAtPath<Material>(
                ShotgunMuzzleFlashMaterialPath);
            if (material == null)
            {
                material = new Material(shader);
                AssetDatabase.CreateAsset(
                    material,
                    ShotgunMuzzleFlashMaterialPath);
            }
            else
            {
                material.shader = shader;
            }

            if (material.HasProperty("_BaseMap"))
            {
                material.SetTexture("_BaseMap", texture);
            }

            if (material.HasProperty("_MainTex"))
            {
                material.SetTexture("_MainTex", texture);
            }

            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", Color.white);
            }

            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", Color.white);
            }

            if (material.HasProperty("_Surface"))
            {
                material.SetFloat("_Surface", 1f);
            }

            if (material.HasProperty("_Blend"))
            {
                material.SetFloat("_Blend", 0f);
            }

            if (material.HasProperty("_SrcBlend"))
            {
                material.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
            }

            if (material.HasProperty("_DstBlend"))
            {
                material.SetFloat(
                    "_DstBlend",
                    (float)BlendMode.OneMinusSrcAlpha);
            }

            if (material.HasProperty("_ZWrite"))
            {
                material.SetFloat("_ZWrite", 0f);
            }

            if (material.HasProperty("_Cull"))
            {
                material.SetFloat("_Cull", (float)CullMode.Off);
            }

            material.SetOverrideTag("RenderType", "Transparent");
            material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            material.DisableKeyword("_FADING_ON");
            material.DisableKeyword("_SOFTPARTICLES_ON");
            material.DisableKeyword("_ALPHAPREMULTIPLY_ON");
            material.SetShaderPassEnabled("ShadowCaster", false);
            material.SetShaderPassEnabled("DepthOnly", false);
            material.renderQueue = (int)RenderQueue.Transparent;
            material.enableInstancing = true;
            EditorUtility.SetDirty(material);
            return material;
        }

        private static GameObject CreateOrUpdateShotgunMuzzleFlashPrefab(
            Mesh mesh,
            Material material)
        {
            Mesh particleMesh = AssetDatabase.LoadAssetAtPath<Mesh>(
                MusketMuzzleFlashMeshPath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference particle mesh is missing.",
                    Path.GetFullPath(MusketMuzzleFlashMeshPath));
            Mesh smokeMesh = AssetDatabase.LoadAssetAtPath<Mesh>(
                MusketMuzzleSmokeMeshPath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference smoke mesh is missing.",
                    Path.GetFullPath(MusketMuzzleSmokeMeshPath));
            Texture2D flameMask = AssetDatabase.LoadAssetAtPath<Texture2D>(
                MusketMuzzleFlameTexturePath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference flame mask is missing.",
                    Path.GetFullPath(MusketMuzzleFlameTexturePath));
            Texture2D smokeMask = AssetDatabase.LoadAssetAtPath<Texture2D>(
                MusketMuzzleSmokeTexturePath) ??
                throw new FileNotFoundException(
                    "Musket quality-reference smoke mask is missing.",
                    Path.GetFullPath(MusketMuzzleSmokeTexturePath));
            Material bloomMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleBloomMaterialPath,
                false,
                flameMask,
                new Color(1.8f, 1.8f, 1.8f, 1f));
            Material hotGasMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleHotGasMaterialPath,
                true,
                flameMask,
                new Color(3.8f, 1.15f, 0.12f, 1f),
                new Color(8.5f, 2.4f, 0.12f, 1f));
            Material smokeMaterial = CreateOrUpdateMusketMuzzleMaterial(
                ShotgunMuzzleSmokeMaterialPath,
                false,
                smokeMask,
                new Color(0.82f, 0.76f, 0.70f, 1f));
            return CreateOrUpdateShotgunMuzzleFlashPrefab(
                particleMesh,
                smokeMesh,
                bloomMaterial,
                hotGasMaterial,
                smokeMaterial);
        }

        private static GameObject CreateOrUpdateShotgunMuzzleFlashPrefab(
            Mesh particleMesh,
            Mesh smokeMesh,
            Material bloomMaterial,
            Material hotGasMaterial,
            Material smokeMaterial)
        {
            GameObject root = new GameObject(ShotgunMuzzleFlashRootName);
            try
            {
                ParticleSystem flashCore =
                    CreateShotgunMuzzleFlashBloomSystem(
                        root.transform,
                        bloomMaterial);
                ParticleSystem hotGas = CreateShotgunMuzzleHotGasSystem(
                    root.transform,
                    smokeMesh,
                    hotGasMaterial);
                ParticleSystem smoke = CreateShotgunMuzzleSmokeSystem(
                    root.transform,
                    smokeMesh,
                    smokeMaterial);
                ParticleSystem embers = CreateShotgunMuzzleEmberSystem(
                    root.transform,
                    particleMesh,
                    hotGasMaterial);
                GameObject lightObject = new GameObject("MuzzleLight");
                lightObject.transform.SetParent(root.transform, false);
                lightObject.transform.localPosition =
                    Vector3.right * 0.07f;
                Light muzzleLight = lightObject.AddComponent<Light>();
                muzzleLight.type = LightType.Point;
                muzzleLight.color = new Color(1f, 0.53f, 0.18f, 1f);
                muzzleLight.range = 1.8f;
                muzzleLight.intensity = 0f;
                muzzleLight.shadows = LightShadows.None;
                muzzleLight.renderMode = LightRenderMode.Auto;
                muzzleLight.enabled = false;

                Type runtimeType = RequireMusketMuzzleFlashRuntimeType(
                    ShotgunMuzzleFlashRuntimeTypeName);
                MonoBehaviour controller = root.AddComponent(runtimeType)
                    as MonoBehaviour ?? throw new InvalidOperationException(
                    "Shotgun muzzle flash controller could not be added.");
                InvokeMusketMuzzleFlashMethod(
                    controller,
                    "ConfigureVolume",
                    flashCore.GetComponent<ParticleSystemRenderer>(),
                    ShotgunMuzzleFlashHotDurationSeconds,
                    ShotgunMuzzleFlashTotalDurationSeconds,
                    ShotgunMuzzleFlashExpansionDurationSeconds,
                    new Vector3(0.65f, 0.55f, 0.55f));
                InvokeMusketMuzzleFlashMethod(
                    controller,
                    "ConfigureLayers",
                    null,
                    hotGas,
                    smoke,
                    embers,
                    muzzleLight,
                    ShotgunMuzzleFlashLightDurationSeconds,
                    ShotgunMuzzleFlashLightPeakIntensity);
                return PrefabUtility.SaveAsPrefabAsset(
                    root,
                    ShotgunMuzzleFlashPrefabPath);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(root);
            }
        }

