        private static ParticleSystem CreateShotgunMuzzleParticleSystem(
            Transform parent,
            string name,
            Mesh mesh,
            Material material,
            bool billboard,
            uint randomSeed)
        {
            GameObject item = new GameObject(name);
            item.transform.SetParent(parent, false);
            item.transform.localRotation = Quaternion.Euler(0f, 90f, 0f);
            ParticleSystem system = item.AddComponent<ParticleSystem>();
            system.useAutoRandomSeed = false;
            system.randomSeed = randomSeed;
            ParticleSystem.MainModule main = system.main;
            main.loop = false;
            main.playOnAwake = false;
            main.simulationSpace = ParticleSystemSimulationSpace.Local;
            main.scalingMode = ParticleSystemScalingMode.Local;
            ParticleSystem.EmissionModule emission = system.emission;
            emission.enabled = true;
            emission.rateOverTime = 0f;
            ParticleSystem.NoiseModule noise = system.noise;
            noise.enabled = false;
            ParticleSystemRenderer renderer =
                item.GetComponent<ParticleSystemRenderer>();
            renderer.renderMode = billboard
                ? ParticleSystemRenderMode.Billboard
                : ParticleSystemRenderMode.Mesh;
            renderer.alignment = billboard
                ? ParticleSystemRenderSpace.View
                : ParticleSystemRenderSpace.Local;
            renderer.mesh = billboard ? null : mesh;
            renderer.sharedMaterial = material;
            renderer.sortMode = billboard
                ? ParticleSystemSortMode.Distance
                : ParticleSystemSortMode.None;
            renderer.normalDirection = billboard ? 0.55f : 1f;
            renderer.cameraVelocityScale = 0f;
            renderer.velocityScale = 0f;
            renderer.lengthScale = 1f;
            renderer.minParticleSize = 0f;
            renderer.maxParticleSize = 0.55f;
            renderer.sortingOrder = string.Equals(
                    name,
                    "PowderEmbers",
                    StringComparison.Ordinal)
                ? 5
                : string.Equals(
                    name,
                    "FlashCore",
                    StringComparison.Ordinal)
                    ? 3
                    : string.Equals(
                        name,
                        "HotGasVolume",
                        StringComparison.Ordinal)
                        ? 2
                        : 1;
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            renderer.motionVectorGenerationMode =
                MotionVectorGenerationMode.ForceNoMotion;
            renderer.lightProbeUsage = LightProbeUsage.Off;
            renderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
            renderer.allowOcclusionWhenDynamic = false;
            return system;
        }

        private static void ConfigureShotgunMuzzleCone(
            ParticleSystem system,
            float angle,
            float radius,
            float length)
        {
            ParticleSystem.ShapeModule shape = system.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Cone;
            shape.angle = angle;
            shape.radius = radius;
            shape.length = length;
        }

        private static AnimationClip CreateOrUpdateUniformlyRetimedClip(
            AnimationClip source,
            string path,
            float durationSeconds,
            out float maximumNormalizedValueError,
            out int totalFloatKeys)
        {
            if (source.length <= 0f)
            {
                throw new InvalidOperationException(
                    source.name + " has no usable duration.");
            }

            float scale = durationSeconds / source.length;
            AnimationClip generated = new AnimationClip();
            EditorUtility.CopySerialized(source, generated);
            generated.name = Path.GetFileNameWithoutExtension(path);
            generated.frameRate = source.frameRate;
            totalFloatKeys = 0;
            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetCurveBindings(source))
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(
                    source,
                    binding);
                Keyframe[] keys = curve.keys;
                totalFloatKeys += keys.Length;
                for (int index = 0; index < keys.Length; index++)
                {
                    Keyframe key = keys[index];
                    key.time *= scale;
                    if (!float.IsInfinity(key.inTangent))
                    {
                        key.inTangent /= scale;
                    }

                    if (!float.IsInfinity(key.outTangent))
                    {
                        key.outTangent /= scale;
                    }

                    keys[index] = key;
                }

                AnimationCurve retimed = new AnimationCurve(keys)
                {
                    preWrapMode = curve.preWrapMode,
                    postWrapMode = curve.postWrapMode
                };
                AnimationUtility.SetEditorCurve(generated, binding, retimed);
            }

            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetObjectReferenceCurveBindings(source))
            {
                ObjectReferenceKeyframe[] keys =
                    AnimationUtility.GetObjectReferenceCurve(source, binding);
                for (int index = 0; index < keys.Length; index++)
                {
                    keys[index].time *= scale;
                }

                AnimationUtility.SetObjectReferenceCurve(
                    generated,
                    binding,
                    keys);
            }

            AnimationEvent[] events = AnimationUtility.GetAnimationEvents(source);
            foreach (AnimationEvent animationEvent in events)
            {
                animationEvent.time *= scale;
            }

            AnimationUtility.SetAnimationEvents(generated, events);
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(source);
            settings.loopTime = true;
            settings.startTime = 0f;
            settings.stopTime = durationSeconds;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                path);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, path);
                existing = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, existing);
                UnityEngine.Object.DestroyImmediate(generated);
                EditorUtility.SetDirty(existing);
            }

            AssetDatabase.SaveAssets();
            maximumNormalizedValueError =
                CalculateMaximumNormalizedCurveValueError(source, existing);
            return existing;
        }

        private static float CalculateMaximumNormalizedCurveValueError(
            AnimationClip source,
            AnimationClip derived)
        {
            float maximum = 0f;
            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetCurveBindings(source))
            {
                AnimationCurve sourceCurve =
                    AnimationUtility.GetEditorCurve(source, binding);
                AnimationCurve derivedCurve =
                    AnimationUtility.GetEditorCurve(derived, binding);
                if (derivedCurve == null)
                {
                    return float.PositiveInfinity;
                }

                for (int sample = 0; sample <= 30; sample++)
                {
                    float phase = sample / 30f;
                    maximum = Mathf.Max(
                        maximum,
                        Mathf.Abs(
                            sourceCurve.Evaluate(source.length * phase) -
                            derivedCurve.Evaluate(derived.length * phase)));
                }
            }

            return maximum;
        }

        private static void ConfigureShotgunMuzzleFlashStateBehaviour(
            AnimatorState state)
        {
            Type behaviourType = RequireMusketMuzzleFlashRuntimeType(
                ShotgunMuzzleFlashBehaviourTypeName);
            StateMachineBehaviour[] behaviours = state.behaviours
                .Where(value =>
                    value != null && behaviourType.IsInstanceOfType(value))
                .ToArray();
            StateMachineBehaviour behaviour = behaviours.FirstOrDefault();
            if (behaviour == null)
            {
                behaviour = state.AddStateMachineBehaviour(behaviourType);
            }

            foreach (StateMachineBehaviour duplicate in behaviours.Skip(1))
            {
                UnityEngine.Object.DestroyImmediate(duplicate, true);
            }

            InvokeMusketMuzzleFlashMethod(
                behaviour,
                "Configure",
                ShotgunMuzzleFlashTriggerNormalizedTime);
            EditorUtility.SetDirty(behaviour);
        }

        [MenuItem("Bellerophon/Player/Capture Shotgun Fire Muzzle Flash Performance Review")]
        internal static void CaptureShotgunFireMuzzleFlashPerformanceReview()
        {
            int stage = SessionState.GetInt(
                ShotgunMuzzleFlashCaptureStageKey,
                0);
            try
            {
                if (stage == 0)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode)
                    {
                        throw new InvalidOperationException(
                            "Shotgun muzzle flash review must start in Edit Mode.");
                    }

                    Scene scene = RequireScene();
                    if (scene.isDirty)
                    {
                        throw new InvalidOperationException(
                            "CargoRunMvp must be clean before Shotgun muzzle flash review.");
                    }

                    ShotgunMuzzleFlashApplicationMetrics apply =
                        ReadJson<ShotgunMuzzleFlashApplicationMetrics>(
                            ShotgunMuzzleFlashApplicationMetricsPath);
                    if (apply.actualPlayModeObserved &&
                        apply.finalReviewExists &&
                        apply.performanceConditions != null &&
                        apply.performanceConditions.Length == 2)
                    {
                        EvaluateShotgunMuzzleFlashRuntimeMetrics(apply);
                        WriteJson(
                            ShotgunMuzzleFlashApplicationMetricsPath,
                            apply);
                        if (apply.passedNumericChecks)
                        {
                            SessionState.EraseInt(
                                ShotgunMuzzleFlashCaptureStageKey);
                            Debug.Log(
                                "[PlayerShotgunMuzzleFlash] Existing one-time direct capture and actual Play Mode samples passed the corrected memory/per-frame evaluation without recapture.");
                            return;
                        }
                    }

                    if (!apply.passedNumericChecks)
                    {
                        throw new InvalidOperationException(
                            "Shotgun muzzle flash apply support checks did not pass.");
                    }

                    SessionState.SetInt(
                        ShotgunMuzzleFlashCaptureStageKey,
                        1);
                    EditorApplication.EnterPlaymode();
                    Debug.Log(
                        "[PlayerShotgunMuzzleFlash] Entering Play Mode for natural-loop direct review and inactive/active performance comparison.");
                    return;
                }

                if (stage == 1)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun muzzle flash review is waiting for Play Mode.");
                    }

                    ShotgunMuzzleFlashRuntimeReview.Start();
                    SessionState.SetInt(
                        ShotgunMuzzleFlashCaptureStageKey,
                        2);
                    Debug.Log(
                        "[PlayerShotgunMuzzleFlash] Natural playback review and performance sampling started.");
                    return;
                }

                if (stage == 2)
                {
                    if (ShotgunMuzzleFlashRuntimeReview.Failure != null)
                    {
                        throw new InvalidOperationException(
                            "Shotgun muzzle flash runtime review failed.",
                            ShotgunMuzzleFlashRuntimeReview.Failure);
                    }

                    if (!ShotgunMuzzleFlashRuntimeReview.IsComplete)
                    {
                        Debug.Log(
                            "[PlayerShotgunMuzzleFlash] Review is still running: " +
                            ShotgunMuzzleFlashRuntimeReview.Status);
                        return;
                    }

                    SessionState.SetInt(
                        ShotgunMuzzleFlashCaptureStageKey,
                        3);
                    EditorApplication.ExitPlaymode();
                    Debug.Log(
                        "[PlayerShotgunMuzzleFlash] Runtime review completed; exiting Play Mode.");
                    return;
                }

                if (EditorApplication.isPlayingOrWillChangePlaymode)
                {
                    if (EditorApplication.isPlaying)
                    {
                        EditorApplication.ExitPlaymode();
                    }

                    return;
                }

                ShotgunMuzzleFlashApplicationMetrics metrics =
                    ReadJson<ShotgunMuzzleFlashApplicationMetrics>(
                        ShotgunMuzzleFlashApplicationMetricsPath);
                if (!metrics.actualPlayModeObserved ||
                    !metrics.performanceSafe ||
                    !metrics.finalReviewExists ||
                    metrics.naturalLoopsObserved < 2 ||
                    metrics.naturalEmissionsObserved < 2)
                {
                    throw new InvalidOperationException(
                        "Shotgun muzzle flash final runtime checks did not pass. " +
                        JsonUtility.ToJson(metrics));
                }

                SessionState.EraseInt(ShotgunMuzzleFlashCaptureStageKey);
                Debug.Log(
                    "[PlayerShotgunMuzzleFlash] One final direct-review sheet and performance metrics are ready: " +
                    Path.GetFullPath(ShotgunMuzzleFlashFinalReviewPath));
            }
            catch
            {
                SessionState.EraseInt(ShotgunMuzzleFlashCaptureStageKey);
                ShotgunMuzzleFlashRuntimeReview.Stop();
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                throw;
            }
        }

        internal static void CaptureShotgunFireVolumetricMuzzleFlashReview()
        {
            CaptureShotgunFireMuzzleFlashPerformanceReview();
        }

        internal static class ShotgunMuzzleFlashRuntimeReview
        {
            private sealed class ConditionSamples
            {
                internal readonly string Name;
                internal readonly List<float> FrameTimes = new List<float>();
                internal readonly List<float> MainThreadTimes = new List<float>();
                internal readonly List<long> GcAllocatedBytes = new List<long>();
                internal readonly List<float> Batches = new List<float>();
                internal readonly List<float> Triangles = new List<float>();

                internal ConditionSamples(string name)
                {
                    Name = name;
                }
            }

            private static readonly float[] ReviewAgesSeconds =
            {
                0.02f,
                0.055f,
                0.10f,
                0.18f,
                0.34f,
                0.55f
            };

            private static Transform target;
            private static Animator animator;
            private static MonoBehaviour effect;
            private static GameObject effectObject;
            private static bool originalEffectActive;
            private static ConditionSamples[] conditions;
            private static List<byte[]> closeFrontFrames;
            private static List<byte[]> closeSideFrames;
            private static List<byte[]> closeObliqueFrames;
            private static List<byte[]> fullFrontFrames;
            private static List<byte[]> musketQualityFrames;
            private static ProfilerRecorder mainThreadRecorder;
            private static ProfilerRecorder gcAllocatedRecorder;
            private static int conditionIndex;
            private static int warmupFrames;
            private static int sampleFrames;
            private static int lastFrameCount;
            private static int nextCaptureIndex;
            private static int activePlayCountStart;
            private static int lastCapturedPlayCount;
            private static int activeStartLoop;
            private static int maximumObservedLoop;
            private static bool running;

            internal static bool IsComplete { get; private set; }
            internal static Exception Failure { get; private set; }
            internal static string Status { get; private set; }

            internal static void Start()
            {
                Stop();
                IsComplete = false;
                Failure = null;
                Status = "initializing";
                Scene scene = SceneManager.GetActiveScene();
                Transform layout = RequireLayout(scene);
                target = RequireTarget(layout, ShotgunFireTargetName);
                animator = RequireAnimator(target);
                Type runtimeType = RequireMusketMuzzleFlashRuntimeType(
                    ShotgunMuzzleFlashRuntimeTypeName);
                effect = target.GetComponentsInChildren(runtimeType, true)
                    .OfType<MonoBehaviour>()
                    .SingleOrDefault() ?? throw new InvalidOperationException(
                    "Shotgun_Fire must contain exactly one muzzle flash controller.");
                effectObject = effect.gameObject;
                originalEffectActive = effectObject.activeSelf;
                conditions = new[]
                {
                    new ConditionSamples("VfxInactive"),
                    new ConditionSamples("VfxActive")
                };
                closeFrontFrames = new List<byte[]>();
                closeSideFrames = new List<byte[]>();
                closeObliqueFrames = new List<byte[]>();
                fullFrontFrames = new List<byte[]>();
                musketQualityFrames = new List<byte[]>();
                mainThreadRecorder = StartRecorder(
                    ProfilerCategory.Internal,
                    "Main Thread");
                gcAllocatedRecorder = StartRecorder(
                    ProfilerCategory.Memory,
                    "GC Allocated In Frame");
                conditionIndex = 0;
                warmupFrames = 0;
                sampleFrames = 0;
                nextCaptureIndex = 0;
                maximumObservedLoop = 0;
                effectObject.SetActive(false);
                lastFrameCount = Time.frameCount;
                running = true;
                EditorApplication.update += Update;
                Status = "VfxInactive warmup";
            }

            internal static void Stop()
            {
                EditorApplication.update -= Update;
                if (effectObject != null)
                {
                    effectObject.SetActive(originalEffectActive);
                }

                DisposeRecorders();
                running = false;
            }

            private static void Update()
            {
                if (!running || !EditorApplication.isPlaying)
                {
                    return;
                }

                try
                {
                    if (Time.frameCount == lastFrameCount)
                    {
                        return;
                    }

                    lastFrameCount = Time.frameCount;
                    if (conditionIndex == 1 && TryCaptureNaturalPhase())
                    {
                        return;
                    }

                    if (warmupFrames < ShotgunMuzzleFlashWarmupFrames)
                    {
                        warmupFrames++;
                        Status = conditions[conditionIndex].Name +
                            " warmup " + warmupFrames + "/" +
                            ShotgunMuzzleFlashWarmupFrames;
                        return;
                    }

                    if (sampleFrames < ShotgunMuzzleFlashSampleFrames)
                    {
                        ConditionSamples current = conditions[conditionIndex];
                        current.FrameTimes.Add(Time.unscaledDeltaTime * 1000f);
                        if (mainThreadRecorder.Valid)
                        {
                            current.MainThreadTimes.Add(
                                mainThreadRecorder.LastValue / 1000000f);
                        }

                        if (gcAllocatedRecorder.Valid)
                        {
                            current.GcAllocatedBytes.Add(
                                Math.Max(0L, gcAllocatedRecorder.LastValue));
                        }

                        current.Batches.Add(UnityStats.batches);
                        current.Triangles.Add(UnityStats.triangles);
                        sampleFrames++;
                    }

                    Status = conditions[conditionIndex].Name + " sample " +
                        sampleFrames + "/" +
                        ShotgunMuzzleFlashSampleFrames;
                    if (sampleFrames < ShotgunMuzzleFlashSampleFrames ||
                        conditionIndex == 1 &&
                        nextCaptureIndex < ReviewAgesSeconds.Length)
                    {
                        return;
                    }

                    if (conditionIndex == 0)
                    {
                        BeginActiveCondition();
                        return;
                    }

                    CompleteReview();
                }
                catch (Exception exception)
                {
                    Failure = exception;
                    Status = "failed: " + exception.Message;
                    Stop();
                }
            }

            private static void BeginActiveCondition()
            {
                conditionIndex = 1;
                warmupFrames = 0;
                sampleFrames = 0;
                effectObject.SetActive(true);
                AnimatorStateInfo stateInfo = animator.GetCurrentAnimatorStateInfo(0);
                activeStartLoop = Mathf.FloorToInt(stateInfo.normalizedTime) + 1;
                maximumObservedLoop = activeStartLoop;
                activePlayCountStart = ReadMusketMuzzleFlashProperty<int>(
                    effect,
                    "PlayCount");
                lastCapturedPlayCount = activePlayCountStart;
                Status = "VfxActive waiting for next natural loop";
            }

            private static bool TryCaptureNaturalPhase()
            {
                AnimatorStateInfo stateInfo = animator.GetCurrentAnimatorStateInfo(0);
                float normalized = stateInfo.normalizedTime;
                maximumObservedLoop = Mathf.Max(
                    maximumObservedLoop,
                    Mathf.FloorToInt(normalized));
                int playCount = ReadMusketMuzzleFlashProperty<int>(
                    effect,
                    "PlayCount");
                float effectAge = ReadMusketMuzzleFlashProperty<float>(
                    effect,
                    "EffectAgeSeconds");
                if (nextCaptureIndex >= ReviewAgesSeconds.Length ||
                    playCount <= lastCapturedPlayCount ||
                    effectAge < ReviewAgesSeconds[nextCaptureIndex])
                {
                    return false;
                }

                CaptureCurrentFrameViews();
                lastCapturedPlayCount = playCount;
                nextCaptureIndex++;
                Status = "VfxActive direct capture " + nextCaptureIndex + "/" +
                    ReviewAgesSeconds.Length;
                return true;
            }

            private static void CaptureCurrentFrameViews()
            {
                Transform muzzle = effectObject.transform;
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    environment.ConfigureView(
                        target,
                        muzzle.position,
                        ShotgunMuzzleFlashReviewOrthoSize);
                    closeFrontFrames.Add(environment.CaptureFront());
                    closeSideFrames.Add(environment.CaptureSide());
                    closeObliqueFrames.Add(environment.CaptureOblique(
                        target,
                        muzzle.position,
                        (target.forward + target.right).normalized,
                        ShotgunMuzzleFlashReviewOrthoSize));
                    environment.ConfigureView(target, 1.05f, 1.35f);
                    fullFrontFrames.Add(environment.CaptureFront());
                }
            }

            private static void CompleteReview()
            {
                int emissions = ReadMusketMuzzleFlashProperty<int>(
                    effect,
                    "PlayCount") - activePlayCountStart;
                int loops = Mathf.Max(
                    0,
                    maximumObservedLoop - activeStartLoop + 1);
                Stop();
                CaptureMusketQualityReferenceFrames();
                List<byte[]> referenceFrames = Enumerable
                    .Range(0, ReviewAgesSeconds.Length)
                    .Select(_ => CreateShotgunMuzzleFlashSamplePanel())
                    .ToList();
                ComposeRows(
                    new[]
                    {
                        referenceFrames,
                        musketQualityFrames,
                        closeFrontFrames,
                        closeSideFrames,
                        closeObliqueFrames,
                        fullFrontFrames
                    },
                    ShotgunMuzzleFlashFinalReviewPath);
                AssetDatabase.ImportAsset(
                    ShotgunMuzzleFlashFinalReviewPath,
                    ImportAssetOptions.ForceUpdate);

                ShotgunMuzzleFlashApplicationMetrics metrics =
                    ReadJson<ShotgunMuzzleFlashApplicationMetrics>(
                        ShotgunMuzzleFlashApplicationMetricsPath);
                metrics.performanceConditions = conditions
                    .Select(ToMetrics)
                    .ToArray();
                metrics.actualPlayModeObserved = true;
                metrics.naturalLoopsObserved = loops;
                metrics.naturalEmissionsObserved = emissions;
                metrics.finalReviewExists = File.Exists(
                    Path.GetFullPath(ShotgunMuzzleFlashFinalReviewPath));
                EvaluateShotgunMuzzleFlashRuntimeMetrics(metrics);
                WriteJson(ShotgunMuzzleFlashApplicationMetricsPath, metrics);
                if (!metrics.passedNumericChecks)
                {
                    throw new InvalidOperationException(
                        "Shotgun muzzle flash runtime support checks failed. " +
                        JsonUtility.ToJson(metrics));
                }

                running = false;
                IsComplete = true;
                Status = "complete";
            }

            private static void CaptureMusketQualityReferenceFrames()
            {
                Scene scene = SceneManager.GetActiveScene();
                Transform layout = RequireLayout(scene);
                Transform musketTarget = RequireTarget(
                    layout,
                    MusketAimFireTargetName);
                Type musketRuntimeType = RequireMusketMuzzleFlashRuntimeType(
                    MusketMuzzleFlashRuntimeTypeName);
                MonoBehaviour musketEffect = musketTarget
                    .GetComponentsInChildren(musketRuntimeType, true)
                    .OfType<MonoBehaviour>()
                    .SingleOrDefault() ?? throw new InvalidOperationException(
                    "Musket_Aim_Fire must contain exactly one quality-reference muzzle flash controller.");
                GameObject musketEffectObject = musketEffect.gameObject;
                bool wasActive = musketEffectObject.activeSelf;
                ParticleSystem[] systems = musketEffectObject
                    .GetComponentsInChildren<ParticleSystem>(true);
                Light qualityLight = musketEffectObject
                    .GetComponentsInChildren<Light>(true)
                    .SingleOrDefault();
                float[] ages = { 0.02f, 0.055f, 0.10f, 0.18f, 0.34f, 0.55f };
                try
                {
                    musketEffectObject.SetActive(true);
                    using (CaptureEnvironment environment =
                           new CaptureEnvironment(musketTarget))
                    {
                        environment.ConfigureView(
                            musketTarget,
                            musketEffectObject.transform.position,
                            ShotgunMuzzleFlashReviewOrthoSize);
                        foreach (float age in ages)
                        {
                            InvokeMusketMuzzleFlashMethod(
                                musketEffect,
                                "PlayEffect");
                            foreach (ParticleSystem system in systems)
                            {
                                system.Simulate(age, true, true, false);
                            }

                            if (qualityLight != null)
                            {
                                qualityLight.enabled = age <= 0.055f;
                            }

                            musketQualityFrames.Add(
                                environment.CaptureSide());
                        }
                    }
                }
                finally
                {
                    foreach (ParticleSystem system in systems)
                    {
                        system.Stop(
                            true,
                            ParticleSystemStopBehavior.StopEmittingAndClear);
                    }

                    if (qualityLight != null)
                    {
                        qualityLight.enabled = false;
                    }

                    musketEffectObject.SetActive(wasActive);
                }
            }

            private static ShotgunMuzzleFlashConditionMetrics ToMetrics(
                ConditionSamples source)
            {
                return new ShotgunMuzzleFlashConditionMetrics
                {
                    condition = source.Name,
                    samples = source.FrameTimes.Count,
                    medianFrameTimeMs = Percentile(source.FrameTimes, 0.5f),
                    p95FrameTimeMs = Percentile(source.FrameTimes, 0.95f),
                    medianMainThreadTimeMs =
                        Percentile(source.MainThreadTimes, 0.5f),
                    p95MainThreadTimeMs =
                        Percentile(source.MainThreadTimes, 0.95f),
                    medianGcAllocatedBytes = (long)Percentile(
                        source.GcAllocatedBytes
                            .Select(value => (float)value)
                            .ToList(),
                        0.5f),
                    medianBatches = Percentile(source.Batches, 0.5f),
                    maximumBatches = source.Batches.Count > 0
                        ? source.Batches.Max()
                        : 0f,
                    medianTriangles = Percentile(source.Triangles, 0.5f),
                    maximumTriangles = source.Triangles.Count > 0
                        ? source.Triangles.Max()
                        : 0f
                };
            }

            private static float Percentile(
                IReadOnlyCollection<float> values,
                float percentile)
            {
                if (values == null || values.Count == 0)
                {
                    return 0f;
                }

                float[] ordered = values.OrderBy(value => value).ToArray();
                float position = Mathf.Clamp01(percentile) *
                    (ordered.Length - 1);
                int lower = Mathf.FloorToInt(position);
                int upper = Mathf.CeilToInt(position);
                return Mathf.Lerp(
                    ordered[lower],
                    ordered[upper],
                    position - lower);
            }

            private static ProfilerRecorder StartRecorder(
                ProfilerCategory category,
                string marker)
            {
                try
                {
                    return ProfilerRecorder.StartNew(category, marker, 32);
                }
                catch
                {
                    return default;
                }
            }

            private static void DisposeRecorders()
            {
                if (mainThreadRecorder.Valid)
                {
                    mainThreadRecorder.Dispose();
                }

                if (gcAllocatedRecorder.Valid)
                {
                    gcAllocatedRecorder.Dispose();
                }
            }

            private static byte[] CreateShotgunMuzzleFlashSamplePanel()
            {
                string sourcePath = Path.GetFullPath(
                    ShotgunMuzzleFlashApprovedSamplePath);
                Texture2D source = new Texture2D(
                    2,
                    2,
                    TextureFormat.RGBA32,
                    false);
                Texture2D panel = new Texture2D(
                    CaptureWidth,
                    CaptureHeight,
                    TextureFormat.RGB24,
                    false);
                try
                {
                    if (!source.LoadImage(File.ReadAllBytes(sourcePath)))
                    {
                        throw new InvalidOperationException(
                            "Approved Shotgun muzzle flash sample could not be decoded.");
                    }

                    Color background = new Color(0.055f, 0.065f, 0.08f, 1f);
                    Color[] pixels = Enumerable.Repeat(
                        background,
                        CaptureWidth * CaptureHeight).ToArray();
                    float scale = Mathf.Min(
                        CaptureWidth / (float)source.width,
                        CaptureHeight / (float)source.height);
                    int drawWidth = Mathf.Max(1, Mathf.RoundToInt(
                        source.width * scale));
                    int drawHeight = Mathf.Max(1, Mathf.RoundToInt(
                        source.height * scale));
                    int offsetX = (CaptureWidth - drawWidth) / 2;
                    int offsetY = (CaptureHeight - drawHeight) / 2;
                    for (int y = 0; y < drawHeight; y++)
                    {
                        for (int x = 0; x < drawWidth; x++)
                        {
                            Color sample = source.GetPixelBilinear(
                                (x + 0.5f) / drawWidth,
                                (y + 0.5f) / drawHeight);
                            int panelIndex = (offsetY + y) * CaptureWidth +
                                             offsetX + x;
                            pixels[panelIndex] = Color.Lerp(
                                background,
                                sample,
                                sample.a);
                        }
                    }

                    panel.SetPixels(pixels);
                    panel.Apply(false, false);
                    return panel.EncodeToPNG();
                }
                finally
                {
                    UnityEngine.Object.DestroyImmediate(source);
                    UnityEngine.Object.DestroyImmediate(panel);
                }
            }
        }

        private static void EvaluateShotgunMuzzleFlashRuntimeMetrics(
            ShotgunMuzzleFlashApplicationMetrics metrics)
        {
            if (metrics.performanceConditions == null ||
                metrics.performanceConditions.Length != 2)
            {
                metrics.performanceSafe = false;
                metrics.passedNumericChecks = false;
                return;
            }

            ShotgunMuzzleFlashConditionMetrics inactive =
                metrics.performanceConditions[0];
            ShotgunMuzzleFlashConditionMetrics active =
                metrics.performanceConditions[1];
            float medianMainThreadAllowance = Mathf.Max(
                2f,
                inactive.medianMainThreadTimeMs * 0.05f);
            float p95MainThreadAllowance = Mathf.Max(
                3f,
                inactive.p95MainThreadTimeMs * 0.05f);
            float triangleAllowance = Mathf.Max(
                10000f,
                inactive.medianTriangles * 0.001f);
            metrics.performanceSafe =
                metrics.importedTextureRuntimeBytes <= 8L * 1024L * 1024L &&
                active.medianMainThreadTimeMs <=
                    inactive.medianMainThreadTimeMs +
                    medianMainThreadAllowance &&
                active.p95MainThreadTimeMs <=
                    inactive.p95MainThreadTimeMs +
                    p95MainThreadAllowance &&
                active.medianGcAllocatedBytes <=
                    inactive.medianGcAllocatedBytes + 1024L &&
                active.medianBatches <= inactive.medianBatches + 64f &&
                active.medianTriangles <=
                    inactive.medianTriangles + triangleAllowance;
            bool staticChecks =
                ShotgunVolumetricMuzzleFlashStaticMetricsPass(metrics);
            metrics.passedNumericChecks =
                staticChecks &&
                metrics.actualPlayModeObserved &&
                metrics.naturalLoopsObserved >= 2 &&
                metrics.naturalEmissionsObserved >= 2 &&
                metrics.finalReviewExists &&
                metrics.performanceSafe &&
                metrics.performanceConditions.All(value =>
                    value.samples == ShotgunMuzzleFlashSampleFrames);
        }

        [MenuItem("Bellerophon/Player/Capture Shotgun Runtime Performance Play Mode")]
        internal static void CaptureShotgunRuntimePerformancePlayMode()
        {
            int stage = SessionState.GetInt(
                ShotgunPerformanceCaptureStageKey,
                0);
            try
            {
                if (stage == 0)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode)
                    {
                        throw new InvalidOperationException(
                            "Shotgun performance capture must start in Edit Mode.");
                    }

                    Scene scene = RequireScene();
                    if (scene.isDirty)
                    {
                        throw new InvalidOperationException(
                            "CargoRunMvp must be clean before Shotgun performance capture.");
                    }

                    SessionState.SetInt(ShotgunPerformanceCaptureStageKey, 1);
                    EditorApplication.EnterPlaymode();
                    Debug.Log(
                        "[PlayerShotgunPerformance] Entering Play Mode for isolated baseline, Animator, renderer, and additional-shadow measurements.");
                    return;
                }

                if (stage == 1)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun performance capture is waiting for Play Mode.");
                    }

                    ShotgunRuntimePerformanceCapture.Start();
                    SessionState.SetInt(ShotgunPerformanceCaptureStageKey, 2);
                    Debug.Log(
                        "[PlayerShotgunPerformance] Runtime sampling started; all temporary component changes will be restored before completion.");
                    return;
                }

                if (stage == 2)
                {
                    if (ShotgunRuntimePerformanceCapture.Failure != null)
                    {
                        throw new InvalidOperationException(
                            "Shotgun performance capture failed.",
                            ShotgunRuntimePerformanceCapture.Failure);
                    }

                    if (!ShotgunRuntimePerformanceCapture.IsComplete)
                    {
                        Debug.Log(
                            "[PlayerShotgunPerformance] Sampling is still running: " +
                            ShotgunRuntimePerformanceCapture.Status);
                        return;
                    }

                    SessionState.SetInt(ShotgunPerformanceCaptureStageKey, 3);
                    EditorApplication.ExitPlaymode();
                    Debug.Log(
                        "[PlayerShotgunPerformance] Sampling completed and temporary state restored; exiting Play Mode.");
                    return;
                }

                if (EditorApplication.isPlayingOrWillChangePlaymode)
                {
                    if (EditorApplication.isPlaying)
                    {
                        EditorApplication.ExitPlaymode();
                    }

                    return;
                }

                SessionState.EraseInt(ShotgunPerformanceCaptureStageKey);
                Debug.Log(
                    "[PlayerShotgunPerformance] Performance metrics are ready at " +
                    Path.GetFullPath(ShotgunRuntimePerformanceCapture.OutputPath));
            }
            catch
            {
                SessionState.EraseInt(ShotgunPerformanceCaptureStageKey);
                ShotgunRuntimePerformanceCapture.Stop();
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                throw;
            }
        }

        internal static class ShotgunRuntimePerformanceCapture
        {
            private sealed class ConditionSamples
            {
                internal readonly string Name;
                internal readonly List<float> FrameTimes = new List<float>();
                internal readonly List<float> MainThreadTimes = new List<float>();
                internal readonly List<float> RenderThreadTimes = new List<float>();
                internal readonly List<long> GcAllocatedBytes = new List<long>();
                internal readonly List<float> Batches = new List<float>();
                internal readonly List<float> Triangles = new List<float>();
                internal readonly List<float> Vertices = new List<float>();

                internal ConditionSamples(string name)
                {
                    Name = name;
                }
            }

            private static readonly string[] ConditionNames =
            {
                "Baseline",
                "ShotgunAnimatorsDisabled",
                "ShotgunRenderersDisabled",
                "AdditionalLightShadowsDisabled"
            };

            private static Animator[] shotgunAnimators;
            private static Renderer[] shotgunRenderers;
            private static Light[] additionalShadowLights;
            private static bool[] animatorEnabled;
            private static AnimatorCullingMode[] animatorCulling;
            private static bool[] rendererEnabled;
            private static LightShadows[] lightShadows;
            private static ConditionSamples[] samples;
            private static ProfilerRecorder mainThreadRecorder;
            private static ProfilerRecorder renderThreadRecorder;
            private static ProfilerRecorder gcAllocatedRecorder;
            private static int conditionIndex;
            private static int warmupFrames;
            private static int sampledFrames;
            private static int lastFrameCount;
            private static bool running;

            internal static bool IsComplete { get; private set; }
            internal static Exception Failure { get; private set; }
            internal static string Status { get; private set; }
            internal static string OutputPath { get; private set; } =
                ShotgunPerformanceMetricsPath;

            internal static void Start()
            {
                Stop();
                IsComplete = false;
                Failure = null;
                Status = "initializing";
                Scene scene = SceneManager.GetActiveScene();
                Transform layout = RequireLayout(scene);
                HashSet<Transform> shotgunTargets = GetShotgunAnimationSpecs()
                    .Select(spec => RequireTarget(layout, spec.TargetName))
                    .ToHashSet();
                shotgunAnimators = shotgunTargets
                    .Select(target => RequireAnimator(target))
                    .ToArray();
                shotgunRenderers = shotgunTargets
                    .SelectMany(target => target.GetComponentsInChildren<Renderer>(true))
                    .Distinct()
                    .ToArray();
                additionalShadowLights = UnityEngine.Object
                    .FindObjectsByType<Light>(FindObjectsInactive.Include, FindObjectsSortMode.None)
                    .Where(light =>
                        light.type != LightType.Directional &&
                        light.enabled &&
                        light.gameObject.activeInHierarchy &&
                        light.shadows != LightShadows.None)
                    .ToArray();
                OutputPath = additionalShadowLights.Length == 0
                    ? ShotgunPerformancePostFixMetricsPath
                    : ShotgunPerformanceMetricsPath;
                animatorEnabled = shotgunAnimators.Select(value => value.enabled).ToArray();
                animatorCulling = shotgunAnimators.Select(value => value.cullingMode).ToArray();
                rendererEnabled = shotgunRenderers.Select(value => value.enabled).ToArray();
                lightShadows = additionalShadowLights.Select(value => value.shadows).ToArray();
                samples = ConditionNames.Select(name => new ConditionSamples(name)).ToArray();
                mainThreadRecorder = StartShotgunRecorder(
                    ProfilerCategory.Internal,
                    "Main Thread");
                renderThreadRecorder = StartShotgunRecorder(
                    ProfilerCategory.Internal,
                    "Render Thread");
                gcAllocatedRecorder = StartShotgunRecorder(
                    ProfilerCategory.Memory,
                    "GC Allocated In Frame");
                conditionIndex = 0;
                warmupFrames = 0;
                sampledFrames = 0;
                lastFrameCount = Time.frameCount;
                ApplyPerformanceCondition(conditionIndex);
                running = true;
                EditorApplication.update += Update;
                Status = ConditionNames[conditionIndex] + " warmup";
            }

            internal static void Stop()
            {
                EditorApplication.update -= Update;
                if (running)
                {
                    RestoreTemporaryState();
                }

                DisposeRecorders();
                running = false;
            }

            private static void Update()
            {
                if (!running || !EditorApplication.isPlaying)
                {
                    return;
                }

                try
                {
                    if (Time.frameCount == lastFrameCount)
                    {
                        return;
                    }

                    lastFrameCount = Time.frameCount;
                    if (warmupFrames < ShotgunPerformanceWarmupFrames)
                    {
                        warmupFrames++;
                        Status = ConditionNames[conditionIndex] +
                            " warmup " + warmupFrames + "/" +
                            ShotgunPerformanceWarmupFrames;
                        return;
                    }

                    ConditionSamples current = samples[conditionIndex];
                    current.FrameTimes.Add(Time.unscaledDeltaTime * 1000f);
                    AddShotgunRecorderTime(mainThreadRecorder, current.MainThreadTimes);
                    AddShotgunRecorderTime(renderThreadRecorder, current.RenderThreadTimes);
                    if (gcAllocatedRecorder.Valid)
                    {
                        current.GcAllocatedBytes.Add(
                            Math.Max(0L, gcAllocatedRecorder.LastValue));
                    }

                    current.Batches.Add(UnityStats.batches);
                    current.Triangles.Add(UnityStats.triangles);
                    current.Vertices.Add(UnityStats.vertices);
                    sampledFrames++;
                    Status = ConditionNames[conditionIndex] +
                        " sample " + sampledFrames + "/" +
                        ShotgunPerformanceSampleFrames;
                    if (sampledFrames < ShotgunPerformanceSampleFrames)
                    {
                        return;
                    }

                    conditionIndex++;
                    if (conditionIndex < ConditionNames.Length)
                    {
                        warmupFrames = 0;
                        sampledFrames = 0;
                        ApplyPerformanceCondition(conditionIndex);
                        Status = ConditionNames[conditionIndex] + " warmup";
                        return;
                    }

                    RestoreTemporaryState();
                    DisposeRecorders();
                    WritePerformanceMetrics();
                    EditorApplication.update -= Update;
                    running = false;
                    IsComplete = true;
                    Status = "complete";
                }
                catch (Exception exception)
                {
                    Failure = exception;
                    Status = "failed: " + exception.Message;
                    Stop();
                }
            }

            private static void ApplyPerformanceCondition(int index)
            {
                RestoreTemporaryState();
                if (index == 1)
                {
                    foreach (Animator animator in shotgunAnimators)
                    {
                        animator.enabled = false;
                    }
                }
                else if (index == 2)
                {
                    foreach (Renderer renderer in shotgunRenderers)
                    {
                        renderer.enabled = false;
                    }
                }
                else if (index == 3)
                {
                    foreach (Light light in additionalShadowLights)
                    {
                        light.shadows = LightShadows.None;
                    }
                }
            }

            private static void RestoreTemporaryState()
            {
                if (shotgunAnimators != null && animatorEnabled != null)
                {
                    for (int index = 0; index < shotgunAnimators.Length; index++)
                    {
                        if (shotgunAnimators[index] == null)
                        {
                            continue;
                        }

                        shotgunAnimators[index].enabled = animatorEnabled[index];
                        shotgunAnimators[index].cullingMode = animatorCulling[index];
                    }
                }

                if (shotgunRenderers != null && rendererEnabled != null)
                {
                    for (int index = 0; index < shotgunRenderers.Length; index++)
                    {
                        if (shotgunRenderers[index] != null)
                        {
                            shotgunRenderers[index].enabled = rendererEnabled[index];
                        }
                    }
                }

                if (additionalShadowLights != null && lightShadows != null)
                {
                    for (int index = 0; index < additionalShadowLights.Length; index++)
                    {
                        if (additionalShadowLights[index] != null)
                        {
                            additionalShadowLights[index].shadows = lightShadows[index];
                        }
                    }
                }
            }

            private static ProfilerRecorder StartShotgunRecorder(
                ProfilerCategory category,
                string marker)
            {
                try
                {
                    return ProfilerRecorder.StartNew(category, marker, 32);
                }
                catch
                {
                    return default;
                }
            }

            private static void AddShotgunRecorderTime(
                ProfilerRecorder recorder,
                ICollection<float> target)
            {
                if (recorder.Valid)
                {
                    target.Add(recorder.LastValue / 1000000f);
                }
            }

            private static void DisposeRecorders()
            {
                if (mainThreadRecorder.Valid)
                {
                    mainThreadRecorder.Dispose();
                }

                if (renderThreadRecorder.Valid)
                {
                    renderThreadRecorder.Dispose();
                }

                if (gcAllocatedRecorder.Valid)
                {
                    gcAllocatedRecorder.Dispose();
                }
            }

            private static void WritePerformanceMetrics()
            {
                Camera camera = Camera.main;
                ShotgunPerformanceMetrics metrics = new ShotgunPerformanceMetrics
                {
                    scene = SceneManager.GetActiveScene().path,
                    camera = camera != null ? camera.name : "none",
                    warmupFramesPerCondition = ShotgunPerformanceWarmupFrames,
                    sampleFramesPerCondition = ShotgunPerformanceSampleFrames,
                    shotgunAnimatorCount = shotgunAnimators.Length,
                    shotgunRendererCount = shotgunRenderers.Length,
                    additionalShadowLightCount = additionalShadowLights.Length,
                    additionalShadowLightPaths = additionalShadowLights
                        .Select(light => GetShotgunHierarchyPath(light.transform))
                        .ToArray(),
                    conditions = samples.Select(ToPerformanceMetrics).ToArray(),
                    temporaryStateRestored = TemporaryStateIsRestored(),
                    validationPriority =
                        "1순위 실제 Play Mode 체감 및 직접 확인, 2순위 동일 조건 수치 보조 비교"
                };
                WriteJson(OutputPath, metrics);
            }

            private static ShotgunPerformanceConditionMetrics ToPerformanceMetrics(
                ConditionSamples source)
            {
                return new ShotgunPerformanceConditionMetrics
                {
                    condition = source.Name,
                    samples = source.FrameTimes.Count,
                    medianFrameTimeMs = ShotgunMedian(source.FrameTimes),
                    p95FrameTimeMs = ShotgunPercentile(source.FrameTimes, 0.95f),
                    medianMainThreadTimeMs = ShotgunMedian(source.MainThreadTimes),
                    p95MainThreadTimeMs = ShotgunPercentile(source.MainThreadTimes, 0.95f),
                    medianRenderThreadTimeMs = ShotgunMedian(source.RenderThreadTimes),
                    p95RenderThreadTimeMs = ShotgunPercentile(source.RenderThreadTimes, 0.95f),
                    medianGcAllocatedBytes = (long)ShotgunMedian(
                        source.GcAllocatedBytes.Select(value => (float)value).ToList()),
                    medianBatches = ShotgunMedian(source.Batches),
                    medianTriangles = ShotgunMedian(source.Triangles),
                    medianVertices = ShotgunMedian(source.Vertices)
                };
            }

            private static float ShotgunMedian(IReadOnlyCollection<float> values)
            {
                return ShotgunPercentile(values, 0.5f);
            }

            private static float ShotgunPercentile(
                IReadOnlyCollection<float> values,
                float percentile)
            {
                if (values == null || values.Count == 0)
                {
                    return 0f;
                }

                float[] ordered = values.OrderBy(value => value).ToArray();
                float position = Mathf.Clamp01(percentile) * (ordered.Length - 1);
                int lower = Mathf.FloorToInt(position);
                int upper = Mathf.CeilToInt(position);
                return Mathf.Lerp(ordered[lower], ordered[upper], position - lower);
            }

            private static bool TemporaryStateIsRestored()
            {
                return shotgunAnimators.Select((value, index) =>
                           value != null &&
                           value.enabled == animatorEnabled[index] &&
                           value.cullingMode == animatorCulling[index]).All(value => value) &&
                       shotgunRenderers.Select((value, index) =>
                           value != null && value.enabled == rendererEnabled[index]).All(value => value) &&
                       additionalShadowLights.Select((value, index) =>
                           value != null && value.shadows == lightShadows[index]).All(value => value);
            }

            private static string GetShotgunHierarchyPath(Transform value)
            {
                List<string> parts = new List<string>();
                Transform current = value;
                while (current != null)
                {
                    parts.Add(current.name);
                    current = current.parent;
                }

                parts.Reverse();
                return string.Join("/", parts);
            }
        }

        [Serializable]
        private sealed class ShotgunCorrectionApplyMetrics
        {
            public string targetSet;
            public float previousLengthMeters;
            public float correctedLengthMeters;
            public float buttStockDownDegrees;
            public float torsoClearanceMeters;
            public float reloadPullDistanceMeters;
            public float reloadDetachedTravelSeconds;
            public float reloadSupportHoldSeconds;
            public string[] triggerDownTargets;
            public string[] triggerOrientationPreservedTargets;
            public string[] lowerBodyPreservedTargets;
            public string musketReloadCorrectedClip;
            public int performanceShadowLightsChanged;
            public bool allNineItemsScaled;
            public bool allNineControllersUseCorrectedClips;
            public bool passedNumericChecks;
            public string validationPriority;
        }

        [MenuItem("Bellerophon/Player/Apply Shotgun Right Arm Grip Corrections")]
        internal static void ApplyShotgunRightArmGripCorrections()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun right-arm grip corrections must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            ShotgunAnimationSpec[] specs = GetShotgunAnimationSpecs();
            Transform[] targets = specs
                .Select(spec => RequireTarget(layout, spec.TargetName))
                .ToArray();
            AnimationClip musketIdle = GetConnectedMusketAnimationClip(
                layout,
                MusketIdleTargetName);
            AnimationClip emptyIdle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                EmptyClipPath) ??
                throw new FileNotFoundException(
                    "Hands_Empty_Idle clip is missing.",
                    Path.GetFullPath(EmptyClipPath));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            ShotgunGripBinding grip = AnalyzeShotgunGripBinding(
                targets[1],
                musketIdle,
                shotgunAsset,
                analysis);
            AnimationClip[] sources =
            {
                LoadSingleEmbeddedClip(
                    ShotgunDrawSourcePath,
                    ShotgunDrawTargetName),
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[1].ClipPath),
                LoadSingleEmbeddedClip(
                    ShotgunStowSourcePath,
                    ShotgunStowTargetName),
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[3].ClipPath),
                null,
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[5].ClipPath),
                LoadSingleEmbeddedClip(
                    ShotgunButtStrikeSourcePath,
                    ShotgunButtStrikeTargetName),
                null,
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[8].ClipPath)
            };
            AnimationClip[] corrected = new AnimationClip[specs.Length];
            for (int index = 0; index < specs.Length; index++)
            {
                ShotgunAnimationSpec spec = specs[index];
                string correctedPath = GetShotgunCorrectedClipPath(
                    spec.TargetName);
                if (string.Equals(spec.ItemMode, "Enter", StringComparison.Ordinal) ||
                    string.Equals(spec.ItemMode, "Exit", StringComparison.Ordinal))
                {
                    corrected[index] =
                        CreateOrUpdateCorrectedShotgunButtTransitionClip(
                            targets[index],
                            musketIdle,
                            shotgunAsset,
                            analysis,
                            grip,
                            correctedPath,
                            spec.TargetName,
                            string.Equals(
                                spec.ItemMode,
                                "Exit",
                                StringComparison.Ordinal));
                    continue;
                }

                AnimationClip source = sources[index] ??
                    throw new InvalidOperationException(
                        spec.TargetName + " source clip is missing.");
                corrected[index] = CreateOrUpdateExactShotgunClipCopy(
                    source,
                    correctedPath,
                    spec.TargetName + "_Corrected");
                BakeShotgunHeldCorrection(
                    corrected[index],
                    source,
                    targets[index],
                    spec,
                    analysis,
                    grip,
                    emptyIdle,
                    index > 5 ? corrected[5] : null);
            }

            AssetDatabase.SaveAssets();
            SessionState.EraseInt(ShotgunAnimationCaptureStageKey);
            Debug.Log(
                "[PlayerShotgunRightArmGrip] Rebuilt only the nine Shotgun corrected clips with the right forearm and wrist untwisted toward performer-left while preserving the requested state-specific right-palm contacts.");
        }

