        internal static void ApplyShotgunReloadSupportHoldAndButtStrikeLeftHandCorrections()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun left-hand attachment corrections must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            ShotgunAnimationSpec[] specs =
                GetShotgunReloadAndButtStrikeLeftHandSpecs();
            Transform shotgunIdleTarget = RequireTarget(
                layout,
                ShotgunIdleTargetName);
            AnimationClip musketIdle = GetConnectedMusketAnimationClip(
                layout,
                MusketIdleTargetName);
            AnimationClip emptyIdle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                EmptyClipPath) ??
                throw new FileNotFoundException(
                    "Hands_Empty_Idle clip is missing.",
                    Path.GetFullPath(EmptyClipPath));
            AnimationClip buttIdle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(
                    ShotgunButtModeIdleTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_ButtMode_Idle corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(
                            ShotgunButtModeIdleTargetName)));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            ShotgunGripBinding grip = AnalyzeShotgunGripBinding(
                shotgunIdleTarget,
                musketIdle,
                shotgunAsset,
                analysis);

            foreach (ShotgunAnimationSpec spec in specs)
            {
                Transform target = RequireTarget(layout, spec.TargetName);
                string correctedPath = GetShotgunCorrectedClipPath(
                    spec.TargetName);
                bool reload = string.Equals(
                    spec.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal);
                AnimationClip source = reload
                    ? AssetDatabase.LoadAssetAtPath<AnimationClip>(
                        spec.ClipPath)
                    : LoadSingleEmbeddedClip(
                        ShotgunButtStrikeSourcePath,
                        ShotgunButtStrikeTargetName);
                if (source == null)
                {
                    throw new FileNotFoundException(
                        spec.TargetName + " source clip is missing.",
                        Path.GetFullPath(spec.ClipPath));
                }

                AnimationClip corrected = CreateOrUpdateExactShotgunClipCopy(
                    source,
                    correctedPath,
                    spec.TargetName + "_Corrected");
                BakeShotgunHeldCorrection(
                    corrected,
                    source,
                    target,
                    spec,
                    analysis,
                    grip,
                    reload ? emptyIdle : null,
                    reload ? null : buttIdle,
                    !reload,
                    !reload);
                BakeShotgunFixedLeftHandAttachment(
                    corrected,
                    target,
                    analysis,
                    reload);
            }

            AssetDatabase.SaveAssets();
            Debug.Log(
                "[PlayerShotgunLeftHandAttachment] Updated only Shotgun_Reload and Shotgun_ButtStrike: Reload keeps its completed underside-support pose without a second pull, and ButtStrike keeps the left palm attached to the shotgun handle through the downward strike.");
        }

