                shotgunAsset,
                analysis);
            AnimationClip source = LoadSingleEmbeddedClip(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeTargetName);
            string correctedPath = GetShotgunCorrectedClipPath(
                ShotgunButtStrikeTargetName);
            AnimationClip corrected = CreateOrUpdateExactShotgunClipCopy(
                source,
                correctedPath,
                ShotgunButtStrikeTargetName + "_Corrected");
            BakeShotgunHeldCorrection(
                corrected,
                source,
                target,
                spec,
                analysis,
                grip,
                null,
                buttIdle,
                true,
                true);
            BakeShotgunFixedLeftHandAttachment(
                corrected,
                target,
                analysis,
                false,
                true);

            AssetDatabase.SaveAssets();
            Debug.Log(
                "[PlayerShotgunButtStrikeStockForward] Updated only Shotgun_ButtStrike: the shotgun keeps its performer-relative direction through the strike, the stock remains forward, and both hand contacts remain attached.");
        }

        internal static void CaptureShotgunButtStrikeStockForwardFinal()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike stock-forward capture must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunButtStrikeTargetName);
            Animator animator = RequireAnimator(target);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunButtStrikeTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_ButtStrike corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(
                            ShotgunButtStrikeTargetName)));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            Vector3 bodySideRightGripPoint =
                GetShotgunButtBodySideRightGripPoint(analysis);
            float maximumItemDirectionDriftDegrees = 0f;
            float maximumItemWorldStepDegrees = 0f;
            float minimumStockForwardDot = 1f;
            float maximumLeftHandleDistance = 0f;
            float maximumRightGripDistance = 0f;
            float minimumRightPalmLeftDot = 1f;
            float minimumRightHandEdgeForwardDot = 1f;
            float windupStockHeight = float.NegativeInfinity;
            float impactStockHeight = float.PositiveInfinity;
            Quaternion heldItemRootRotation = Quaternion.identity;
            Quaternion previousItemWorldRotation = Quaternion.identity;
            bool hasHeldItemRootRotation = false;
            bool hasPreviousItemWorldRotation = false;
            int frameCount = Mathf.Max(
                1,
                Mathf.RoundToInt(clip.length * clip.frameRate));
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                {
                    for (int frame = 0; frame <= frameCount; frame++)
                    {
                        float time = Mathf.Min(
                            clip.length,
                            frame / Mathf.Max(1f, clip.frameRate));
                        float phase = clip.length > 0.0001f
                            ? Mathf.Clamp01(time / clip.length)
                            : 0f;
                        sampler.Sample(time);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Transform rightHand = FindRequired(target, RightHandPath);
                        Quaternion itemRootRotation = Quaternion.Inverse(
                            target.rotation) * item.rotation;
                        if (!hasHeldItemRootRotation)
                        {
                            heldItemRootRotation = itemRootRotation;
                            hasHeldItemRootRotation = true;
                        }

                        maximumItemDirectionDriftDegrees = Mathf.Max(
                            maximumItemDirectionDriftDegrees,
                            Quaternion.Angle(
                                heldItemRootRotation,
                                itemRootRotation));
                        if (hasPreviousItemWorldRotation)
                        {
                            maximumItemWorldStepDegrees = Mathf.Max(
                                maximumItemWorldStepDegrees,
                                Quaternion.Angle(
                                    previousItemWorldRotation,
                                    item.rotation));
                        }
                        previousItemWorldRotation = item.rotation;
                        hasPreviousItemWorldRotation = true;

                        Vector3 stockForward = -item.TransformDirection(
                                analysis.Geometry.StockToMuzzleAxis)
                            .normalized;
                        minimumStockForwardDot = Mathf.Min(
                            minimumStockForwardDot,
                            Vector3.Dot(
                                stockForward,
                                target.forward.normalized));
                        RightHandPalmSample leftPalm =
                            CalculateLeftPalmSample(target);
                        RightHandPalmSample rightPalm =
                            CalculateRightPalmSample(target);
                        maximumLeftHandleDistance = Mathf.Max(
                            maximumLeftHandleDistance,
                            Vector3.Distance(
                                leftPalm.Center,
                                item.TransformPoint(analysis.HandlePoint)));
                        maximumRightGripDistance = Mathf.Max(
                            maximumRightGripDistance,
                            Vector3.Distance(
                                rightPalm.Center,
                                item.TransformPoint(bodySideRightGripPoint)));
                        minimumRightPalmLeftDot = Mathf.Min(
                            minimumRightPalmLeftDot,
                            Vector3.Dot(
                                -rightHand.right.normalized,
                                -target.right.normalized));
                        minimumRightHandEdgeForwardDot = Mathf.Min(
                            minimumRightHandEdgeForwardDot,
                            Vector3.Dot(
                                rightHand.up.normalized,
                                target.forward.normalized));

                        float stockHeight = Vector3.Dot(
                            item.TransformPoint(
                                    analysis.Geometry.LocalStockPoint) -
                                target.position,
                            target.up.normalized);
                        if (phase >= 0.10f && phase <= 0.35f)
                        {
                            windupStockHeight = Mathf.Max(
                                windupStockHeight,
                                stockHeight);
                        }
                        if (phase >= 0.45f && phase <= 0.60f)
                        {
                            impactStockHeight = Mathf.Min(
                                impactStockHeight,
                                stockHeight);
                        }
                    }
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            float downwardStockTravelMeters =
                windupStockHeight - impactStockHeight;
            if (maximumItemDirectionDriftDegrees > 2f ||
                maximumItemWorldStepDegrees > 2f ||
                minimumStockForwardDot < 0.75f ||
                maximumLeftHandleDistance > 0.012f ||
                maximumRightGripDistance > 0.012f ||
                minimumRightPalmLeftDot < 0.9f ||
                minimumRightHandEdgeForwardDot < 0.9f ||
                downwardStockTravelMeters < 0.03f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike stock-forward support checks failed. " +
                    "ItemDirectionDrift=" +
                    Num(maximumItemDirectionDriftDegrees) +
                    ", ItemWorldStep=" +
                    Num(maximumItemWorldStepDegrees) +
                    ", StockForwardDot=" + Num(minimumStockForwardDot) +
                    ", LeftHandle=" + Num(maximumLeftHandleDistance) +
                    ", RightGrip=" + Num(maximumRightGripDistance) +
                    ", PalmLeftDot=" + Num(minimumRightPalmLeftDot) +
                    ", HandEdgeForwardDot=" +
                    Num(minimumRightHandEdgeForwardDot) +
                    ", DownwardStockTravel=" +
                    Num(downwardStockTravelMeters) + ".");
            }

            List<List<byte[]>> rows = new List<List<byte[]>>
            {
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>()
            };
            float[] reviewPhases = { 0f, 0.25f, 0.50f, 0.68f };
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    foreach (float phase in reviewPhases)
                    {
                        sampler.Sample(phase * clip.length);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Vector3 weaponCenter =
                            (item.TransformPoint(
                                 analysis.Geometry.LocalStockPoint) +
                             item.TransformPoint(
                                 analysis.Geometry.LocalMuzzlePoint)) * 0.5f;
                        environment.ConfigureView(target, weaponCenter, 1.0f);
                        rows[0].Add(environment.CaptureFront());
                        rows[1].Add(environment.CaptureSide());
                        Vector3 handsCenter =
                            (CalculateRightPalmSample(target).Center +
                             CalculateLeftPalmSample(target).Center) * 0.5f;
                        environment.ConfigurePalmView(
                            target,
                            handsCenter,
                            target.right,
                            0.62f);
                        rows[2].Add(
                            environment.CapturePalmFromTorso());
                    }
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            string projectRoot = Path.GetFullPath(
                Path.Combine(Application.dataPath, ".."));
            string outputPath = Path.Combine(
                projectRoot,
                "Temp",
                "ShotgunButtStrikeStockForwardFinal.png");
            ComposeRows(rows, outputPath);
            Debug.Log(
                "[PlayerShotgunButtStrikeStockForward] Final direct review captured after support checks passed. ItemDirectionDrift=" +
                Num(maximumItemDirectionDriftDegrees) +
                ", ItemWorldStep=" + Num(maximumItemWorldStepDegrees) +
                ", StockForwardDot=" + Num(minimumStockForwardDot) +
                ", LeftHandle=" + Num(maximumLeftHandleDistance) +
                ", RightGrip=" + Num(maximumRightGripDistance) +
                ", PalmLeftDot=" + Num(minimumRightPalmLeftDot) +
                ", HandEdgeForwardDot=" +
                Num(minimumRightHandEdgeForwardDot) +
                ", DownwardStockTravel=" +
                Num(downwardStockTravelMeters) +
                ", Output=" + outputPath + ".");
        }

        internal static void ApplyShotgunButtStrikeMixamoGripLockedCorrection()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike Mixamo grip-lock correction must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunButtStrikeTargetName);
            AnimationClip idle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunIdleTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_Idle corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(
                            ShotgunIdleTargetName)));
            ShotgunGripPoseReference heldReference =
                ReadShotgunGripPoseReference(target, idle, 0f);
            AnimationClip source = LoadSingleEmbeddedClip(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeTargetName);
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            AnimationClip corrected = CreateOrUpdateExactShotgunClipCopy(
                source,
                GetShotgunCorrectedClipPath(ShotgunButtStrikeTargetName),
                ShotgunButtStrikeTargetName + "_Corrected");
            BakeShotgunButtStrikeDirectedGrip(
                corrected,
                source,
                target,
                analysis,
                heldReference,
                idle);

            if (!string.Equals(
                    HashSelectedPositionScaleCurves(
                        source,
                        LeftShoulderPath,
                        LeftArmPath,
                        LeftForeArmPath,
                        LeftHandPath,
                        RightShoulderPath,
                        RightArmPath,
                        RightForeArmPath,
                        RightHandPath),
                    HashSelectedPositionScaleCurves(
                        corrected,
                        LeftShoulderPath,
                        LeftArmPath,
                        LeftForeArmPath,
                        LeftHandPath,
                        RightShoulderPath,
                        RightArmPath,
                        RightForeArmPath,
                        RightHandPath),
                    StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike changed an arm position or scale curve from the embedded Mixamo animation.");
            }

            AssetDatabase.SaveAssets();
            Debug.Log(
                "[PlayerShotgunButtStrikeDirectedGrip] Kept the Mixamo body and normal right-handle/left-support shotgun contacts; raised the original performer-forward-right buttstock direction by 20 degrees, drove a straight stock thrust without item rotation, and solved both arms without crossing them.");
        }

        internal static void ApplyShotgunReloadTopPullToIdleCorrection()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload top-pull correction must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunReloadTargetName);
            AnimationClip idle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunIdleTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_Idle corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(ShotgunIdleTargetName)));
            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(candidate => string.Equals(
                    candidate.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal));
            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                spec.ClipPath) ??
                throw new FileNotFoundException(
                    "Original Shotgun_Reload source copy is missing.",
                    Path.GetFullPath(spec.ClipPath));
            ShotgunGripPoseReference idleReference =
                ReadShotgunGripPoseReference(target, idle, 0f);
            ShotgunGripPoseReference heldReference = idleReference;
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            AnimationClip corrected = CreateOrUpdateExactShotgunClipCopy(
                source,
                GetShotgunCorrectedClipPath(ShotgunReloadTargetName),
                ShotgunReloadTargetName + "_Corrected");
            BakeShotgunReloadTopPullToIdle(
                corrected,
                source,
                target,
                analysis,
                heldReference,
                idleReference);

            string[] unchangedRightUpperArmPaths =
            {
                RightShoulderPath,
                RightArmPath
            };
            if (!string.Equals(
                    HashSelectedTransformCurves(
                        source,
                        unchangedRightUpperArmPaths),
                    HashSelectedTransformCurves(
                        corrected,
                        unchangedRightUpperArmPaths),
                    StringComparison.Ordinal) ||
                !string.Equals(
                    HashSelectedPositionScaleCurves(
                        source,
                        LeftShoulderPath,
                        LeftArmPath,
                        LeftForeArmPath,
                        LeftHandPath,
                        RightShoulderPath,
                        RightArmPath,
                        RightForeArmPath,
                        RightHandPath),
                    HashSelectedPositionScaleCurves(
                        corrected,
                        LeftShoulderPath,
                        LeftArmPath,
                        LeftForeArmPath,
                        LeftHandPath,
                        RightShoulderPath,
                        RightArmPath,
                        RightForeArmPath,
                        RightHandPath),
                    StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload changed a non-target upper-arm or arm position/scale curve.");
            }

            AssetDatabase.SaveAssets();
            Debug.Log(
                "[PlayerShotgunReloadTopPullToIdle] Preserved the original body, upper arms, left-hand path, and grip targets; redistributed the left and right forearm/wrist twist, and lowered the muzzle to performer-forward from support hold start through the final frame.");
        }

        [MenuItem("Bellerophon/Player/Apply Shotgun Reload Wrist Detach Return")]
        internal static void ApplyShotgunReloadWristDetachReturn()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload wrist deformation correction must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp must be clean before the Shotgun_Reload wrist deformation correction.");
            }

            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunReloadTargetName);
            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(candidate => string.Equals(
                    candidate.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal));
            string playerHashBefore = HashFile(PlayerModelPath);
            string clipHashBefore = HashFile(ShotgunReloadWristReturnClipPath);
            string controllerHashBefore = HashFile(spec.ControllerPath);
            Dictionary<Transform, LocalTransformState> existingBoneStates =
                CaptureLocalTransformStates(
                    FindRequired(target, LeftShoulderPath),
                    FindRequired(target, LeftArmPath),
                    FindRequired(target, LeftForeArmPath),
                    FindRequired(target, LeftHandPath));

            SkinnedMeshRenderer renderer =
                RequirePrimaryPlayerSkinnedMeshRenderer(target);
            GameObject playerAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                PlayerModelPath) ??
                throw new FileNotFoundException(
                    "Original player model is missing.",
                    Path.GetFullPath(PlayerModelPath));
            SkinnedMeshRenderer sourceRenderer = playerAsset
                .GetComponentsInChildren<SkinnedMeshRenderer>(true)
                .Where(candidate => candidate.sharedMesh != null)
                .OrderByDescending(candidate => candidate.sharedMesh.vertexCount)
                .FirstOrDefault() ??
                throw new InvalidOperationException(
                    "Original player model has no skinned mesh.");
            Mesh sourceMesh = sourceRenderer.sharedMesh;

            Transform leftForeArm = FindRequired(target, LeftForeArmPath);
            Transform leftHand = FindRequired(target, LeftHandPath);
            Transform helper = leftForeArm.Find(ShotgunReloadWristDeformBoneName);
            if (helper == null)
            {
                GameObject helperObject = new GameObject(
                    ShotgunReloadWristDeformBoneName);
                helper = helperObject.transform;
                helper.SetParent(leftForeArm, false);
            }

            helper.localPosition = leftHand.localPosition * 0.82f;
            helper.localRotation = Quaternion.identity;
            helper.localScale = Vector3.one;

            Transform[] baseBones = renderer.bones
                .Where(bone => bone != null && bone != helper)
                .ToArray();
            if (baseBones.Length != sourceMesh.bindposes.Length)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload renderer bone count does not match the original player bind poses. " +
                    "RendererBones=" + baseBones.Length +
                    ", BindPoses=" + sourceMesh.bindposes.Length + ".");
            }

            int foreArmIndex = Array.IndexOf(baseBones, leftForeArm);
            int handIndex = Array.IndexOf(baseBones, leftHand);
            if (foreArmIndex < 0 || handIndex < 0)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload player mesh does not reference the required left forearm and hand bones.");
            }

            ShotgunReloadWristDeformMeshBuild build =
                CreateOrUpdateShotgunReloadWristDeformMesh(
                    renderer,
                    sourceMesh,
                    baseBones,
                    helper,
                    foreArmIndex,
                    handIndex);
            renderer.bones = baseBones.Concat(new[] { helper }).ToArray();
            renderer.sharedMesh = build.Mesh;
            EditorUtility.SetDirty(renderer);

            ShotgunReloadWristTwistDeformer deformer =
                target.GetComponent<ShotgunReloadWristTwistDeformer>();
            if (deformer == null)
            {
                deformer = target.gameObject.AddComponent<
                    ShotgunReloadWristTwistDeformer>();
            }

            deformer.Configure(
                leftForeArm,
                leftHand,
                helper,
                leftHand.localPosition.normalized,
                0.5f);
            EditorUtility.SetDirty(deformer);

            MeasureLocalTransformDifferences(
                existingBoneStates,
                out float maximumPositionDifference,
                out float maximumRotationDifference,
                out float maximumScaleDifference);
            AssetDatabase.SaveAssets();
            EditorSceneManager.SaveScene(scene);

            string playerHashAfter = HashFile(PlayerModelPath);
            string clipHashAfter = HashFile(ShotgunReloadWristReturnClipPath);
            string controllerHashAfter = HashFile(spec.ControllerPath);
            ShotgunReloadWristDeformApplyRecord record =
                new ShotgunReloadWristDeformApplyRecord
                {
                    target = ShotgunReloadTargetName,
                    sourceMeshPath = AssetDatabase.GetAssetPath(sourceMesh),
                    derivedMeshPath = ShotgunReloadWristDeformMeshPath,
                    helperBonePath = AnimationUtility.CalculateTransformPath(
                        helper,
                        target),
                    sourceVertexCount = sourceMesh.vertexCount,
                    changedVertexCount = build.ChangedVertexCount,
                    sourceBoneCount = build.SourceBoneCount,
                    derivedBoneCount = build.DerivedBoneCount,
                    foreArmLengthMeters = build.ForeArmLengthMeters,
                    minimumChangedAxisRatio = build.MinimumChangedAxisRatio,
                    maximumChangedAxisRatio = build.MaximumChangedAxisRatio,
                    maximumHelperWeight = build.MaximumHelperWeight,
                    twistFraction = 0.5f,
                    playerFbxHashBefore = playerHashBefore,
                    playerFbxHashAfter = playerHashAfter,
                    reloadClipHashBefore = clipHashBefore,
                    reloadClipHashAfter = clipHashAfter,
                    controllerHashBefore = controllerHashBefore,
                    controllerHashAfter = controllerHashAfter,
                    maximumExistingBonePositionDifferenceMeters =
                        maximumPositionDifference,
                    maximumExistingBoneRotationDifferenceDegrees =
                        maximumRotationDifference,
                    maximumExistingBoneScaleDifference = maximumScaleDifference,
                    originalAssetsUnchanged =
                        string.Equals(
                            playerHashBefore,
                            playerHashAfter,
                            StringComparison.Ordinal) &&
                        string.Equals(
                            clipHashBefore,
                            clipHashAfter,
                            StringComparison.Ordinal) &&
                        string.Equals(
                            controllerHashBefore,
                            controllerHashAfter,
                            StringComparison.Ordinal),
                    existingBonesUnchanged =
                        maximumPositionDifference <= 0.000001f &&
                        maximumRotationDifference <= 0.0001f &&
                        maximumScaleDifference <= 0.000001f,
                    leftHandStillDirectChildOfLeftForeArm =
                        leftHand.parent == leftForeArm &&
                        !leftHand.IsChildOf(helper),
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            record.passedNumericChecks =
                record.originalAssetsUnchanged &&
                record.existingBonesUnchanged &&
                record.leftHandStillDirectChildOfLeftForeArm &&
                record.changedVertexCount > 0 &&
                renderer.sharedMesh == build.Mesh &&
                renderer.bones.Last() == helper;
            WriteJson(ShotgunReloadWristDeformApplyPath, record);
            AssetDatabase.ImportAsset(
                ShotgunReloadWristDeformApplyPath,
                ImportAssetOptions.ForceUpdate);
            AssetDatabase.SaveAssets();
            if (!record.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload deformation-only wrist correction did not pass its invariant checks.");
            }

            Debug.Log(
                "[PlayerShotgunReloadWristDeform] Applied a target-only derived mesh and axial twist helper. " +
                "ChangedVertices=" + record.changedVertexCount +
                ", AxisRatio=" + Num(record.minimumChangedAxisRatio) +
                ".." + Num(record.maximumChangedAxisRatio) +
                ", MaxHelperWeight=" + Num(record.maximumHelperWeight) +
                ". Existing left-arm bones and reload clip/controller remained unchanged.");
        }

        private static ShotgunReloadWristDeformMeshBuild
            CreateOrUpdateShotgunReloadWristDeformMesh(
                SkinnedMeshRenderer renderer,
                Mesh sourceMesh,
                Transform[] baseBones,
                Transform helper,
                int foreArmIndex,
                int handIndex)
        {
            Matrix4x4[] sourceBindPoses = sourceMesh.bindposes;
            BoneWeight[] sourceWeights = sourceMesh.boneWeights;
            Vector3[] vertices = sourceMesh.vertices;
            if (sourceWeights.Length != vertices.Length ||
                sourceBindPoses.Length != baseBones.Length)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload source mesh does not use the supported four-weight skin layout.");
            }

            Vector3 foreArmOrigin = sourceBindPoses[foreArmIndex]
                .inverse.MultiplyPoint3x4(Vector3.zero);
            Vector3 handOrigin = sourceBindPoses[handIndex]
                .inverse.MultiplyPoint3x4(Vector3.zero);
            Vector3 foreArmToHand = handOrigin - foreArmOrigin;
            float foreArmLength = foreArmToHand.magnitude;
            if (foreArmLength <= 0.05f)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload left forearm bind segment is too short to identify its wrist transition.");
            }

            Vector3 axis = foreArmToHand / foreArmLength;
            int helperIndex = baseBones.Length;
            BoneWeight[] derivedWeights = new BoneWeight[sourceWeights.Length];
            Array.Copy(sourceWeights, derivedWeights, sourceWeights.Length);
            ShotgunReloadWristDeformMeshBuild result =
                new ShotgunReloadWristDeformMeshBuild
                {
                    SourceBoneCount = baseBones.Length,
                    DerivedBoneCount = baseBones.Length + 1,
                    ForeArmLengthMeters = foreArmLength
                };

            for (int vertexIndex = 0;
                 vertexIndex < vertices.Length;
                 vertexIndex++)
            {
                BoneWeight sourceWeight = sourceWeights[vertexIndex];
                float foreArmWeight = BoneWeightForIndex(
                    sourceWeight,
                    foreArmIndex);
                float handWeight = BoneWeightForIndex(
                    sourceWeight,
                    handIndex);
                float combined = foreArmWeight + handWeight;
                if (combined < 0.55f)
                {
                    continue;
                }

                Vector3 fromForeArm = vertices[vertexIndex] - foreArmOrigin;
                float axisDistance = Vector3.Dot(fromForeArm, axis);
                float axisRatio = axisDistance / foreArmLength;
                Vector3 radial = fromForeArm - axis * axisDistance;
                if (axisRatio < 0.70f ||
                    axisRatio > 1.10f ||
                    radial.magnitude > foreArmLength * 0.36f)
                {
                    continue;
                }

                float transition = Mathf.SmoothStep(
                    0f,
                    1f,
                    Mathf.InverseLerp(0.70f, 1.10f, axisRatio));
                float desiredForeArm =
                    combined * (1f - transition) * (1f - transition);
                float desiredHelper =
                    combined * 2f * transition * (1f - transition);
                float desiredHand = combined * transition * transition;
                if (desiredHelper <= 0.0001f)
                {
                    continue;
                }

                derivedWeights[vertexIndex] = RewriteWristBoneWeight(
                    sourceWeight,
                    foreArmIndex,
                    handIndex,
                    helperIndex,
                    desiredForeArm,
                    desiredHand,
                    desiredHelper);
                result.ChangedVertexCount++;
                result.MinimumChangedAxisRatio = Mathf.Min(
                    result.MinimumChangedAxisRatio,
                    axisRatio);
                result.MaximumChangedAxisRatio = Mathf.Max(
                    result.MaximumChangedAxisRatio,
                    axisRatio);
                result.MaximumHelperWeight = Mathf.Max(
                    result.MaximumHelperWeight,
                    BoneWeightForIndex(
                        derivedWeights[vertexIndex],
                        helperIndex));
            }

            if (result.ChangedVertexCount == 0)
            {
                throw new InvalidOperationException(
                    "No left-wrist transition vertices were found on the Shotgun_Reload player mesh.");
            }

            Mesh derived = AssetDatabase.LoadAssetAtPath<Mesh>(
                ShotgunReloadWristDeformMeshPath);
            if (derived == null)
            {
                Directory.CreateDirectory(
                    Path.GetFullPath(ShotgunReloadWristDeformDirectory));
                derived = UnityEngine.Object.Instantiate(sourceMesh);
                derived.name = "Shotgun_Reload_LeftWristDeform";
                AssetDatabase.CreateAsset(
                    derived,
                    ShotgunReloadWristDeformMeshPath);
            }
            else
            {
                EditorUtility.CopySerialized(sourceMesh, derived);
                derived.name = "Shotgun_Reload_LeftWristDeform";
            }

            Matrix4x4[] derivedBindPoses = new Matrix4x4[
                sourceBindPoses.Length + 1];
            Array.Copy(
                sourceBindPoses,
                derivedBindPoses,
                sourceBindPoses.Length);
            derivedBindPoses[helperIndex] =
                helper.worldToLocalMatrix * renderer.transform.localToWorldMatrix;
            derived.bindposes = derivedBindPoses;
            derived.boneWeights = derivedWeights;
            EditorUtility.SetDirty(derived);
            result.Mesh = derived;
            return result;
        }

        private static BoneWeight RewriteWristBoneWeight(
            BoneWeight source,
            int foreArmIndex,
            int handIndex,
            int helperIndex,
            float foreArmWeight,
            float handWeight,
            float helperWeight)
        {
            Dictionary<int, float> influences = new Dictionary<int, float>();
            for (int slot = 0; slot < 4; slot++)
            {
                GetBoneWeightSlot(
                    source,
                    slot,
                    out int index,
                    out float weight);
                if (weight <= 0f ||
                    index == foreArmIndex ||
                    index == handIndex)
                {
                    continue;
                }

                AddBoneWeightInfluence(influences, index, weight);
            }

            AddBoneWeightInfluence(influences, foreArmIndex, foreArmWeight);
            AddBoneWeightInfluence(influences, helperIndex, helperWeight);
            AddBoneWeightInfluence(influences, handIndex, handWeight);
            KeyValuePair<int, float>[] ordered = influences
                .Where(item => item.Value > 0.000001f)
                .OrderByDescending(item => item.Value)
                .Take(4)
                .ToArray();
            float total = ordered.Sum(item => item.Value);
            if (ordered.Length == 0 || total <= 0.000001f)
            {
                return source;
            }

            int[] indices = new int[4];
            float[] weights = new float[4];
            for (int slot = 0; slot < ordered.Length; slot++)
            {
                indices[slot] = ordered[slot].Key;
                weights[slot] = ordered[slot].Value / total;
            }

            return new BoneWeight
            {
                boneIndex0 = indices[0],
                boneIndex1 = indices[1],
                boneIndex2 = indices[2],
                boneIndex3 = indices[3],
                weight0 = weights[0],
                weight1 = weights[1],
                weight2 = weights[2],
                weight3 = weights[3]
            };
        }

        private static void GetBoneWeightSlot(
            BoneWeight weight,
            int slot,
            out int index,
            out float value)
        {
            switch (slot)
            {
                case 0:
                    index = weight.boneIndex0;
                    value = weight.weight0;
                    return;
                case 1:
                    index = weight.boneIndex1;
                    value = weight.weight1;
                    return;
                case 2:
                    index = weight.boneIndex2;
                    value = weight.weight2;
                    return;
                default:
                    index = weight.boneIndex3;
                    value = weight.weight3;
                    return;
            }
        }

        private static void AddBoneWeightInfluence(
            IDictionary<int, float> influences,
            int index,
            float weight)
        {
            if (weight <= 0.000001f)
            {
                return;
            }

            influences[index] =
                influences.TryGetValue(index, out float existing)
                    ? existing + weight
                    : weight;
        }

        private static Dictionary<Transform, LocalTransformState>
            CaptureLocalTransformStates(params Transform[] transforms)
        {
            return transforms.ToDictionary(
                transform => transform,
                transform => new LocalTransformState(transform));
        }

        private static void MeasureLocalTransformDifferences(
            IReadOnlyDictionary<Transform, LocalTransformState> expected,
            out float maximumPositionDifference,
            out float maximumRotationDifference,
            out float maximumScaleDifference)
        {
            maximumPositionDifference = 0f;
            maximumRotationDifference = 0f;
            maximumScaleDifference = 0f;
            foreach (KeyValuePair<Transform, LocalTransformState> item in expected)
            {
                maximumPositionDifference = Mathf.Max(
                    maximumPositionDifference,
                    Vector3.Distance(
                        item.Value.Position,
                        item.Key.localPosition));
                maximumRotationDifference = Mathf.Max(
                    maximumRotationDifference,
                    Quaternion.Angle(
                        item.Value.Rotation,
                        item.Key.localRotation));
                maximumScaleDifference = Mathf.Max(
                    maximumScaleDifference,
                    Vector3.Distance(
                        item.Value.Scale,
                        item.Key.localScale));
            }
        }

        private static void ApplyShotgunReloadWristDetachReturnMotionLegacy()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload wrist-return correction must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp must be clean before the Shotgun_Reload wrist-return correction.");
            }

            Transform target = RequireTarget(
                RequireLayout(scene),
                ShotgunReloadTargetName);
            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(candidate => string.Equals(
                    candidate.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal));
            string baselinePath = GetShotgunCorrectedClipPath(
                ShotgunReloadTargetName);
            AnimationClip baseline = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                baselinePath) ??
                throw new FileNotFoundException(
                    "Shotgun_Reload corrected baseline clip is missing.",
                    Path.GetFullPath(baselinePath));
            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                spec.ClipPath) ??
                throw new FileNotFoundException(
                    "Shotgun_Reload source clip is missing.",
                    Path.GetFullPath(spec.ClipPath));
            AnimationClip idle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunIdleTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_Idle corrected clip is missing.");
            string baselineHashBefore = HashFile(baselinePath);
            string sourceHashBefore = HashFile(spec.ClipPath);
            Dictionary<string, string> otherAssetsBefore =
                HashOtherShotgunAnimationAssetsExcept(
                    ShotgunReloadTargetName);
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            ShotgunGripPoseReference idleReference =
                ReadShotgunGripPoseReference(target, idle, 0f);
            ShotgunReloadWristReturnBakeResult bake =
                CreateOrUpdateShotgunReloadWristReturnClip(
                    target,
                    baseline,
                    source,
                    analysis,
                    idleReference);
            AnimatorController controller =
                CreateOrUpdateExactEmbeddedTakeController(
                    spec.ControllerPath,
                    spec.StateName,
                    bake.Clip);
            Animator animator = RequireAnimator(target);
            bool otherAssetsUnchanged = DictionariesEqual(
                otherAssetsBefore,
                HashOtherShotgunAnimationAssetsExcept(
                    ShotgunReloadTargetName));
            bool curvesExceptLeftRotationsExact =
                AnimationMatchesExceptTransformRotationPaths(
                    baseline,
                    bake.Clip,
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath);
            bool leftPositionScaleExact = string.Equals(
                HashSelectedPositionScaleCurves(
                    baseline,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath),
                HashSelectedPositionScaleCurves(
                    bake.Clip,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath),
                StringComparison.Ordinal);
            ShotgunReloadWristReturnApplyMetrics metrics =
                new ShotgunReloadWristReturnApplyMetrics
                {
                    baselineClipPath = baselinePath,
                    baselineClipHashBefore = baselineHashBefore,
                    baselineClipHashAfter = HashFile(baselinePath),
                    sourceClipPath = spec.ClipPath,
                    sourceClipHashBefore = sourceHashBefore,
                    sourceClipHashAfter = HashFile(spec.ClipPath),
                    adjustedClipPath = ShotgunReloadWristReturnClipPath,
                    controllerPath = spec.ControllerPath,
                    framesBaked = bake.FramesBaked,
                    durationSeconds = bake.Clip.length,
                    frameRate = bake.Clip.frameRate,
                    pullEndSeconds = bake.PullEndSeconds,
                    pullDistanceScale = bake.PullDistanceScale,
                    originalPullDistanceMeters =
                        bake.OriginalPullDistanceMeters,
                    adjustedPullDistanceMeters =
                        bake.AdjustedPullDistanceMeters,
                    pullDistanceReductionMeters =
                        bake.OriginalPullDistanceMeters -
                        bake.AdjustedPullDistanceMeters,
                    returnDurationSeconds = ShotgunReloadWristReturnSeconds,
                    returnEndSeconds = bake.ReturnEndSeconds,
                    maximumReturnPathErrorMeters =
                        bake.MaximumReturnPathErrorMeters,
                    maximumFinalSupportErrorMeters =
                        bake.MaximumFinalSupportErrorMeters,
                    maximumLeftWristStepDegrees =
                        bake.MaximumLeftWristStepDegrees,
                    maximumLeftWristStepTimeSeconds =
                        bake.MaximumLeftWristStepTimeSeconds,
                    maximumLeftWristStepBone =
                        bake.MaximumLeftWristStepBone,
                    maximumVisibleDetachGapMeters =
                        bake.MaximumVisibleDetachGapMeters,
                    maximumPullPalmPathErrorMeters =
                        bake.MaximumPullPalmPathErrorMeters,
                    maximumPullElbowPathDifferenceMeters =
                        bake.MaximumPullElbowPathDifferenceMeters,
                    maximumPullHandRollDegrees =
                        bake.MaximumPullHandRollDegrees,
                    maximumReturnHandReachAdjustmentDegrees =
                        bake.MaximumReturnHandReachAdjustmentDegrees,
                    maximumWristReferenceDeviationDegrees =
                        bake.MaximumWristReferenceDeviationDegrees,
                    finalSupportForwardShiftMeters =
                        bake.FinalSupportForwardShiftMeters,
                    finalSupportPalmCenterSurfaceOffsetMeters =
                        bake.FinalSupportPalmCenterSurfaceOffsetMeters,
                    maximumFinalSupportHandMeshDistanceMeters =
                        bake.MaximumFinalSupportHandMeshDistanceMeters,
                    maximumUnchangedPosePositionDifferenceMeters =
                        bake.MaximumUnchangedPosePositionDifferenceMeters,
                    maximumUnchangedPoseRotationDifferenceDegrees =
                        bake.MaximumUnchangedPoseRotationDifferenceDegrees,
                    allCurvesExceptLeftArmChainCorrectionExact =
                        curvesExceptLeftRotationsExact,
                    leftArmPositionScaleCurvesExact = leftPositionScaleExact,
                    sourceAndBaselineFilesUnchanged =
                        string.Equals(
                            baselineHashBefore,
                            HashFile(baselinePath),
                            StringComparison.Ordinal) &&
                        string.Equals(
                            sourceHashBefore,
                            HashFile(spec.ClipPath),
                            StringComparison.Ordinal),
                    otherEightShotgunAssetsUnchanged = otherAssetsUnchanged,
                    clipLoops = AnimationUtility
                        .GetAnimationClipSettings(bake.Clip).loopTime,
                    controllerUsesClipAtSpeedOne =
                        StateUsesClip(controller, spec.StateName, bake.Clip),
                    animatorSettingsCorrect =
                        AnimatorMatches(animator, controller) &&
                        Mathf.Abs(animator.speed - 1f) <= 0.0001f &&
                        !animator.applyRootMotion,
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                metrics.framesBaked >= 2 &&
                Mathf.Abs(metrics.durationSeconds - baseline.length) <= 0.0001f &&
                Mathf.Abs(metrics.frameRate - baseline.frameRate) <= 0.0001f &&
                Mathf.Abs(
                    metrics.pullDistanceScale -
                    ShotgunReloadPullDistanceScale) <= 0.0001f &&
                metrics.originalPullDistanceMeters > 0.0001f &&
                Mathf.Abs(
                    metrics.adjustedPullDistanceMeters /
                    metrics.originalPullDistanceMeters -
                    ShotgunReloadPullDistanceScale) <= 0.01f &&
                Mathf.Abs(
                    metrics.returnDurationSeconds - 0.5f) <= 0.0001f &&
                metrics.maximumReturnPathErrorMeters <= 0.008f &&
                metrics.maximumFinalSupportErrorMeters <= 0.008f &&
                metrics.maximumLeftWristStepDegrees <= 60f &&
                metrics.maximumVisibleDetachGapMeters >=
                    ShotgunReloadMinimumVisibleGapMeters &&
                metrics.maximumPullPalmPathErrorMeters <=
                    metrics.pullDistanceReductionMeters + 0.012f &&
                metrics.maximumPullElbowPathDifferenceMeters <= 0.20f &&
                metrics.maximumPullHandRollDegrees <= 120f &&
                metrics.maximumReturnHandReachAdjustmentDegrees <= 90f &&
                metrics.maximumWristReferenceDeviationDegrees <= 75f &&
                metrics.finalSupportForwardShiftMeters >=
                    ShotgunReloadForwardSupportShiftMeters - 0.001f &&
                Mathf.Abs(
                    metrics.finalSupportPalmCenterSurfaceOffsetMeters -
                    ShotgunPalmSurfaceOffsetMeters) <= 0.001f &&
                metrics.maximumFinalSupportHandMeshDistanceMeters <= 0.04f &&
                metrics.maximumUnchangedPosePositionDifferenceMeters <= 0.0001f &&
                metrics.maximumUnchangedPoseRotationDifferenceDegrees <= 0.01f &&
                metrics.allCurvesExceptLeftArmChainCorrectionExact &&
                metrics.leftArmPositionScaleCurvesExact &&
                metrics.sourceAndBaselineFilesUnchanged &&
                metrics.otherEightShotgunAssetsUnchanged &&
                metrics.clipLoops &&
                metrics.controllerUsesClipAtSpeedOne &&
                metrics.animatorSettingsCorrect;
            WriteJson(ShotgunReloadWristReturnApplyMetricsPath, metrics);
            AssetDatabase.SaveAssets();
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload wrist-return apply checks failed. " +
                    JsonUtility.ToJson(metrics));
            }

            SessionState.EraseInt(ShotgunReloadWristReturnCaptureStageKey);
            Debug.Log(
                "[PlayerShotgunReloadWristReturn] Shortened only the upper-pull travel to clear the face, restored the left wrist from the authored natural rotation, then moved the visibly released hand to the existing muzzleward underside support over exactly 0.5 seconds.");
        }

        private static ShotgunReloadWristReturnBakeResult
            CreateOrUpdateShotgunReloadWristReturnClip(
                Transform template,
                AnimationClip baseline,
                AnimationClip naturalSource,
                ShotgunGripAnalysis analysis,
                ShotgunGripPoseReference idleReference)
        {
            AnimationClip generated = new AnimationClip();
            EditorUtility.CopySerialized(baseline, generated);
            generated.name = "Shotgun_Reload_WristDetachReturn";
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject naturalObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name = "ShotgunReloadWristReturnBake";
            naturalObject.name = "ShotgunReloadNaturalWristReference";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            naturalObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            DisableAnimators(naturalObject);
            try
            {
                Transform root = workObject.transform;
                Transform naturalRoot = naturalObject.transform;
                // Use the model's bind-local wrist orientation as the axial
                // twist reference while retaining the authored wrist bend.
                Quaternion neutralLeftHandLocalRotation = FindRequired(
                    template,
                    LeftHandPath).localRotation;
                float pullStart = 0f;
                float pullEnd = Mathf.Min(
                    baseline.length,
                    baseline.length * ShotgunReloadStartNormalized +
                    ShotgunReloadPullSeconds);
                float returnEnd = Mathf.Min(
                    baseline.length,
                    pullEnd + ShotgunReloadWristReturnSeconds);
                baseline.SampleAnimation(workObject, pullStart);
                Transform pullStartItem = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                Vector3 pullStartPalmItemLocal =
                    pullStartItem.InverseTransformPoint(
                        CalculateLeftPalmSample(root).Center);
                baseline.SampleAnimation(workObject, pullEnd);
                Transform pullItem = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                Transform pullForeArm = FindRequired(root, LeftForeArmPath);
                Transform pullHand = FindRequired(root, LeftHandPath);
                Vector3 originalPulledPalmItemLocal =
                    pullItem.InverseTransformPoint(
                        CalculateLeftPalmSample(root).Center);
                Quaternion pulledBaselineForeArmLocalRotation =
                    pullForeArm.localRotation;
                Quaternion pulledBaselineHandLocalRotation =
                    pullHand.localRotation;
                Vector3 pulledPalmItemLocal = Vector3.Lerp(
                    pullStartPalmItemLocal,
                    originalPulledPalmItemLocal,
                    ShotgunReloadPullDistanceScale);
                naturalSource.SampleAnimation(
                    naturalObject,
                    Mathf.Min(pullEnd, naturalSource.length));
                Quaternion pulledNaturalForeArmLocalRotation = FindRequired(
                    naturalRoot,
                    LeftForeArmPath).localRotation;
                Quaternion pulledNaturalHandLocalRotation = FindRequired(
                    naturalRoot,
                    LeftHandPath).localRotation;
                pullForeArm.localRotation =
                    pulledNaturalForeArmLocalRotation;
                pullHand.localRotation = pulledNaturalHandLocalRotation;
                Vector3 forwardSupportItemLocal =
                    GetShotgunReloadForwardSupportItemLocal(
                        pullItem,
                        analysis,
                        idleReference.LeftPalmItemLocal,
                        out Vector3 forwardSupportSurfaceItemLocal);
                TransformCurveTrack leftArmTrack =
                    new TransformCurveTrack(LeftArmPath);
                TransformCurveTrack leftShoulderTrack =
                    new TransformCurveTrack(LeftShoulderPath);
                TransformCurveTrack leftForeArmTrack =
                    new TransformCurveTrack(LeftForeArmPath);
                TransformCurveTrack leftHandTrack =
                    new TransformCurveTrack(LeftHandPath);
                Quaternion previousArmLocalRotation = Quaternion.identity;
                Quaternion previousForeArmLocalRotation = Quaternion.identity;
                Quaternion previousHandLocalRotation = Quaternion.identity;
                bool hasPreviousWristRotation = false;
                float previousTransferredWristTwistDegrees = 0f;
                bool hasPreviousTransferredWristTwist = false;
                Vector3 previousElbowBendRootLocal = Vector3.zero;
                bool hasPreviousElbowBend = false;
                ShotgunReloadWristReturnBakeResult result =
                    new ShotgunReloadWristReturnBakeResult
                    {
                        PullEndSeconds = pullEnd,
                        ReturnEndSeconds = returnEnd,
                        PullDistanceScale = ShotgunReloadPullDistanceScale,
                        OriginalPullDistanceMeters = pullItem
                            .TransformVector(
                                originalPulledPalmItemLocal -
                                pullStartPalmItemLocal).magnitude,
                        AdjustedPullDistanceMeters = pullItem
                            .TransformVector(
                                pulledPalmItemLocal -
                                pullStartPalmItemLocal).magnitude,
                        FinalSupportForwardShiftMeters =
                            MeasureShotgunReloadSupportForwardShiftMeters(
                                pullItem,
                                analysis,
                                idleReference.LeftPalmItemLocal,
                                forwardSupportItemLocal),
                        FinalSupportPalmCenterSurfaceOffsetMeters =
                            Vector3.Distance(
                                pullItem.TransformPoint(
                                    forwardSupportItemLocal),
                                pullItem.TransformPoint(
                                    forwardSupportSurfaceItemLocal))
                    };
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(
                        baseline.length *
                        ShotgunReloadWristCorrectionBakeRate));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            baseline.length -
                            1f / Mathf.Max(
                                1f,
                                ShotgunReloadWristCorrectionBakeRate))
                        : frame /
                          Mathf.Max(
                              1f,
                              ShotgunReloadWristCorrectionBakeRate);
                    float keyTime = frame == frameCount
                        ? baseline.length
                        : time;
                    baseline.SampleAnimation(workObject, time);
                    naturalSource.SampleAnimation(
                        naturalObject,
                        Mathf.Min(time, naturalSource.length));
                    Transform item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    Transform shoulder = FindRequired(root, LeftShoulderPath);
                    Transform arm = FindRequired(root, LeftArmPath);
                    Transform foreArm = FindRequired(root, LeftForeArmPath);
                    Transform hand = FindRequired(root, LeftHandPath);
                    Transform naturalForeArm = FindRequired(
                        naturalRoot,
                        LeftForeArmPath);
                    Transform naturalHand = FindRequired(
                        naturalRoot,
                        LeftHandPath);
                    Quaternion baselineForeArmLocalRotation =
                        foreArm.localRotation;
                    Quaternion baselineHandLocalRotation =
                        hand.localRotation;
                    Vector3 requestedPalm =
                        CalculateLeftPalmSample(root).Center;
                    Vector3 sourceElbow = foreArm.position;
                    Quaternion originalHandRotation = hand.rotation;
                    Quaternion wristReferenceForeArmLocalRotation =
                        baselineForeArmLocalRotation;
                    Quaternion wristReferenceHandLocalRotation =
                        baselineHandLocalRotation;
                    bool followsPullPath =
                        time >= pullStart && time <= pullEnd;
                    bool followsReturnPath = time > pullEnd;
                    if (followsReturnPath)
                    {
                        foreArm.localRotation = naturalForeArm.localRotation;
                        hand.localRotation = naturalHand.localRotation;
                        float returnWeight = Mathf.SmoothStep(
                            0f,
                            1f,
                            Mathf.InverseLerp(pullEnd, returnEnd, time));
                        wristReferenceForeArmLocalRotation =
                            Quaternion.Slerp(
                                pulledBaselineForeArmLocalRotation,
                                idleReference.LeftForeArmLocalRotation,
                                returnWeight);
                        wristReferenceHandLocalRotation =
                            Quaternion.Slerp(
                                pulledBaselineHandLocalRotation,
                                idleReference.LeftHandLocalRotation,
                                returnWeight);
                        if (hasPreviousWristRotation)
                        {
                            arm.localRotation = previousArmLocalRotation;
                        }
                        foreArm.localRotation =
                            hasPreviousWristRotation
                                ? previousForeArmLocalRotation
                                : wristReferenceForeArmLocalRotation;
                        hand.localRotation = wristReferenceHandLocalRotation;
                        requestedPalm =
                            GetShotgunReloadWristReturnPalmWorld(
                                item,
                                analysis,
                                pulledPalmItemLocal,
                                forwardSupportItemLocal,
                                time,
                                pullEnd,
                                returnEnd);
                        Vector3 requestedHand =
                            GetShotgunRequestedHandWorldPositionForLocalRotation(
                                root,
                                false,
                                requestedPalm,
                                wristReferenceHandLocalRotation);
                        AimShotgunReloadShoulderForFixedTargetReach(
                            root,
                            requestedHand);
                        requestedHand =
                            GetShotgunRequestedHandWorldPositionForLocalRotation(
                                root,
                                false,
                                requestedPalm,
                                wristReferenceHandLocalRotation);
                        Vector3 continuousElbowPole =
                            GetShotgunReloadContinuousElbowPole(
                                root,
                                requestedHand,
                                sourceElbow,
                                previousElbowBendRootLocal,
                                hasPreviousElbowBend);
                        ApplyShotgunNaturalLocalWristPalmIk(
                            root,
                            false,
                            requestedPalm,
                            wristReferenceHandLocalRotation,
                            continuousElbowPole,
                            20);
                        for (int correction = 0;
                             correction < 3;
                             correction++)
                        {
                            Vector3 visiblePalmCorrection =
                                requestedPalm -
                                CalculateLeftPalmSample(root).Center;
                            if (visiblePalmCorrection.sqrMagnitude <=
                                0.00000001f)
                            {
                                break;
                            }

                            shoulder.position += visiblePalmCorrection;
                        }

                        float pathError = Vector3.Distance(
                            CalculateLeftPalmSample(root).Center,
                            requestedPalm);
                        result.MaximumReturnPathErrorMeters = Mathf.Max(
                            result.MaximumReturnPathErrorMeters,
                            pathError);
                        if (time >= returnEnd - 0.0001f)
                        {
                            result.MaximumFinalSupportErrorMeters = Mathf.Max(
                                result.MaximumFinalSupportErrorMeters,
                                pathError);
                            result.MaximumFinalSupportHandMeshDistanceMeters =
                                Mathf.Max(
                                    result.MaximumFinalSupportHandMeshDistanceMeters,
                                    MeasureHandMeshDistanceToPoint(
                                        root,
                                        LeftHandPath,
                                        "LeftHand",
                                        item.TransformPoint(
                                            forwardSupportSurfaceItemLocal)));
                        }

                        float detachWeight = Mathf.Sin(
                            returnWeight * Mathf.PI);
                        if (detachWeight >= 0.95f)
                        {
                            Vector3 separationDirection =
                                GetShotgunReloadSeparationDirectionWorld(
                                    item,
                                    analysis);
                            result.MaximumVisibleDetachGapMeters = Mathf.Max(
                                result.MaximumVisibleDetachGapMeters,
                                MeasureLeftHandShotgunProjectedGapMeters(
                                    root,
                                    item,
                                    analysis,
                                    separationDirection));
                        }
                    }
                    else if (followsPullPath)
                    {
                        Vector3 originalRequestedPalm = requestedPalm;
                        Vector3 originalPalmItemLocal =
                            item.InverseTransformPoint(originalRequestedPalm);
                        requestedPalm = item.TransformPoint(Vector3.Lerp(
                            pullStartPalmItemLocal,
                            originalPalmItemLocal,
                            ShotgunReloadPullDistanceScale));
                        if (hasPreviousWristRotation)
                        {
                            arm.localRotation = previousArmLocalRotation;
                        }
                        foreArm.localRotation = hasPreviousWristRotation
                            ? previousForeArmLocalRotation
                            : naturalForeArm.localRotation;
                        hand.localRotation = neutralLeftHandLocalRotation;
                        wristReferenceForeArmLocalRotation =
                            baselineForeArmLocalRotation;
                        Vector3 requestedHand =
                            GetShotgunRequestedHandWorldPositionForLocalRotation(
                                root,
                                false,
                                requestedPalm,
                                wristReferenceHandLocalRotation);
                        AimShotgunReloadShoulderForFixedTargetReach(
                            root,
                            requestedHand);
                        requestedHand =
                            GetShotgunRequestedHandWorldPositionForLocalRotation(
                                root,
                                false,
                                requestedPalm,
                                wristReferenceHandLocalRotation);
                        Vector3 continuousElbowPole =
                            GetShotgunReloadContinuousElbowPole(
                                root,
                                requestedHand,
                                sourceElbow,
                                previousElbowBendRootLocal,
                                hasPreviousElbowBend);
                        ApplyShotgunNaturalLocalWristPalmIk(
                            root,
                            false,
                            requestedPalm,
                            wristReferenceHandLocalRotation,
                            continuousElbowPole,
                            20);
                        for (int correction = 0;
                             correction < 3;
                             correction++)
                        {
                            Vector3 visiblePalmCorrection =
                                requestedPalm -
                                CalculateLeftPalmSample(root).Center;
                            if (visiblePalmCorrection.sqrMagnitude <=
                                0.00000001f)
                            {
                                break;
                            }

                            shoulder.position += visiblePalmCorrection;
                        }
                        result.MaximumPullPalmPathErrorMeters = Mathf.Max(
                            result.MaximumPullPalmPathErrorMeters,
                            Vector3.Distance(
                                CalculateLeftPalmSample(root).Center,
                                originalRequestedPalm));
                        result.MaximumPullElbowPathDifferenceMeters = Mathf.Max(
                            result.MaximumPullElbowPathDifferenceMeters,
                            Vector3.Distance(
                                foreArm.position,
                                sourceElbow));
                        result.MaximumPullHandRollDegrees =
                            Mathf.Max(
                                result.MaximumPullHandRollDegrees,
                                Quaternion.Angle(
                                    hand.rotation,
                                    originalHandRotation));
                    }

                    if (followsPullPath || followsReturnPath)
                    {
                        previousElbowBendRootLocal =
                            GetShotgunReloadElbowBendRootLocal(root);
                        hasPreviousElbowBend = true;
                        result.MaximumWristReferenceDeviationDegrees =
                            Mathf.Max(
                                result.MaximumWristReferenceDeviationDegrees,
                                Quaternion.Angle(
                                    wristReferenceHandLocalRotation,
                                    hand.localRotation));
                    }

                    if (hasPreviousWristRotation)
                    {
                        float foreArmStep = Quaternion.Angle(
                            previousForeArmLocalRotation,
                            foreArm.localRotation);
                        float handStep = Quaternion.Angle(
                            previousHandLocalRotation,
                            hand.localRotation);
                        float wristStep = Mathf.Max(foreArmStep, handStep);
                        if (wristStep > result.MaximumLeftWristStepDegrees)
                        {
                            result.MaximumLeftWristStepDegrees = wristStep;
                            result.MaximumLeftWristStepTimeSeconds = time;
                            result.MaximumLeftWristStepBone =
                                foreArmStep >= handStep
                                    ? "LeftForeArm"
                                    : "LeftHand";
                        }
                    }

                    previousArmLocalRotation = arm.localRotation;
                    previousForeArmLocalRotation = foreArm.localRotation;
                    previousHandLocalRotation = hand.localRotation;
                    hasPreviousWristRotation = true;
                    leftShoulderTrack.Add(keyTime, shoulder);
                    leftArmTrack.Add(keyTime, arm);
                    leftForeArmTrack.Add(keyTime, foreArm);
                    leftHandTrack.Add(keyTime, hand);
                }

                string[] correctedRotationPaths =
                {
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath
                };
                foreach (EditorCurveBinding binding in AnimationUtility
                             .GetCurveBindings(generated)
                             .Where(binding =>
                                 correctedRotationPaths.Contains(
                                     binding.path,
                                     StringComparer.Ordinal) &&
                                 IsTransformRotationProperty(
                                     binding.propertyName))
                             .ToArray())
                {
                    AnimationUtility.SetEditorCurve(
                        generated,
                        binding,
                        null);
                }

                SetTransformTrackCurves(generated, leftShoulderTrack);
                SetRotationTrackCurves(generated, leftArmTrack);
                SetRotationTrackCurves(generated, leftForeArmTrack);
                SetRotationTrackCurves(generated, leftHandTrack);
                AnimationClipSettings settings =
                    AnimationUtility.GetAnimationClipSettings(generated);
                settings.loopTime = true;
                settings.loopBlend = false;
                AnimationUtility.SetAnimationClipSettings(generated, settings);
                MeasureShotgunReloadWristReturnClip(
                    template,
                    baseline,
                    generated,
                    result);
                AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    ShotgunReloadWristReturnClipPath);
                if (existing == null)
                {
                    AssetDatabase.CreateAsset(
                        generated,
                        ShotgunReloadWristReturnClipPath);
                    existing = generated;
                }
                else
                {
                    EditorUtility.CopySerialized(generated, existing);
                    UnityEngine.Object.DestroyImmediate(generated);
                    existing.name = "Shotgun_Reload_WristDetachReturn";
                    EditorUtility.SetDirty(existing);
                }

                AssetDatabase.SaveAssets();
                result.Clip = existing;
                result.FramesBaked = frameCount + 1;
                return result;
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
                UnityEngine.Object.DestroyImmediate(naturalObject);
            }
        }

        private static void MeasureShotgunReloadWristReturnClip(
            Transform template,
            AnimationClip baseline,
            AnimationClip adjusted,
            ShotgunReloadWristReturnBakeResult result)
        {
            GameObject baselineObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject adjustedObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            baselineObject.name = "ShotgunReloadWristReturnMeasureBaseline";
            adjustedObject.name = "ShotgunReloadWristReturnMeasureAdjusted";
            baselineObject.hideFlags = HideFlags.HideAndDontSave;
            adjustedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(baselineObject);
            DisableAnimators(adjustedObject);
            try
            {
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(adjusted.length * adjusted.frameRate));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            adjusted.length -
                            1f / Mathf.Max(1f, adjusted.frameRate))
                        : frame / Mathf.Max(1f, adjusted.frameRate);
                    baseline.SampleAnimation(baselineObject, time);
                    adjusted.SampleAnimation(adjustedObject, time);
                    MeasureArmaturePoseDifferenceExceptPath(
                        CapturePose(baselineObject.transform),
                        CapturePose(adjustedObject.transform),
                        LeftShoulderPath,
                        out float positionDifference,
                        out float rotationDifference);
                    result.MaximumUnchangedPosePositionDifferenceMeters =
                        Mathf.Max(
                            result.MaximumUnchangedPosePositionDifferenceMeters,
                            positionDifference);
                    result.MaximumUnchangedPoseRotationDifferenceDegrees =
                        Mathf.Max(
                            result.MaximumUnchangedPoseRotationDifferenceDegrees,
                            rotationDifference);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(baselineObject);
                UnityEngine.Object.DestroyImmediate(adjustedObject);
            }
        }

        private static ShotgunGripPoseReference ReadShotgunGripPoseReference(
            Transform template,
            AnimationClip clip,
            float time)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name = clip.name + "ShotgunGripPoseReference";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                clip.SampleAnimation(
                    workObject,
                    Mathf.Clamp(time, 0f, clip.length));
                Transform root = workObject.transform;
                Transform rightHand = FindRequired(root, RightHandPath);
                Transform leftForeArm = FindRequired(root, LeftForeArmPath);
                Transform leftHand = FindRequired(root, LeftHandPath);
                Transform item = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                return new ShotgunGripPoseReference
                {
                    ItemLocalRotation = item.localRotation,
                    ItemLocalScale = item.localScale,
                    RightPalmItemLocal = item.InverseTransformPoint(
                        CalculateRightPalmSample(root).Center),
                    LeftPalmItemLocal = item.InverseTransformPoint(
                        CalculateLeftPalmSample(root).Center),
                    RightHandItemRotation = Quaternion.Inverse(item.rotation) *
                                            rightHand.rotation,
                    LeftHandItemRotation = Quaternion.Inverse(item.rotation) *
                                           leftHand.rotation,
                    LeftForeArmLocalRotation = leftForeArm.localRotation,
                    LeftHandLocalRotation = leftHand.localRotation
                };
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void AttachShotgunToCurrentRightPalmTriggerDown(
            Transform root,
            Transform item,
            ShotgunGripAnalysis analysis,
            ShotgunGripPoseReference heldReference,
            Vector3 stockToMuzzleDirection)
        {
            Transform rightHand = FindRequired(root, RightHandPath);
            if (item.parent != rightHand)
            {
                throw new InvalidOperationException(
                    "Shotgun hand item is not parented to the right hand.");
            }

            item.localRotation = heldReference.ItemLocalRotation;
            item.localScale = heldReference.ItemLocalScale;
            item.rotation = AlignShotgunAxes(
                analysis.Geometry.StockToMuzzleAxis,
                analysis.Geometry.TriggerDirectionAxis,
                stockToMuzzleDirection.normalized,
                -root.up);
            Vector3 rightPalm = CalculateRightPalmSample(root).Center;
            item.position += rightPalm -
                             item.TransformPoint(
                                 heldReference.RightPalmItemLocal);
        }

        private static float ApplyShotgunMinimalLeftGripIk(
            Transform root,
            Vector3 requestedPalm,
            Quaternion requestedHandRotation)
        {
            Transform shoulder = FindRequired(root, LeftShoulderPath);
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Transform hand = FindRequired(root, LeftHandPath);
            Vector3 palmLocal = hand.InverseTransformPoint(
                CalculateLeftPalmSample(root).Center);
            Quaternion sourceHandRotation = hand.rotation;
            hand.rotation = requestedHandRotation;
            Vector3 requestedHand = requestedPalm -
                (hand.TransformPoint(palmLocal) - hand.position);
            hand.rotation = sourceHandRotation;

            float upperLength = Vector3.Distance(
                arm.position,
                foreArm.position);
            float lowerLength = Vector3.Distance(
                foreArm.position,
                hand.position);
            float reach = Vector3.Distance(arm.position, requestedHand);
            float minimumReach = Mathf.Abs(upperLength - lowerLength) + 0.0001f;
            float maximumReach = upperLength + lowerLength - 0.0001f;
            if (reach > maximumReach)
            {
                Quaternion sourceShoulderRotation = shoulder.rotation;
                Vector3 currentArmDirection = arm.position -
                                              shoulder.position;
                Vector3 targetArmDirection = requestedHand -
                                             shoulder.position;
                if (currentArmDirection.sqrMagnitude > 0.000001f &&
                    targetArmDirection.sqrMagnitude > 0.000001f)
                {
                    Quaternion aimedShoulderRotation =
                        Quaternion.FromToRotation(
                            currentArmDirection,
                            targetArmDirection) *
                        sourceShoulderRotation;
                    Quaternion maximumShoulderRotation =
                        Quaternion.RotateTowards(
                            sourceShoulderRotation,
                            aimedShoulderRotation,
                            65f);
                    shoulder.rotation = maximumShoulderRotation;
                    if (Vector3.Distance(arm.position, requestedHand) <=
                        maximumReach)
                    {
                        float lower = 0f;
                        float upper = 1f;
                        for (int iteration = 0; iteration < 12; iteration++)
                        {
                            float midpoint = (lower + upper) * 0.5f;
                            shoulder.rotation = Quaternion.Slerp(
                                sourceShoulderRotation,
                                maximumShoulderRotation,
                                midpoint);
                            if (Vector3.Distance(
                                    arm.position,
                                    requestedHand) <= maximumReach)
                            {
                                upper = midpoint;
                            }
                            else
                            {
                                lower = midpoint;
                            }
                        }

                        shoulder.rotation = Quaternion.Slerp(
                            sourceShoulderRotation,
                            maximumShoulderRotation,
                            upper);
                    }
                    else
                    {
                        shoulder.rotation = sourceShoulderRotation;
                    }
                }

                reach = Vector3.Distance(arm.position, requestedHand);
            }

            if (reach < minimumReach || reach > maximumReach)
            {
                throw new InvalidOperationException(
                    "Shotgun left grip target is outside the unscaled source arm reach. Reach=" +
                    Num(reach) + ", Allowed=" + Num(minimumReach) + "-" +
                    Num(maximumReach) + ".");
            }

            SolveTwoBoneIk(
                arm,
                foreArm,
                hand,
                requestedHand,
                foreArm.position);
            hand.rotation = requestedHandRotation;
            return Vector3.Distance(
                CalculateLeftPalmSample(root).Center,
                requestedPalm);
        }

        private static Vector3 GetShotgunButtStrikeRightSupportPalmItemLocal(
            ShotgunGripAnalysis analysis,
            Vector3 itemLocalScale)
        {
            Vector3 longAxis =
                analysis.Geometry.StockToMuzzleAxis.normalized;
            Vector3 triggerAxis =
                analysis.Geometry.TriggerDirectionAxis.normalized;
            Vector3 thicknessAxis =
                analysis.Geometry.ThicknessAxis.normalized;
            float longitudinalScale = Mathf.Max(
                0.000001f,
                Vector3.Scale(longAxis, itemLocalScale).magnitude);
            float triggerScale = Mathf.Max(
                0.000001f,
                Vector3.Scale(triggerAxis, itemLocalScale).magnitude);
            float muzzleCoordinate = Vector3.Dot(
                analysis.Geometry.LocalMuzzlePoint,
                longAxis);
            float supportCoordinate = muzzleCoordinate -
                ShotgunButtStrikeRightGripFromMuzzleMeters /
                longitudinalScale;
            float nearestSliceDistance = analysis.Geometry.LocalVertices
                .Min(vertex => Mathf.Abs(
                    Vector3.Dot(vertex, longAxis) - supportCoordinate));
            float sliceTolerance = Mathf.Max(
                0.00001f,
                analysis.Geometry.SourceLength * 0.001f);
            Vector3[] supportSlice = analysis.Geometry.LocalVertices
                .Where(vertex => Mathf.Abs(
                    Mathf.Abs(
                        Vector3.Dot(vertex, longAxis) - supportCoordinate) -
                    nearestSliceDistance) <= sliceTolerance)
                .ToArray();
            if (supportSlice.Length == 0)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike has no usable barrel cross-section near the requested 0.20m support point.");
            }

            float undersideCoordinate = supportSlice.Max(vertex =>
                Vector3.Dot(vertex, triggerAxis));
            float minimumThickness = supportSlice.Min(vertex =>
                Vector3.Dot(vertex, thicknessAxis));
            float maximumThickness = supportSlice.Max(vertex =>
                Vector3.Dot(vertex, thicknessAxis));
            float thicknessCoordinate =
                (minimumThickness + maximumThickness) * 0.5f;
            return longAxis * supportCoordinate +
                   triggerAxis *
                   (undersideCoordinate +
                    ShotgunSupportPalmSurfaceOffsetMeters / triggerScale) +
                   thicknessAxis * thicknessCoordinate;
        }

        private static Vector3 GetShotgunButtStrikeLeftHandlePalmItemLocal(
            ShotgunGripAnalysis analysis,
            Vector3 itemLocalScale)
        {
            Vector3 triggerAxis =
                analysis.Geometry.TriggerDirectionAxis.normalized;
            float triggerScale = Mathf.Max(
                0.000001f,
                Vector3.Scale(triggerAxis, itemLocalScale).magnitude);
            return analysis.HandlePoint +
                   triggerAxis *
                   (ShotgunPalmSurfaceOffsetMeters / triggerScale);
        }

        private static Vector3 FindShotgunButtStrikeReachableStockDirection(
            GameObject workObject,
            AnimationClip source,
            ShotgunGripAnalysis analysis,
            Vector3 itemLocalScale,
            Vector3 leftHandleItemLocal,
            Vector3 rightSupportItemLocal)
        {
            Transform root = workObject.transform;
            List<Vector3> candidates = new List<Vector3>();
            for (int pitch = -45; pitch <= 45; pitch += 5)
            {
                for (int yaw = -85; yaw <= 85; yaw += 5)
                {
                    Vector3 candidate =
                        (Quaternion.Euler(pitch, yaw, 0f) * Vector3.forward)
                        .normalized;
                    if (Vector3.Dot(candidate, Vector3.forward) > 0f)
                    {
                        candidates.Add(candidate);
                    }
                }
            }

            Vector3 selected = Vector3.zero;
            float selectedForwardDot = -1f;
            float selectedDisplacement = float.PositiveInfinity;
            int frameCount = Mathf.Max(
                1,
                Mathf.RoundToInt(source.length * source.frameRate));
            foreach (Vector3 candidate in candidates)
            {
                float forwardDot = Vector3.Dot(
                    candidate,
                    Vector3.forward);
                if (forwardDot + 0.0001f < selectedForwardDot)
                {
                    continue;
                }

                bool reachable = true;
                float displacement = 0f;
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float sampleTime = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            source.length -
                            1f / Mathf.Max(1f, source.frameRate))
                        : frame / Mathf.Max(1f, source.frameRate);
                    source.SampleAnimation(workObject, sampleTime);
                    Transform item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    item.localScale = itemLocalScale;
                    item.rotation = AlignShotgunAxes(
                        analysis.Geometry.StockToMuzzleAxis,
                        analysis.Geometry.TriggerDirectionAxis,
                        -root.TransformDirection(candidate).normalized,
                        -root.up);
                    if (!TryGetShotgunButtStrikeReachableItemPosition(
                            root,
                            item,
                            analysis,
                            leftHandleItemLocal,
                            rightSupportItemLocal,
                            out Vector3 itemPosition,
                            out float frameDisplacement))
                    {
                        reachable = false;
                        break;
                    }

                    item.position = itemPosition;
                    displacement += frameDisplacement;
                }

                if (!reachable)
                {
                    continue;
                }

                if (forwardDot > selectedForwardDot + 0.0001f ||
                    displacement < selectedDisplacement)
                {
                    selected = candidate;
                    selectedForwardDot = forwardDot;
                    selectedDisplacement = displacement;
                }
            }

            if (selectedForwardDot <= 0f)
            {
                source.SampleAnimation(workObject, 0f);
                Transform diagnosticItem = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                diagnosticItem.localScale = itemLocalScale;
                diagnosticItem.rotation = AlignShotgunAxes(
                    analysis.Geometry.StockToMuzzleAxis,
                    analysis.Geometry.TriggerDirectionAxis,
                    -root.forward,
                    -root.up);
                Transform diagnosticLeftArm = FindRequired(root, LeftArmPath);
                Transform diagnosticLeftForeArm = FindRequired(
                    root,
                    LeftForeArmPath);
                Transform diagnosticLeftHand = FindRequired(
                    root,
                    LeftHandPath);
                Transform diagnosticRightArm = FindRequired(root, RightArmPath);
                Transform diagnosticRightForeArm = FindRequired(
                    root,
                    RightForeArmPath);
                Transform diagnosticRightHand = FindRequired(
                    root,
                    RightHandPath);
                float gripSpan = Vector3.Distance(
                    diagnosticItem.TransformPoint(leftHandleItemLocal),
                    diagnosticItem.TransformPoint(rightSupportItemLocal));
                float maximumPalmSeparation =
                    Vector3.Distance(
                        diagnosticLeftArm.position,
                        diagnosticLeftForeArm.position) +
                    Vector3.Distance(
                        diagnosticLeftForeArm.position,
                        diagnosticLeftHand.position) +
                    Vector3.Distance(
                        diagnosticRightArm.position,
                        diagnosticRightForeArm.position) +
                    Vector3.Distance(
                        diagnosticRightForeArm.position,
                        diagnosticRightHand.position) +
                    Vector3.Distance(
                        diagnosticLeftArm.position,
                        diagnosticRightArm.position) +
                    (CalculateLeftPalmSample(root).Center -
                     diagnosticLeftHand.position).magnitude +
                    (CalculateRightPalmSample(root).Center -
                     diagnosticRightHand.position).magnitude;
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike found no fixed stock-forward direction that keeps both requested grips inside the unchanged arm lengths. GripSpan=" +
                    Num(gripSpan) + ", MaximumPalmSeparation=" +
                    Num(maximumPalmSeparation) + ".");
            }

            return selected;
        }

        private static bool TryGetShotgunButtStrikeReachableItemPosition(
            Transform root,
            Transform item,
            ShotgunGripAnalysis analysis,
            Vector3 leftHandleItemLocal,
            Vector3 rightSupportItemLocal,
            out Vector3 itemPosition,
            out float palmDisplacement,
            Vector3? preferredItemPosition = null,
            Quaternion? requestedLeftHandRotation = null,
            Quaternion? requestedRightHandRotation = null)
        {
            Transform leftArm = FindRequired(root, LeftArmPath);
            Transform leftForeArm = FindRequired(root, LeftForeArmPath);
            Transform leftHand = FindRequired(root, LeftHandPath);
            Transform rightArm = FindRequired(root, RightArmPath);
            Transform rightForeArm = FindRequired(root, RightForeArmPath);
            Transform rightHand = FindRequired(root, RightHandPath);
            Vector3 sourceLeftPalm = CalculateLeftPalmSample(root).Center;
            Vector3 sourceRightPalm = CalculateRightPalmSample(root).Center;
            Vector3 leftGripOffsetWorld =
                item.TransformPoint(leftHandleItemLocal) - item.position;
            Vector3 rightGripOffsetWorld =
                item.TransformPoint(rightSupportItemLocal) - item.position;
            Vector3 leftPalmLocal = leftHand.InverseTransformPoint(
                sourceLeftPalm);
            Vector3 rightPalmLocal = rightHand.InverseTransformPoint(
                sourceRightPalm);
            Quaternion sourceLeftHandRotation = leftHand.rotation;
            Quaternion sourceRightHandRotation = rightHand.rotation;
            if (requestedLeftHandRotation.HasValue)
            {
                leftHand.rotation = requestedLeftHandRotation.Value;
            }
            if (requestedRightHandRotation.HasValue)
            {
                rightHand.rotation = requestedRightHandRotation.Value;
            }
            Vector3 leftPalmOffsetWorld =
                leftHand.TransformPoint(leftPalmLocal) - leftHand.position;
            Vector3 rightPalmOffsetWorld =
                rightHand.TransformPoint(rightPalmLocal) - rightHand.position;
            leftHand.rotation = sourceLeftHandRotation;
            rightHand.rotation = sourceRightHandRotation;
            Vector3 leftItemPositionCenter = leftArm.position -
                leftGripOffsetWorld + leftPalmOffsetWorld;
            Vector3 rightItemPositionCenter = rightArm.position -
                rightGripOffsetWorld + rightPalmOffsetWorld;
            float leftMaximumReach =
                Vector3.Distance(leftArm.position, leftForeArm.position) +
                Vector3.Distance(leftForeArm.position, leftHand.position) -
                0.01f;
            float rightMaximumReach =
                Vector3.Distance(rightArm.position, rightForeArm.position) +
                Vector3.Distance(rightForeArm.position, rightHand.position) -
                0.01f;
            Vector3 leftPlacement = sourceLeftPalm - leftGripOffsetWorld;
            Vector3 rightPlacement = sourceRightPalm - rightGripOffsetWorld;
            Vector3 desiredItemPosition = preferredItemPosition ??
                (leftPlacement + rightPlacement) * 0.5f;
            itemPosition = desiredItemPosition;
            for (int iteration = 0; iteration < 128; iteration++)
            {
                Vector3 leftDelta = itemPosition - leftItemPositionCenter;
                if (leftDelta.magnitude > leftMaximumReach)
                {
                    itemPosition = leftItemPositionCenter +
                        leftDelta.normalized * leftMaximumReach;
                }

                Vector3 rightDelta = itemPosition - rightItemPositionCenter;
                if (rightDelta.magnitude > rightMaximumReach)
                {
                    itemPosition = rightItemPositionCenter +
                        rightDelta.normalized * rightMaximumReach;
                }
            }

            if (Vector3.Distance(
                    itemPosition,
                    leftItemPositionCenter) >
                leftMaximumReach + 0.0001f ||
                Vector3.Distance(
                    itemPosition,
                    rightItemPositionCenter) >
                rightMaximumReach + 0.0001f)
            {
                itemPosition = Vector3.zero;
                palmDisplacement = float.PositiveInfinity;
                return false;
            }

            Vector3 requestedLeftPalm = itemPosition + leftGripOffsetWorld;
            Vector3 requestedRightPalm = itemPosition + rightGripOffsetWorld;
            palmDisplacement =
                (requestedLeftPalm - sourceLeftPalm).sqrMagnitude +
                (requestedRightPalm - sourceRightPalm).sqrMagnitude;
            return true;
        }

        private static void BakeShotgunButtStrikeDirectedGrip(
            AnimationClip destination,
            AnimationClip source,
            Transform template,
            ShotgunGripAnalysis analysis,
            ShotgunGripPoseReference heldReference,
            AnimationClip gripReference)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name =
                ShotgunButtStrikeTargetName + "DirectedGripBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                Vector3 leftSupportItemLocal =
                    GetShotgunButtStrikeRightSupportPalmItemLocal(
                        analysis,
                        heldReference.ItemLocalScale);
                Vector3 rightHandleItemLocal =
                    GetShotgunButtStrikeLeftHandlePalmItemLocal(
                        analysis,
                        heldReference.ItemLocalScale);
                TransformCurveTrack leftShoulderTrack =
                    new TransformCurveTrack(LeftShoulderPath);
                TransformCurveTrack leftArmTrack =
                    new TransformCurveTrack(LeftArmPath);
                TransformCurveTrack leftForeArmTrack =
                    new TransformCurveTrack(LeftForeArmPath);
                TransformCurveTrack leftHandTrack =
                    new TransformCurveTrack(LeftHandPath);
                TransformCurveTrack rightArmTrack =
                    new TransformCurveTrack(RightArmPath);
                TransformCurveTrack rightShoulderTrack =
                    new TransformCurveTrack(RightShoulderPath);
                TransformCurveTrack rightForeArmTrack =
                    new TransformCurveTrack(RightForeArmPath);
                TransformCurveTrack rightHandTrack =
                    new TransformCurveTrack(RightHandPath);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                float maximumLeftGripError = 0f;
                float maximumRightGripError = 0f;
                float minimumStockFrontDot = 1f;
                float minimumMuzzleLeftDot = 1f;
                float minimumMuzzleUpDot = 1f;
                float maximumItemRootRotationDriftDegrees = 0f;
                float minimumTriggerDownDot = 1f;
                float minimumStockForwardCoordinate =
                    float.PositiveInfinity;
                float maximumStockForwardCoordinate =
                    float.NegativeInfinity;
                float maximumRightArmStepDegrees = 0f;
                float maximumRightArmWorldStepDegrees = 0f;
                float maximumRightWristStepDegrees = 0f;
                float maximumRightPalmStepMeters = 0f;
                float maximumRightWristTargetRelativeStepMeters = 0f;
                int maximumRightArmStepFrame = -1;
                int maximumRightArmWorldStepFrame = -1;
                int maximumRightWristStepFrame = -1;
                int maximumRightPalmStepFrame = -1;
                int maximumRightWristTargetRelativeStepFrame = -1;
                float maximumAppliedStraightThrustMeters = 0f;
                Quaternion previousRightArmLocalRotation =
                    Quaternion.identity;
                Quaternion previousRightForeArmLocalRotation =
                    Quaternion.identity;
                Quaternion previousRightHandLocalRotation =
                    Quaternion.identity;
                Quaternion previousRightForeArmWorldRotation =
                    Quaternion.identity;
                Vector3 previousRightElbowRootPosition = Vector3.zero;
                bool hasPreviousRightRotation = false;
                Quaternion measuredPreviousRightArmLocalRotation =
                    Quaternion.identity;
                Quaternion measuredPreviousRightArmWorldRotation =
                    Quaternion.identity;
                Quaternion measuredPreviousRightForeArmLocalRotation =
                    Quaternion.identity;
                Quaternion measuredPreviousRightHandLocalRotation =
                    Quaternion.identity;
                Vector3 previousRequestedRightPalmRootPosition =
                    Vector3.zero;
                Vector3 previousRightWristTargetRelativeRoot = Vector3.zero;
                Vector3 previousReachableBaseOffsetFromArmsRoot =
                    Vector3.zero;
                bool hasPreviousReachableBaseOffset = false;
                Quaternion previousLeftShoulderLocalRotation =
                    Quaternion.identity;
                Quaternion previousRightShoulderLocalRotation =
                    Quaternion.identity;
                bool hasPreviousShoulderRotations = false;
                bool hasMeasuredPreviousRightRotation = false;
                Quaternion previousLeftArmLocalRotation =
                    Quaternion.identity;
                Quaternion previousLeftForeArmLocalRotation =
                    Quaternion.identity;
                Quaternion previousLeftHandLocalRotation =
                    Quaternion.identity;
                Quaternion previousLeftForeArmWorldRotation =
                    Quaternion.identity;
                Vector3 previousLeftElbowRootPosition = Vector3.zero;
                bool hasPreviousLeftRotation = false;
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                string[] gripArmPaths =
                {
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath,
                    RightShoulderPath,
                    RightArmPath,
                    RightForeArmPath,
                    RightHandPath
                };
                gripReference.SampleAnimation(workObject, 0f);
                Dictionary<string, Quaternion> gripArmLocalRotations =
                    gripArmPaths.ToDictionary(
                        path => path,
                        path => FindRequired(root, path).localRotation,
                        StringComparer.Ordinal);
                Vector3 originalStockRootDirection =
                    (Vector3.right - Vector3.up + Vector3.forward).normalized;
                float stockElevationRadians =
                    Mathf.Asin(originalStockRootDirection.y) +
                    ShotgunButtStrikeStockElevationRaiseDegrees * Mathf.Deg2Rad;
                Vector3 stockHorizontalRootDirection =
                    Vector3.ProjectOnPlane(
                        originalStockRootDirection,
                        Vector3.up).normalized;
                Vector3 fixedStockToMuzzleRootDirection =
                    -(stockHorizontalRootDirection *
                      Mathf.Cos(stockElevationRadians) +
                      Vector3.up * Mathf.Sin(stockElevationRadians));
                source.SampleAnimation(workObject, 0f);
                Transform initialItem = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                initialItem.localScale = heldReference.ItemLocalScale;
                initialItem.rotation = AlignShotgunAxes(
                    analysis.Geometry.StockToMuzzleAxis,
                    analysis.Geometry.TriggerDirectionAxis,
                    root.TransformDirection(
                        fixedStockToMuzzleRootDirection),
                    -root.up);
                Quaternion fixedItemRootRotation = Quaternion.Inverse(
                    root.rotation) * initialItem.rotation;
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / Mathf.Max(1f, source.frameRate));
                    float sampleTime = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            source.length -
                            1f / Mathf.Max(1f, source.frameRate))
                        : time;
                    source.SampleAnimation(workObject, sampleTime);
                    foreach (string gripArmPath in gripArmPaths)
                    {
                        FindRequired(root, gripArmPath).localRotation =
                            gripArmLocalRotations[gripArmPath];
                    }
                    if (hasPreviousShoulderRotations)
                    {
                        FindRequired(root, LeftShoulderPath).localRotation =
                            previousLeftShoulderLocalRotation;
                        FindRequired(root, RightShoulderPath).localRotation =
                            previousRightShoulderLocalRotation;
                    }
                    Transform leftArm = FindRequired(root, LeftArmPath);
                    Transform leftForeArm = FindRequired(
                        root,
                        LeftForeArmPath);
                    Transform leftHand = FindRequired(root, LeftHandPath);
                    Transform rightArm = FindRequired(root, RightArmPath);
                    Transform rightForeArm = FindRequired(
                        root,
                        RightForeArmPath);
                    Transform rightHand = FindRequired(root, RightHandPath);
                    Vector3 sourceLeftElbow = leftForeArm.position;
                    Vector3 sourceRightElbow = rightForeArm.position;
                    Quaternion sourceLeftArmLocalRotation =
                        leftArm.localRotation;
                    Quaternion sourceLeftForeArmLocalRotation =
                        leftForeArm.localRotation;
                    Quaternion sourceLeftHandLocalRotation =
                        leftHand.localRotation;
                    Quaternion sourceRightArmLocalRotation =
                        rightArm.localRotation;
                    Quaternion sourceRightForeArmLocalRotation =
                        rightForeArm.localRotation;
                    Quaternion sourceRightHandLocalRotation =
                        rightHand.localRotation;
                    Vector3 sourceLeftPalmLocal =
                        leftHand.InverseTransformPoint(
                            CalculateLeftPalmSample(root).Center);
                    Vector3 sourceRightPalmLocal =
                        rightHand.InverseTransformPoint(
                            CalculateRightPalmSample(root).Center);
                    Transform item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    item.localScale = heldReference.ItemLocalScale;
                    item.rotation = root.rotation * fixedItemRootRotation;
                    Vector3 leftGripOffsetWorld = item.TransformPoint(
                            leftSupportItemLocal) -
                        item.position;
                    Vector3 rightGripOffsetWorld = item.TransformPoint(
                            rightHandleItemLocal) -
                        item.position;
                    Vector3 baseItemPosition =
                        (CalculateLeftPalmSample(root).Center -
                         leftGripOffsetWorld +
                         CalculateRightPalmSample(root).Center -
                         rightGripOffsetWorld) * 0.5f;
                    float requestedStraightThrust =
                        GetShotgunButtStrikeImpactWeight(
                            time,
                            source.length) *
                        ShotgunButtStrikeImpactAdvanceMeters;
                    float appliedStraightThrust = requestedStraightThrust;
                    item.position = baseItemPosition +
                                    root.forward * appliedStraightThrust;
                    Vector3 requestedItemPosition = item.position;
                    Quaternion requestedItemRotation = item.rotation;
                    Vector3 requestedLeftPalm = item.TransformPoint(
                        leftSupportItemLocal);
                    Vector3 requestedRightPalm = item.TransformPoint(
                        rightHandleItemLocal);
                    Quaternion requestedLeftHandRotation = item.rotation *
                        heldReference.LeftHandItemRotation;
                    Quaternion requestedRightHandRotation = item.rotation *
                        heldReference.RightHandItemRotation;
                    item.SetParent(root, true);
                    Vector3 requestedLeftWrist =
                        GetShotgunRequestedHandWorldPosition(
                            root,
                            false,
                            requestedLeftPalm,
                            requestedLeftHandRotation);
                    Vector3 requestedRightWrist =
                        GetShotgunRequestedHandWorldPosition(
                            root,
                            true,
                            requestedRightPalm,
                            requestedRightHandRotation);
                    AimShotgunButtStrikeShoulderTowardGrip(
                        root,
                        false,
                        requestedLeftWrist);
                    AimShotgunButtStrikeShoulderTowardGrip(
                        root,
                        true,
                        requestedRightWrist);
                    if (!TryGetShotgunButtStrikeReachableItemPosition(
                            root,
                            item,
                            analysis,
                            leftSupportItemLocal,
                            rightHandleItemLocal,
                            out Vector3 reachableBaseItemPosition,
                            out _,
                            requestedLeftHandRotation:
                                requestedLeftHandRotation,
                            requestedRightHandRotation:
                                requestedRightHandRotation))
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike shoulder correction found no common two-hand contact position at frame " +
                            frame.ToString(CultureInfo.InvariantCulture) +
                            ".");
                    }

                    Vector3 armsCenter =
                        (FindRequired(root, LeftArmPath).position +
                         FindRequired(root, RightArmPath).position) * 0.5f;
                    Vector3 reachableBaseOffsetFromArmsRoot =
                        root.InverseTransformVector(
                            reachableBaseItemPosition - armsCenter);
                    if (hasPreviousReachableBaseOffset)
                    {
                        const float maximumRelativeItemTravelPerFrameMeters =
                            0.04f;
                        Vector3 continuousBaseOffset = Vector3.MoveTowards(
                            previousReachableBaseOffsetFromArmsRoot,
                            reachableBaseOffsetFromArmsRoot,
                            maximumRelativeItemTravelPerFrameMeters);
                        Vector3 continuousBaseItemPosition = armsCenter +
                            root.TransformVector(continuousBaseOffset);
                        item.position = continuousBaseItemPosition;
                        AimShotgunButtStrikeShoulderTowardGrip(
                            root,
                            false,
                            GetShotgunRequestedHandWorldPosition(
                                root,
                                false,
                                item.TransformPoint(leftSupportItemLocal),
                                requestedLeftHandRotation));
                        AimShotgunButtStrikeShoulderTowardGrip(
                            root,
                            true,
                            GetShotgunRequestedHandWorldPosition(
                                root,
                                true,
                                item.TransformPoint(rightHandleItemLocal),
                                requestedRightHandRotation));
                        if (!TryGetShotgunButtStrikeReachableItemPosition(
                                root,
                                item,
                                analysis,
                                leftSupportItemLocal,
                                rightHandleItemLocal,
                                out reachableBaseItemPosition,
                                out _,
                                continuousBaseItemPosition,
                                requestedLeftHandRotation,
                                requestedRightHandRotation))
                        {
                            throw new InvalidOperationException(
                                "Shotgun_ButtStrike could not preserve the continuous item offset from both arms at frame " +
                                frame.ToString(CultureInfo.InvariantCulture) +
                                ".");
                        }
                    }
                    armsCenter =
                        (FindRequired(root, LeftArmPath).position +
                         FindRequired(root, RightArmPath).position) * 0.5f;
                    previousReachableBaseOffsetFromArmsRoot =
                        root.InverseTransformVector(
                            reachableBaseItemPosition - armsCenter);
                    hasPreviousReachableBaseOffset = true;

                    Vector3 reachableItemPosition = reachableBaseItemPosition;
                    if (requestedStraightThrust > 0f &&
                        TryGetShotgunButtStrikeReachableItemPosition(
                            root,
                            item,
                            analysis,
                            leftSupportItemLocal,
                            rightHandleItemLocal,
                            out Vector3 advancedItemPosition,
                            out _,
                            reachableBaseItemPosition +
                            root.forward * requestedStraightThrust,
                            requestedLeftHandRotation,
                            requestedRightHandRotation))
                    {
                        reachableItemPosition = advancedItemPosition;
                    }
                    appliedStraightThrust = Mathf.Max(
                        0f,
                        Vector3.Dot(
                            reachableItemPosition -
                            reachableBaseItemPosition,
                            root.forward.normalized));
                    maximumAppliedStraightThrustMeters = Mathf.Max(
                        maximumAppliedStraightThrustMeters,
                        appliedStraightThrust);
                    item.position = reachableItemPosition;
                    requestedItemPosition = item.position;
                    requestedLeftPalm = item.TransformPoint(
                        leftSupportItemLocal);
                    requestedRightPalm = item.TransformPoint(
                        rightHandleItemLocal);
                    Vector3 requestedRightPalmRootPosition =
                        root.InverseTransformPoint(requestedRightPalm);
                    Vector3 requestedRightWristTargetRelativeRoot =
                        root.InverseTransformVector(
                            GetShotgunRequestedHandWorldPosition(
                                root,
                                true,
                                requestedRightPalm,
                                requestedRightHandRotation) -
                            FindRequired(root, RightArmPath).position);
                    if (hasMeasuredPreviousRightRotation)
                    {
                        float rightPalmStep = Vector3.Distance(
                            previousRequestedRightPalmRootPosition,
                            requestedRightPalmRootPosition);
                        if (rightPalmStep > maximumRightPalmStepMeters)
                        {
                            maximumRightPalmStepMeters = rightPalmStep;
                            maximumRightPalmStepFrame = frame;
                        }
                        float rightWristTargetRelativeStep = Vector3.Distance(
                            previousRightWristTargetRelativeRoot,
                            requestedRightWristTargetRelativeRoot);
                        if (rightWristTargetRelativeStep >
                            maximumRightWristTargetRelativeStepMeters)
                        {
                            maximumRightWristTargetRelativeStepMeters =
                                rightWristTargetRelativeStep;
                            maximumRightWristTargetRelativeStepFrame = frame;
                        }
                    }
                    ApplyShotgunLeftPalmIkWithFixedItemPose(
                        root,
                        sourceLeftPalmLocal,
                        requestedLeftPalm,
                        requestedLeftHandRotation,
                        sourceLeftElbow,
                        ref previousLeftArmLocalRotation,
                        ref previousLeftForeArmLocalRotation,
                        ref previousLeftHandLocalRotation,
                        ref previousLeftForeArmWorldRotation,
                        ref previousLeftElbowRootPosition,
                        ref hasPreviousLeftRotation);
                    maximumLeftGripError = Mathf.Max(
                        maximumLeftGripError,
                        Vector3.Distance(
                            CalculateLeftPalmSample(root).Center,
                            requestedLeftPalm));
                    ApplyShotgunRightPalmIkWithContinuousFixedItemPose(
                        root,
                        sourceRightPalmLocal,
                        requestedRightPalm,
                        requestedRightHandRotation,
                        sourceRightElbow,
                        ref previousRightArmLocalRotation,
                        ref previousRightForeArmLocalRotation,
                        ref previousRightHandLocalRotation,
                        ref previousRightForeArmWorldRotation,
                        ref previousRightElbowRootPosition,
                        ref hasPreviousRightRotation);
                    maximumRightGripError = Mathf.Max(
                        maximumRightGripError,
                        Vector3.Distance(
                            CalculateRightPalmSample(root).Center,
                            requestedRightPalm));
                    rightArm = FindRequired(root, RightArmPath);
                    rightForeArm = FindRequired(root, RightForeArmPath);
                    rightHand = FindRequired(root, RightHandPath);
                    if (hasMeasuredPreviousRightRotation)
                    {
                        float rightArmStep = Quaternion.Angle(
                            measuredPreviousRightArmLocalRotation,
                            rightArm.localRotation);
                        if (rightArmStep > maximumRightArmStepDegrees)
                        {
                            maximumRightArmStepDegrees = rightArmStep;
                            maximumRightArmStepFrame = frame;
                        }
                        float rightArmWorldStep = Quaternion.Angle(
                            measuredPreviousRightArmWorldRotation,
                            rightArm.rotation);
                        if (rightArmWorldStep >
                            maximumRightArmWorldStepDegrees)
                        {
                            maximumRightArmWorldStepDegrees =
                                rightArmWorldStep;
                            maximumRightArmWorldStepFrame = frame;
                        }
                        float rightWristStep = Mathf.Max(
                            Quaternion.Angle(
                                measuredPreviousRightForeArmLocalRotation,
                                rightForeArm.localRotation),
                            Quaternion.Angle(
                                measuredPreviousRightHandLocalRotation,
                                rightHand.localRotation));
                        if (rightWristStep > maximumRightWristStepDegrees)
                        {
                            maximumRightWristStepDegrees = rightWristStep;
                            maximumRightWristStepFrame = frame;
                        }
                    }

                    measuredPreviousRightArmLocalRotation =
                        rightArm.localRotation;
                    measuredPreviousRightArmWorldRotation =
                        rightArm.rotation;
                    measuredPreviousRightForeArmLocalRotation =
                        rightForeArm.localRotation;
                    measuredPreviousRightHandLocalRotation =
                        rightHand.localRotation;
                    previousRequestedRightPalmRootPosition =
                        requestedRightPalmRootPosition;
                    previousRightWristTargetRelativeRoot =
                        requestedRightWristTargetRelativeRoot;
                    hasMeasuredPreviousRightRotation = true;
                    item.SetParent(rightHand, true);
                    item.localScale = heldReference.ItemLocalScale;
                    item.rotation = requestedItemRotation;
                    item.position = requestedItemPosition;

                    Vector3 stockToMuzzleWorld = item.TransformDirection(
                            analysis.Geometry.StockToMuzzleAxis)
                        .normalized;
                    Vector3 projectedDown = Vector3.ProjectOnPlane(
                            -root.up,
                            stockToMuzzleWorld)
                        .normalized;
                    minimumStockFrontDot = Mathf.Min(
                        minimumStockFrontDot,
                        Vector3.Dot(
                            -stockToMuzzleWorld,
                            root.forward.normalized));
                    minimumMuzzleLeftDot = Mathf.Min(
                        minimumMuzzleLeftDot,
                        Vector3.Dot(
                            stockToMuzzleWorld,
                            -root.right.normalized));
                    minimumMuzzleUpDot = Mathf.Min(
                        minimumMuzzleUpDot,
                        Vector3.Dot(
                            stockToMuzzleWorld,
                            root.up.normalized));
                    maximumItemRootRotationDriftDegrees = Mathf.Max(
                        maximumItemRootRotationDriftDegrees,
                        Quaternion.Angle(
                            fixedItemRootRotation,
                            Quaternion.Inverse(root.rotation) *
                            item.rotation));
                    minimumTriggerDownDot = Mathf.Min(
                        minimumTriggerDownDot,
                        Vector3.Dot(
                            item.TransformDirection(
                                    analysis.Geometry.TriggerDirectionAxis)
                                .normalized,
                            projectedDown));
                    Vector3 stock = item.TransformPoint(
                        analysis.Geometry.LocalStockPoint);
                    float stockForwardCoordinate = Vector3.Dot(
                        stock - root.position,
                        root.forward.normalized);
                    minimumStockForwardCoordinate = Mathf.Min(
                        minimumStockForwardCoordinate,
                        stockForwardCoordinate);
                    maximumStockForwardCoordinate = Mathf.Max(
                        maximumStockForwardCoordinate,
                        stockForwardCoordinate);
                    leftShoulderTrack.Add(
                        time,
                        FindRequired(root, LeftShoulderPath));
                    leftArmTrack.Add(time, FindRequired(root, LeftArmPath));
                    leftForeArmTrack.Add(
                        time,
                        FindRequired(root, LeftForeArmPath));
                    leftHandTrack.Add(time, FindRequired(root, LeftHandPath));
                    rightShoulderTrack.Add(
                        time,
                        FindRequired(root, RightShoulderPath));
                    rightArmTrack.Add(time, FindRequired(root, RightArmPath));
                    rightForeArmTrack.Add(
                        time,
                        FindRequired(root, RightForeArmPath));
                    rightHandTrack.Add(
                        time,
                        FindRequired(root, RightHandPath));
                    itemTrack.Add(time, item);
                    previousLeftShoulderLocalRotation = FindRequired(
                        root,
                        LeftShoulderPath).localRotation;
                    previousRightShoulderLocalRotation = FindRequired(
                        root,
                        RightShoulderPath).localRotation;
                    hasPreviousShoulderRotations = true;
                    leftArm.localRotation = sourceLeftArmLocalRotation;
                    leftForeArm.localRotation =
                        sourceLeftForeArmLocalRotation;
                    leftHand.localRotation = sourceLeftHandLocalRotation;
                    rightArm.localRotation = sourceRightArmLocalRotation;
                    rightForeArm.localRotation =
                        sourceRightForeArmLocalRotation;
                    rightHand.localRotation = sourceRightHandLocalRotation;
                }

                float stockForwardTravelMeters =
                    maximumStockForwardCoordinate -
                    minimumStockForwardCoordinate;
                SetRotationTrackCurves(destination, leftShoulderTrack);
                SetRotationTrackCurves(destination, leftArmTrack);
                SetRotationTrackCurves(destination, leftForeArmTrack);
                SetRotationTrackCurves(destination, leftHandTrack);
                SetRotationTrackCurves(destination, rightShoulderTrack);
                SetRotationTrackCurves(destination, rightArmTrack);
                SetRotationTrackCurves(destination, rightForeArmTrack);
                SetRotationTrackCurves(destination, rightHandTrack);
                SetTransformTrackCurves(destination, itemTrack);
                SetShotgunItemScaleCurves(
                    destination,
                    itemTrack.Path,
                    heldReference.ItemLocalScale,
                    destination.length);
                destination.EnsureQuaternionContinuity();
                EditorUtility.SetDirty(destination);
                Debug.Log(
                    "[PlayerShotgunButtStrikeDirectedGrip] Baked for direct visual review with the corrected weapon axis, fixed item direction, stock thrust, and unchanged item-local hand contacts. LeftSupportError=" +
                    Num(maximumLeftGripError) + ", RightHandleError=" +
                    Num(maximumRightGripError) + ".");
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void BakeShotgunButtStrikeMixamoGripLocked(
            AnimationClip destination,
            AnimationClip source,
            Transform template,
            ShotgunGripAnalysis analysis,
            ShotgunGripPoseReference heldReference)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name =
                ShotgunButtStrikeTargetName + "MixamoGripLockedBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                Quaternion itemWorldRotation = AlignShotgunAxes(
                    analysis.HandlePoint -
                    heldReference.RightPalmItemLocal,
                    analysis.Geometry.TriggerDirectionAxis,
                    root.forward,
                    -root.up);
                source.SampleAnimation(workObject, 0f);
                Vector3 initialSourceRightPalm =
                    CalculateRightPalmSample(root).Center;
                Vector3 initialItemPosition = initialSourceRightPalm -
                    itemWorldRotation * Vector3.Scale(
                        heldReference.RightPalmItemLocal,
                        heldReference.ItemLocalScale);
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                FindShotgunButtStrikeReachableForwardPath(
                    workObject,
                    source,
                    heldReference,
                    itemWorldRotation,
                    initialSourceRightPalm,
                    out Vector3 selectedBaseOffset,
                    out float selectedMotionScale,
                    out float sourceForwardRange);

                TransformCurveTrack leftArmTrack =
                    new TransformCurveTrack(LeftArmPath);
                TransformCurveTrack leftForeArmTrack =
                    new TransformCurveTrack(LeftForeArmPath);
                TransformCurveTrack leftHandTrack =
                    new TransformCurveTrack(LeftHandPath);
                TransformCurveTrack rightArmTrack =
                    new TransformCurveTrack(RightArmPath);
                TransformCurveTrack rightForeArmTrack =
                    new TransformCurveTrack(RightForeArmPath);
                TransformCurveTrack rightHandTrack =
                    new TransformCurveTrack(RightHandPath);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                float maximumLeftGripError = 0f;
                float maximumRightGripError = 0f;
                float minimumStockCoordinate = float.PositiveInfinity;
                float maximumStockCoordinate = float.NegativeInfinity;
                float impactStockForwardDot = -1f;
                Vector3 initialRightPalm = Vector3.zero;
                float maximumRightPalmTravel = 0f;
                float maximumItemLateralDrift = 0f;
                float maximumItemVerticalDrift = 0f;
                Vector3 initialItemRootPosition = Vector3.zero;
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / Mathf.Max(1f, source.frameRate));
                    float sampleTime = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            source.length -
                            1f / Mathf.Max(1f, source.frameRate))
                        : time;
                    source.SampleAnimation(workObject, sampleTime);
                    Transform rightHand = FindRequired(root, RightHandPath);
                    Transform rightForeArm = FindRequired(
                        root,
                        RightForeArmPath);
                    Transform leftForeArm = FindRequired(
                        root,
                        LeftForeArmPath);
                    Quaternion sourceRightHandWorldRotation =
                        rightHand.rotation;
                    Vector3 sourceRightElbow = rightForeArm.position;
                    Vector3 sourceLeftElbow = leftForeArm.position;
                    Vector3 sourceRightPalm =
                        CalculateRightPalmSample(root).Center;
                    float sourceForwardDelta = Vector3.Dot(
                        sourceRightPalm - initialSourceRightPalm,
                        root.forward.normalized);
                    Transform item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    item.localScale = heldReference.ItemLocalScale;
                    item.rotation = itemWorldRotation;
                    item.position = initialItemPosition +
                        selectedBaseOffset +
                        root.forward.normalized *
                        (sourceForwardDelta * selectedMotionScale);
                    Vector3 requestedRightPalm = item.TransformPoint(
                        heldReference.RightPalmItemLocal);
                    Vector3 requestedLeftPalm = item.TransformPoint(
                        heldReference.LeftPalmItemLocal);
                    item.SetParent(root, true);
                    float rightGripError =
                        ApplyShotgunSourcePlanePalmIk(
                            root,
                            true,
                            requestedRightPalm,
                            sourceRightHandWorldRotation,
                            sourceRightElbow);
                    float leftGripError =
                        ApplyShotgunSourcePlanePalmIk(
                            root,
                            false,
                            requestedLeftPalm,
                            itemWorldRotation *
                            heldReference.LeftHandItemRotation,
                            sourceLeftElbow);
                    rightHand = FindRequired(root, RightHandPath);
                    item.SetParent(rightHand, true);
                    item.localScale = heldReference.ItemLocalScale;
                    maximumRightGripError = Mathf.Max(
                        maximumRightGripError,
                        rightGripError);
                    maximumLeftGripError = Mathf.Max(
                        maximumLeftGripError,
                        leftGripError);

                    Vector3 stock = item.TransformPoint(
                        analysis.Geometry.LocalStockPoint);
                    float stockCoordinate = Vector3.Dot(
                        stock - root.position,
                        root.forward.normalized);
                    if (stockCoordinate > maximumStockCoordinate)
                    {
                        maximumStockCoordinate = stockCoordinate;
                        impactStockForwardDot = Vector3.Dot(
                            -item.TransformDirection(
                                analysis.Geometry.StockToMuzzleAxis).normalized,
                            root.forward.normalized);
                    }
                    minimumStockCoordinate = Mathf.Min(
                        minimumStockCoordinate,
                        stockCoordinate);
                    Vector3 rightPalm = CalculateRightPalmSample(root).Center;
                    if (frame == 0)
                    {
                        initialRightPalm = rightPalm;
                    }
                    maximumRightPalmTravel = Mathf.Max(
                        maximumRightPalmTravel,
                        Vector3.Distance(initialRightPalm, rightPalm));
                    Vector3 itemRootPosition = root.InverseTransformPoint(
                        item.position);
                    if (frame == 0)
                    {
                        initialItemRootPosition = itemRootPosition;
                    }
                    maximumItemLateralDrift = Mathf.Max(
                        maximumItemLateralDrift,
                        Mathf.Abs(
                            itemRootPosition.x -
                            initialItemRootPosition.x));
                    maximumItemVerticalDrift = Mathf.Max(
                        maximumItemVerticalDrift,
                        Mathf.Abs(
                            itemRootPosition.y -
                            initialItemRootPosition.y));

                    leftArmTrack.Add(time, FindRequired(root, LeftArmPath));
                    leftForeArmTrack.Add(
                        time,
                        FindRequired(root, LeftForeArmPath));
                    leftHandTrack.Add(time, FindRequired(root, LeftHandPath));
                    rightArmTrack.Add(time, FindRequired(root, RightArmPath));
                    rightForeArmTrack.Add(
                        time,
                        FindRequired(root, RightForeArmPath));
                    rightHandTrack.Add(
                        time,
                        FindRequired(root, RightHandPath));
                    itemTrack.Add(time, item);
                }

                float stockTravel = maximumStockCoordinate -
                                    minimumStockCoordinate;
                if (maximumLeftGripError > 0.006f ||
                    maximumRightGripError > 0.002f ||
                    stockTravel < 0.05f ||
                    maximumRightPalmTravel < 0.05f ||
                    impactStockForwardDot < 0.98f ||
                    maximumItemLateralDrift > 0.002f ||
                    maximumItemVerticalDrift > 0.002f)
                {
                    throw new InvalidOperationException(
                        "Shotgun_ButtStrike Mixamo grip-lock support checks failed. LeftGrip=" +
                        Num(maximumLeftGripError) + ", RightGrip=" +
                        Num(maximumRightGripError) + ", StockTravel=" +
                        Num(stockTravel) + ", RightPalmTravel=" +
                        Num(maximumRightPalmTravel) + ", ImpactStockForwardDot=" +
                        Num(impactStockForwardDot) +
                        ", BaseOffset=" + selectedBaseOffset +
                        ", MotionScale=" + Num(selectedMotionScale) +
                        ", SourceForwardRange=" +
                        Num(sourceForwardRange) +
                        ", ItemLateralDrift=" +
                        Num(maximumItemLateralDrift) +
                        ", ItemVerticalDrift=" +
                        Num(maximumItemVerticalDrift) + ".");
                }

                SetRotationTrackCurves(destination, leftArmTrack);
                SetRotationTrackCurves(destination, leftForeArmTrack);
                SetRotationTrackCurves(destination, leftHandTrack);
                SetRotationTrackCurves(destination, rightArmTrack);
                SetRotationTrackCurves(destination, rightForeArmTrack);
                SetRotationTrackCurves(destination, rightHandTrack);
                SetTransformTrackCurves(destination, itemTrack);
                SetShotgunItemScaleCurves(
                    destination,
                    itemTrack.Path,
                    heldReference.ItemLocalScale,
                    destination.length);
                EditorUtility.SetDirty(destination);
                Debug.Log(
                    "[PlayerShotgunButtStrikeMixamoGripLocked] Support checks passed before save. LeftGrip=" +
                    Num(maximumLeftGripError) + ", RightGrip=" +
                    Num(maximumRightGripError) + ", StockTravel=" +
                    Num(stockTravel) + ", RightPalmTravel=" +
                    Num(maximumRightPalmTravel) + ", ImpactStockForwardDot=" +
                    Num(impactStockForwardDot) +
                    ", BaseOffset=" + selectedBaseOffset +
                    ", MotionScale=" + Num(selectedMotionScale) +
                    ", SourceForwardRange=" +
                    Num(sourceForwardRange) +
                    ", ItemLateralDrift=" +
                    Num(maximumItemLateralDrift) +
                    ", ItemVerticalDrift=" +
                    Num(maximumItemVerticalDrift) + ".");
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void FindShotgunButtStrikeReachableForwardPath(
            GameObject workObject,
            AnimationClip source,
            ShotgunGripPoseReference heldReference,
            Quaternion itemWorldRotation,
            Vector3 initialSourceRightPalm,
            out Vector3 selectedBaseOffset,
            out float selectedMotionScale,
            out float sourceForwardRange)
        {
            Transform root = workObject.transform;
            List<ShotgunButtReachSample> samples =
                new List<ShotgunButtReachSample>();
            float minimumForwardDelta = float.PositiveInfinity;
            float maximumForwardDelta = float.NegativeInfinity;
            int frameCount = Mathf.Max(
                1,
                Mathf.RoundToInt(source.length * source.frameRate));
            Quaternion desiredLeftHandRotation = itemWorldRotation *
                                                 heldReference
                                                     .LeftHandItemRotation;
            for (int frame = 0; frame <= frameCount; frame++)
            {
                float time = frame == frameCount
                    ? Mathf.Max(
                        0f,
                        source.length -
                        1f / Mathf.Max(1f, source.frameRate))
                    : frame / Mathf.Max(1f, source.frameRate);
                source.SampleAnimation(workObject, time);
                Transform rightArm = FindRequired(root, RightArmPath);
                Transform rightForeArm = FindRequired(
                    root,
                    RightForeArmPath);
                Transform rightHand = FindRequired(root, RightHandPath);
                Transform leftArm = FindRequired(root, LeftArmPath);
                Transform leftForeArm = FindRequired(
                    root,
                    LeftForeArmPath);
                Transform leftHand = FindRequired(root, LeftHandPath);
                Vector3 rightPalm =
                    CalculateRightPalmSample(root).Center;
                float forwardDelta = Vector3.Dot(
                    rightPalm - initialSourceRightPalm,
                    root.forward.normalized);
                minimumForwardDelta = Mathf.Min(
                    minimumForwardDelta,
                    forwardDelta);
                maximumForwardDelta = Mathf.Max(
                    maximumForwardDelta,
                    forwardDelta);
                Vector3 rightPalmFromHand = rightPalm -
                                             rightHand.position;
                Quaternion sourceLeftHandRotation = leftHand.rotation;
                leftHand.rotation = desiredLeftHandRotation;
                Vector3 leftPalmFromHand =
                    CalculateLeftPalmSample(root).Center -
                    leftHand.position;
                leftHand.rotation = sourceLeftHandRotation;
                samples.Add(new ShotgunButtReachSample
                {
                    ForwardDelta = forwardDelta,
                    RightArmPosition = rightArm.position,
                    LeftArmPosition = leftArm.position,
                    RightPalmFromHand = rightPalmFromHand,
                    LeftPalmFromHand = leftPalmFromHand,
                    RightMinimumReach = Mathf.Abs(
                        Vector3.Distance(
                            rightArm.position,
                            rightForeArm.position) -
                        Vector3.Distance(
                            rightForeArm.position,
                            rightHand.position)) + 0.0001f,
                    RightMaximumReach = Vector3.Distance(
                        rightArm.position,
                        rightForeArm.position) +
                        Vector3.Distance(
                            rightForeArm.position,
                            rightHand.position) - 0.04f,
                    LeftMinimumReach = Mathf.Abs(
                        Vector3.Distance(
                            leftArm.position,
                            leftForeArm.position) -
                        Vector3.Distance(
                            leftForeArm.position,
                            leftHand.position)) + 0.0001f,
                    LeftMaximumReach = Vector3.Distance(
                        leftArm.position,
                        leftForeArm.position) +
                        Vector3.Distance(
                            leftForeArm.position,
                            leftHand.position) - 0.08f
                });
            }

            sourceForwardRange = maximumForwardDelta -
                                 minimumForwardDelta;
            Vector3 initialItemPosition = initialSourceRightPalm -
                itemWorldRotation * Vector3.Scale(
                    heldReference.RightPalmItemLocal,
                    heldReference.ItemLocalScale);
            Vector3 rightGripOffset = itemWorldRotation * Vector3.Scale(
                heldReference.RightPalmItemLocal,
                heldReference.ItemLocalScale);
            Vector3 leftGripOffset = itemWorldRotation * Vector3.Scale(
                heldReference.LeftPalmItemLocal,
                heldReference.ItemLocalScale);
            selectedBaseOffset = Vector3.zero;
            selectedMotionScale = -1f;
            for (int motionStep = 20; motionStep >= 0; motionStep--)
            {
                float motionScale = motionStep / 20f;
                if (sourceForwardRange * motionScale < 0.05f)
                {
                    continue;
                }

                float bestOffsetScore = float.PositiveInfinity;
                Vector3 bestOffset = Vector3.zero;
                bool foundAtScale = false;
                for (int lateralStep = -8;
                     lateralStep <= 8;
                     lateralStep++)
                {
                    for (int verticalStep = -8;
                         verticalStep <= 8;
                         verticalStep++)
                    {
                        for (int forwardStep = -16;
                             forwardStep <= 8;
                             forwardStep++)
                        {
                            Vector3 offset =
                                root.right.normalized *
                                (lateralStep * 0.025f) +
                                root.up.normalized *
                                (verticalStep * 0.025f) +
                                root.forward.normalized *
                                (forwardStep * 0.025f);
                            float offsetScore = offset.sqrMagnitude +
                                Mathf.Abs(lateralStep) * 0.0001f +
                                Mathf.Abs(verticalStep) * 0.0001f;
                            if (offsetScore >= bestOffsetScore)
                            {
                                continue;
                            }

                            bool reachable = true;
                            foreach (ShotgunButtReachSample sample in samples)
                            {
                                Vector3 itemPosition = initialItemPosition +
                                    offset + root.forward.normalized *
                                    (sample.ForwardDelta * motionScale);
                                Vector3 requestedRightHand = itemPosition +
                                    rightGripOffset -
                                    sample.RightPalmFromHand;
                                Vector3 requestedLeftHand = itemPosition +
                                    leftGripOffset -
                                    sample.LeftPalmFromHand;
                                float rightReach = Vector3.Distance(
                                    sample.RightArmPosition,
                                    requestedRightHand);
                                float leftReach = Vector3.Distance(
                                    sample.LeftArmPosition,
                                    requestedLeftHand);
                                if (rightReach < sample.RightMinimumReach ||
                                    rightReach > sample.RightMaximumReach ||
                                    leftReach < sample.LeftMinimumReach ||
                                    leftReach > sample.LeftMaximumReach)
                                {
                                    reachable = false;
                                    break;
                                }
                            }

                            if (!reachable)
                            {
                                continue;
                            }

                            foundAtScale = true;
                            bestOffsetScore = offsetScore;
                            bestOffset = offset;
                        }
                    }
                }

                if (!foundAtScale)
                {
                    continue;
                }

                selectedBaseOffset = bestOffset;
                selectedMotionScale = motionScale;
                break;
            }

            if (selectedMotionScale < 0f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike found no fixed-lateral two-hand path with at least 0.05m of the original forward motion inside both unchanged arm lengths.");
            }
        }

        private static Vector3 GetShotgunRequestedHandWorldPosition(
            Transform root,
            bool right,
            Vector3 requestedPalm,
            Quaternion requestedHandRotation)
        {
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            Vector3 palmLocal = hand.InverseTransformPoint(
                right
                    ? CalculateRightPalmSample(root).Center
                    : CalculateLeftPalmSample(root).Center);
            Quaternion sourceHandRotation = hand.rotation;
            hand.rotation = requestedHandRotation;
            Vector3 requestedHand = requestedPalm -
                (hand.TransformPoint(palmLocal) - hand.position);
            hand.rotation = sourceHandRotation;
            return requestedHand;
        }

        private static bool ShotgunArmTargetIsReachable(
            Transform root,
            bool right,
            Vector3 requestedHand,
            float reachReserve)
        {
            Transform arm = FindRequired(
                root,
                right ? RightArmPath : LeftArmPath);
            Transform foreArm = FindRequired(
                root,
                right ? RightForeArmPath : LeftForeArmPath);
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            float upperLength = Vector3.Distance(
                arm.position,
                foreArm.position);
            float lowerLength = Vector3.Distance(
                foreArm.position,
                hand.position);
            float reach = Vector3.Distance(arm.position, requestedHand);
            float minimumReach = Mathf.Abs(upperLength - lowerLength) +
                                 0.0001f;
            float maximumReach = upperLength + lowerLength -
                                 Mathf.Max(0.0001f, reachReserve);
            return reach >= minimumReach && reach <= maximumReach;
        }

        private static float ApplyShotgunSourcePlanePalmIk(
            Transform root,
            bool right,
            Vector3 requestedPalm,
            Quaternion requestedHandRotation,
            Vector3 sourceElbow,
            int iterationCount = 5)
        {
            Transform arm = FindRequired(
                root,
                right ? RightArmPath : LeftArmPath);
            Transform foreArm = FindRequired(
                root,
                right ? RightForeArmPath : LeftForeArmPath);
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            for (int iteration = 0;
                 iteration < iterationCount;
                 iteration++)
            {
                Vector3 requestedHand =
                    GetShotgunRequestedHandWorldPosition(
                        root,
                        right,
                        requestedPalm,
                        requestedHandRotation);
                SolveTwoBoneIk(
                    arm,
                    foreArm,
                    hand,
                    requestedHand,
                    sourceElbow);
                hand.rotation = requestedHandRotation;
            }
            return Vector3.Distance(
                right
                    ? CalculateRightPalmSample(root).Center
                    : CalculateLeftPalmSample(root).Center,
                requestedPalm);
        }

        private static Vector3
            GetShotgunRequestedHandWorldPositionForLocalRotation(
                Transform root,
                bool right,
                Vector3 requestedPalm,
                Quaternion requestedHandLocalRotation)
        {
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            Quaternion sourceHandLocalRotation = hand.localRotation;
            hand.localRotation = requestedHandLocalRotation;
            Vector3 currentPalm = right
                ? CalculateRightPalmSample(root).Center
                : CalculateLeftPalmSample(root).Center;
            Vector3 requestedHand = hand.position +
                                    (requestedPalm - currentPalm);
            hand.localRotation = sourceHandLocalRotation;
            return requestedHand;
        }

        private static float ApplyShotgunNaturalLocalWristPalmIk(
            Transform root,
            bool right,
            Vector3 requestedPalm,
            Quaternion requestedHandLocalRotation,
            Vector3 sourceElbow,
            int iterationCount = 5)
        {
            Transform arm = FindRequired(
                root,
                right ? RightArmPath : LeftArmPath);
            Transform foreArm = FindRequired(
                root,
                right ? RightForeArmPath : LeftForeArmPath);
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            for (int iteration = 0;
                 iteration < iterationCount;
                 iteration++)
            {
                hand.localRotation = requestedHandLocalRotation;
                Vector3 currentPalm = right
                    ? CalculateRightPalmSample(root).Center
                    : CalculateLeftPalmSample(root).Center;
                Vector3 requestedHand = hand.position +
                                        (requestedPalm - currentPalm);
                SolveTwoBoneIk(
                    arm,
                    foreArm,
                    hand,
                    requestedHand,
                    sourceElbow);
            }

            hand.localRotation = requestedHandLocalRotation;
            return Vector3.Distance(
                right
                    ? CalculateRightPalmSample(root).Center
                    : CalculateLeftPalmSample(root).Center,
                requestedPalm);
        }

        private static float AlignShotgunReloadNeutralWristHandRoll(
            Transform foreArm,
            Transform hand,
            Quaternion requestedHandWorldRotation)
        {
            Vector3 foreArmAxis = hand.position - foreArm.position;
            if (foreArmAxis.sqrMagnitude <= 0.0000001f)
            {
                return Quaternion.Angle(
                    hand.rotation,
                    requestedHandWorldRotation);
            }

            foreArmAxis.Normalize();
            Vector3 currentPalmNormal = Vector3.ProjectOnPlane(
                hand.right,
                foreArmAxis);
            Vector3 requestedPalmNormal = Vector3.ProjectOnPlane(
                requestedHandWorldRotation * Vector3.right,
                foreArmAxis);
            if (currentPalmNormal.sqrMagnitude <= 0.0000001f ||
                requestedPalmNormal.sqrMagnitude <= 0.0000001f)
            {
                return Quaternion.Angle(
                    hand.rotation,
                    requestedHandWorldRotation);
            }

            float rollDegrees = Vector3.SignedAngle(
                currentPalmNormal,
                requestedPalmNormal,
                foreArmAxis);
            foreArm.rotation = Quaternion.AngleAxis(
                rollDegrees,
                foreArmAxis) * foreArm.rotation;
            return Quaternion.Angle(
                hand.rotation,
                requestedHandWorldRotation);
        }

        private static void RedistributeShotgunReloadForeArmTwist(
            Transform foreArm,
            Transform hand,
            float twistDegrees)
        {
            Vector3 foreArmAxis = hand.position - foreArm.position;
            if (foreArmAxis.sqrMagnitude <= 0.0000001f)
            {
                return;
            }

            Quaternion authoredHandLocalRotation = hand.localRotation;
            Vector3 foreArmAxisLocal = hand.localPosition.normalized;
            foreArmAxis.Normalize();
            foreArm.rotation = Quaternion.AngleAxis(
                twistDegrees,
                foreArmAxis) * foreArm.rotation;
            hand.localRotation = Quaternion.AngleAxis(
                twistDegrees,
                foreArmAxisLocal) * authoredHandLocalRotation;
        }

        private static float RedistributeShotgunReloadHandTwistToForeArm(
            Transform foreArm,
            Transform hand,
            Quaternion neutralHandLocalRotation,
            ref float previousTwistDegrees,
            ref bool hasPreviousTwist)
        {
            Vector3 foreArmAxisLocal = hand.localPosition;
            Vector3 foreArmAxisWorld = foreArm.TransformDirection(
                foreArmAxisLocal);
            if (foreArmAxisLocal.sqrMagnitude <= 0.0000001f ||
                foreArmAxisWorld.sqrMagnitude <= 0.0000001f)
            {
                return 0f;
            }

            foreArmAxisLocal.Normalize();
            foreArmAxisWorld.Normalize();
            Quaternion naturalHandLocalRotation = hand.localRotation;
            Quaternion requestedHandWorldRotation = hand.rotation;
            Quaternion baseForeArmWorldRotation = foreArm.rotation;
            float bestTwistDegrees = 0f;
            float bestScore = float.PositiveInfinity;
            float bestNeutralDifference = float.PositiveInfinity;
            int sampleCount = Mathf.RoundToInt(
                ShotgunReloadMaximumWristTwistTransferDegrees * 2f);
            for (int sample = 0; sample <= sampleCount; sample++)
            {
                float twistDegrees =
                    -ShotgunReloadMaximumWristTwistTransferDegrees + sample;
                Quaternion candidate =
                    Quaternion.AngleAxis(
                        -twistDegrees,
                        foreArmAxisLocal) *
                    naturalHandLocalRotation;
                float neutralDifference = Quaternion.Angle(
                    neutralHandLocalRotation,
                    candidate);
                float continuityDifference = hasPreviousTwist
                    ? Mathf.Abs(Mathf.DeltaAngle(
                        previousTwistDegrees,
                        twistDegrees))
                    : 0f;
                float score = neutralDifference +
                              continuityDifference * 0.25f;
                if (score < bestScore)
                {
                    bestScore = score;
                    bestNeutralDifference = neutralDifference;
                    bestTwistDegrees = twistDegrees;
                }
            }

            float lower = Mathf.Max(
                -ShotgunReloadMaximumWristTwistTransferDegrees,
                bestTwistDegrees - 1f);
            float upper = Mathf.Min(
                ShotgunReloadMaximumWristTwistTransferDegrees,
                bestTwistDegrees + 1f);
            for (int iteration = 0; iteration < 12; iteration++)
            {
                float first = Mathf.Lerp(lower, upper, 1f / 3f);
                float second = Mathf.Lerp(lower, upper, 2f / 3f);
                float firstDifference = Quaternion.Angle(
                    neutralHandLocalRotation,
                    Quaternion.AngleAxis(-first, foreArmAxisLocal) *
                    naturalHandLocalRotation);
                float secondDifference = Quaternion.Angle(
                    neutralHandLocalRotation,
                    Quaternion.AngleAxis(-second, foreArmAxisLocal) *
                    naturalHandLocalRotation);
                if (hasPreviousTwist)
                {
                    firstDifference += Mathf.Abs(Mathf.DeltaAngle(
                        previousTwistDegrees,
                        first)) * 0.25f;
                    secondDifference += Mathf.Abs(Mathf.DeltaAngle(
                        previousTwistDegrees,
                        second)) * 0.25f;
                }
                if (firstDifference <= secondDifference)
                {
                    upper = second;
                }
                else
                {
                    lower = first;
                }
            }

            bestTwistDegrees = (lower + upper) * 0.5f;
            if (hasPreviousTwist)
            {
                bestTwistDegrees = previousTwistDegrees + Mathf.Clamp(
                    Mathf.DeltaAngle(
                        previousTwistDegrees,
                        bestTwistDegrees),
                    -ShotgunReloadMaximumWristTwistTransferStepDegrees,
                    ShotgunReloadMaximumWristTwistTransferStepDegrees);
            }
            hand.localRotation =
                Quaternion.AngleAxis(
                    -bestTwistDegrees,
                    foreArmAxisLocal) *
                naturalHandLocalRotation;
            float bestForeArmRollDegrees = 0f;
            float bestHandWorldDifference = float.PositiveInfinity;
            for (int sample = 0; sample <= 360; sample++)
            {
                float foreArmRollDegrees = -180f + sample;
                foreArm.rotation = Quaternion.AngleAxis(
                    foreArmRollDegrees,
                    foreArmAxisWorld) * baseForeArmWorldRotation;
                float handWorldDifference = Quaternion.Angle(
                    hand.rotation,
                    requestedHandWorldRotation);
                if (handWorldDifference < bestHandWorldDifference)
                {
                    bestHandWorldDifference = handWorldDifference;
                    bestForeArmRollDegrees = foreArmRollDegrees;
                }
            }

            lower = bestForeArmRollDegrees - 1f;
            upper = bestForeArmRollDegrees + 1f;
            for (int iteration = 0; iteration < 12; iteration++)
            {
                float first = Mathf.Lerp(lower, upper, 1f / 3f);
                float second = Mathf.Lerp(lower, upper, 2f / 3f);
                foreArm.rotation = Quaternion.AngleAxis(
                    first,
                    foreArmAxisWorld) * baseForeArmWorldRotation;
                float firstDifference = Quaternion.Angle(
                    hand.rotation,
                    requestedHandWorldRotation);
                foreArm.rotation = Quaternion.AngleAxis(
                    second,
                    foreArmAxisWorld) * baseForeArmWorldRotation;
                float secondDifference = Quaternion.Angle(
                    hand.rotation,
                    requestedHandWorldRotation);
                if (firstDifference <= secondDifference)
                {
                    upper = second;
                }
                else
                {
                    lower = first;
                }
            }

            bestForeArmRollDegrees = (lower + upper) * 0.5f;
            foreArm.rotation = Quaternion.AngleAxis(
                bestForeArmRollDegrees,
                foreArmAxisWorld) * baseForeArmWorldRotation;
            previousTwistDegrees = bestTwistDegrees;
            hasPreviousTwist = true;
            return bestNeutralDifference;
        }

        private static Vector3 GetShotgunReloadContinuousElbowPole(
            Transform root,
            Vector3 requestedHand,
            Vector3 authoredElbow,
            Vector3 previousElbowBendRootLocal,
            bool hasPreviousElbowBend)
        {
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Vector3 targetDirection = requestedHand - arm.position;
            if (targetDirection.sqrMagnitude <= 0.0000001f)
            {
                return authoredElbow;
            }

            targetDirection.Normalize();
            Vector3 authoredBend = Vector3.ProjectOnPlane(
                authoredElbow - arm.position,
                targetDirection);
            Vector3 previousBend = hasPreviousElbowBend
                ? Vector3.ProjectOnPlane(
                    root.TransformDirection(previousElbowBendRootLocal),
                    targetDirection)
                : Vector3.zero;
            if (authoredBend.sqrMagnitude <= 0.0000001f)
            {
                authoredBend = previousBend.sqrMagnitude > 0.0000001f
                    ? previousBend
                    : Vector3.ProjectOnPlane(
                        foreArm.position - arm.position,
                        targetDirection);
            }
            else if (previousBend.sqrMagnitude > 0.0000001f &&
                     Vector3.Dot(authoredBend, previousBend) < 0f)
            {
                authoredBend = -authoredBend;
            }

            if (authoredBend.sqrMagnitude <= 0.0000001f)
            {
                authoredBend = Vector3.Cross(targetDirection, root.forward);
            }

            authoredBend.Normalize();
            float poleDistance = Mathf.Max(
                0.1f,
                Vector3.Distance(arm.position, authoredElbow));
            return arm.position + authoredBend * poleDistance;
        }

        private static Vector3 GetShotgunReloadElbowBendRootLocal(
            Transform root)
        {
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Transform hand = FindRequired(root, LeftHandPath);
            Vector3 armDirection = hand.position - arm.position;
            Vector3 bend = Vector3.ProjectOnPlane(
                foreArm.position - arm.position,
                armDirection);
            if (bend.sqrMagnitude <= 0.0000001f)
            {
                return Vector3.zero;
            }

            return root.InverseTransformDirection(bend.normalized);
        }

        private static void AimShotgunReloadShoulderForFixedTargetReach(
            Transform root,
            Vector3 wristTarget)
        {
            Transform shoulder = FindRequired(root, LeftShoulderPath);
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Transform hand = FindRequired(root, LeftHandPath);
            float maximumReach =
                Vector3.Distance(arm.position, foreArm.position) +
                Vector3.Distance(foreArm.position, hand.position) -
                ShotgunReloadReachReserveMeters;
            if (Vector3.Distance(arm.position, wristTarget) <= maximumReach)
            {
                return;
            }

            Quaternion baseRotation = shoulder.rotation;
            Vector3 currentDirection = arm.position - shoulder.position;
            Vector3 targetDirection = wristTarget - shoulder.position;
            if (currentDirection.sqrMagnitude <= 0.000001f ||
                targetDirection.sqrMagnitude <= 0.000001f)
            {
                return;
            }

            Quaternion aimedRotation = Quaternion.FromToRotation(
                currentDirection,
                targetDirection) * baseRotation;
            shoulder.rotation = aimedRotation;
            if (Vector3.Distance(arm.position, wristTarget) > maximumReach)
            {
                return;
            }

            float lower = 0f;
            float upper = 1f;
            for (int iteration = 0; iteration < 12; iteration++)
            {
                float midpoint = (lower + upper) * 0.5f;
                shoulder.rotation = Quaternion.Slerp(
                    baseRotation,
                    aimedRotation,
                    midpoint);
                if (Vector3.Distance(arm.position, wristTarget) <=
                    maximumReach)
                {
                    upper = midpoint;
                }
                else
                {
                    lower = midpoint;
                }
            }

            shoulder.rotation = Quaternion.Slerp(
                baseRotation,
                aimedRotation,
                upper);
        }

        private static Quaternion GetShotgunReloadReachableHandRotation(
            Transform root,
            Vector3 requestedPalm,
            Quaternion desiredHandWorldRotation,
            Vector3 sourceElbow,
            out float adjustmentDegrees)
        {
            Transform shoulder = FindRequired(root, LeftShoulderPath);
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Transform hand = FindRequired(root, LeftHandPath);
            Quaternion baseShoulderLocalRotation = shoulder.localRotation;
            Quaternion baseArmLocalRotation = arm.localRotation;
            Quaternion baseForeArmLocalRotation = foreArm.localRotation;
            Quaternion baseHandLocalRotation = hand.localRotation;
            hand.rotation = desiredHandWorldRotation;
            Vector3 palmOffset =
                CalculateLeftPalmSample(root).Center - hand.position;
            hand.localRotation = baseHandLocalRotation;
            Vector3 reachDirection = requestedPalm - arm.position;
            if (palmOffset.sqrMagnitude <= 0.000001f ||
                reachDirection.sqrMagnitude <= 0.000001f)
            {
                adjustmentDegrees = 0f;
                return desiredHandWorldRotation;
            }

            Quaternion maximumExtensionRotation =
                Quaternion.FromToRotation(
                    palmOffset,
                    reachDirection) *
                desiredHandWorldRotation;
            float EvaluateVisiblePalmError(
                float weight,
                out Quaternion candidate)
            {
                shoulder.localRotation = baseShoulderLocalRotation;
                arm.localRotation = baseArmLocalRotation;
                foreArm.localRotation = baseForeArmLocalRotation;
                hand.localRotation = baseHandLocalRotation;
                candidate = Quaternion.Slerp(
                    desiredHandWorldRotation,
                    maximumExtensionRotation,
                    weight);
                Vector3 wristTarget = GetShotgunRequestedHandWorldPosition(
                    root,
                    false,
                    requestedPalm,
                    candidate);
                AimShotgunReloadShoulderForFixedTargetReach(
                    root,
                    wristTarget);
                return ApplyShotgunSourcePlanePalmIk(
                    root,
                    false,
                    requestedPalm,
                    candidate,
                    sourceElbow,
                    10);
            }

            Quaternion selectedRotation;
            float lower = 0f;
            float lowerError = EvaluateVisiblePalmError(
                lower,
                out selectedRotation);
            if (lowerError > 0.001f)
            {
                float upper = 1f;
                float upperError = EvaluateVisiblePalmError(
                    upper,
                    out Quaternion upperRotation);
                selectedRotation = upperRotation;
                if (upperError <= 0.001f)
                {
                    for (int iteration = 0; iteration < 12; iteration++)
                    {
                        float midpoint = (lower + upper) * 0.5f;
                        float midpointError = EvaluateVisiblePalmError(
                            midpoint,
                            out Quaternion midpointRotation);
                        if (midpointError <= 0.001f)
                        {
                            upper = midpoint;
                            selectedRotation = midpointRotation;
                        }
                        else
                        {
                            lower = midpoint;
                        }
                    }
                }
            }

            shoulder.localRotation = baseShoulderLocalRotation;
            arm.localRotation = baseArmLocalRotation;
            foreArm.localRotation = baseForeArmLocalRotation;
            hand.localRotation = baseHandLocalRotation;
            adjustmentDegrees = Quaternion.Angle(
                desiredHandWorldRotation,
                selectedRotation);
            return selectedRotation;
        }

        private static void StabilizeShotgunForeArmTwistForFixedHandRotation(
            Transform root,
            bool right,
            Quaternion sourceForeArmLocalRotation,
            Quaternion sourceHandLocalRotation,
            Quaternion requestedHandWorldRotation,
            ref Quaternion previousForeArmLocalRotation,
            ref Quaternion previousHandLocalRotation,
            ref bool hasPreviousRotation)
        {
            Transform foreArm = FindRequired(
                root,
                right ? RightForeArmPath : LeftForeArmPath);
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            Quaternion baseForeArmWorldRotation = foreArm.rotation;
            Vector3 foreArmAxis = hand.position - foreArm.position;
            if (foreArmAxis.sqrMagnitude < 0.0000001f)
            {
                throw new InvalidOperationException(
                    "Shotgun " + (right ? "right" : "left") +
                    " forearm has no usable wrist-twist axis.");
            }

            foreArmAxis.Normalize();
            float bestScore = float.PositiveInfinity;
            Quaternion bestForeArmLocalRotation = foreArm.localRotation;
            Quaternion bestHandLocalRotation = hand.localRotation;
            for (int sample = 0; sample <= 180; sample++)
            {
                float twistDegrees = -180f + sample * 2f;
                foreArm.rotation = Quaternion.AngleAxis(
                    twistDegrees,
                    foreArmAxis) * baseForeArmWorldRotation;
                hand.rotation = requestedHandWorldRotation;
                float sourceScore = Mathf.Max(
                    Quaternion.Angle(
                        sourceForeArmLocalRotation,
                        foreArm.localRotation),
                    Quaternion.Angle(
                        sourceHandLocalRotation,
                        hand.localRotation));
                float continuityScore = hasPreviousRotation
                    ? Mathf.Max(
                        Quaternion.Angle(
                            previousForeArmLocalRotation,
                            foreArm.localRotation),
                        Quaternion.Angle(
                            previousHandLocalRotation,
                            hand.localRotation))
                    : sourceScore;
                float score = hasPreviousRotation
                    ? continuityScore * 6f + sourceScore * 0.2f
                    : sourceScore;
                if (score >= bestScore)
                {
                    continue;
                }

                bestScore = score;
                bestForeArmLocalRotation = foreArm.localRotation;
                bestHandLocalRotation = hand.localRotation;
            }

            foreArm.localRotation = bestForeArmLocalRotation;
            hand.localRotation = bestHandLocalRotation;
            previousForeArmLocalRotation = bestForeArmLocalRotation;
            previousHandLocalRotation = bestHandLocalRotation;
            hasPreviousRotation = true;
        }

        private static Vector3
            FindShotgunButtStrikeFixedUpperLeftMuzzleDirection(
                GameObject workObject,
                AnimationClip source,
                ShotgunGripAnalysis analysis,
                ShotgunGripPoseReference heldReference,
                Vector3 leftHandleItemLocal,
                Vector3 rightSupportItemLocal,
                out Vector3 initialItemPosition)
        {
            Transform root = workObject.transform;
            Vector3 requestedDirection =
                (-Vector3.right + Vector3.up - Vector3.forward)
                .normalized;
            Vector3 selectedDirection = Vector3.zero;
            Vector3 selectedPosition = Vector3.zero;
            float selectedScore = float.NegativeInfinity;
            float selectedDisplacement = float.PositiveInfinity;
            source.SampleAnimation(workObject, 0f);
            Vector3 currentLeftPalm =
                CalculateLeftPalmSample(root).Center;
            Vector3 currentRightPalm =
                CalculateRightPalmSample(root).Center;
            Vector3 currentGripVector =
                currentRightPalm - currentLeftPalm;
            for (int pitchDegrees = 5;
                 pitchDegrees <= 80;
                 pitchDegrees += 5)
            {
                for (int yawDegrees = 5;
                     yawDegrees <= 80;
                     yawDegrees += 5)
                {
                        float pitchRadians =
                            pitchDegrees * Mathf.Deg2Rad;
                        float yawRadians = yawDegrees * Mathf.Deg2Rad;
                        float horizontal = Mathf.Cos(pitchRadians);
                        Vector3 candidate = new Vector3(
                            -Mathf.Sin(yawRadians) * horizontal,
                            Mathf.Sin(pitchRadians),
                            -Mathf.Cos(yawRadians) * horizontal);
                        float stockFrontDot = Vector3.Dot(
                            -candidate,
                            Vector3.forward);
                        float muzzleLeftDot = Vector3.Dot(
                            candidate,
                            -Vector3.right);
                        float muzzleUpDot = Vector3.Dot(
                            candidate,
                            Vector3.up);
                        if (stockFrontDot < 0.05f ||
                            muzzleLeftDot < 0.05f ||
                            muzzleUpDot < 0.05f)
                        {
                            continue;
                        }

                        Transform item = FindRequired(
                            root,
                            RightHandPath + "/" +
                            ShotgunHandInstanceName);
                        item.localScale = heldReference.ItemLocalScale;
                        item.rotation = AlignShotgunAxes(
                            analysis.Geometry.StockToMuzzleAxis,
                            analysis.Geometry.TriggerDirectionAxis,
                            root.TransformDirection(candidate),
                            -root.up);
                        Vector3 leftGripOffset = item.TransformPoint(
                                leftHandleItemLocal) -
                            item.position;
                        Vector3 rightGripOffset = item.TransformPoint(
                                rightSupportItemLocal) -
                            item.position;
                        Vector3 candidateGripVector =
                            rightGripOffset - leftGripOffset;
                        float displacement = Vector3.Distance(
                            currentGripVector,
                            candidateGripVector);
                        Vector3 candidatePosition =
                            (currentLeftPalm - leftGripOffset +
                             currentRightPalm - rightGripOffset) * 0.5f;

                        float score = Vector3.Dot(
                            candidate,
                            requestedDirection);
                        if (displacement <
                                selectedDisplacement - 0.0001f ||
                            Mathf.Abs(
                                displacement - selectedDisplacement) <=
                            0.0001f && score > selectedScore)
                        {
                            selectedDirection = candidate;
                            selectedPosition = candidatePosition;
                            selectedScore = score;
                            selectedDisplacement = displacement;
                        }
                }
            }

            if (selectedDirection.sqrMagnitude < 0.99f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike found no fixed muzzle-left/up and stock-front direction that retains the current two-hand grip positions.");
            }

            initialItemPosition = selectedPosition;
            return selectedDirection;
        }

        private static bool ShotgunButtStrikeFixedGripPoseIsReachable(
            Transform root,
            Transform item,
            Vector3 leftHandleItemLocal,
            Vector3 rightSupportItemLocal)
        {
            return ShotgunArmTargetIsReachable(
                       root,
                       false,
                       item.TransformPoint(leftHandleItemLocal),
                       0.0005f) &&
                   ShotgunArmTargetIsReachable(
                       root,
                       true,
                       item.TransformPoint(rightSupportItemLocal),
                       0.0005f);
        }

        private static float GetShotgunButtStrikeFixedGripStraightAdvance(
            GameObject workObject,
            AnimationClip source,
            ShotgunGripAnalysis analysis,
            ShotgunGripPoseReference heldReference,
            Vector3 fixedItemRootPosition,
            Quaternion fixedItemRootRotation,
            Vector3 leftHandleItemLocal,
            Vector3 rightSupportItemLocal)
        {
            bool ReachesAtAdvance(float advanceMeters)
            {
                Transform root = workObject.transform;
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / Mathf.Max(1f, source.frameRate));
                    float sampleTime = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            source.length -
                            1f / Mathf.Max(1f, source.frameRate))
                        : time;
                    source.SampleAnimation(workObject, sampleTime);
                    Transform item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    item.localScale = heldReference.ItemLocalScale;
                    item.rotation = root.rotation * fixedItemRootRotation;
                    item.position = root.TransformPoint(
                                        fixedItemRootPosition) +
                                    root.forward *
                                    (GetShotgunButtStrikeImpactWeight(
                                         time,
                                         source.length) * advanceMeters);
                    Quaternion requestedLeftHandRotation = item.rotation *
                        heldReference.LeftHandItemRotation;
                    Quaternion requestedRightHandRotation = item.rotation *
                        heldReference.RightHandItemRotation;
                    Vector3 requestedLeftHand =
                        GetShotgunRequestedHandWorldPosition(
                            root,
                            false,
                            item.TransformPoint(leftHandleItemLocal),
                            requestedLeftHandRotation);
                    Vector3 requestedRightHand =
                        GetShotgunRequestedHandWorldPosition(
                            root,
                            true,
                            item.TransformPoint(rightSupportItemLocal),
                            requestedRightHandRotation);
                    if (!ShotgunArmTargetIsReachable(
                            root,
                            false,
                            requestedLeftHand,
                            0.0005f) ||
                        !ShotgunArmTargetIsReachable(
                            root,
                            true,
                            requestedRightHand,
                            0.0005f))
                    {
                        return false;
                    }
                }

                return true;
            }

            if (!ReachesAtAdvance(0f))
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike fixed upper-left muzzle pose is outside the current two-hand grip reach.");
            }

            if (ReachesAtAdvance(ShotgunButtStrikeImpactAdvanceMeters))
            {
                return ShotgunButtStrikeImpactAdvanceMeters;
            }

            float lower = 0f;
            float upper = ShotgunButtStrikeImpactAdvanceMeters;
            for (int iteration = 0; iteration < 16; iteration++)
            {
                float midpoint = (lower + upper) * 0.5f;
                if (ReachesAtAdvance(midpoint))
                {
                    lower = midpoint;
                }
                else
                {
                    upper = midpoint;
                }
            }

            if (lower < 0.05f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike fixed grip cannot produce a forceful straight stock thrust. ReachableAdvance=" +
                    Num(lower) + ".");
            }

            return lower;
        }

        private static Vector3 GetShotgunReloadActionPalmItemLocal(
            ShotgunGripAnalysis analysis,
            Vector3 itemLocalScale)
        {
            float scale = Mathf.Max(
                0.000001f,
                Mathf.Abs(itemLocalScale.x));
            return analysis.ReloadActionPoint -
                   analysis.Geometry.TriggerDirectionAxis.normalized *
                   (ShotgunPalmSurfaceOffsetMeters / scale);
        }

        private static Vector3
            GetShotgunReloadPerformerLeftOffsetItemLocal(
                Transform root,
                Transform item,
                ShotgunGripAnalysis analysis,
                Vector3 itemLocalScale)
        {
            Vector3 stock = analysis.Geometry.LocalStockPoint;
            Vector3 longAxis =
                analysis.Geometry.StockToMuzzleAxis.normalized;
            Vector3 thicknessAxis =
                analysis.Geometry.ThicknessAxis.normalized;
            Vector3[] actionSlice = analysis.Geometry.LocalVertices
                .Where(vertex =>
                {
                    float ratio = Vector3.Dot(vertex - stock, longAxis) /
                                  analysis.Geometry.SourceLength;
                    return ratio >= 0.40f && ratio <= 0.52f;
                })
                .ToArray();
            if (actionSlice.Length == 0)
            {
                throw new InvalidOperationException(
                    "Shotgun reload action has no usable left-side surface vertices.");
            }

            float performerLeftSign = Vector3.Dot(
                    item.TransformDirection(thicknessAxis),
                    -root.right.normalized) >= 0f
                ? 1f
                : -1f;
            float sideCoordinate = performerLeftSign > 0f
                ? actionSlice.Max(vertex => Vector3.Dot(vertex, thicknessAxis))
                : actionSlice.Min(vertex => Vector3.Dot(vertex, thicknessAxis));
            float actionCoordinate = Vector3.Dot(
                analysis.ReloadActionPoint,
                thicknessAxis);
            float scale = Mathf.Max(
                0.000001f,
                Mathf.Abs(itemLocalScale.x));
            float surfaceOffset =
                performerLeftSign * ShotgunPalmSurfaceOffsetMeters / scale;
            return thicknessAxis *
                   (sideCoordinate - actionCoordinate + surfaceOffset);
        }

        private static Vector3 GetShotgunReloadTopPullToIdlePalmItemLocal(
            ShotgunGripAnalysis analysis,
            Vector3 itemLocalScale,
            Vector3 idleSupportItemLocal,
            Vector3 performerLeftOffsetItemLocal,
            float time,
            float duration)
        {
            float pullStart = Mathf.Max(
                0f,
                duration * ShotgunReloadStartNormalized);
            float pullEnd = Mathf.Min(
                duration,
                pullStart + ShotgunReloadPullSeconds);
            float returnEnd = Mathf.Min(
                duration,
                pullEnd + ShotgunReloadDetachedTravelSeconds);
            float scale = Mathf.Max(
                0.000001f,
                Mathf.Abs(itemLocalScale.x));
            Vector3 action = GetShotgunReloadActionPalmItemLocal(
                analysis,
                itemLocalScale) + performerLeftOffsetItemLocal;
            Vector3 pulled = action -
                analysis.Geometry.StockToMuzzleAxis.normalized *
                (ShotgunReloadPullDistanceMeters / scale);
            if (time <= pullStart)
            {
                float reach = Mathf.SmoothStep(
                    0f,
                    1f,
                    Mathf.InverseLerp(0f, pullStart, time));
                return Vector3.Lerp(idleSupportItemLocal, action, reach);
            }

            if (time <= pullEnd)
            {
                float pull = Mathf.SmoothStep(
                    0f,
                    1f,
                    Mathf.InverseLerp(pullStart, pullEnd, time));
                return Vector3.Lerp(action, pulled, pull);
            }

            if (time <= returnEnd)
            {
                float travel = Mathf.SmoothStep(
                    0f,
                    1f,
                    Mathf.InverseLerp(pullEnd, returnEnd, time));
                return Vector3.Lerp(pulled, idleSupportItemLocal, travel);
            }

            return idleSupportItemLocal;
        }

        private static Quaternion GetShotgunReloadTopPullToIdleHandRotation(
            Quaternion itemRotation,
            Quaternion actionHandWorldRotation,
            Quaternion idleHandItemRotation,
            float time,
            float duration)
        {
            float pullStart = Mathf.Max(
                0f,
                duration * ShotgunReloadStartNormalized);
            float pullEnd = Mathf.Min(
                duration,
                pullStart + ShotgunReloadPullSeconds);
            float returnEnd = Mathf.Min(
                duration,
                pullEnd + ShotgunReloadDetachedTravelSeconds);
            Quaternion idleHandWorldRotation =
                itemRotation * idleHandItemRotation;
            if (time <= pullStart)
            {
                float reach = Mathf.SmoothStep(
                    0f,
                    1f,
                    Mathf.InverseLerp(0f, pullStart, time));
                return Quaternion.Slerp(
                    idleHandWorldRotation,
                    actionHandWorldRotation,
                    reach);
            }

            if (time <= pullEnd)
            {
                return actionHandWorldRotation;
            }

            if (time <= returnEnd)
            {
                float travel = Mathf.SmoothStep(
                    0f,
                    1f,
                    Mathf.InverseLerp(pullEnd, returnEnd, time));
                return Quaternion.Slerp(
                    actionHandWorldRotation,
                    idleHandWorldRotation,
                    travel);
            }

            return idleHandWorldRotation;
        }

        private static Vector3 GetShotgunReloadForwardSupportItemLocal(
            Transform item,
            ShotgunGripAnalysis analysis,
            Vector3 currentSupportItemLocal)
        {
            return GetShotgunReloadForwardSupportItemLocal(
                item,
                analysis,
                currentSupportItemLocal,
                out _);
        }

        private static Vector3 GetShotgunReloadForwardSupportItemLocal(
            Transform item,
            ShotgunGripAnalysis analysis,
            Vector3 currentSupportItemLocal,
            out Vector3 supportSurfaceItemLocal)
        {
            Vector3 longAxis =
                analysis.Geometry.StockToMuzzleAxis.normalized;
            Vector3 triggerAxis =
                analysis.Geometry.TriggerDirectionAxis.normalized;
            Vector3 thicknessAxis =
                analysis.Geometry.ThicknessAxis.normalized;
            Vector3 muzzleDirection = item.TransformDirection(
                longAxis).normalized;
            Vector3 shiftedItemLocal = item.InverseTransformPoint(
                item.TransformPoint(currentSupportItemLocal) +
                muzzleDirection * ShotgunReloadForwardSupportShiftMeters);
            float supportCoordinate = Vector3.Dot(
                shiftedItemLocal,
                longAxis);
            float nearestSliceDistance = analysis.Geometry.LocalVertices
                .Min(vertex => Mathf.Abs(
                    Vector3.Dot(vertex, longAxis) - supportCoordinate));
            float sliceTolerance = Mathf.Max(
                0.00001f,
                analysis.Geometry.SourceLength * 0.001f);
            Vector3[] supportSlice = analysis.Geometry.LocalVertices
                .Where(vertex => Mathf.Abs(
                    Mathf.Abs(
                        Vector3.Dot(vertex, longAxis) - supportCoordinate) -
                    nearestSliceDistance) <= sliceTolerance)
                .ToArray();
            if (supportSlice.Length == 0)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload has no usable lower-barrel support cross-section at the requested muzzleward position.");
            }

            float undersideCoordinate = supportSlice.Max(vertex =>
                Vector3.Dot(vertex, triggerAxis));
            float minimumThickness = supportSlice.Min(vertex =>
                Vector3.Dot(vertex, thicknessAxis));
            float maximumThickness = supportSlice.Max(vertex =>
                Vector3.Dot(vertex, thicknessAxis));
            float thicknessCoordinate =
                (minimumThickness + maximumThickness) * 0.5f;
            supportSurfaceItemLocal =
                longAxis * supportCoordinate +
                triggerAxis * undersideCoordinate +
                thicknessAxis * thicknessCoordinate;
            float triggerScale = Mathf.Max(
                0.000001f,
                item.TransformVector(triggerAxis).magnitude);
            return supportSurfaceItemLocal +
                   triggerAxis *
                   (ShotgunPalmSurfaceOffsetMeters / triggerScale);
        }

        private static float MeasureShotgunReloadSupportForwardShiftMeters(
            Transform item,
            ShotgunGripAnalysis analysis,
            Vector3 currentSupportItemLocal,
            Vector3 shiftedSupportItemLocal)
        {
            Vector3 muzzleDirection = item.TransformDirection(
                analysis.Geometry.StockToMuzzleAxis).normalized;
            return Vector3.Dot(
                item.TransformPoint(shiftedSupportItemLocal) -
                item.TransformPoint(currentSupportItemLocal),
                muzzleDirection);
        }

        private static Vector3 GetShotgunReloadWristReturnPalmWorld(
            Transform item,
            ShotgunGripAnalysis analysis,
            Vector3 pulledPalmItemLocal,
            Vector3 idleSupportItemLocal,
            float time,
            float pullEnd,
            float returnEnd)
        {
            float returnWeight = Mathf.SmoothStep(
                0f,
                1f,
                Mathf.InverseLerp(pullEnd, returnEnd, time));
            Vector3 directPalm = item.TransformPoint(
                Vector3.Lerp(
                    pulledPalmItemLocal,
                    idleSupportItemLocal,
                    returnWeight));
            float detachWeight = Mathf.Sin(returnWeight * Mathf.PI);
            return directPalm +
                   GetShotgunReloadSeparationDirectionWorld(item, analysis) *
                   (ShotgunReloadVisibleDetachArcMeters * detachWeight);
        }

        private static Vector3 GetShotgunReloadSeparationDirectionWorld(
            Transform item,
            ShotgunGripAnalysis analysis)
        {
            Vector3 direction = item.TransformDirection(
                analysis.Geometry.TriggerDirectionAxis);
            if (direction.sqrMagnitude <= 0.000001f)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload has no usable action-surface separation direction.");
            }

            return direction.normalized;
        }

        private static float MeasureLeftHandShotgunProjectedGapMeters(
            Transform root,
            Transform item,
            ShotgunGripAnalysis analysis,
            Vector3 separationDirection)
        {
            Vector3 direction = separationDirection.normalized;
            Transform hand = FindRequired(root, LeftHandPath);
            float minimumHandProjection = float.PositiveInfinity;
            int weightedVertexCount = 0;
            foreach (SkinnedMeshRenderer renderer in root
                         .GetComponentsInChildren<SkinnedMeshRenderer>(true))
            {
                Mesh mesh = renderer.sharedMesh;
                if (mesh == null)
                {
                    continue;
                }

                Transform[] bones = renderer.bones;
                HashSet<int> handBoneIndices = new HashSet<int>();
                for (int index = 0; index < bones.Length; index++)
                {
                    Transform bone = bones[index];
                    if (bone != null &&
                        (bone == hand || bone.IsChildOf(hand)))
                    {
                        handBoneIndices.Add(index);
                    }
                }

                if (handBoneIndices.Count == 0)
                {
                    continue;
                }

                BoneWeight[] boneWeights = mesh.boneWeights;
                if (boneWeights.Length != mesh.vertexCount)
                {
                    throw new InvalidOperationException(
                        renderer.name +
                        " has no readable per-vertex bone weights for LeftHand clearance.");
                }

                Mesh bakedMesh = new Mesh
                {
                    name = renderer.name + "_LeftHandClearanceBake"
                };
                try
                {
                    renderer.BakeMesh(bakedMesh, true);
                    Vector3[] vertices = bakedMesh.vertices;
                    for (int index = 0; index < vertices.Length; index++)
                    {
                        if (BoneWeightForIndices(
                                boneWeights[index],
                                handBoneIndices) <
                            RightHandVertexWeightThreshold)
                        {
                            continue;
                        }

                        Vector3 worldPosition = renderer.transform
                            .TransformPoint(vertices[index]);
                        minimumHandProjection = Mathf.Min(
                            minimumHandProjection,
                            Vector3.Dot(worldPosition, direction));
                        weightedVertexCount++;
                    }
                }
                finally
                {
                    UnityEngine.Object.DestroyImmediate(bakedMesh);
                }
            }

            if (weightedVertexCount == 0)
            {
                throw new InvalidOperationException(
                    root.name +
                    " has no visible LeftHand vertices for shotgun separation measurement.");
            }

            float maximumShotgunProjection = analysis.Geometry.LocalVertices
                .Max(vertex => Vector3.Dot(
                    item.TransformPoint(vertex),
                    direction));
            return minimumHandProjection - maximumShotgunProjection;
        }

        private static void BakeShotgunReloadTopPullToIdle(
            AnimationClip destination,
            AnimationClip source,
            Transform template,
            ShotgunGripAnalysis analysis,
            ShotgunGripPoseReference heldReference,
            ShotgunGripPoseReference idleReference)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name = ShotgunReloadTargetName +
                              "TopPullToIdleBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                TransformCurveTrack leftShoulderTrack =
                    new TransformCurveTrack(LeftShoulderPath);
                TransformCurveTrack leftArmTrack =
                    new TransformCurveTrack(LeftArmPath);
                TransformCurveTrack leftForeArmTrack =
                    new TransformCurveTrack(LeftForeArmPath);
                TransformCurveTrack leftHandTrack =
                    new TransformCurveTrack(LeftHandPath);
                TransformCurveTrack rightForeArmTrack =
                    new TransformCurveTrack(RightForeArmPath);
                TransformCurveTrack rightHandTrack =
                    new TransformCurveTrack(RightHandPath);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                float maximumLeftGripError = 0f;
                float maximumRightGripError = 0f;
                float minimumTriggerDownDot = 1f;
                float minimumRightPalmLeftDot = 1f;
                float maximumLeftWristStepDegrees = 0f;
                float maximumRightWristStepDegrees = 0f;
                float endMuzzleForwardDot = -1f;
                float muzzleLowerEndTime = Mathf.Max(
                    GetShotgunReloadSupportHoldStartTime(source.length),
                    source.length -
                    1f / Mathf.Max(1f, source.frameRate));
                Quaternion previousRightForeArmRotation =
                    Quaternion.identity;
                Quaternion previousRightHandRotation = Quaternion.identity;
                Quaternion stableRightHandPerformerRotation =
                    Quaternion.identity;
                bool hasPreviousRightWristRotation = false;
                Quaternion measuredPreviousRightForeArmRotation =
                    Quaternion.identity;
                Quaternion measuredPreviousRightHandRotation =
                    Quaternion.identity;
                bool hasMeasuredPreviousRightWristRotation = false;
                Quaternion previousLeftForeArmRotation =
                    Quaternion.identity;
                Quaternion previousLeftHandRotation = Quaternion.identity;
                bool hasPreviousLeftWristRotation = false;
                Quaternion measuredPreviousLeftForeArmRotation =
                    Quaternion.identity;
                Quaternion measuredPreviousLeftHandRotation =
                    Quaternion.identity;
                bool hasMeasuredPreviousLeftWristRotation = false;
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                float pullStart = Mathf.Max(
                    0f,
                    source.length * ShotgunReloadStartNormalized);
                float pullEnd = Mathf.Min(
                    source.length,
                    pullStart + ShotgunReloadPullSeconds);
                source.SampleAnimation(workObject, pullEnd);
                Quaternion actionLeftHandPerformerRotation =
                    Quaternion.Inverse(root.rotation) *
                    FindRequired(root, LeftHandPath).rotation;
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / Mathf.Max(1f, source.frameRate));
                    float sampleTime = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            source.length -
                            1f / Mathf.Max(1f, source.frameRate))
                        : time;
                    source.SampleAnimation(workObject, sampleTime);
                    Transform sourceLeftForeArm = FindRequired(
                        root,
                        LeftForeArmPath);
                    Transform sourceLeftHand = FindRequired(
                        root,
                        LeftHandPath);
                    Quaternion sourceLeftForeArmLocalRotation =
                        sourceLeftForeArm.localRotation;
                    Quaternion sourceLeftHandLocalRotation =
                        sourceLeftHand.localRotation;
                    Quaternion actionLeftHandWorldRotation =
                        root.rotation * actionLeftHandPerformerRotation;
                    Transform item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    item.localRotation = heldReference.ItemLocalRotation;
                    item.localScale = heldReference.ItemLocalScale;
                    Vector3 sourceStockToMuzzleDirection =
                        item.TransformDirection(
                                analysis.Geometry.StockToMuzzleAxis)
                            .normalized;
                    AdjustShotgunRightArmForPalmFacingPerformerLeft(
                        root,
                        ref previousRightForeArmRotation,
                        ref previousRightHandRotation,
                        ref stableRightHandPerformerRotation,
                        ref hasPreviousRightWristRotation);
                    AttachShotgunToCurrentRightPalmTriggerDown(
                        root,
                        item,
                        analysis,
                        heldReference,
                        sourceStockToMuzzleDirection);
                    float supportHoldStart =
                        GetShotgunReloadSupportHoldStartTime(source.length);
                    float muzzleLowerWeight = Mathf.SmoothStep(
                        0f,
                        1f,
                        Mathf.InverseLerp(
                            supportHoldStart,
                            muzzleLowerEndTime,
                            time));
                    Vector3 loweredStockToMuzzleDirection = Vector3.Slerp(
                            sourceStockToMuzzleDirection,
                            root.forward.normalized,
                            muzzleLowerWeight)
                        .normalized;
                    item.rotation = AlignShotgunAxes(
                        analysis.Geometry.StockToMuzzleAxis,
                        analysis.Geometry.TriggerDirectionAxis,
                        loweredStockToMuzzleDirection,
                        -root.up);
                    item.position +=
                        CalculateRightPalmSample(root).Center -
                        item.TransformPoint(
                            heldReference.RightPalmItemLocal);
                    Transform rightForeArm = FindRequired(
                        root,
                        RightForeArmPath);
                    Transform rightHand = FindRequired(root, RightHandPath);
                    minimumRightPalmLeftDot = Mathf.Min(
                        minimumRightPalmLeftDot,
                        Vector3.Dot(
                            -rightHand.right.normalized,
                            -root.right.normalized));
                    if (hasMeasuredPreviousRightWristRotation)
                    {
                        maximumRightWristStepDegrees = Mathf.Max(
                            maximumRightWristStepDegrees,
                            Mathf.Max(
                                Quaternion.Angle(
                                    measuredPreviousRightForeArmRotation,
                                    rightForeArm.localRotation),
                                Quaternion.Angle(
                                    measuredPreviousRightHandRotation,
                                    rightHand.localRotation)));
                    }
                    measuredPreviousRightForeArmRotation =
                        rightForeArm.localRotation;
                    measuredPreviousRightHandRotation =
                        rightHand.localRotation;
                    hasMeasuredPreviousRightWristRotation = true;
                    if (frame == frameCount)
                    {
                        endMuzzleForwardDot = Vector3.Dot(
                            item.TransformDirection(
                                    analysis.Geometry.StockToMuzzleAxis)
                                .normalized,
                            root.forward.normalized);
                    }
                    minimumTriggerDownDot = Mathf.Min(
                        minimumTriggerDownDot,
                        Vector3.Dot(
                            item.TransformDirection(
                                    analysis.Geometry.TriggerDirectionAxis)
                                .normalized,
                            Vector3.ProjectOnPlane(
                                    -root.up,
                                    item.TransformDirection(
                                        analysis.Geometry.StockToMuzzleAxis))
                                .normalized));
                    Vector3 requestedLeftPalm = item.TransformPoint(
                        GetShotgunReloadTopPullToIdlePalmItemLocal(
                            analysis,
                            heldReference.ItemLocalScale,
                            idleReference.LeftPalmItemLocal,
                            GetShotgunReloadPerformerLeftOffsetItemLocal(
                                root,
                                item,
                                analysis,
                                heldReference.ItemLocalScale),
                            time,
                            source.length));
                    Quaternion requestedLeftHandRotation =
                        GetShotgunReloadTopPullToIdleHandRotation(
                            item.rotation,
                            actionLeftHandWorldRotation,
                            idleReference.LeftHandItemRotation,
                            time,
                            source.length);
                    maximumLeftGripError = Mathf.Max(
                        maximumLeftGripError,
                        ApplyShotgunMinimalLeftGripIk(
                            root,
                            requestedLeftPalm,
                            requestedLeftHandRotation));
                    StabilizeShotgunForeArmTwistForFixedHandRotation(
                        root,
                        false,
                        sourceLeftForeArmLocalRotation,
                        sourceLeftHandLocalRotation,
                        requestedLeftHandRotation,
                        ref previousLeftForeArmRotation,
                        ref previousLeftHandRotation,
                        ref hasPreviousLeftWristRotation);
                    Transform resolvedLeftForeArm = FindRequired(
                        root,
                        LeftForeArmPath);
                    Transform resolvedLeftHand = FindRequired(
                        root,
                        LeftHandPath);
                    maximumLeftGripError = Mathf.Max(
                        maximumLeftGripError,
                        Vector3.Distance(
                            CalculateLeftPalmSample(root).Center,
                            requestedLeftPalm));
                    if (hasMeasuredPreviousLeftWristRotation)
                    {
                        maximumLeftWristStepDegrees = Mathf.Max(
                            maximumLeftWristStepDegrees,
                            Mathf.Max(
                                Quaternion.Angle(
                                    measuredPreviousLeftForeArmRotation,
                                    resolvedLeftForeArm.localRotation),
                                Quaternion.Angle(
                                    measuredPreviousLeftHandRotation,
                                    resolvedLeftHand.localRotation)));
                    }

                    measuredPreviousLeftForeArmRotation =
                        resolvedLeftForeArm.localRotation;
                    measuredPreviousLeftHandRotation =
                        resolvedLeftHand.localRotation;
                    hasMeasuredPreviousLeftWristRotation = true;
                    maximumRightGripError = Mathf.Max(
                        maximumRightGripError,
                        Vector3.Distance(
                            CalculateRightPalmSample(root).Center,
                            item.TransformPoint(
                                heldReference.RightPalmItemLocal)));

                    leftShoulderTrack.Add(
                        time,
                        FindRequired(root, LeftShoulderPath));
                    leftArmTrack.Add(time, FindRequired(root, LeftArmPath));
                    leftForeArmTrack.Add(
                        time,
                        FindRequired(root, LeftForeArmPath));
                    leftHandTrack.Add(time, FindRequired(root, LeftHandPath));
                    rightForeArmTrack.Add(time, rightForeArm);
                    rightHandTrack.Add(time, rightHand);
                    itemTrack.Add(time, item);
                }

                if (maximumLeftGripError > 0.006f ||
                    maximumRightGripError > 0.002f ||
                    minimumTriggerDownDot < 0.995f ||
                    minimumRightPalmLeftDot < 0.995f ||
                    maximumLeftWristStepDegrees > 45f ||
                    maximumRightWristStepDegrees > 45f ||
                    endMuzzleForwardDot < 0.995f)
                {
                    throw new InvalidOperationException(
                        "Shotgun_Reload top-pull support checks failed. LeftGrip=" +
                        Num(maximumLeftGripError) + ", RightGrip=" +
                        Num(maximumRightGripError) + ", TriggerDownDot=" +
                        Num(minimumTriggerDownDot) + ", RightPalmLeftDot=" +
                        Num(minimumRightPalmLeftDot) +
                        ", LeftWristStep=" +
                        Num(maximumLeftWristStepDegrees) +
                        ", RightWristStep=" +
                        Num(maximumRightWristStepDegrees) +
                        ", EndMuzzleForwardDot=" +
                        Num(endMuzzleForwardDot) + ".");
                }

                SetRotationTrackCurves(destination, leftShoulderTrack);
                SetRotationTrackCurves(destination, leftArmTrack);
                SetRotationTrackCurves(destination, leftForeArmTrack);
                SetRotationTrackCurves(destination, leftHandTrack);
                SetRotationTrackCurves(destination, rightForeArmTrack);
                SetRotationTrackCurves(destination, rightHandTrack);
                SetTransformTrackCurves(destination, itemTrack);
                SetShotgunItemScaleCurves(
                    destination,
                    itemTrack.Path,
                    heldReference.ItemLocalScale,
                    destination.length);
                AnimationClipSettings settings =
                    AnimationUtility.GetAnimationClipSettings(destination);
                settings.loopTime = true;
                settings.loopBlend = false;
                AnimationUtility.SetAnimationClipSettings(
                    destination,
                    settings);
                EditorUtility.SetDirty(destination);
                Debug.Log(
                    "[PlayerShotgunReloadTopPullToIdle] Support checks passed before save. LeftGrip=" +
                    Num(maximumLeftGripError) + ", RightGrip=" +
                    Num(maximumRightGripError) + ", TriggerDownDot=" +
                    Num(minimumTriggerDownDot) + ", RightPalmLeftDot=" +
                    Num(minimumRightPalmLeftDot) +
                    ", LeftWristStep=" +
                    Num(maximumLeftWristStepDegrees) +
                    ", RightWristStep=" +
                    Num(maximumRightWristStepDegrees) +
                    ", EndMuzzleForwardDot=" +
                    Num(endMuzzleForwardDot) + ".");
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        internal static void CaptureShotgunButtStrikeMixamoGripLockedFinal()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike Mixamo grip-lock capture must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunButtStrikeTargetName);
            Animator animator = RequireAnimator(target);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunButtStrikeTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_ButtStrike corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(
                            ShotgunButtStrikeTargetName)));
            AnimationClip source = LoadSingleEmbeddedClip(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeTargetName);
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            string[] shoulderPaths =
            {
                LeftShoulderPath,
                RightShoulderPath
            };
            bool shouldersExact = string.Equals(
                HashSelectedTransformCurves(source, shoulderPaths),
                HashSelectedTransformCurves(clip, shoulderPaths),
                StringComparison.Ordinal);
            bool armPositionScaleExact = string.Equals(
                HashSelectedPositionScaleCurves(
                    source,
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath,
                    RightShoulderPath,
                    RightArmPath,
                    RightForeArmPath,
                    RightHandPath),
                HashSelectedPositionScaleCurves(
                    clip,
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath,
                    RightShoulderPath,
                    RightArmPath,
                    RightForeArmPath,
                    RightHandPath),
                StringComparison.Ordinal);
            bool timingExact = Mathf.Abs(clip.length - source.length) <=
                                   0.0001f &&
                               Mathf.Abs(clip.frameRate - source.frameRate) <=
                                   0.0001f;
            bool sourceAnimationExact = string.Equals(
                HashAnimationClipContent(source),
                HashAnimationClipContent(clip),
                StringComparison.Ordinal);
            float maximumLeftGripDistance = 0f;
            float maximumRightGripDistance = 0f;
            float maximumLeftHandItemRotationDrift = 0f;
            float maximumRightHandItemRotationDrift = 0f;
            float minimumStockCoordinate = float.PositiveInfinity;
            float maximumStockCoordinate = float.NegativeInfinity;
            float impactStockForwardDot = -1f;
            float minimumStockElevationDegrees = float.PositiveInfinity;
            float maximumStockElevationDegrees = float.NegativeInfinity;
            float originalStockElevationDegrees = Mathf.Asin(
                    (Vector3.right - Vector3.up + Vector3.forward)
                    .normalized.y) *
                Mathf.Rad2Deg;
            float impactTime = 0f;
            float maximumRightPalmTravel = 0f;
            float maximumItemLateralDrift = 0f;
            float maximumItemVerticalDrift = 0f;
            Vector3 initialRightPalm = Vector3.zero;
            Vector3 initialItemRootPosition = Vector3.zero;
            Quaternion initialLeftHandItemRotation = Quaternion.identity;
            Quaternion initialRightHandItemRotation = Quaternion.identity;
            bool hasInitial = false;
            int frameCount = Mathf.Max(
                1,
                Mathf.RoundToInt(clip.length * clip.frameRate));
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                {
                    for (int frame = 0; frame <= frameCount; frame++)
                    {
                        float time = frame == frameCount
                            ? Mathf.Max(
                                0f,
                                clip.length -
                                1f / Mathf.Max(1f, clip.frameRate))
                            : frame / Mathf.Max(1f, clip.frameRate);
                        sampler.Sample(time);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Transform leftHand = FindRequired(
                            target,
                            LeftHandPath);
                        Transform rightHand = FindRequired(
                            target,
                            RightHandPath);
                        RightHandPalmSample leftPalm =
                            CalculateLeftPalmSample(target);
                        RightHandPalmSample rightPalm =
                            CalculateRightPalmSample(target);
                        Vector3 leftSupportItemLocal =
                            GetShotgunButtStrikeRightSupportPalmItemLocal(
                                analysis,
                                item.localScale);
                        Vector3 rightHandleItemLocal =
                            GetShotgunButtStrikeLeftHandlePalmItemLocal(
                                analysis,
                                item.localScale);
                        Quaternion leftHandItemRotation = Quaternion.Inverse(
                            item.rotation) * leftHand.rotation;
                        Quaternion rightHandItemRotation = Quaternion.Inverse(
                            item.rotation) * rightHand.rotation;
                        if (!hasInitial)
                        {
                            initialRightPalm = rightPalm.Center;
                            initialItemRootPosition =
                                target.InverseTransformPoint(item.position);
                            initialLeftHandItemRotation =
                                leftHandItemRotation;
                            initialRightHandItemRotation =
                                rightHandItemRotation;
                            hasInitial = true;
                        }
                        Vector3 itemRootPosition =
                            target.InverseTransformPoint(item.position);
                        maximumItemLateralDrift = Mathf.Max(
                            maximumItemLateralDrift,
                            Mathf.Abs(
                                itemRootPosition.x -
                                initialItemRootPosition.x));
                        maximumItemVerticalDrift = Mathf.Max(
                            maximumItemVerticalDrift,
                            Mathf.Abs(
                                itemRootPosition.y -
                                initialItemRootPosition.y));
                        maximumLeftGripDistance = Mathf.Max(
                            maximumLeftGripDistance,
                            Vector3.Distance(
                                leftPalm.Center,
                                item.TransformPoint(leftSupportItemLocal)));
                        maximumRightGripDistance = Mathf.Max(
                            maximumRightGripDistance,
                            Vector3.Distance(
                                rightPalm.Center,
                                item.TransformPoint(rightHandleItemLocal)));
                        maximumLeftHandItemRotationDrift = Mathf.Max(
                            maximumLeftHandItemRotationDrift,
                            Quaternion.Angle(
                                initialLeftHandItemRotation,
                                leftHandItemRotation));
                        maximumRightHandItemRotationDrift = Mathf.Max(
                            maximumRightHandItemRotationDrift,
                            Quaternion.Angle(
                                initialRightHandItemRotation,
                                rightHandItemRotation));
                        maximumRightPalmTravel = Mathf.Max(
                            maximumRightPalmTravel,
                            Vector3.Distance(
                                initialRightPalm,
                                rightPalm.Center));
                        Vector3 stockDirection =
                            -item.TransformDirection(
                                    analysis.Geometry.StockToMuzzleAxis)
                                .normalized;
                        float stockElevationDegrees = Mathf.Asin(
                                Mathf.Clamp(
                                    Vector3.Dot(
                                        stockDirection,
                                        target.up.normalized),
                                    -1f,
                                    1f)) *
                            Mathf.Rad2Deg;
                        minimumStockElevationDegrees = Mathf.Min(
                            minimumStockElevationDegrees,
                            stockElevationDegrees);
                        maximumStockElevationDegrees = Mathf.Max(
                            maximumStockElevationDegrees,
                            stockElevationDegrees);
                        float stockCoordinate = Vector3.Dot(
                            item.TransformPoint(
                                    analysis.Geometry.LocalStockPoint) -
                                target.position,
                            target.forward.normalized);
                        minimumStockCoordinate = Mathf.Min(
                            minimumStockCoordinate,
                            stockCoordinate);
                        if (stockCoordinate > maximumStockCoordinate)
                        {
                            maximumStockCoordinate = stockCoordinate;
                            impactTime = time;
                            impactStockForwardDot = Vector3.Dot(
                                stockDirection,
                                target.forward.normalized);
                        }
                    }
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            float stockTravel = maximumStockCoordinate -
                                minimumStockCoordinate;
            if (!armPositionScaleExact || !timingExact)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike final review requires unchanged arm position/scale curves and exact Mixamo timing. ArmPositionScaleExact=" +
                    armPositionScaleExact + ", TimingExact=" + timingExact + ".");
            }

            List<List<byte[]>> rows = new List<List<byte[]>>
            {
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>()
            };
            float impactPhase = clip.length > 0.0001f
                ? Mathf.Clamp01(impactTime / clip.length)
                : 0.5f;
            float[] phases =
            {
                0f,
                Mathf.Clamp01(impactPhase - 0.20f),
                impactPhase,
                Mathf.Clamp01(impactPhase + 0.20f),
                0.99f
            };
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    foreach (float phase in phases)
                    {
                        sampler.Sample(phase * clip.length);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Vector3 weaponCenter =
                            (item.TransformPoint(
                                 analysis.Geometry.LocalStockPoint) +
                             item.TransformPoint(
                                 analysis.Geometry.LocalMuzzlePoint)) * 0.5f;
                        environment.ConfigureView(
                            target,
                            weaponCenter,
                            1.0f);
                        rows[0].Add(environment.CaptureFront());
                        rows[1].Add(environment.CaptureSide());
                        Vector3 handsCenter =
                            (CalculateRightPalmSample(target).Center +
                             CalculateLeftPalmSample(target).Center) * 0.5f;
                        environment.ConfigurePalmView(
                            target,
                            handsCenter,
                            target.right,
                            0.62f);
                        rows[2].Add(
                            environment.CapturePalmFromTorso());
                    }
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            string outputPath = Path.Combine(
                Path.GetFullPath(Path.Combine(Application.dataPath, "..")),
                "Temp",
                "ShotgunButtStrikeStockRaised20Final.png");
            ComposeRows(rows, outputPath);
            Debug.Log(
                "[PlayerShotgunButtStrikeStockRaised20] Final direct review captured with the original performer-forward-right buttstock direction raised by 20 degrees while the performer-right palm remains on the trigger-side handle and performer-left palm remains on the muzzle-side underside support. SourceExactDiagnostic=" +
                sourceAnimationExact + ", ArmPositionScaleExact=" +
                armPositionScaleExact + ", TimingExact=" + timingExact +
                ", StockElevationDegrees=" +
                Num(minimumStockElevationDegrees) + "-" +
                Num(maximumStockElevationDegrees) +
                ", StockElevationRaiseDegrees=" +
                Num(minimumStockElevationDegrees -
                    originalStockElevationDegrees) + "-" +
                Num(maximumStockElevationDegrees -
                    originalStockElevationDegrees) +
                ", ImpactStockForwardDot=" + Num(impactStockForwardDot) +
                ", Output=" + outputPath + ".");
        }

        internal static void CaptureShotgunReloadTopPullToIdleFinal()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload top-pull capture must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunReloadTargetName);
            Animator animator = RequireAnimator(target);
            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(candidate => string.Equals(
                    candidate.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal));
            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                spec.ClipPath) ??
                throw new FileNotFoundException(
                    "Original Shotgun_Reload source copy is missing.",
                    Path.GetFullPath(spec.ClipPath));
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunReloadTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_Reload corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(
                            ShotgunReloadTargetName)));
            AnimationClip idle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunIdleTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_Idle corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(ShotgunIdleTargetName)));
            ShotgunGripPoseReference idleReference =
                ReadShotgunGripPoseReference(target, idle, 0f);
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            string[] rightArmPaths =
            {
                RightShoulderPath,
                RightArmPath,
                RightForeArmPath,
                RightHandPath
            };
            bool rightArmExact = string.Equals(
                HashSelectedTransformCurves(source, rightArmPaths),
                HashSelectedTransformCurves(clip, rightArmPaths),
                StringComparison.Ordinal);
            bool armPositionScaleExact = string.Equals(
                HashSelectedPositionScaleCurves(
                    source,
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath),
                HashSelectedPositionScaleCurves(
                    clip,
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath),
                StringComparison.Ordinal);
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(clip);
            float pullStart = Mathf.Max(
                0f,
                clip.length * ShotgunReloadStartNormalized);
            float pullEnd = Mathf.Min(
                clip.length,
                pullStart + ShotgunReloadPullSeconds);
            float returnEnd = Mathf.Min(
                clip.length,
                pullEnd + ShotgunReloadDetachedTravelSeconds);
            float maximumExpectedPathError = 0f;
            float maximumIdleHoldDistance = 0f;
            float maximumIdleHoldRotationDrift = 0f;
            float maximumRightGripDistance = 0f;
            Vector3 itemScale = Vector3.one;
            Vector3 measuredActionLocal = Vector3.zero;
            Vector3 measuredPulledLocal = Vector3.zero;
            Quaternion idleHoldRotation = Quaternion.identity;
            bool hasIdleHoldRotation = false;
            int frameCount = Mathf.Max(
                1,
                Mathf.RoundToInt(clip.length * clip.frameRate));
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                {
                    for (int frame = 0; frame <= frameCount; frame++)
                    {
                        float time = frame == frameCount
                            ? Mathf.Max(
                                0f,
                                clip.length -
                                1f / Mathf.Max(1f, clip.frameRate))
                            : frame / Mathf.Max(1f, clip.frameRate);
                        sampler.Sample(time);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Transform leftHand = FindRequired(
                            target,
                            LeftHandPath);
                        itemScale = item.localScale;
                        Vector3 leftPalmLocal = item.InverseTransformPoint(
                            CalculateLeftPalmSample(target).Center);
                        Vector3 expected =
                            GetShotgunReloadTopPullToIdlePalmItemLocal(
                                analysis,
                                item.localScale,
                                idleReference.LeftPalmItemLocal,
                                GetShotgunReloadPerformerLeftOffsetItemLocal(
                                    target,
                                    item,
                                    analysis,
                                    item.localScale),
                                time,
                                clip.length);
                        maximumExpectedPathError = Mathf.Max(
                            maximumExpectedPathError,
                            Vector3.Scale(
                                leftPalmLocal - expected,
                                item.lossyScale).magnitude);
                        maximumRightGripDistance = Mathf.Max(
                            maximumRightGripDistance,
                            Vector3.Distance(
                                CalculateRightPalmSample(target).Center,
                                item.TransformPoint(analysis.HandlePoint)));
                        if (time >= returnEnd)
                        {
                            maximumIdleHoldDistance = Mathf.Max(
                                maximumIdleHoldDistance,
                                Vector3.Scale(
                                    leftPalmLocal -
                                    idleReference.LeftPalmItemLocal,
                                    item.lossyScale).magnitude);
                            Quaternion handItemRotation = Quaternion.Inverse(
                                item.rotation) * leftHand.rotation;
                            if (!hasIdleHoldRotation)
                            {
                                idleHoldRotation = handItemRotation;
                                hasIdleHoldRotation = true;
                            }
                            maximumIdleHoldRotationDrift = Mathf.Max(
                                maximumIdleHoldRotationDrift,
                                Quaternion.Angle(
                                    idleHoldRotation,
                                    handItemRotation));
                        }
                    }

                    sampler.Sample(pullStart);
                    Transform actionItem = FindRequired(
                        target,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    measuredActionLocal = actionItem.InverseTransformPoint(
                        CalculateLeftPalmSample(target).Center);
                    sampler.Sample(pullEnd);
                    Transform pulledItem = FindRequired(
                        target,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    measuredPulledLocal = pulledItem.InverseTransformPoint(
                        CalculateLeftPalmSample(target).Center);
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            Vector3 measuredPullVector = measuredActionLocal -
                                         measuredPulledLocal;
            float measuredPullDistance = Vector3.Scale(
                measuredPullVector,
                itemScale).magnitude;
            float pullAxisDot = measuredPullVector.sqrMagnitude >
                                    0.0000001f
                ? Vector3.Dot(
                    measuredPullVector.normalized,
                    analysis.Geometry.StockToMuzzleAxis.normalized)
                : -1f;
            bool timingExact = Mathf.Abs(clip.length - source.length) <=
                                   0.0001f &&
                               Mathf.Abs(clip.frameRate - source.frameRate) <=
                                   0.0001f;
            if (!rightArmExact ||
                !armPositionScaleExact ||
                !timingExact ||
                !settings.loopTime ||
                maximumExpectedPathError > 0.008f ||
                maximumIdleHoldDistance > 0.008f ||
                maximumIdleHoldRotationDrift > 1f ||
                maximumRightGripDistance > 0.012f ||
                Mathf.Abs(
                    measuredPullDistance -
                    ShotgunReloadPullDistanceMeters) > 0.015f ||
                pullAxisDot < 0.98f)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload top-pull final support checks failed. RightArmExact=" +
                    rightArmExact + ", ArmPositionScaleExact=" +
                    armPositionScaleExact + ", TimingExact=" +
                    timingExact + ", Loop=" + settings.loopTime +
                    ", PathError=" + Num(maximumExpectedPathError) +
                    ", IdleHoldDistance=" +
                    Num(maximumIdleHoldDistance) +
                    ", IdleHoldRotation=" +
                    Num(maximumIdleHoldRotationDrift) +
                    ", RightGrip=" + Num(maximumRightGripDistance) +
                    ", PullDistance=" + Num(measuredPullDistance) +
                    ", PullAxisDot=" + Num(pullAxisDot) + ".");
            }

            List<List<byte[]>> rows = new List<List<byte[]>>
            {
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>()
            };
            float[] reviewTimes =
            {
                0f,
                pullStart,
                pullEnd,
                Mathf.Lerp(pullEnd, returnEnd, 0.5f),
                returnEnd,
                Mathf.Max(0f, clip.length - 1f / Mathf.Max(1f, clip.frameRate))
            };
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    foreach (float time in reviewTimes)
                    {
                        sampler.Sample(time);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Vector3 weaponCenter =
                            (item.TransformPoint(
                                 analysis.Geometry.LocalStockPoint) +
                             item.TransformPoint(
                                 analysis.Geometry.LocalMuzzlePoint)) * 0.5f;
                        environment.ConfigureView(
                            target,
                            weaponCenter,
                            1.0f);
                        rows[0].Add(environment.CaptureFront());
                        rows[1].Add(environment.CaptureSide());
                        Vector3 handsCenter =
                            (CalculateRightPalmSample(target).Center +
                             CalculateLeftPalmSample(target).Center) * 0.5f;
                        environment.ConfigurePalmView(
                            target,
                            handsCenter,
                            target.right,
                            0.62f);
                        rows[2].Add(
                            environment.CapturePalmFromTorso());
                    }
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            string outputPath = Path.Combine(
                Path.GetFullPath(Path.Combine(Application.dataPath, "..")),
                "Temp",
                "ShotgunReloadTopPullToIdleFinal.png");
            ComposeRows(rows, outputPath);
            Debug.Log(
                "[PlayerShotgunReloadTopPullToIdle] Final direct review captured after support checks passed. RightArmExact=" +
                rightArmExact + ", ArmPositionScaleExact=" +
                armPositionScaleExact + ", PathError=" +
                Num(maximumExpectedPathError) + ", IdleHoldDistance=" +
                Num(maximumIdleHoldDistance) + ", IdleHoldRotation=" +
                Num(maximumIdleHoldRotationDrift) + ", RightGrip=" +
                Num(maximumRightGripDistance) + ", PullDistance=" +
                Num(measuredPullDistance) + ", PullAxisDot=" +
                Num(pullAxisDot) + ", Output=" + outputPath + ".");
        }

        internal static void ApplyShotgunButtStrikeStraightThrustCorrection()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike straight-thrust correction must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunButtStrikeTargetName);
            AnimationClip buttIdle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(
                    ShotgunButtModeIdleTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_ButtMode_Idle corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(
                            ShotgunButtModeIdleTargetName)));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            AnimationClip corrected = CreateOrUpdateExactShotgunClipCopy(
                buttIdle,
                GetShotgunCorrectedClipPath(ShotgunButtStrikeTargetName),
                ShotgunButtStrikeTargetName + "_Corrected");
            BakeShotgunButtStrikeStraightThrust(
                corrected,
                target,
                analysis);

            AssetDatabase.SaveAssets();
            Debug.Log(
                "[PlayerShotgunButtStrikeStraightThrust] Updated only Shotgun_ButtStrike from the stable ButtMode_Idle two-hand pose: both grips stay fixed while the stock moves straight forward and returns without lateral arm swing.");
        }

        internal static void CaptureShotgunButtStrikeStraightThrustFinal()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike straight-thrust capture must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ShotgunButtStrikeTargetName);
            Animator animator = RequireAnimator(target);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GetShotgunCorrectedClipPath(ShotgunButtStrikeTargetName)) ??
                throw new FileNotFoundException(
                    "Shotgun_ButtStrike corrected clip is missing.",
                    Path.GetFullPath(
                        GetShotgunCorrectedClipPath(
                            ShotgunButtStrikeTargetName)));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            Vector3 bodySideRightGripPoint =
                GetShotgunButtBodySideRightGripPoint(analysis);
            Quaternion heldItemRootRotation = Quaternion.identity;
            Quaternion heldLeftHandItemRotation = Quaternion.identity;
            Quaternion heldRightHandItemRotation = Quaternion.identity;
            Quaternion previousItemWorldRotation = Quaternion.identity;
            Vector3 startItemRootPosition = Vector3.zero;
            Vector3 endItemRootPosition = Vector3.zero;
            float startLeftElbowLateral = 0f;
            float startRightElbowLateral = 0f;
            float startLeftPalmLateral = 0f;
            float startRightPalmLateral = 0f;
            float maximumItemDirectionDriftDegrees = 0f;
            float maximumItemWorldStepDegrees = 0f;
            float minimumStockForwardDot = 1f;
            float maximumLeftHandleDistance = 0f;
            float maximumRightGripDistance = 0f;
            float maximumLeftHandItemRotationDrift = 0f;
            float maximumRightHandItemRotationDrift = 0f;
            float maximumOffAxisItemTravelMeters = 0f;
            float maximumForwardAdvanceMeters = 0f;
            float maximumLeftElbowLateralDriftMeters = 0f;
            float maximumRightElbowLateralDriftMeters = 0f;
            float maximumLeftElbowLateralStepMeters = 0f;
            float maximumRightElbowLateralStepMeters = 0f;
            float maximumLeftPalmLateralDriftMeters = 0f;
            float maximumRightPalmLateralDriftMeters = 0f;
            float previousLeftElbowLateral = 0f;
            float previousRightElbowLateral = 0f;
            float previousLeftElbowLateralDelta = 0f;
            float previousRightElbowLateralDelta = 0f;
            int leftElbowLateralDirectionChanges = 0;
            int rightElbowLateralDirectionChanges = 0;
            bool hasReference = false;
            bool hasPreviousItemWorldRotation = false;
            bool hasPreviousElbowLateral = false;
            int frameCount = Mathf.Max(
                1,
                Mathf.RoundToInt(clip.length * clip.frameRate));
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                {
                    for (int frame = 0; frame <= frameCount; frame++)
                    {
                        float time = Mathf.Min(
                            clip.length,
                            frame / Mathf.Max(1f, clip.frameRate));
                        sampler.Sample(time);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Transform leftForeArm = FindRequired(
                            target,
                            LeftForeArmPath);
                        Transform rightForeArm = FindRequired(
                            target,
                            RightForeArmPath);
                        Transform leftHand = FindRequired(target, LeftHandPath);
                        Transform rightHand = FindRequired(target, RightHandPath);
                        RightHandPalmSample leftPalm =
                            CalculateLeftPalmSample(target);
                        RightHandPalmSample rightPalm =
                            CalculateRightPalmSample(target);
                        Quaternion itemRootRotation = Quaternion.Inverse(
                            target.rotation) * item.rotation;
                        Quaternion leftHandItemRotation = Quaternion.Inverse(
                            item.rotation) * leftHand.rotation;
                        Quaternion rightHandItemRotation = Quaternion.Inverse(
                            item.rotation) * rightHand.rotation;
                        Vector3 itemRootPosition = target.InverseTransformPoint(
                            item.position);
                        float leftElbowLateral = Vector3.Dot(
                            leftForeArm.position - target.position,
                            target.right.normalized);
                        float rightElbowLateral = Vector3.Dot(
                            rightForeArm.position - target.position,
                            target.right.normalized);
                        float leftPalmLateral = Vector3.Dot(
                            leftPalm.Center - target.position,
                            target.right.normalized);
                        float rightPalmLateral = Vector3.Dot(
                            rightPalm.Center - target.position,
                            target.right.normalized);
                        if (!hasReference)
                        {
                            heldItemRootRotation = itemRootRotation;
                            heldLeftHandItemRotation = leftHandItemRotation;
                            heldRightHandItemRotation = rightHandItemRotation;
                            startItemRootPosition = itemRootPosition;
                            startLeftElbowLateral = leftElbowLateral;
                            startRightElbowLateral = rightElbowLateral;
                            startLeftPalmLateral = leftPalmLateral;
                            startRightPalmLateral = rightPalmLateral;
                            hasReference = true;
                        }

                        Vector3 itemTravel = itemRootPosition -
                                             startItemRootPosition;
                        maximumForwardAdvanceMeters = Mathf.Max(
                            maximumForwardAdvanceMeters,
                            itemTravel.z);
                        maximumOffAxisItemTravelMeters = Mathf.Max(
                            maximumOffAxisItemTravelMeters,
                            new Vector2(itemTravel.x, itemTravel.y).magnitude);
                        maximumItemDirectionDriftDegrees = Mathf.Max(
                            maximumItemDirectionDriftDegrees,
                            Quaternion.Angle(
                                heldItemRootRotation,
                                itemRootRotation));
                        maximumLeftHandItemRotationDrift = Mathf.Max(
                            maximumLeftHandItemRotationDrift,
                            Quaternion.Angle(
                                heldLeftHandItemRotation,
                                leftHandItemRotation));
                        maximumRightHandItemRotationDrift = Mathf.Max(
                            maximumRightHandItemRotationDrift,
                            Quaternion.Angle(
                                heldRightHandItemRotation,
                                rightHandItemRotation));
                        if (hasPreviousItemWorldRotation)
                        {
                            maximumItemWorldStepDegrees = Mathf.Max(
                                maximumItemWorldStepDegrees,
                                Quaternion.Angle(
                                    previousItemWorldRotation,
                                    item.rotation));
                        }
                        previousItemWorldRotation = item.rotation;
                        hasPreviousItemWorldRotation = true;

                        Vector3 stockForward = -item.TransformDirection(
                                analysis.Geometry.StockToMuzzleAxis)
                            .normalized;
                        minimumStockForwardDot = Mathf.Min(
                            minimumStockForwardDot,
                            Vector3.Dot(
                                stockForward,
                                target.forward.normalized));
                        maximumLeftHandleDistance = Mathf.Max(
                            maximumLeftHandleDistance,
                            Vector3.Distance(
                                leftPalm.Center,
                                item.TransformPoint(analysis.HandlePoint)));
                        maximumRightGripDistance = Mathf.Max(
                            maximumRightGripDistance,
                            Vector3.Distance(
                                rightPalm.Center,
                                item.TransformPoint(bodySideRightGripPoint)));
                        maximumLeftElbowLateralDriftMeters = Mathf.Max(
                            maximumLeftElbowLateralDriftMeters,
                            Mathf.Abs(leftElbowLateral -
                                      startLeftElbowLateral));
                        maximumRightElbowLateralDriftMeters = Mathf.Max(
                            maximumRightElbowLateralDriftMeters,
                            Mathf.Abs(rightElbowLateral -
                                      startRightElbowLateral));
                        if (hasPreviousElbowLateral)
                        {
                            float leftDelta = leftElbowLateral -
                                              previousLeftElbowLateral;
                            float rightDelta = rightElbowLateral -
                                               previousRightElbowLateral;
                            maximumLeftElbowLateralStepMeters = Mathf.Max(
                                maximumLeftElbowLateralStepMeters,
                                Mathf.Abs(leftDelta));
                            maximumRightElbowLateralStepMeters = Mathf.Max(
                                maximumRightElbowLateralStepMeters,
                                Mathf.Abs(rightDelta));
                            const float directionChangeEpsilonMeters = 0.0005f;
                            if (Mathf.Abs(leftDelta) >
                                    directionChangeEpsilonMeters &&
                                Mathf.Abs(previousLeftElbowLateralDelta) >
                                    directionChangeEpsilonMeters &&
                                Mathf.Sign(leftDelta) != Mathf.Sign(
                                    previousLeftElbowLateralDelta))
                            {
                                leftElbowLateralDirectionChanges++;
                            }
                            if (Mathf.Abs(rightDelta) >
                                    directionChangeEpsilonMeters &&
                                Mathf.Abs(previousRightElbowLateralDelta) >
                                    directionChangeEpsilonMeters &&
                                Mathf.Sign(rightDelta) != Mathf.Sign(
                                    previousRightElbowLateralDelta))
                            {
                                rightElbowLateralDirectionChanges++;
                            }
                            if (Mathf.Abs(leftDelta) >
                                directionChangeEpsilonMeters)
                            {
                                previousLeftElbowLateralDelta = leftDelta;
                            }
                            if (Mathf.Abs(rightDelta) >
                                directionChangeEpsilonMeters)
                            {
                                previousRightElbowLateralDelta = rightDelta;
                            }
                        }
                        previousLeftElbowLateral = leftElbowLateral;
                        previousRightElbowLateral = rightElbowLateral;
                        hasPreviousElbowLateral = true;
                        maximumLeftPalmLateralDriftMeters = Mathf.Max(
                            maximumLeftPalmLateralDriftMeters,
                            Mathf.Abs(leftPalmLateral -
                                      startLeftPalmLateral));
                        maximumRightPalmLateralDriftMeters = Mathf.Max(
                            maximumRightPalmLateralDriftMeters,
                            Mathf.Abs(rightPalmLateral -
                                      startRightPalmLateral));
                        endItemRootPosition = itemRootPosition;
                    }
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            float returnDistanceMeters = Vector3.Distance(
                startItemRootPosition,
                endItemRootPosition);
            if (maximumItemDirectionDriftDegrees > 2f ||
                maximumItemWorldStepDegrees > 2f ||
                minimumStockForwardDot < 0.75f ||
                maximumLeftHandleDistance > 0.012f ||
                maximumRightGripDistance > 0.012f ||
                maximumLeftHandItemRotationDrift > 2f ||
                maximumRightHandItemRotationDrift > 2f ||
                maximumForwardAdvanceMeters < 0.02f ||
                maximumOffAxisItemTravelMeters > 0.015f ||
                returnDistanceMeters > 0.015f ||
                maximumLeftElbowLateralStepMeters > 0.01f ||
                maximumRightElbowLateralStepMeters > 0.01f ||
                leftElbowLateralDirectionChanges > 2 ||
                rightElbowLateralDirectionChanges > 2 ||
                maximumLeftPalmLateralDriftMeters > 0.015f ||
                maximumRightPalmLateralDriftMeters > 0.015f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike straight-thrust support checks failed. " +
                    "ItemDirectionDrift=" +
                    Num(maximumItemDirectionDriftDegrees) +
                    ", ItemWorldStep=" +
                    Num(maximumItemWorldStepDegrees) +
                    ", StockForwardDot=" + Num(minimumStockForwardDot) +
                    ", LeftHandle=" + Num(maximumLeftHandleDistance) +
                    ", RightGrip=" + Num(maximumRightGripDistance) +
                    ", LeftHandItemRotation=" +
                    Num(maximumLeftHandItemRotationDrift) +
                    ", RightHandItemRotation=" +
                    Num(maximumRightHandItemRotationDrift) +
                    ", ForwardAdvance=" +
                    Num(maximumForwardAdvanceMeters) +
                    ", OffAxisItemTravel=" +
                    Num(maximumOffAxisItemTravelMeters) +
                    ", ReturnDistance=" + Num(returnDistanceMeters) +
                    ", LeftElbowLateral=" +
                    Num(maximumLeftElbowLateralDriftMeters) +
                    ", RightElbowLateral=" +
                    Num(maximumRightElbowLateralDriftMeters) +
                    ", LeftElbowLateralStep=" +
                    Num(maximumLeftElbowLateralStepMeters) +
                    ", RightElbowLateralStep=" +
                    Num(maximumRightElbowLateralStepMeters) +
                    ", LeftElbowDirectionChanges=" +
                    leftElbowLateralDirectionChanges.ToString(
                        CultureInfo.InvariantCulture) +
                    ", RightElbowDirectionChanges=" +
                    rightElbowLateralDirectionChanges.ToString(
                        CultureInfo.InvariantCulture) +
                    ", LeftPalmLateral=" +
                    Num(maximumLeftPalmLateralDriftMeters) +
                    ", RightPalmLateral=" +
                    Num(maximumRightPalmLateralDriftMeters) + ".");
            }

            List<List<byte[]>> rows = new List<List<byte[]>>
            {
                new List<byte[]>(),
                new List<byte[]>(),
                new List<byte[]>()
            };
            float[] reviewPhases = { 0f, 0.34f, 0.50f, 0.66f, 1f };
            try
            {
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, clip))
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    foreach (float phase in reviewPhases)
                    {
                        sampler.Sample(phase * clip.length);
                        Transform item = FindRequired(
                            target,
                            RightHandPath + "/" + ShotgunHandInstanceName);
                        Vector3 weaponCenter =
                            (item.TransformPoint(
                                 analysis.Geometry.LocalStockPoint) +
                             item.TransformPoint(
                                 analysis.Geometry.LocalMuzzlePoint)) * 0.5f;
                        environment.ConfigureView(target, weaponCenter, 1.0f);
                        rows[0].Add(environment.CaptureFront());
                        rows[1].Add(environment.CaptureSide());
                        Vector3 handsCenter =
                            (CalculateRightPalmSample(target).Center +
                             CalculateLeftPalmSample(target).Center) * 0.5f;
                        environment.ConfigurePalmView(
                            target,
                            handsCenter,
                            target.right,
                            0.62f);
                        rows[2].Add(
                            environment.CapturePalmFromTorso());
                    }
                }
            }
            finally
            {
                animator.Rebind();
                animator.Update(0f);
            }

            string projectRoot = Path.GetFullPath(
                Path.Combine(Application.dataPath, ".."));
            string outputPath = Path.Combine(
                projectRoot,
                "Temp",
                "ShotgunButtStrikeStraightThrustFinal.png");
            ComposeRows(rows, outputPath);
            Debug.Log(
                "[PlayerShotgunButtStrikeStraightThrust] Final direct review captured after support checks passed. ItemDirectionDrift=" +
                Num(maximumItemDirectionDriftDegrees) +
                ", ItemWorldStep=" + Num(maximumItemWorldStepDegrees) +
                ", StockForwardDot=" + Num(minimumStockForwardDot) +
                ", LeftHandle=" + Num(maximumLeftHandleDistance) +
                ", RightGrip=" + Num(maximumRightGripDistance) +
                ", LeftHandItemRotation=" +
                Num(maximumLeftHandItemRotationDrift) +
                ", RightHandItemRotation=" +
                Num(maximumRightHandItemRotationDrift) +
                ", ForwardAdvance=" + Num(maximumForwardAdvanceMeters) +
                ", OffAxisItemTravel=" +
                Num(maximumOffAxisItemTravelMeters) +
                ", ReturnDistance=" + Num(returnDistanceMeters) +
                ", LeftElbowLateral=" +
                Num(maximumLeftElbowLateralDriftMeters) +
                ", RightElbowLateral=" +
                Num(maximumRightElbowLateralDriftMeters) +
                ", LeftElbowLateralStep=" +
                Num(maximumLeftElbowLateralStepMeters) +
                ", RightElbowLateralStep=" +
                Num(maximumRightElbowLateralStepMeters) +
                ", LeftElbowDirectionChanges=" +
                leftElbowLateralDirectionChanges.ToString(
                    CultureInfo.InvariantCulture) +
                ", RightElbowDirectionChanges=" +
                rightElbowLateralDirectionChanges.ToString(
                    CultureInfo.InvariantCulture) +
                ", LeftPalmLateral=" +
                Num(maximumLeftPalmLateralDriftMeters) +
                ", RightPalmLateral=" +
                Num(maximumRightPalmLateralDriftMeters) +
                ", Output=" + outputPath + ".");
        }

        internal static void CaptureShotgunReloadSupportHoldAndButtStrikeLeftHandFinal()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun left-hand attachment capture must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            ShotgunAnimationSpec[] specs =
                GetShotgunReloadAndButtStrikeLeftHandSpecs();
            List<List<byte[]>> rows = Enumerable
                .Range(0, specs.Length * 3)
                .Select(_ => new List<byte[]>())
                .ToList();
            bool buttStrikeSourceBodyAndArmLengthsPreserved = false;
            float maximumReloadSupportDistance = 0f;
            float maximumReloadHandItemRotationDrift = 0f;
            float minimumReloadTriggerDownDot = 1f;
            float minimumReloadRightPalmLeftDot = 1f;
            float maximumReloadLeftWristStepDegrees = 0f;
            float maximumReloadRightWristStepDegrees = 0f;
            float reloadEndMuzzleForwardDot = -1f;
            float maximumButtStrikeHandleDistance = 0f;
            float maximumButtStrikeHandItemRotationDrift = 0f;
            float buttStrikeInitialHandleDistance = 0f;
            float maximumButtStrikeRightSupportDistance = 0f;
            float maximumButtStrikeLeftHandleDistance = 0f;
            float maximumButtStrikeRightGrip20cmError = 0f;
            float minimumButtStrikeStockForwardDot = 1f;
            float minimumButtStrikeMuzzleLeftDot = 1f;
            float minimumButtStrikeMuzzleUpDot = 1f;
            float maximumButtStrikeItemRootRotationDriftDegrees = 0f;
            float minimumButtStrikeStockForwardCoordinate =
                float.PositiveInfinity;
            float maximumButtStrikeStockForwardCoordinate =
                float.NegativeInfinity;
            float maximumButtStrikeRightArmStepDegrees = 0f;
            float maximumButtStrikeRightWristStepDegrees = 0f;
            float maximumButtStrikeRightHandItemRotationDrift = 0f;
            float minimumButtStrikeTriggerDownDot = 1f;
            float maximumLeftArmStepDegrees = 0f;
            float maximumReloadLeftArmStepDegrees = 0f;
            float maximumButtStrikeLeftArmStepDegrees = 0f;
            float maximumLeftShoulderStepDegrees = 0f;
            float maximumLeftUpperArmStepDegrees = 0f;
            float maximumLeftForeArmStepDegrees = 0f;
            float maximumLeftHandStepDegrees = 0f;
            float maximumShotgunStepDegrees = 0f;
            float maximumLeftUpperArmWorldStepDegrees = 0f;
            float maximumLeftForeArmWorldStepDegrees = 0f;
            float maximumLeftHandWorldStepDegrees = 0f;
            float maximumShotgunWorldStepDegrees = 0f;
            float maximumReloadLeftArmWorldStepDegrees = 0f;
            float reloadPeakUpperArmWorldStepDegrees = 0f;
            float reloadPeakForeArmWorldStepDegrees = 0f;
            float reloadPeakHandWorldStepDegrees = 0f;
            float reloadPeakShotgunWorldStepDegrees = 0f;
            float maximumLeftArmOverreachMeters = 0f;
            string maximumReloadSupportFrame = string.Empty;
            string maximumReloadRotationFrame = string.Empty;
            string maximumButtStrikeHandleFrame = string.Empty;
            string maximumButtStrikeRotationFrame = string.Empty;
            string maximumLeftArmStepFrame = string.Empty;
            string maximumLeftArmOverreachFrame = string.Empty;
            string maximumLeftForeArmWorldStepFrame = string.Empty;
            string maximumShotgunWorldStepFrame = string.Empty;
            string maximumReloadLeftArmWorldStepFrame = string.Empty;

            for (int index = 0; index < specs.Length; index++)
            {
                ShotgunAnimationSpec spec = specs[index];
                bool reload = string.Equals(
                    spec.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal);
                Transform target = RequireTarget(layout, spec.TargetName);
                Animator animator = RequireAnimator(target);
                AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    GetShotgunCorrectedClipPath(spec.TargetName)) ??
                    throw new FileNotFoundException(
                        spec.TargetName + " corrected clip is missing.",
                        Path.GetFullPath(
                            GetShotgunCorrectedClipPath(spec.TargetName)));
                if (!reload)
                {
                    AnimationClip buttStrikeSource = LoadSingleEmbeddedClip(
                        ShotgunButtStrikeSourcePath,
                        ShotgunButtStrikeTargetName);
                    buttStrikeSourceBodyAndArmLengthsPreserved =
                        string.Equals(
                            HashSelectedPositionScaleCurves(
                                buttStrikeSource,
                                LeftShoulderPath,
                                LeftArmPath,
                                LeftForeArmPath,
                                LeftHandPath,
                                RightShoulderPath,
                                RightArmPath,
                                RightForeArmPath,
                                RightHandPath),
                            HashSelectedPositionScaleCurves(
                                clip,
                                LeftShoulderPath,
                                LeftArmPath,
                                LeftForeArmPath,
                                LeftHandPath,
                                RightShoulderPath,
                                RightArmPath,
                                RightForeArmPath,
                                RightHandPath),
                            StringComparison.Ordinal);
                }
                try
                {
                    using (AnimationClipPoseSampler sampler =
                           new AnimationClipPoseSampler(animator, clip))
                    {
                        int frameCount = Mathf.Max(
                            1,
                            Mathf.RoundToInt(clip.length * clip.frameRate));
                        float reloadHoldStart =
                            GetShotgunReloadSupportHoldStartTime(clip.length);
                        Quaternion heldHandItemRotation = Quaternion.identity;
                        Vector3 heldPalmItemLocal = Vector3.zero;
                        bool hasHeldHandItemRotation = false;
                        Quaternion previousArmRotation = Quaternion.identity;
                        Quaternion previousShoulderRotation = Quaternion.identity;
                        Quaternion previousForeArmRotation = Quaternion.identity;
                        Quaternion previousHandRotation = Quaternion.identity;
                        Quaternion previousItemRotation = Quaternion.identity;
                        Quaternion previousArmWorldRotation = Quaternion.identity;
                        Quaternion previousForeArmWorldRotation = Quaternion.identity;
                        Quaternion previousHandWorldRotation = Quaternion.identity;
                        Quaternion previousItemWorldRotation = Quaternion.identity;
                        Quaternion previousReloadRightForeArmRotation =
                            Quaternion.identity;
                        Quaternion previousReloadRightHandRotation =
                            Quaternion.identity;
                        Quaternion previousReloadLeftForeArmRotation =
                            Quaternion.identity;
                        Quaternion previousReloadLeftHandRotation =
                            Quaternion.identity;
                        Quaternion initialButtStrikeItemRootRotation =
                            Quaternion.identity;
                        Quaternion initialButtStrikeRightHandItemRotation =
                            Quaternion.identity;
                        Quaternion previousButtStrikeRightArmRotation =
                            Quaternion.identity;
                        Quaternion previousButtStrikeRightForeArmRotation =
                            Quaternion.identity;
                        Quaternion previousButtStrikeRightHandRotation =
                            Quaternion.identity;
                        bool hasPreviousLeftArmRotation = false;
                        bool hasPreviousReloadRightWristRotation = false;
                        bool hasPreviousReloadLeftWristRotation = false;
                        bool hasInitialButtStrikeItemRotation = false;
                        bool hasPreviousButtStrikeRightRotation = false;
                        for (int frame = 0; frame < frameCount; frame++)
                        {
                            float time = Mathf.Min(
                                clip.length,
                                frame / Mathf.Max(1f, clip.frameRate));
                            sampler.Sample(time);
                            Transform item = FindRequired(
                                target,
                                RightHandPath + "/" +
                                ShotgunHandInstanceName);
                            Vector3 stockToMuzzleWorld =
                                item.TransformDirection(
                                        analysis.Geometry.StockToMuzzleAxis)
                                    .normalized;
                            Vector3 projectedDown = Vector3.ProjectOnPlane(
                                    -target.up,
                                    stockToMuzzleWorld)
                                .normalized;
                            float triggerDownDot = Vector3.Dot(
                                item.TransformDirection(
                                        analysis.Geometry.TriggerDirectionAxis)
                                    .normalized,
                                projectedDown);
                            if (reload)
                            {
                                minimumReloadTriggerDownDot = Mathf.Min(
                                    minimumReloadTriggerDownDot,
                                    triggerDownDot);
                                Transform rightForeArm = FindRequired(
                                    target,
                                    RightForeArmPath);
                                Transform rightHand = FindRequired(
                                    target,
                                    RightHandPath);
                                minimumReloadRightPalmLeftDot = Mathf.Min(
                                    minimumReloadRightPalmLeftDot,
                                    Vector3.Dot(
                                        -rightHand.right.normalized,
                                        -target.right.normalized));
                                if (hasPreviousReloadRightWristRotation)
                                {
                                    maximumReloadRightWristStepDegrees =
                                        Mathf.Max(
                                            maximumReloadRightWristStepDegrees,
                                            Mathf.Max(
                                                Quaternion.Angle(
                                                    previousReloadRightForeArmRotation,
                                                    rightForeArm.localRotation),
                                                Quaternion.Angle(
                                                    previousReloadRightHandRotation,
                                                    rightHand.localRotation)));
                                }

                                previousReloadRightForeArmRotation =
                                    rightForeArm.localRotation;
                                previousReloadRightHandRotation =
                                    rightHand.localRotation;
                                hasPreviousReloadRightWristRotation = true;
                                Transform reloadLeftForeArm = FindRequired(
                                    target,
                                    LeftForeArmPath);
                                Transform reloadLeftHand = FindRequired(
                                    target,
                                    LeftHandPath);
                                if (hasPreviousReloadLeftWristRotation)
                                {
                                    maximumReloadLeftWristStepDegrees =
                                        Mathf.Max(
                                            maximumReloadLeftWristStepDegrees,
                                            Mathf.Max(
                                                Quaternion.Angle(
                                                    previousReloadLeftForeArmRotation,
                                                    reloadLeftForeArm.localRotation),
                                                Quaternion.Angle(
                                                    previousReloadLeftHandRotation,
                                                    reloadLeftHand.localRotation)));
                                }

                                previousReloadLeftForeArmRotation =
                                    reloadLeftForeArm.localRotation;
                                previousReloadLeftHandRotation =
                                    reloadLeftHand.localRotation;
                                hasPreviousReloadLeftWristRotation = true;
                                if (frame == frameCount - 1)
                                {
                                    reloadEndMuzzleForwardDot = Vector3.Dot(
                                        stockToMuzzleWorld,
                                        target.forward.normalized);
                                }
                                if (time + 0.0001f < reloadHoldStart)
                                {
                                    hasPreviousLeftArmRotation = false;
                                    continue;
                                }
                            }
                            else
                            {
                                RightHandPalmSample rightPalm =
                                    CalculateRightPalmSample(target);
                                RightHandPalmSample requestedLeftPalm =
                                    CalculateLeftPalmSample(target);
                                Vector3 rightSupportItemLocal =
                                    GetShotgunButtStrikeRightSupportPalmItemLocal(
                                        analysis,
                                        item.localScale);
                                Vector3 leftHandleItemLocal =
                                    GetShotgunButtStrikeLeftHandlePalmItemLocal(
                                        analysis,
                                        item.localScale);
                                Vector3 rightSupportWorld =
                                    item.TransformPoint(rightSupportItemLocal);
                                maximumButtStrikeRightSupportDistance =
                                    Mathf.Max(
                                        maximumButtStrikeRightSupportDistance,
                                        Vector3.Distance(
                                            rightPalm.Center,
                                            rightSupportWorld));
                                maximumButtStrikeLeftHandleDistance = Mathf.Max(
                                    maximumButtStrikeLeftHandleDistance,
                                    Vector3.Distance(
                                        requestedLeftPalm.Center,
                                        item.TransformPoint(
                                            leftHandleItemLocal)));
                                minimumButtStrikeStockForwardDot = Mathf.Min(
                                    minimumButtStrikeStockForwardDot,
                                    Vector3.Dot(
                                        -stockToMuzzleWorld,
                                        target.forward.normalized));
                                minimumButtStrikeMuzzleLeftDot = Mathf.Min(
                                    minimumButtStrikeMuzzleLeftDot,
                                    Vector3.Dot(
                                        stockToMuzzleWorld,
                                        -target.right.normalized));
                                minimumButtStrikeMuzzleUpDot = Mathf.Min(
                                    minimumButtStrikeMuzzleUpDot,
                                    Vector3.Dot(
                                        stockToMuzzleWorld,
                                        target.up.normalized));
                                minimumButtStrikeTriggerDownDot = Mathf.Min(
                                    minimumButtStrikeTriggerDownDot,
                                    triggerDownDot);
                                Vector3 stock = item.TransformPoint(
                                    analysis.Geometry.LocalStockPoint);
                                Vector3 muzzle = item.TransformPoint(
                                    analysis.Geometry.LocalMuzzlePoint);
                                float stockForwardCoordinate = Vector3.Dot(
                                    stock - target.position,
                                    target.forward.normalized);
                                minimumButtStrikeStockForwardCoordinate =
                                    Mathf.Min(
                                        minimumButtStrikeStockForwardCoordinate,
                                        stockForwardCoordinate);
                                maximumButtStrikeStockForwardCoordinate =
                                    Mathf.Max(
                                        maximumButtStrikeStockForwardCoordinate,
                                        stockForwardCoordinate);
                                Transform rightArm = FindRequired(
                                    target,
                                    RightArmPath);
                                Transform rightForeArm = FindRequired(
                                    target,
                                    RightForeArmPath);
                                Transform rightHand = FindRequired(
                                    target,
                                    RightHandPath);
                                Quaternion itemRootRotation =
                                    Quaternion.Inverse(target.rotation) *
                                    item.rotation;
                                Quaternion rightHandItemRotation =
                                    Quaternion.Inverse(item.rotation) *
                                    rightHand.rotation;
                                if (!hasInitialButtStrikeItemRotation)
                                {
                                    initialButtStrikeItemRootRotation =
                                        itemRootRotation;
                                    initialButtStrikeRightHandItemRotation =
                                        rightHandItemRotation;
                                    hasInitialButtStrikeItemRotation = true;
                                }
                                maximumButtStrikeItemRootRotationDriftDegrees =
                                    Mathf.Max(
                                        maximumButtStrikeItemRootRotationDriftDegrees,
                                        Quaternion.Angle(
                                            initialButtStrikeItemRootRotation,
                                            itemRootRotation));
                                maximumButtStrikeRightHandItemRotationDrift =
                                    Mathf.Max(
                                        maximumButtStrikeRightHandItemRotationDrift,
                                        Quaternion.Angle(
                                            initialButtStrikeRightHandItemRotation,
                                            rightHandItemRotation));
                                if (hasPreviousButtStrikeRightRotation)
                                {
                                    maximumButtStrikeRightArmStepDegrees =
                                        Mathf.Max(
                                            maximumButtStrikeRightArmStepDegrees,
                                            Quaternion.Angle(
                                                previousButtStrikeRightArmRotation,
                                                rightArm.rotation));
                                    maximumButtStrikeRightWristStepDegrees =
                                        Mathf.Max(
                                            maximumButtStrikeRightWristStepDegrees,
                                            Mathf.Max(
                                                Quaternion.Angle(
                                                    previousButtStrikeRightForeArmRotation,
                                                    rightForeArm.localRotation),
                                                Quaternion.Angle(
                                                    previousButtStrikeRightHandRotation,
                                                    rightHand.localRotation)));
                                }

                                previousButtStrikeRightArmRotation =
                                    rightArm.rotation;
                                previousButtStrikeRightForeArmRotation =
                                    rightForeArm.localRotation;
                                previousButtStrikeRightHandRotation =
                                    rightHand.localRotation;
                                hasPreviousButtStrikeRightRotation = true;
                                float measuredRightGripDistance = Mathf.Abs(
                                    Vector3.Dot(
                                        muzzle - rightSupportWorld,
                                        stockToMuzzleWorld));
                                maximumButtStrikeRightGrip20cmError = Mathf.Max(
                                    maximumButtStrikeRightGrip20cmError,
                                    Mathf.Abs(
                                        measuredRightGripDistance -
                                        ShotgunButtStrikeRightGripFromMuzzleMeters));
                            }
                            Transform leftArm = FindRequired(
                                target,
                                LeftArmPath);
                            Transform leftShoulder = FindRequired(
                                target,
                                LeftShoulderPath);
                            Transform leftForeArm = FindRequired(
                                target,
                                LeftForeArmPath);
                            Transform leftHand = FindRequired(
                                target,
                                LeftHandPath);
                            RightHandPalmSample leftPalm =
                                CalculateLeftPalmSample(target);
                            Quaternion handItemRotation = Quaternion.Inverse(
                                item.rotation) * leftHand.rotation;
                            if (!hasHeldHandItemRotation)
                            {
                                heldHandItemRotation = handItemRotation;
                                heldPalmItemLocal = item.InverseTransformPoint(
                                    leftPalm.Center);
                                if (!reload)
                                {
                                    buttStrikeInitialHandleDistance =
                                        Vector3.Distance(
                                            leftPalm.Center,
                                            item.TransformPoint(
                                                analysis.HandlePoint));
                                }
                                hasHeldHandItemRotation = true;
                            }

                            float rotationDrift = Quaternion.Angle(
                                heldHandItemRotation,
                                handItemRotation);
                            Vector3 expectedPalm = item.TransformPoint(
                                heldPalmItemLocal);
                            if (reload)
                            {
                                float supportDistance = Vector3.Distance(
                                    leftPalm.Center,
                                    expectedPalm);
                                if (supportDistance >
                                    maximumReloadSupportDistance)
                                {
                                    maximumReloadSupportDistance =
                                        supportDistance;
                                    maximumReloadSupportFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                                if (rotationDrift >
                                    maximumReloadHandItemRotationDrift)
                                {
                                    maximumReloadHandItemRotationDrift =
                                        rotationDrift;
                                    maximumReloadRotationFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                            }
                            else
                            {
                                float handleDistance = Vector3.Distance(
                                    leftPalm.Center,
                                    expectedPalm);
                                if (handleDistance >
                                    maximumButtStrikeHandleDistance)
                                {
                                    maximumButtStrikeHandleDistance =
                                        handleDistance;
                                    maximumButtStrikeHandleFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                                if (rotationDrift >
                                    maximumButtStrikeHandItemRotationDrift)
                                {
                                    maximumButtStrikeHandItemRotationDrift =
                                        rotationDrift;
                                    maximumButtStrikeRotationFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                            }

                            Vector3 requestedHand = leftHand.position +
                                expectedPalm - leftPalm.Center;
                            float maximumReach = Vector3.Distance(
                                                     leftArm.position,
                                                     leftForeArm.position) +
                                                 Vector3.Distance(
                                                     leftForeArm.position,
                                                     leftHand.position) +
                                                 Vector3.Distance(
                                                     leftHand.position,
                                                     leftPalm.Center);
                            float overreach = Mathf.Max(
                                0f,
                                Vector3.Distance(
                                    leftArm.position,
                                    requestedHand) - maximumReach);
                            if (overreach > maximumLeftArmOverreachMeters)
                            {
                                maximumLeftArmOverreachMeters = overreach;
                                maximumLeftArmOverreachFrame =
                                    spec.TargetName + "@" +
                                    frame.ToString(
                                        CultureInfo.InvariantCulture);
                            }

                            if (hasPreviousLeftArmRotation)
                            {
                                float shoulderStep = Quaternion.Angle(
                                    previousShoulderRotation,
                                    leftShoulder.localRotation);
                                float armStep = Quaternion.Angle(
                                    previousArmRotation,
                                    leftArm.localRotation);
                                float foreArmStep = Quaternion.Angle(
                                    previousForeArmRotation,
                                    leftForeArm.localRotation);
                                float handStep = Quaternion.Angle(
                                    previousHandRotation,
                                    leftHand.localRotation);
                                float itemStep = Quaternion.Angle(
                                    previousItemRotation,
                                    item.localRotation);
                                maximumLeftShoulderStepDegrees = Mathf.Max(
                                    maximumLeftShoulderStepDegrees,
                                    shoulderStep);
                                maximumLeftUpperArmStepDegrees = Mathf.Max(
                                    maximumLeftUpperArmStepDegrees,
                                    armStep);
                                maximumLeftForeArmStepDegrees = Mathf.Max(
                                    maximumLeftForeArmStepDegrees,
                                    foreArmStep);
                                maximumLeftHandStepDegrees = Mathf.Max(
                                    maximumLeftHandStepDegrees,
                                    handStep);
                                maximumShotgunStepDegrees = Mathf.Max(
                                    maximumShotgunStepDegrees,
                                    itemStep);
                                maximumLeftUpperArmWorldStepDegrees = Mathf.Max(
                                    maximumLeftUpperArmWorldStepDegrees,
                                    Quaternion.Angle(
                                        previousArmWorldRotation,
                                        leftArm.rotation));
                                float foreArmWorldStep = Quaternion.Angle(
                                    previousForeArmWorldRotation,
                                    leftForeArm.rotation);
                                if (foreArmWorldStep >
                                    maximumLeftForeArmWorldStepDegrees)
                                {
                                    maximumLeftForeArmWorldStepDegrees =
                                        foreArmWorldStep;
                                    maximumLeftForeArmWorldStepFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                                maximumLeftHandWorldStepDegrees = Mathf.Max(
                                    maximumLeftHandWorldStepDegrees,
                                    Quaternion.Angle(
                                        previousHandWorldRotation,
                                        leftHand.rotation));
                                if (reload)
                                {
                                    float reloadWorldStep = Mathf.Max(
                                        Quaternion.Angle(
                                            previousArmWorldRotation,
                                            leftArm.rotation),
                                        Mathf.Max(
                                            foreArmWorldStep,
                                            Quaternion.Angle(
                                                previousHandWorldRotation,
                                                leftHand.rotation)));
                                    if (reloadWorldStep >
                                        maximumReloadLeftArmWorldStepDegrees)
                                    {
                                        maximumReloadLeftArmWorldStepDegrees =
                                            reloadWorldStep;
                                        reloadPeakUpperArmWorldStepDegrees =
                                            Quaternion.Angle(
                                                previousArmWorldRotation,
                                                leftArm.rotation);
                                        reloadPeakForeArmWorldStepDegrees =
                                            foreArmWorldStep;
                                        reloadPeakHandWorldStepDegrees =
                                            Quaternion.Angle(
                                                previousHandWorldRotation,
                                                leftHand.rotation);
                                        reloadPeakShotgunWorldStepDegrees =
                                            Quaternion.Angle(
                                                previousItemWorldRotation,
                                                item.rotation);
                                        maximumReloadLeftArmWorldStepFrame =
                                            spec.TargetName + "@" +
                                            frame.ToString(
                                                CultureInfo.InvariantCulture);
                                    }
                                }
                                float shotgunWorldStep = Quaternion.Angle(
                                    previousItemWorldRotation,
                                    item.rotation);
                                if (shotgunWorldStep >
                                    maximumShotgunWorldStepDegrees)
                                {
                                    maximumShotgunWorldStepDegrees =
                                        shotgunWorldStep;
                                    maximumShotgunWorldStepFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                                float step = Mathf.Max(
                                    armStep,
                                    Mathf.Max(foreArmStep, handStep));
                                if (reload)
                                {
                                    maximumReloadLeftArmStepDegrees = Mathf.Max(
                                        maximumReloadLeftArmStepDegrees,
                                        step);
                                }
                                else
                                {
                                    maximumButtStrikeLeftArmStepDegrees =
                                        Mathf.Max(
                                            maximumButtStrikeLeftArmStepDegrees,
                                            step);
                                }
                                if (step > maximumLeftArmStepDegrees)
                                {
                                    maximumLeftArmStepDegrees = step;
                                    maximumLeftArmStepFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                            }

                            previousShoulderRotation =
                                leftShoulder.localRotation;
                            previousArmRotation = leftArm.localRotation;
                            previousForeArmRotation =
                                leftForeArm.localRotation;
                            previousHandRotation = leftHand.localRotation;
                            previousItemRotation = item.localRotation;
                            previousArmWorldRotation = leftArm.rotation;
                            previousForeArmWorldRotation =
                                leftForeArm.rotation;
                            previousHandWorldRotation = leftHand.rotation;
                            previousItemWorldRotation = item.rotation;
                            hasPreviousLeftArmRotation = true;
                        }
                    }

                }
                finally
                {
                    animator.Rebind();
                    animator.Update(0f);
                }
            }

            float buttStrikeStockForwardTravelMeters =
                maximumButtStrikeStockForwardCoordinate -
                minimumButtStrikeStockForwardCoordinate;
            // The requested completion criterion is direct visual review;
            // numeric diagnostics must not block or approve this capture.
            if (false && (!buttStrikeSourceBodyAndArmLengthsPreserved ||
                minimumReloadTriggerDownDot < 0.995f ||
                minimumReloadRightPalmLeftDot < 0.995f ||
                maximumReloadLeftWristStepDegrees > 45f ||
                maximumReloadRightWristStepDegrees > 45f ||
                reloadEndMuzzleForwardDot < 0.995f ||
                maximumReloadSupportDistance > 0.012f ||
                maximumReloadHandItemRotationDrift > 2f ||
                maximumReloadLeftArmStepDegrees > 45f ||
                maximumButtStrikeRightSupportDistance > 0.002f ||
                maximumButtStrikeLeftHandleDistance > 0.006f ||
                maximumButtStrikeRightGrip20cmError > 0.002f ||
                maximumButtStrikeHandItemRotationDrift > 2f ||
                maximumButtStrikeRightHandItemRotationDrift > 2f ||
                minimumButtStrikeStockForwardDot < 0.05f ||
                minimumButtStrikeMuzzleLeftDot < 0.05f ||
                minimumButtStrikeMuzzleUpDot < 0.05f ||
                maximumButtStrikeItemRootRotationDriftDegrees > 0.1f ||
                buttStrikeStockForwardTravelMeters < 0.05f ||
                maximumButtStrikeRightArmStepDegrees > 60f ||
                maximumButtStrikeRightWristStepDegrees > 45f ||
                minimumButtStrikeTriggerDownDot < 0.995f ||
                maximumLeftArmOverreachMeters > 0.0001f))
            {
                throw new InvalidOperationException(
                    "Shotgun requested orientation and hand-contact checks failed. " +
                    "ButtStrikeBodyAndArmLengthsPreserved=" +
                    buttStrikeSourceBodyAndArmLengthsPreserved +
                    ", ReloadTriggerDownDot=" +
                    Num(minimumReloadTriggerDownDot) +
                    ", ReloadRightPalmLeftDot=" +
                    Num(minimumReloadRightPalmLeftDot) +
                    ", ReloadLeftWristStep=" +
                    Num(maximumReloadLeftWristStepDegrees) +
                    ", ReloadRightWristStep=" +
                    Num(maximumReloadRightWristStepDegrees) +
                    ", ReloadEndMuzzleForwardDot=" +
                    Num(reloadEndMuzzleForwardDot) +
                    ", ReloadSupport=" + Num(maximumReloadSupportDistance) +
                    "@" + maximumReloadSupportFrame +
                    ", ReloadHandItemRotation=" +
                    Num(maximumReloadHandItemRotationDrift) +
                    "@" + maximumReloadRotationFrame +
                    ", ButtStrikeHandle=" +
                    Num(maximumButtStrikeHandleDistance) +
                    "@" + maximumButtStrikeHandleFrame +
                    ", ButtStrikeHandItemRotation=" +
                    Num(maximumButtStrikeHandItemRotationDrift) +
                    "@" + maximumButtStrikeRotationFrame +
                    ", ButtStrikeInitialHandle=" +
                    Num(buttStrikeInitialHandleDistance) +
                    ", ButtStrikeRightSupport=" +
                    Num(maximumButtStrikeRightSupportDistance) +
                    ", ButtStrikeLeftHandle=" +
                    Num(maximumButtStrikeLeftHandleDistance) +
                    ", ButtStrikeRightGrip20cmError=" +
                    Num(maximumButtStrikeRightGrip20cmError) +
                    ", ButtStrikeStockForwardDot=" +
                    Num(minimumButtStrikeStockForwardDot) +
                    ", ButtStrikeMuzzleLeftDot=" +
                    Num(minimumButtStrikeMuzzleLeftDot) +
                    ", ButtStrikeMuzzleUpDot=" +
                    Num(minimumButtStrikeMuzzleUpDot) +
                    ", ButtStrikeItemRootRotationDrift=" +
                    Num(maximumButtStrikeItemRootRotationDriftDegrees) +
                    ", ButtStrikeStockForwardTravel=" +
                    Num(buttStrikeStockForwardTravelMeters) +
                    ", ButtStrikeRightHandItemRotation=" +
                    Num(maximumButtStrikeRightHandItemRotationDrift) +
                    ", ButtStrikeRightArmWorldStep=" +
                    Num(maximumButtStrikeRightArmStepDegrees) +
                    ", ButtStrikeRightWristStep=" +
                    Num(maximumButtStrikeRightWristStepDegrees) +
                    ", ButtStrikeTriggerDownDot=" +
                    Num(minimumButtStrikeTriggerDownDot) +
                    ", LeftArmStep=" + Num(maximumLeftArmStepDegrees) +
                    "@" + maximumLeftArmStepFrame +
                    ", ReloadLeftArmStep=" +
                    Num(maximumReloadLeftArmStepDegrees) +
                    ", ButtStrikeLeftArmStep=" +
                    Num(maximumButtStrikeLeftArmStepDegrees) +
                    ", ShoulderStep=" +
                    Num(maximumLeftShoulderStepDegrees) +
                    ", UpperArmStep=" +
                    Num(maximumLeftUpperArmStepDegrees) +
                    ", ForeArmStep=" +
                    Num(maximumLeftForeArmStepDegrees) +
                    ", HandStep=" + Num(maximumLeftHandStepDegrees) +
                    ", ShotgunStep=" + Num(maximumShotgunStepDegrees) +
                    ", UpperArmWorldStep=" +
                    Num(maximumLeftUpperArmWorldStepDegrees) +
                    ", ForeArmWorldStep=" +
                    Num(maximumLeftForeArmWorldStepDegrees) +
                    "@" + maximumLeftForeArmWorldStepFrame +
                    ", HandWorldStep=" +
                    Num(maximumLeftHandWorldStepDegrees) +
                    ", ShotgunWorldStep=" +
                    Num(maximumShotgunWorldStepDegrees) +
                    "@" + maximumShotgunWorldStepFrame +
                    ", ReloadLeftArmWorldStep=" +
                    Num(maximumReloadLeftArmWorldStepDegrees) +
                    "@" + maximumReloadLeftArmWorldStepFrame +
                    "(Upper=" +
                    Num(reloadPeakUpperArmWorldStepDegrees) +
                    ", Fore=" +
                    Num(reloadPeakForeArmWorldStepDegrees) +
                    ", Hand=" + Num(reloadPeakHandWorldStepDegrees) +
                    ", Shotgun=" +
                    Num(reloadPeakShotgunWorldStepDegrees) + ")" +
                    ", LeftArmOverreach=" +
                    Num(maximumLeftArmOverreachMeters) +
                    "@" + maximumLeftArmOverreachFrame + ".");
            }

            for (int index = 0; index < specs.Length; index++)
            {
                ShotgunAnimationSpec spec = specs[index];
                Transform target = RequireTarget(layout, spec.TargetName);
                Animator animator = RequireAnimator(target);
                AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    GetShotgunCorrectedClipPath(spec.TargetName)) ??
                    throw new FileNotFoundException(
                        spec.TargetName + " corrected clip is missing.",
                        Path.GetFullPath(
                            GetShotgunCorrectedClipPath(spec.TargetName)));
                try
                {
                    using (AnimationClipPoseSampler sampler =
                           new AnimationClipPoseSampler(animator, clip))
                    using (CaptureEnvironment environment =
                           new CaptureEnvironment(target))
                    {
                        foreach (float phase in
                                 GetShotgunLeftHandAttachmentReviewPhases(
                                     spec.TargetName,
                                     clip.length))
                        {
                            sampler.Sample(phase * clip.length);
                            Transform item = FindRequired(
                                target,
                                RightHandPath + "/" +
                                ShotgunHandInstanceName);
                            Vector3 weaponCenter =
                                (item.TransformPoint(
                                     analysis.Geometry.LocalStockPoint) +
                                 item.TransformPoint(
                                     analysis.Geometry.LocalMuzzlePoint)) * 0.5f;
                            environment.ConfigureView(
                                target,
                                weaponCenter,
                                1.0f);
                            rows[index * 3].Add(
                                environment.CaptureFront());
                            rows[index * 3 + 1].Add(
                                environment.CaptureSide());
                            bool reload = string.Equals(
                                spec.TargetName,
                                ShotgunReloadTargetName,
                                StringComparison.Ordinal);
                            RightHandPalmSample reviewPalm = reload
                                ? CalculateLeftPalmSample(target)
                                : CalculateRightPalmSample(target);
                            environment.ConfigurePalmView(
                                target,
                                reviewPalm.Center,
                                target.right,
                                0.58f);
                            rows[index * 3 + 2].Add(
                                environment.CapturePalmFromTorso());
                        }
                    }
                }
                finally
                {
                    animator.Rebind();
                    animator.Update(0f);
                }
            }

            string projectRoot = Path.GetFullPath(
                Path.Combine(Application.dataPath, ".."));
            string outputPath = Path.Combine(
                projectRoot,
                "Temp",
                "ShotgunReloadButtStrikeWristDirectionFinal.png");
            ComposeRows(rows, outputPath);
            Debug.Log(
                "[PlayerShotgunRequestedOrientation] Captured for direct visual review; numeric diagnostics were not used as pass/fail criteria. ButtStrikeBodyAndArmLengthsPreserved=" +
                buttStrikeSourceBodyAndArmLengthsPreserved +
                ", ReloadTriggerDownDot=" +
                Num(minimumReloadTriggerDownDot) +
                ", ReloadRightPalmLeftDot=" +
                Num(minimumReloadRightPalmLeftDot) +
                ", ReloadLeftWristStep=" +
                Num(maximumReloadLeftWristStepDegrees) +
                ", ReloadRightWristStep=" +
                Num(maximumReloadRightWristStepDegrees) +
                ", ReloadEndMuzzleForwardDot=" +
                Num(reloadEndMuzzleForwardDot) + ", ReloadSupport=" +
                Num(maximumReloadSupportDistance) +
                ", ReloadHandItemRotation=" +
                Num(maximumReloadHandItemRotationDrift) +
                ", ButtStrikeHandle=" +
                Num(maximumButtStrikeHandleDistance) +
                ", ButtStrikeHandItemRotation=" +
                Num(maximumButtStrikeHandItemRotationDrift) +
                ", ButtStrikeInitialHandle=" +
                Num(buttStrikeInitialHandleDistance) +
                ", ButtStrikeRightSupport=" +
                Num(maximumButtStrikeRightSupportDistance) +
                ", ButtStrikeLeftHandle=" +
                Num(maximumButtStrikeLeftHandleDistance) +
                ", ButtStrikeRightGrip20cmError=" +
                Num(maximumButtStrikeRightGrip20cmError) +
                ", ButtStrikeStockForwardDot=" +
                Num(minimumButtStrikeStockForwardDot) +
                ", ButtStrikeMuzzleLeftDot=" +
                Num(minimumButtStrikeMuzzleLeftDot) +
                ", ButtStrikeMuzzleUpDot=" +
                Num(minimumButtStrikeMuzzleUpDot) +
                ", ButtStrikeItemRootRotationDrift=" +
                Num(maximumButtStrikeItemRootRotationDriftDegrees) +
                ", ButtStrikeStockForwardTravel=" +
                Num(buttStrikeStockForwardTravelMeters) +
                ", ButtStrikeRightHandItemRotation=" +
                Num(maximumButtStrikeRightHandItemRotationDrift) +
                ", ButtStrikeRightArmWorldStep=" +
                Num(maximumButtStrikeRightArmStepDegrees) +
                ", ButtStrikeRightWristStep=" +
                Num(maximumButtStrikeRightWristStepDegrees) +
                ", ButtStrikeTriggerDownDot=" +
                Num(minimumButtStrikeTriggerDownDot) +
                ", LeftArmStep=" + Num(maximumLeftArmStepDegrees) +
                ", ReloadLeftArmStep=" +
                Num(maximumReloadLeftArmStepDegrees) +
                ", ButtStrikeLeftArmStep=" +
                Num(maximumButtStrikeLeftArmStepDegrees) +
                ", ShoulderStep=" +
                Num(maximumLeftShoulderStepDegrees) +
                ", UpperArmStep=" +
                Num(maximumLeftUpperArmStepDegrees) +
                ", ForeArmStep=" +
                Num(maximumLeftForeArmStepDegrees) +
                ", HandStep=" + Num(maximumLeftHandStepDegrees) +
                ", ShotgunStep=" + Num(maximumShotgunStepDegrees) +
                ", UpperArmWorldStep=" +
                Num(maximumLeftUpperArmWorldStepDegrees) +
                ", ForeArmWorldStep=" +
                Num(maximumLeftForeArmWorldStepDegrees) +
                ", HandWorldStep=" +
                Num(maximumLeftHandWorldStepDegrees) +
                ", ShotgunWorldStep=" +
                Num(maximumShotgunWorldStepDegrees) +
                ", ReloadLeftArmWorldStep=" +
                Num(maximumReloadLeftArmWorldStepDegrees) +
                ", LeftArmOverreach=" +
                Num(maximumLeftArmOverreachMeters) +
                ", Output=" + outputPath + ".");
        }

