        private static void CaptureShotgunRightArmGripFinal(
            ShotgunAnimationSpec[] specs,
            string outputFileName,
            bool requireHandEdgeForward,
            bool requireButtBodySideGrip = false)
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun right-arm grip capture must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            List<List<byte[]>> rows = specs
                .Select(_ => new List<byte[]>())
                .ToList();
            float maximumPalmDistance = 0f;
            float maximumSettledButtPalmDistance = 0f;
            float maximumRightArmStepDegrees = 0f;
            float maximumRightWristStepDegrees = 0f;
            float minimumRightPalmLeftDot = 1f;
            float minimumRightHandEdgeForwardDot = 1f;
            float minimumHandSeparationMeters = requireButtBodySideGrip
                ? float.PositiveInfinity
                : 0f;
            float gripScale = ShotgunDesignLengthMeters /
                analysis.Geometry.SourceLength;
            float previousButtGripSpanMeters = Vector3.Distance(
                analysis.HandlePoint,
                analysis.SupportPoint) * gripScale;
            Vector3 bodySideRightGripPoint =
                GetShotgunButtBodySideRightGripPoint(analysis);
            float bodySideButtGripSpanMeters = Vector3.Distance(
                analysis.HandlePoint,
                bodySideRightGripPoint) * gripScale;
            float rightBodywardMoveMeters = Vector3.Distance(
                analysis.SupportPoint,
                bodySideRightGripPoint) * gripScale;
            string maximumPalmFrame = string.Empty;
            string maximumSettledButtPalmFrame = string.Empty;
            string maximumArmStepFrame = string.Empty;
            string maximumWristStepFrame = string.Empty;
            string minimumPalmLeftFrame = string.Empty;
            string minimumHandEdgeForwardFrame = string.Empty;
            string minimumHandSeparationFrame = string.Empty;

            for (int index = 0; index < specs.Length; index++)
            {
                ShotgunAnimationSpec spec = specs[index];
                Transform target = RequireTarget(layout, spec.TargetName);
                Animator animator = RequireAnimator(target);
                AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    GetShotgunCorrectedClipPath(spec.TargetName)) ??
                    throw new FileNotFoundException(
                        spec.TargetName + " corrected clip is missing.",
                        Path.GetFullPath(
                            GetShotgunCorrectedClipPath(spec.TargetName)));
                try
                {
                    using (AnimationClipPoseSampler sampler =
                           new AnimationClipPoseSampler(animator, clip))
                    {
                        int frameCount = Mathf.Max(
                            1,
                            Mathf.RoundToInt(clip.length * clip.frameRate));
                        Quaternion previousArmRotation = Quaternion.identity;
                        Quaternion previousForeArmRotation = Quaternion.identity;
                        Quaternion previousHandRotation = Quaternion.identity;
                        bool hasPreviousArmRotation = false;
                        bool hasPreviousWristRotation = false;
                        for (int frame = 0; frame < frameCount; frame++)
                        {
                            float time = Mathf.Min(
                                clip.length,
                                frame / Mathf.Max(1f, clip.frameRate));
                            sampler.Sample(time);
                            Transform rightArm = FindRequired(
                                target,
                                RightArmPath);
                            Transform rightForeArm = FindRequired(
                                target,
                                RightForeArmPath);
                            Transform rightHand = FindRequired(
                                target,
                                RightHandPath);
                            Transform item = FindRequired(
                                target,
                                RightHandPath + "/" +
                                ShotgunHandInstanceName);
                            RightHandPalmSample palm =
                                CalculateRightPalmSample(target);
                            if (requireButtBodySideGrip)
                            {
                                RightHandPalmSample leftPalm =
                                    CalculateLeftPalmSample(target);
                                float handSeparation = Vector3.Distance(
                                    palm.Center,
                                    leftPalm.Center);
                                if (handSeparation < minimumHandSeparationMeters)
                                {
                                    minimumHandSeparationMeters = handSeparation;
                                    minimumHandSeparationFrame =
                                        spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                            }
                            float palmLeftDot = Vector3.Dot(
                                -rightHand.right.normalized,
                                -target.right.normalized);
                            float handEdgeForwardDot = Vector3.Dot(
                                rightHand.up.normalized,
                                target.forward.normalized);
                            if (palmLeftDot < minimumRightPalmLeftDot)
                            {
                                minimumRightPalmLeftDot = palmLeftDot;
                                minimumPalmLeftFrame = spec.TargetName + "@" +
                                    frame.ToString(
                                        CultureInfo.InvariantCulture);
                            }
                            if (handEdgeForwardDot <
                                minimumRightHandEdgeForwardDot)
                            {
                                minimumRightHandEdgeForwardDot =
                                    handEdgeForwardDot;
                                minimumHandEdgeForwardFrame =
                                    spec.TargetName + "@" +
                                    frame.ToString(
                                        CultureInfo.InvariantCulture);
                            }

                            if (hasPreviousWristRotation)
                            {
                                float wristStep = Mathf.Max(
                                    Quaternion.Angle(
                                        previousForeArmRotation,
                                        rightForeArm.localRotation),
                                    Quaternion.Angle(
                                        previousHandRotation,
                                        rightHand.localRotation));
                                if (wristStep > maximumRightWristStepDegrees)
                                {
                                    maximumRightWristStepDegrees = wristStep;
                                    maximumWristStepFrame = spec.TargetName +
                                        "@" + frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                            }

                            previousForeArmRotation =
                                rightForeArm.localRotation;
                            previousHandRotation = rightHand.localRotation;
                            hasPreviousWristRotation = true;
                            float buttBlend = GetShotgunButtBlend(
                                spec,
                                time);
                            bool twoHandWindowRequired =
                                string.Equals(
                                    spec.TargetName,
                                    ShotgunDrawTargetName,
                                    StringComparison.Ordinal) ||
                                string.Equals(
                                    spec.TargetName,
                                    ShotgunStowTargetName,
                                    StringComparison.Ordinal);
                            bool rightGripExpected =
                                !twoHandWindowRequired ||
                                GetShotgunLeftSupportWeight(
                                    spec.TargetName,
                                    time,
                                    clip.length) >= 0.9f;
                            if (!rightGripExpected)
                            {
                                hasPreviousArmRotation = false;
                                continue;
                            }

                            Vector3 expectedPalm;
                            if (string.Equals(
                                    spec.ItemMode,
                                    "Normal",
                                    StringComparison.Ordinal))
                            {
                                expectedPalm = item.TransformPoint(
                                    analysis.HandlePoint);
                            }
                            else if (string.Equals(
                                         spec.ItemMode,
                                         "Butt",
                                         StringComparison.Ordinal))
                            {
                                expectedPalm = item.TransformPoint(
                                    requireButtBodySideGrip
                                        ? bodySideRightGripPoint
                                        : analysis.SupportPoint);
                            }
                            else
                            {
                                GetShotgunButtRegripTargets(
                                    target,
                                    item,
                                    analysis,
                                    buttBlend,
                                    out expectedPalm,
                                    out Vector3 _,
                                    out Vector3 _,
                                    out Vector3 _,
                                    requireButtBodySideGrip);
                            }

                            float palmDistance = Vector3.Distance(
                                palm.Center,
                                expectedPalm);
                            if (palmDistance > maximumPalmDistance)
                            {
                                maximumPalmDistance = palmDistance;
                                maximumPalmFrame = spec.TargetName + "@" +
                                    frame.ToString(
                                        CultureInfo.InvariantCulture);
                            }
                            if (requireButtBodySideGrip &&
                                buttBlend >= 0.99f &&
                                palmDistance > maximumSettledButtPalmDistance)
                            {
                                maximumSettledButtPalmDistance = palmDistance;
                                maximumSettledButtPalmFrame =
                                    spec.TargetName + "@" +
                                    frame.ToString(
                                        CultureInfo.InvariantCulture);
                            }

                            if (hasPreviousArmRotation)
                            {
                                float armStep = Quaternion.Angle(
                                    previousArmRotation,
                                    rightArm.localRotation);
                                if (armStep > maximumRightArmStepDegrees)
                                {
                                    maximumRightArmStepDegrees = armStep;
                                    maximumArmStepFrame = spec.TargetName + "@" +
                                        frame.ToString(
                                            CultureInfo.InvariantCulture);
                                }
                            }

                            previousArmRotation = rightArm.localRotation;
                            hasPreviousArmRotation = true;
                        }

                    }
                }
                finally
                {
                    animator.Rebind();
                    animator.Update(0f);
                }
            }

            if (maximumPalmDistance >
                    (requireButtBodySideGrip ? 0.035f : 0.012f) ||
                (requireButtBodySideGrip &&
                 maximumSettledButtPalmDistance > 0.012f) ||
                maximumRightArmStepDegrees > 75f ||
                maximumRightWristStepDegrees > 75f ||
                minimumRightPalmLeftDot < 0.9f ||
                (requireHandEdgeForward &&
                 minimumRightHandEdgeForwardDot < 0.9f) ||
                (requireButtBodySideGrip &&
                 (minimumHandSeparationMeters <
                      ShotgunButtMinimumActualHandSeparationMeters ||
                  bodySideButtGripSpanMeters <=
                      previousButtGripSpanMeters + 0.03f ||
                  rightBodywardMoveMeters <= 0.03f)))
            {
                throw new InvalidOperationException(
                    "Shotgun right-arm grip support checks failed. Palm=" +
                    Num(maximumPalmDistance) +
                    "@" + maximumPalmFrame +
                    ", SettledButtPalm=" +
                    Num(maximumSettledButtPalmDistance) +
                    "@" + maximumSettledButtPalmFrame +
                    ", ArmStep=" + Num(maximumRightArmStepDegrees) +
                    "@" + maximumArmStepFrame +
                    ", WristStep=" + Num(maximumRightWristStepDegrees) +
                    "@" + maximumWristStepFrame +
                    ", PalmLeftDot=" + Num(minimumRightPalmLeftDot) +
                    "@" + minimumPalmLeftFrame +
                    ", HandEdgeForwardDot=" +
                    Num(minimumRightHandEdgeForwardDot) +
                    "@" + minimumHandEdgeForwardFrame +
                    ", HandSeparation=" +
                    Num(minimumHandSeparationMeters) +
                    "@" + minimumHandSeparationFrame +
                    ", PreviousButtGripSpan=" +
                    Num(previousButtGripSpanMeters) +
                    ", BodySideButtGripSpan=" +
                    Num(bodySideButtGripSpanMeters) +
                    ", RightBodywardMove=" +
                    Num(rightBodywardMoveMeters) + ".");
            }

            for (int index = 0; index < specs.Length; index++)
            {
                ShotgunAnimationSpec spec = specs[index];
                Transform target = RequireTarget(layout, spec.TargetName);
                Animator animator = RequireAnimator(target);
                AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    GetShotgunCorrectedClipPath(spec.TargetName)) ??
                    throw new FileNotFoundException(
                        spec.TargetName + " corrected clip is missing.",
                        Path.GetFullPath(
                            GetShotgunCorrectedClipPath(spec.TargetName)));
                try
                {
                    using (AnimationClipPoseSampler sampler =
                           new AnimationClipPoseSampler(animator, clip))
                    using (CaptureEnvironment environment =
                           new CaptureEnvironment(target))
                    {
                        foreach (float phase in
                                 GetShotgunRightArmReviewPhases(
                                     spec.TargetName))
                        {
                            sampler.Sample(phase * clip.length);
                            Vector3 handsCenter =
                                (CalculateRightPalmSample(target).Center +
                                 CalculateLeftPalmSample(target).Center) * 0.5f;
                            environment.ConfigurePalmView(
                                target,
                                handsCenter,
                                -target.right,
                                0.62f);
                            rows[index].Add(
                                environment.CapturePalmFromTorso());
                        }
                    }
                }
                finally
                {
                    animator.Rebind();
                    animator.Update(0f);
                }
            }

            string projectRoot = Path.GetFullPath(
                Path.Combine(Application.dataPath, ".."));
            string outputPath = Path.Combine(
                projectRoot,
                "Temp",
                outputFileName);
            ComposeRows(rows, outputPath);
            Debug.Log(
                "[PlayerShotgunRightArmGrip] Final direct review captured after support checks passed. Palm=" +
                Num(maximumPalmDistance) +
                ", SettledButtPalm=" +
                Num(maximumSettledButtPalmDistance) +
                ", ArmStep=" + Num(maximumRightArmStepDegrees) +
                ", WristStep=" + Num(maximumRightWristStepDegrees) +
                ", PalmLeftDot=" + Num(minimumRightPalmLeftDot) +
                ", HandEdgeForwardDot=" +
                Num(minimumRightHandEdgeForwardDot) +
                ", HandSeparation=" +
                Num(minimumHandSeparationMeters) +
                ", PreviousButtGripSpan=" +
                Num(previousButtGripSpanMeters) +
                ", BodySideButtGripSpan=" +
                Num(bodySideButtGripSpanMeters) +
                ", RightBodywardMove=" +
                Num(rightBodywardMoveMeters) +
                ", Output=" + outputPath + ".");
        }

        private static float GetShotgunButtBlend(
            ShotgunAnimationSpec spec,
            float time)
        {
            if (string.Equals(spec.ItemMode, "Normal", StringComparison.Ordinal))
            {
                return 0f;
            }

            if (string.Equals(spec.ItemMode, "Butt", StringComparison.Ordinal))
            {
                return 1f;
            }

            float raw = Mathf.Clamp01(
                time / Mathf.Max(ShotgunButtTransitionSeconds, 0.0001f));
            float smooth = raw * raw * (3f - 2f * raw);
            return string.Equals(spec.ItemMode, "Exit", StringComparison.Ordinal)
                ? 1f - smooth
                : smooth;
        }

        private static float[] GetShotgunRightArmReviewPhases(string targetName)
        {
            if (string.Equals(
                    targetName,
                    ShotgunDrawTargetName,
                    StringComparison.Ordinal))
            {
                return new[] { 0.58f, 0.74f, 0.92f };
            }

            if (string.Equals(
                    targetName,
                    ShotgunStowTargetName,
                    StringComparison.Ordinal))
            {
                return new[] { 0.02f, 0.10f, 0.18f };
            }

            if (string.Equals(
                    targetName,
                    ShotgunButtModeEnterTargetName,
                    StringComparison.Ordinal) ||
                string.Equals(
                    targetName,
                    ShotgunButtModeExitTargetName,
                    StringComparison.Ordinal))
            {
                return new[] { 0f, 0.34f, 0.67f };
            }

            return new[] { 0f, 0.42f, 0.84f };
        }

        internal static void ApplyShotgunAnimationCorrections()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                throw new InvalidOperationException(
                    "Shotgun corrections must be applied in Edit Mode.");
            }

            ShotgunPerformanceMetrics performance =
                ReadJson<ShotgunPerformanceMetrics>(ShotgunPerformanceMetricsPath);
            ShotgunPerformanceConditionMetrics baseline = performance.conditions
                .Single(value => string.Equals(
                    value.condition,
                    "Baseline",
                    StringComparison.Ordinal));
            ShotgunPerformanceConditionMetrics noAdditionalShadows =
                performance.conditions.Single(value => string.Equals(
                    value.condition,
                    "AdditionalLightShadowsDisabled",
                    StringComparison.Ordinal));
            if (!performance.temporaryStateRestored ||
                noAdditionalShadows.medianFrameTimeMs >=
                baseline.medianFrameTimeMs * 0.95f)
            {
                throw new InvalidOperationException(
                    "The isolated Play Mode measurement did not confirm additional-light shadows as the frame-rate cause.");
            }

            // Rebuild the exact requested source set first, then layer only the
            // user-approved hand, wrist, item-orientation, and ButtMode corrections.
            ConnectOriginalMusketReloadForShotgunCopy();
            ApplyShotgunAnimationSet();
            AnimationClip correctedMusketReload =
                CreateOrUpdateMusketReloadPalmCorrection();

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            ShotgunAnimationSpec[] specs = GetShotgunAnimationSpecs();
            Transform[] targets = specs
                .Select(spec => RequireTarget(layout, spec.TargetName))
                .ToArray();
            AnimationClip musketIdle = GetConnectedMusketAnimationClip(
                layout,
                MusketIdleTargetName);
            AnimationClip emptyIdle = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                EmptyClipPath) ??
                throw new FileNotFoundException(
                    "Hands_Empty_Idle clip is missing.",
                    Path.GetFullPath(EmptyClipPath));
            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            ShotgunGripBinding grip = AnalyzeShotgunGripBinding(
                targets[1],
                musketIdle,
                shotgunAsset,
                analysis);
            ApplyCorrectedShotgunButtBinding(
                targets[1],
                musketIdle,
                shotgunAsset,
                analysis,
                grip);
            AnimationClip[] sources =
            {
                LoadSingleEmbeddedClip(
                    ShotgunDrawSourcePath,
                    ShotgunDrawTargetName),
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[1].ClipPath),
                LoadSingleEmbeddedClip(
                    ShotgunStowSourcePath,
                    ShotgunStowTargetName),
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[3].ClipPath),
                null,
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[5].ClipPath),
                LoadSingleEmbeddedClip(
                    ShotgunButtStrikeSourcePath,
                    ShotgunButtStrikeTargetName),
                null,
                AssetDatabase.LoadAssetAtPath<AnimationClip>(specs[8].ClipPath)
            };
            AnimationClip[] corrected = new AnimationClip[specs.Length];
            for (int index = 0; index < specs.Length; index++)
            {
                ShotgunAnimationSpec spec = specs[index];
                string correctedPath = GetShotgunCorrectedClipPath(spec.TargetName);
                if (string.Equals(spec.ItemMode, "Enter", StringComparison.Ordinal) ||
                    string.Equals(spec.ItemMode, "Exit", StringComparison.Ordinal))
                {
                    corrected[index] =
                        CreateOrUpdateCorrectedShotgunButtTransitionClip(
                            targets[index],
                            musketIdle,
                            shotgunAsset,
                            analysis,
                            grip,
                            correctedPath,
                            spec.TargetName,
                            string.Equals(
                                spec.ItemMode,
                                "Exit",
                                StringComparison.Ordinal));
                }
                else
                {
                    AnimationClip source = sources[index] ??
                        throw new InvalidOperationException(
                            spec.TargetName + " source clip is missing.");
                    corrected[index] = CreateOrUpdateExactShotgunClipCopy(
                        source,
                        correctedPath,
                        spec.TargetName + "_Corrected");
                    BakeShotgunHeldCorrection(
                        corrected[index],
                        source,
                        targets[index],
                        spec,
                        analysis,
                        grip,
                        emptyIdle,
                        index > 5 ? corrected[5] : null);
                }

                bool startsButt = string.Equals(
                    spec.ItemMode,
                    "Butt",
                    StringComparison.Ordinal) ||
                    string.Equals(spec.ItemMode, "Exit", StringComparison.Ordinal);
                ReplaceShotgunHandItem(
                    targets[index],
                    shotgunAsset,
                    grip,
                    startsButt);
                AnimatorController controller =
                    CreateOrUpdateExactEmbeddedTakeController(
                        spec.ControllerPath,
                        spec.StateName,
                        corrected[index]);
                Animator animator = ConfigureAnimator(targets[index], controller);
                animator.speed = 1f;
                EditorUtility.SetDirty(animator);
            }

            int performanceLightsChanged =
                ApplyConfirmedShotgunPerformanceFix(scene, performance);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            AssetDatabase.SaveAssets();

            bool allScaled = targets.All(target =>
            {
                Transform item = FindRequired(
                    target,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                return Mathf.Abs(item.localScale.x - grip.NormalLocalScale.x) <=
                           0.000001f &&
                       Mathf.Abs(item.localScale.y - grip.NormalLocalScale.y) <=
                           0.000001f &&
                       Mathf.Abs(item.localScale.z - grip.NormalLocalScale.z) <=
                           0.000001f;
            });
            bool allControllersCorrect = specs.Select((spec, index) =>
            {
                Animator animator = RequireAnimator(targets[index]);
                AnimatorController controller =
                    animator.runtimeAnimatorController as AnimatorController;
                return controller != null &&
                       StateUsesClip(
                           controller,
                           spec.StateName,
                           corrected[index]);
            }).All(value => value);
            ShotgunCorrectionApplyMetrics metrics =
                new ShotgunCorrectionApplyMetrics
                {
                    targetSet = string.Join(", ", specs.Select(value => value.TargetName)),
                    previousLengthMeters = 1f,
                    correctedLengthMeters = ShotgunDesignLengthMeters,
                    buttStockDownDegrees = ShotgunButtStockDownDegrees,
                    torsoClearanceMeters = ShotgunTorsoClearanceMeters,
                    reloadPullDistanceMeters = ShotgunReloadPullDistanceMeters,
                    reloadDetachedTravelSeconds =
                        ShotgunReloadDetachedTravelSeconds,
                    reloadSupportHoldSeconds = ShotgunReloadSupportHoldSeconds,
                    triggerDownTargets = new[]
                    {
                        ShotgunDrawTargetName,
                        ShotgunIdleTargetName,
                        ShotgunStowTargetName,
                        ShotgunFireTargetName,
                        ShotgunButtModeEnterTargetName,
                        ShotgunButtModeIdleTargetName,
                        ShotgunButtStrikeTargetName,
                        ShotgunButtModeExitTargetName,
                        ShotgunReloadTargetName
                    },
                    triggerOrientationPreservedTargets = Array.Empty<string>(),
                    lowerBodyPreservedTargets = new[]
                    {
                        ShotgunButtModeEnterTargetName,
                        ShotgunButtModeExitTargetName
                    },
                    musketReloadCorrectedClip =
                        AssetDatabase.GetAssetPath(correctedMusketReload),
                    performanceShadowLightsChanged = performanceLightsChanged,
                    allNineItemsScaled = allScaled,
                    allNineControllersUseCorrectedClips = allControllersCorrect,
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                Mathf.Abs(metrics.correctedLengthMeters - 1.3f) <= 0.0001f &&
                Mathf.Abs(metrics.buttStockDownDegrees - 30f) <= 0.0001f &&
                Mathf.Abs(
                    metrics.reloadDetachedTravelSeconds - 0.3f) <= 0.0001f &&
                Mathf.Abs(
                    metrics.reloadSupportHoldSeconds - 0.5f) <= 0.0001f &&
                metrics.performanceShadowLightsChanged > 0 &&
                metrics.allNineItemsScaled &&
                metrics.allNineControllersUseCorrectedClips;
            WriteJson(
                ShotgunCorrectionValidationDirectory +
                "/correction_apply_metrics.json",
                metrics);
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun correction support checks failed: " +
                    JsonUtility.ToJson(metrics));
            }

            SessionState.EraseInt(ShotgunAnimationCaptureStageKey);
            Debug.Log(
                "[PlayerShotgunCorrection] Applied 1.3m scale, state-specific two-hand supports, two-hand ButtMode rotation with Idle lower body, 30-degree stock-down clearance, trigger-down corrections, both reload hand corrections, and the confirmed additional-shadow performance fix.");
        }

        private static string GetShotgunCorrectedClipPath(string targetName)
        {
            return ShotgunAnimationDirectory + "/" +
                   targetName + "_Corrected.anim";
        }

        private static AnimationClip CreateOrUpdateMusketReloadPalmCorrection()
        {
            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, MusketReloadTargetName);
            Animator animator = RequireAnimator(target);
            AnimatorController controller =
                animator.runtimeAnimatorController as AnimatorController ??
                throw new InvalidOperationException(
                    "Musket_Reload does not use an AnimatorController.");
            AnimatorState state = controller.layers[0].stateMachine.defaultState ??
                throw new InvalidOperationException(
                    "Musket_Reload controller has no default state.");
            MusketAnimationSpec reloadSpec = GetMusketAnimationSpecs()
                .Single(spec => string.Equals(
                    spec.TargetName,
                    MusketReloadTargetName,
                    StringComparison.Ordinal));
            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                reloadSpec.GeneratedClipPath) ??
                throw new FileNotFoundException(
                    "The original generated Musket_Reload clip is missing.",
                    Path.GetFullPath(reloadSpec.GeneratedClipPath));
            string correctedPath =
                "Assets/_Project/Art/Player/Animations/Musket/" +
                "Musket_Reload_PalmCorrected.anim";
            AnimationClip corrected = CreateOrUpdateExactShotgunClipCopy(
                source,
                correctedPath,
                "Musket_Reload_PalmCorrected");
            GameObject workObject = UnityEngine.Object.Instantiate(target.gameObject);
            workObject.name = "MusketReloadPalmCorrectionBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                TransformCurveTrack rightForeArmTrack =
                    new TransformCurveTrack(RightForeArmPath);
                TransformCurveTrack rightHandTrack =
                    new TransformCurveTrack(RightHandPath);
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / Mathf.Max(1f, source.frameRate));
                    float sampleTime = frame == frameCount
                        ? Mathf.Max(
                            0f,
                            source.length -
                            1f / Mathf.Max(1f, source.frameRate))
                        : time;
                    source.SampleAnimation(workObject, sampleTime);
                    Transform rightArm = FindRequired(root, RightArmPath);
                    Transform rightForeArm = FindRequired(root, RightForeArmPath);
                    Transform rightHand = FindRequired(root, RightHandPath);
                    RotateForearmAndHandForPalmFacingDirection(
                        rightArm,
                        rightForeArm,
                        rightHand,
                        GetCharacterLeftDirection(root),
                        Vector3.forward);
                    rightHandTrack.Add(time, rightHand);
                    rightForeArmTrack.Add(time, rightForeArm);
                }

                SetRotationTrackCurves(corrected, rightForeArmTrack);
                SetRotationTrackCurves(corrected, rightHandTrack);
                corrected.EnsureQuaternionContinuity();
                EditorUtility.SetDirty(corrected);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }

            state.motion = corrected;
            state.speed = 1f;
            EditorUtility.SetDirty(controller);
            AssetDatabase.SaveAssets();
            return corrected;
        }

        private static void ConnectOriginalMusketReloadForShotgunCopy()
        {
            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, MusketReloadTargetName);
            Animator animator = RequireAnimator(target);
            AnimatorController controller =
                animator.runtimeAnimatorController as AnimatorController ??
                throw new InvalidOperationException(
                    "Musket_Reload does not use an AnimatorController.");
            AnimatorState state = controller.layers[0].stateMachine.defaultState ??
                throw new InvalidOperationException(
                    "Musket_Reload controller has no default state.");
            MusketAnimationSpec reloadSpec = GetMusketAnimationSpecs()
                .Single(spec => string.Equals(
                    spec.TargetName,
                    MusketReloadTargetName,
                    StringComparison.Ordinal));
            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                reloadSpec.GeneratedClipPath) ??
                throw new FileNotFoundException(
                    "The original generated Musket_Reload clip is missing.",
                    Path.GetFullPath(reloadSpec.GeneratedClipPath));
            state.motion = source;
            state.speed = 1f;
            EditorUtility.SetDirty(controller);
            AssetDatabase.SaveAssets();
        }

        private static void BakeShotgunHeldCorrection(
            AnimationClip destination,
            AnimationClip source,
            Transform template,
            ShotgunAnimationSpec spec,
            ShotgunGripAnalysis analysis,
            ShotgunGripBinding grip,
            AnimationClip emptyIdleReference,
            AnimationClip buttIdleReference,
            bool handEdgeForward = false,
            bool buttBodySideRightGrip = false)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(template.gameObject);
            workObject.name = spec.TargetName + "ShotgunCorrectionBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                source.SampleAnimation(workObject, 0f);
                Transform rightHand = FindRequired(root, RightHandPath);
                Transform leftHand = FindRequired(root, LeftHandPath);
                Vector3 rightPalmLocal = rightHand.InverseTransformPoint(
                    CalculateRightPalmSample(root).Center);
                Vector3 leftPalmLocal = leftHand.InverseTransformPoint(
                    CalculateLeftPalmSample(root).Center);
                List<string> armPaths = new List<string>
                {
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath,
                    RightForeArmPath,
                    RightHandPath
                };
                if (buttBodySideRightGrip)
                {
                    armPaths.Add(RightArmPath);
                }
                Dictionary<string, TransformCurveTrack> armTracks = armPaths
                    .ToDictionary(
                        path => path,
                        path => new TransformCurveTrack(path),
                        StringComparer.Ordinal);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                bool stow = string.Equals(
                    spec.TargetName,
                    ShotgunStowTargetName,
                    StringComparison.Ordinal);
                bool buttStrike = string.Equals(
                    spec.TargetName,
                    ShotgunButtStrikeTargetName,
                    StringComparison.Ordinal);
                Quaternion previousRightForeArmRotation = Quaternion.identity;
                Quaternion previousRightHandRotation = Quaternion.identity;
                Quaternion stableRightHandPerformerRotation =
                    Quaternion.identity;
                bool hasPreviousRightWristRotation = false;
                // These rotations select the continuous elbow solution for
                // the body-side right-hand grip across sampled frames.
                Quaternion previousBodyGripRightArmRotation = Quaternion.identity;
                Quaternion previousBodyGripRightForeArmRotation = Quaternion.identity;
                Quaternion previousBodyGripRightHandRotation = Quaternion.identity;
                bool hasPreviousBodyGripRightArmRotation = false;
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / Mathf.Max(1f, source.frameRate));
                    float leftWeight = GetShotgunLeftSupportWeight(
                        spec.TargetName,
                        time,
                        source.length);
                    source.SampleAnimation(workObject, time);
                    if (stow)
                    {
                        BlendShotgunArmsFromReferenceClip(
                            workObject,
                            source,
                            emptyIdleReference,
                            time,
                            source.length,
                            1f - leftWeight,
                            false);
                    }
                    else if (buttStrike)
                    {
                        BlendShotgunArmsFromReferenceClip(
                            workObject,
                            source,
                            buttIdleReference ??
                            throw new InvalidOperationException(
                                "Shotgun_ButtMode_Idle correction is required before ButtStrike."),
                            time,
                            source.length,
                            1f,
                            false);
                    }
                    rightHand = FindRequired(root, RightHandPath);
                    leftHand = FindRequired(root, LeftHandPath);
                    if (handEdgeForward)
                    {
                        AdjustShotgunRightArmForPalmLeftHandEdgeForward(
                            root,
                            ref previousRightForeArmRotation,
                            ref previousRightHandRotation,
                            ref hasPreviousRightWristRotation);
                    }
                    else
                    {
                        AdjustShotgunRightArmForPalmFacingPerformerLeft(
                            root,
                            ref previousRightForeArmRotation,
                            ref previousRightHandRotation,
                            ref stableRightHandPerformerRotation,
                            ref hasPreviousRightWristRotation);
                    }
                    Transform item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    item.localScale = grip.NormalLocalScale;
                    bool butt = string.Equals(
                        spec.ItemMode,
                        "Butt",
                        StringComparison.Ordinal);
                    bool reload = string.Equals(
                        spec.TargetName,
                        ShotgunReloadTargetName,
                        StringComparison.Ordinal);
                    bool preserveDrawStowOrientation =
                        string.Equals(
                            spec.TargetName,
                            ShotgunDrawTargetName,
                            StringComparison.Ordinal) ||
                        string.Equals(
                            spec.TargetName,
                            ShotgunStowTargetName,
                            StringComparison.Ordinal);
                    Vector3 desiredItemPosition;
                    Quaternion desiredItemRotation;
                    if (butt)
                    {
                        ShotgunTorsoClearanceProfile torsoProfile =
                            MeasureShotgunTorsoClearanceProfile(
                                root,
                                true);
                        ConfigureShotgunButtWorldPose(
                            root,
                            rightHand.TransformPoint(rightPalmLocal),
                            item,
                            analysis,
                            torsoProfile,
                            out desiredItemPosition,
                            out desiredItemRotation,
                            buttStrike ? 0.12f : 0.40f);
                        desiredItemPosition =
                            rightHand.TransformPoint(rightPalmLocal) -
                            desiredItemRotation * Vector3.Scale(
                                analysis.SupportPoint,
                                item.lossyScale);
                        if (buttStrike && buttBodySideRightGrip)
                        {
                            Vector3 rightGripOffset =
                                desiredItemRotation * Vector3.Scale(
                                    GetShotgunButtBodySideRightGripPoint(
                                        analysis),
                                    item.lossyScale);
                            Vector3 leftGripOffset =
                                desiredItemRotation * Vector3.Scale(
                                    analysis.HandlePoint,
                                    item.lossyScale);
                            ResolveShotgunReachableHeldPose(
                                root,
                                item,
                                analysis,
                                torsoProfile,
                                CalculateRightPalmSample(root).Center,
                                CalculateLeftPalmSample(root).Center,
                                rightGripOffset,
                                leftGripOffset,
                                true,
                                0f,
                                ref desiredItemPosition,
                                desiredItemRotation);
                        }
                    }
                    else if (preserveDrawStowOrientation)
                    {
                        item.localPosition = grip.NormalLocalPosition;
                        item.localRotation = grip.NormalLocalRotation;
                        item.localScale = grip.NormalLocalScale;
                        Vector3 sourceItemPosition = item.position;
                        Quaternion sourceItemRotation = item.rotation;
                        ConfigureShotgunNormalWorldPose(
                            root,
                            rightHand.TransformPoint(rightPalmLocal),
                            item,
                            analysis,
                            out Vector3 heldItemPosition,
                            out Quaternion heldItemRotation);
                        // Finish the right-palm grip as soon as the pose has
                        // become a two-hand hold; leftWeight still controls
                        // the left-arm release/reach timing independently.
                        float twoHandGripWeight = Mathf.SmoothStep(
                            0f,
                            1f,
                            Mathf.InverseLerp(0f, 0.9f, leftWeight));
                        desiredItemPosition = Vector3.Lerp(
                            sourceItemPosition,
                            heldItemPosition,
                            twoHandGripWeight);
                        desiredItemRotation = Quaternion.Slerp(
                            sourceItemRotation,
                            heldItemRotation,
                            twoHandGripWeight);
                        item.position = desiredItemPosition;
                        item.rotation = desiredItemRotation;
                        item.localScale = grip.NormalLocalScale;
                    }
                    else
                    {
                        ConfigureShotgunNormalWorldPose(
                            root,
                            rightHand.TransformPoint(rightPalmLocal),
                            item,
                            analysis,
                            out desiredItemPosition,
                            out desiredItemRotation);
                    }

                    item.position = desiredItemPosition;
                    item.rotation = desiredItemRotation;
                    item.localScale = grip.NormalLocalScale;
                    Vector3 leftGripTarget;
                    if (butt)
                    {
                        leftGripTarget = item.TransformPoint(
                            analysis.HandlePoint);
                    }
                    else if (reload)
                    {
                        GetShotgunReloadLeftGripTarget(
                            item,
                            analysis,
                            time,
                            source.length,
                            out leftGripTarget,
                            out Vector3 _);
                    }
                    else
                    {
                        Vector3 surfaceNormal = item.TransformDirection(
                            analysis.Geometry.TriggerDirectionAxis);
                        leftGripTarget = item.TransformPoint(
                                             analysis.ForwardSupportPoint) +
                                         surfaceNormal *
                                         GetShotgunSupportPalmOffsetMeters(
                                             spec.TargetName);
                    }

                    item.position = desiredItemPosition;
                    item.rotation = desiredItemRotation;
                    item.localScale = grip.NormalLocalScale;

                    if (butt && buttBodySideRightGrip)
                    {
                        Vector3 bodySideRightGripTarget = item.TransformPoint(
                            GetShotgunButtBodySideRightGripPoint(analysis));
                        MoveShotgunRightPalmToFixedItemGrip(
                            root,
                            rightHand,
                            item,
                            rightPalmLocal,
                            bodySideRightGripTarget,
                            grip.NormalLocalScale,
                            ref previousBodyGripRightArmRotation,
                            ref previousBodyGripRightForeArmRotation,
                            ref previousBodyGripRightHandRotation,
                            ref hasPreviousBodyGripRightArmRotation);
                        previousRightForeArmRotation = FindRequired(
                            root,
                            RightForeArmPath).localRotation;
                        previousRightHandRotation = rightHand.localRotation;
                    }

                    if (butt)
                    {
                        ApplyShotgunPalmIk(
                            root,
                            false,
                            leftPalmLocal,
                            item.TransformPoint(analysis.HandlePoint),
                            root.right,
                            true,
                            0f,
                            Vector3.forward,
                            !buttStrike);
                    }
                    else
                    {
                        if (leftWeight > 0.0001f)
                        {
                            Transform leftArm = FindRequired(root, LeftArmPath);
                            Transform leftForeArm = FindRequired(
                                root,
                                LeftForeArmPath);
                            Quaternion sourceArm = leftArm.localRotation;
                            Quaternion sourceForeArm = leftForeArm.localRotation;
                            Quaternion sourceHand = leftHand.localRotation;
                            Vector3 palmTarget;
                            Vector3 palmDirection;
                            if (reload)
                            {
                                GetShotgunReloadLeftGripTarget(
                                    item,
                                    analysis,
                                    time,
                                    source.length,
                                    out palmTarget,
                                    out palmDirection);
                            }
                            else
                            {
                                Vector3 surfaceNormal = item.TransformDirection(
                                    analysis.Geometry.TriggerDirectionAxis);
                                palmTarget = item.TransformPoint(
                                        analysis.ForwardSupportPoint) +
                                    surfaceNormal *
                                    GetShotgunSupportPalmOffsetMeters(
                                        spec.TargetName);
                                palmDirection = -surfaceNormal;
                            }
                            ApplyShotgunPalmIk(
                                root,
                                false,
                                leftPalmLocal,
                                palmTarget,
                                palmDirection,
                                reload);
                            leftArm.localRotation = Quaternion.Slerp(
                                sourceArm,
                                leftArm.localRotation,
                                leftWeight);
                            leftForeArm.localRotation = Quaternion.Slerp(
                                sourceForeArm,
                                leftForeArm.localRotation,
                                leftWeight);
                            leftHand.localRotation = Quaternion.Slerp(
                                sourceHand,
                                leftHand.localRotation,
                                leftWeight);
                        }
                    }

                    foreach (string path in armPaths)
                    {
                        armTracks[path].Add(time, FindRequired(root, path));
                    }

                    itemTrack.Add(time, item);
                }

                foreach (TransformCurveTrack track in armTracks.Values)
                {
                    SetRotationTrackCurves(destination, track);
                }

                SetTransformTrackCurves(destination, itemTrack);
                SetShotgunItemScaleCurves(
                    destination,
                    itemTrack.Path,
                    grip.NormalLocalScale,
                    source.length);
                destination.EnsureQuaternionContinuity();
                EditorUtility.SetDirty(destination);
                AssetDatabase.SaveAssets();
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void BlendShotgunArmsFromReferenceClip(
            GameObject workObject,
            AnimationClip source,
            AnimationClip reference,
            float sourceTime,
            float sourceDuration,
            float weight,
            bool includeRightArm)
        {
            float blend = Mathf.Clamp01(weight);
            if (blend <= 0.0001f)
            {
                return;
            }

            float normalized = sourceDuration > 0.0001f
                ? Mathf.Clamp01(sourceTime / sourceDuration)
                : 0f;
            reference.SampleAnimation(
                workObject,
                normalized * reference.length);
            Transform root = workObject.transform;
            Quaternion referenceShoulder =
                FindRequired(root, LeftShoulderPath).localRotation;
            Quaternion referenceArm =
                FindRequired(root, LeftArmPath).localRotation;
            Quaternion referenceForeArm =
                FindRequired(root, LeftForeArmPath).localRotation;
            Quaternion referenceHand =
                FindRequired(root, LeftHandPath).localRotation;
            Quaternion referenceRightShoulder = includeRightArm
                ? FindRequired(root, RightShoulderPath).localRotation
                : Quaternion.identity;
            Quaternion referenceRightArm = includeRightArm
                ? FindRequired(root, RightArmPath).localRotation
                : Quaternion.identity;
            Quaternion referenceRightForeArm = includeRightArm
                ? FindRequired(root, RightForeArmPath).localRotation
                : Quaternion.identity;
            Quaternion referenceRightHand = includeRightArm
                ? FindRequired(root, RightHandPath).localRotation
                : Quaternion.identity;

            source.SampleAnimation(workObject, sourceTime);
            Transform shoulder = FindRequired(root, LeftShoulderPath);
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Transform hand = FindRequired(root, LeftHandPath);
            shoulder.localRotation = Quaternion.Slerp(
                shoulder.localRotation,
                referenceShoulder,
                blend);
            arm.localRotation = Quaternion.Slerp(
                arm.localRotation,
                referenceArm,
                blend);
            foreArm.localRotation = Quaternion.Slerp(
                foreArm.localRotation,
                referenceForeArm,
                blend);
            hand.localRotation = Quaternion.Slerp(
                hand.localRotation,
                referenceHand,
                blend);
            if (!includeRightArm)
            {
                return;
            }

            Transform rightShoulder = FindRequired(root, RightShoulderPath);
            Transform rightArm = FindRequired(root, RightArmPath);
            Transform rightForeArm = FindRequired(root, RightForeArmPath);
            Transform rightHand = FindRequired(root, RightHandPath);
            rightShoulder.localRotation = Quaternion.Slerp(
                rightShoulder.localRotation,
                referenceRightShoulder,
                blend);
            rightArm.localRotation = Quaternion.Slerp(
                rightArm.localRotation,
                referenceRightArm,
                blend);
            rightForeArm.localRotation = Quaternion.Slerp(
                rightForeArm.localRotation,
                referenceRightForeArm,
                blend);
            rightHand.localRotation = Quaternion.Slerp(
                rightHand.localRotation,
                referenceRightHand,
                blend);
        }

        private static void BakeShotgunButtStrikeStraightThrust(
            AnimationClip destination,
            Transform template,
            ShotgunGripAnalysis analysis)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name =
                ShotgunButtStrikeTargetName + "StraightThrustBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                destination.SampleAnimation(workObject, 0f);
                Transform rightHand = FindRequired(root, RightHandPath);
                Transform leftHand = FindRequired(root, LeftHandPath);
                Transform leftForeArm = FindRequired(root, LeftForeArmPath);
                Transform rightForeArm = FindRequired(root, RightForeArmPath);
                Transform item = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                Vector3 rightPalmLocal = rightHand.InverseTransformPoint(
                    CalculateRightPalmSample(root).Center);
                Vector3 leftPalmLocal = leftHand.InverseTransformPoint(
                    CalculateLeftPalmSample(root).Center);
                Quaternion heldRightHandItemRotation = Quaternion.Inverse(
                    item.rotation) * rightHand.rotation;
                Quaternion heldLeftHandItemRotation = Quaternion.Inverse(
                    item.rotation) * leftHand.rotation;
                Vector3 heldLeftWristItemLocal = item.InverseTransformPoint(
                    leftHand.position +
                    item.TransformPoint(analysis.HandlePoint) -
                    leftHand.TransformPoint(leftPalmLocal));
                Quaternion heldItemRootRotation = Quaternion.Inverse(
                    root.rotation) * item.rotation;
                Vector3 heldItemRootPosition = root.InverseTransformPoint(
                    item.position);
                Vector3 heldElbowRootPosition = root.InverseTransformPoint(
                    leftForeArm.position);
                Vector3 heldRightElbowRootPosition = root.InverseTransformPoint(
                    rightForeArm.position);
                Vector3 itemScale = item.localScale;
                Vector3 rightGripLocal =
                    GetShotgunButtBodySideRightGripPoint(analysis);
                Vector3 heldRightWristItemLocal = item.InverseTransformPoint(
                    rightHand.position +
                    item.TransformPoint(rightGripLocal) -
                    rightHand.TransformPoint(rightPalmLocal));
                float straightThrustDistance =
                    GetShotgunButtStrikeReachableStraightAdvance(
                        root,
                        item,
                        heldLeftWristItemLocal,
                        heldRightWristItemLocal,
                        ShotgunButtStrikeImpactAdvanceMeters);
                string[] adjustedPaths =
                {
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath,
                    RightShoulderPath,
                    RightArmPath,
                    RightForeArmPath,
                    RightHandPath
                };
                Dictionary<string, TransformCurveTrack> tracks =
                    adjustedPaths.ToDictionary(
                        path => path,
                        path => new TransformCurveTrack(path),
                        StringComparer.Ordinal);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                Quaternion previousLeftArmRotation = Quaternion.identity;
                Quaternion previousLeftForeArmRotation = Quaternion.identity;
                Quaternion previousLeftHandRotation = Quaternion.identity;
                Quaternion previousLeftForeArmWorldRotation =
                    Quaternion.identity;
                Vector3 previousLeftElbowRootPosition = Vector3.zero;
                bool hasPreviousLeftArmRotation = false;
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(
                        destination.length * destination.frameRate));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        destination.length,
                        frame / Mathf.Max(1f, destination.frameRate));
                    destination.SampleAnimation(workObject, time);
                    rightHand = FindRequired(root, RightHandPath);
                    leftHand = FindRequired(root, LeftHandPath);
                    item = FindRequired(
                        root,
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    float forwardAdvance =
                        GetShotgunButtStrikeImpactWeight(
                            time,
                            destination.length) *
                        straightThrustDistance;
                    item.localScale = itemScale;
                    item.rotation = root.rotation * heldItemRootRotation;
                    item.position = root.TransformPoint(
                                        heldItemRootPosition) +
                                    root.forward * forwardAdvance;
                    ApplyShotgunRightPalmIkWithFixedItemPose(
                        root,
                        rightHand,
                        item,
                        rightPalmLocal,
                        item.TransformPoint(rightGripLocal),
                        item.rotation * heldRightHandItemRotation,
                        itemScale,
                        root.TransformPoint(heldRightElbowRootPosition));
                    AimShotgunLeftShoulderForFixedTargetReach(
                        root,
                        item.TransformPoint(heldLeftWristItemLocal));
                    ApplyShotgunLeftPalmIkWithFixedItemPose(
                        root,
                        leftPalmLocal,
                        item.TransformPoint(analysis.HandlePoint),
                        item.rotation * heldLeftHandItemRotation,
                        root.TransformPoint(heldElbowRootPosition),
                        ref previousLeftArmRotation,
                        ref previousLeftForeArmRotation,
                        ref previousLeftHandRotation,
                        ref previousLeftForeArmWorldRotation,
                        ref previousLeftElbowRootPosition,
                        ref hasPreviousLeftArmRotation);

                    foreach (string path in adjustedPaths)
                    {
                        tracks[path].Add(time, FindRequired(root, path));
                    }
                    itemTrack.Add(time, item);
                }

                foreach (TransformCurveTrack track in tracks.Values)
                {
                    SetRotationTrackCurves(destination, track);
                }
                SetTransformTrackCurves(destination, itemTrack);
                SetShotgunItemScaleCurves(
                    destination,
                    itemTrack.Path,
                    itemScale,
                    destination.length);
                destination.EnsureQuaternionContinuity();
                AnimationClipSettings settings =
                    AnimationUtility.GetAnimationClipSettings(destination);
                settings.loopTime = false;
                settings.loopBlend = false;
                AnimationUtility.SetAnimationClipSettings(
                    destination,
                    settings);
                EditorUtility.SetDirty(destination);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static float GetShotgunButtStrikeReachableStraightAdvance(
            Transform root,
            Transform item,
            Vector3 leftWristItemLocal,
            Vector3 rightWristItemLocal,
            float requestedAdvanceMeters)
        {
            float leftAdvance = GetShotgunStraightAdvanceWithinArmReach(
                root,
                item,
                false,
                leftWristItemLocal,
                requestedAdvanceMeters);
            float rightAdvance = GetShotgunStraightAdvanceWithinArmReach(
                root,
                item,
                true,
                rightWristItemLocal,
                requestedAdvanceMeters);
            float sharedAdvance = Mathf.Min(leftAdvance, rightAdvance) - 0.005f;
            if (sharedAdvance <= 0.02f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike two-hand grip has no usable straight-thrust reach.");
            }

            return sharedAdvance;
        }

        private static float GetShotgunStraightAdvanceWithinArmReach(
            Transform root,
            Transform item,
            bool right,
            Vector3 wristItemLocal,
            float requestedAdvanceMeters)
        {
            Transform arm = FindRequired(
                root,
                right ? RightArmPath : LeftArmPath);
            Transform foreArm = FindRequired(
                root,
                right ? RightForeArmPath : LeftForeArmPath);
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            float maximumReach =
                Vector3.Distance(arm.position, foreArm.position) +
                Vector3.Distance(foreArm.position, hand.position) - 0.0005f;
            Vector3 baseTarget = item.TransformPoint(wristItemLocal);
            if (Vector3.Distance(arm.position, baseTarget) > maximumReach)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike stable two-hand pose starts outside " +
                    (right ? "right" : "left") + " arm reach.");
            }

            Vector3 requestedTarget = baseTarget +
                                      root.forward * requestedAdvanceMeters;
            if (Vector3.Distance(arm.position, requestedTarget) <= maximumReach)
            {
                return requestedAdvanceMeters;
            }

            float lower = 0f;
            float upper = requestedAdvanceMeters;
            for (int iteration = 0; iteration < 16; iteration++)
            {
                float midpoint = (lower + upper) * 0.5f;
                Vector3 target = baseTarget + root.forward * midpoint;
                if (Vector3.Distance(arm.position, target) <= maximumReach)
                {
                    lower = midpoint;
                }
                else
                {
                    upper = midpoint;
                }
            }

            return lower;
        }

        private static void ApplyShotgunRightPalmIkWithFixedItemPose(
            Transform root,
            Transform rightHand,
            Transform item,
            Vector3 palmLocal,
            Vector3 requestedPalm,
            Quaternion requestedHandRotation,
            Vector3 itemLocalScale,
            Vector3 elbowPole)
        {
            Vector3 itemWorldPosition = item.position;
            Quaternion itemWorldRotation = item.rotation;
            Transform rightArm = FindRequired(root, RightArmPath);
            Transform rightForeArm = FindRequired(root, RightForeArmPath);
            item.SetParent(root, true);
            for (int iteration = 0; iteration < 5; iteration++)
            {
                rightHand.rotation = requestedHandRotation;
                Vector3 requestedHand = rightHand.position +
                    requestedPalm - rightHand.TransformPoint(palmLocal);
                SolveTwoBoneIk(
                    rightArm,
                    rightForeArm,
                    rightHand,
                    requestedHand,
                    elbowPole);
            }
            rightHand.rotation = requestedHandRotation;
            item.SetParent(rightHand, true);
            item.position = itemWorldPosition;
            item.rotation = itemWorldRotation;
            item.localScale = itemLocalScale;
        }

        private static AnimationClip
            CreateOrUpdateCorrectedShotgunButtTransitionClip(
                Transform template,
                AnimationClip idleSource,
                GameObject shotgunAsset,
                ShotgunGripAnalysis analysis,
                ShotgunGripBinding grip,
                string path,
                string clipName,
                bool reverse,
                bool handEdgeForward = false,
                bool buttBodySideRightGrip = false)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(template.gameObject);
            workObject.name = clipName + "CorrectedBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                AnimationClip generated = CreateShotgunIdleTimelineBase(
                    idleSource,
                    clipName + "_Corrected");
                idleSource.SampleAnimation(workObject, 0f);
                Transform rightHand = FindRequired(root, RightHandPath);
                Transform leftHand = FindRequired(root, LeftHandPath);
                Vector3 rightPalmLocal = rightHand.InverseTransformPoint(
                    CalculateRightPalmSample(root).Center);
                Vector3 leftPalmLocal = leftHand.InverseTransformPoint(
                    CalculateLeftPalmSample(root).Center);
                GameObject itemObject = UnityEngine.Object.Instantiate(shotgunAsset);
                itemObject.name = ShotgunHandInstanceName;
                itemObject.hideFlags = HideFlags.HideAndDontSave;
                itemObject.transform.SetParent(rightHand, false);
                Transform item = itemObject.transform;
                List<string> armPaths = new List<string>
                {
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath,
                    RightForeArmPath,
                    RightHandPath
                };
                if (buttBodySideRightGrip)
                {
                    armPaths.Add(RightArmPath);
                }
                Dictionary<string, TransformCurveTrack> armTracks = armPaths
                    .ToDictionary(
                        value => value,
                        value => new TransformCurveTrack(value),
                        StringComparer.Ordinal);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                Quaternion previousRightForeArmRotation = Quaternion.identity;
                Quaternion previousRightHandRotation = Quaternion.identity;
                Quaternion stableRightHandPerformerRotation =
                    Quaternion.identity;
                bool hasPreviousRightWristRotation = false;
                // These rotations select the continuous elbow solution for
                // the body-side right-hand grip throughout Enter/Exit.
                Quaternion previousBodyGripRightArmRotation = Quaternion.identity;
                Quaternion previousBodyGripRightForeArmRotation = Quaternion.identity;
                Quaternion previousBodyGripRightHandRotation = Quaternion.identity;
                bool hasPreviousBodyGripRightArmRotation = false;
                int frameCount = Mathf.RoundToInt(
                    ShotgunButtClipSeconds * ShotgunButtClipFrameRate);
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = frame / ShotgunButtClipFrameRate;
                    float idleTime = idleSource.length > 0.0001f
                        ? Mathf.Clamp01(time / ShotgunButtClipSeconds) *
                          idleSource.length
                        : 0f;
                    idleSource.SampleAnimation(workObject, idleTime);
                    rightHand = FindRequired(root, RightHandPath);
                    leftHand = FindRequired(root, LeftHandPath);
                    if (handEdgeForward)
                    {
                        AdjustShotgunRightArmForPalmLeftHandEdgeForward(
                            root,
                            ref previousRightForeArmRotation,
                            ref previousRightHandRotation,
                            ref hasPreviousRightWristRotation);
                    }
                    else
                    {
                        AdjustShotgunRightArmForPalmFacingPerformerLeft(
                            root,
                            ref previousRightForeArmRotation,
                            ref previousRightHandRotation,
                            ref stableRightHandPerformerRotation,
                            ref hasPreviousRightWristRotation);
                    }
                    item.SetParent(rightHand, false);
                    item.localScale = grip.NormalLocalScale;
                    ConfigureShotgunNormalWorldPose(
                        root,
                        rightHand.TransformPoint(rightPalmLocal),
                        item,
                        analysis,
                        out Vector3 normalPosition,
                        out Quaternion normalRotation);
                    ConfigureShotgunButtWorldPose(
                        root,
                        rightHand.TransformPoint(rightPalmLocal),
                        item,
                        analysis,
                        MeasureShotgunTorsoClearanceProfile(
                            root,
                            true),
                        out Vector3 buttPosition,
                        out Quaternion buttRotation);
                    float raw = Mathf.Clamp01(
                        time / ShotgunButtTransitionSeconds);
                    float smooth = raw * raw * (3f - 2f * raw);
                    float blend = reverse ? 1f - smooth : smooth;
                    Vector3 desiredPosition = Vector3.Lerp(
                        normalPosition,
                        buttPosition,
                        blend);
                    Quaternion desiredRotation = Quaternion.Slerp(
                        normalRotation,
                        buttRotation,
                        blend);
                    item.position = desiredPosition;
                    item.rotation = desiredRotation;
                    item.localScale = grip.NormalLocalScale;
                    GetShotgunButtRegripTargets(
                        root,
                        item,
                        analysis,
                        blend,
                        out Vector3 rightGripTarget,
                        out Vector3 _,
                        out Vector3 _,
                        out Vector3 _);
                    desiredPosition +=
                        rightHand.TransformPoint(rightPalmLocal) -
                        rightGripTarget;
                    item.position = desiredPosition;
                    item.rotation = desiredRotation;
                    item.localScale = grip.NormalLocalScale;
                    if (buttBodySideRightGrip)
                    {
                        GetShotgunButtRegripTargets(
                            root,
                            item,
                            analysis,
                            blend,
                            out Vector3 bodySideRightGripTarget,
                            out Vector3 _,
                            out Vector3 _,
                            out Vector3 _,
                            true);
                        MoveShotgunRightPalmToFixedItemGrip(
                            root,
                            rightHand,
                            item,
                            rightPalmLocal,
                            bodySideRightGripTarget,
                            grip.NormalLocalScale,
                            ref previousBodyGripRightArmRotation,
                            ref previousBodyGripRightForeArmRotation,
                            ref previousBodyGripRightHandRotation,
                            ref hasPreviousBodyGripRightArmRotation);
                        previousRightForeArmRotation = FindRequired(
                            root,
                            RightForeArmPath).localRotation;
                        previousRightHandRotation = rightHand.localRotation;
                    }
                    GetShotgunButtRegripTargets(
                        root,
                        item,
                        analysis,
                        blend,
                        out Vector3 _,
                        out Vector3 leftGripTarget,
                        out Vector3 _,
                        out Vector3 leftPalmDirection,
                        buttBodySideRightGrip);
                    ApplyShotgunPalmIk(
                        root,
                        false,
                        leftPalmLocal,
                        leftGripTarget,
                        leftPalmDirection);
                    foreach (string armPath in armPaths)
                    {
                        armTracks[armPath].Add(
                            time,
                            FindRequired(root, armPath));
                    }

                    itemTrack.Add(time, item);
                }

                foreach (TransformCurveTrack track in armTracks.Values)
                {
                    SetRotationTrackCurves(generated, track);
                }

                SetTransformTrackCurves(generated, itemTrack);
                SetShotgunItemScaleCurves(
                    generated,
                    itemTrack.Path,
                    grip.NormalLocalScale,
                    ShotgunButtClipSeconds);
                generated.EnsureQuaternionContinuity();
                AnimationClipSettings settings =
                    AnimationUtility.GetAnimationClipSettings(generated);
                settings.loopTime = true;
                settings.loopBlend = false;
                AnimationUtility.SetAnimationClipSettings(generated, settings);
                AnimationClip existing =
                    AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
                if (existing == null)
                {
                    AssetDatabase.CreateAsset(generated, path);
                    existing = generated;
                }
                else
                {
                    EditorUtility.CopySerialized(generated, existing);
                    UnityEngine.Object.DestroyImmediate(generated);
                    existing.name = clipName + "_Corrected";
                    EditorUtility.SetDirty(existing);
                }

                UnityEngine.Object.DestroyImmediate(itemObject);
                AssetDatabase.SaveAssets();
                return existing;
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void GetShotgunButtRegripTargets(
            Transform root,
            Transform item,
            ShotgunGripAnalysis analysis,
            float buttBlend,
            out Vector3 rightTarget,
            out Vector3 leftTarget,
            out Vector3 rightPalmDirection,
            out Vector3 leftPalmDirection,
            bool buttBodySideRightGrip = false)
        {
            float blend = Mathf.Clamp01(buttBlend);
            // Regrip on the weapon itself. The right hand moves first toward
            // the barrel support, then the left hand follows toward the rear
            // handle, so the hands never meet at one shared staging point.
            float rightMove = Mathf.SmoothStep(
                0f,
                1f,
                Mathf.InverseLerp(0.12f, 0.62f, blend));
            float leftMove = Mathf.SmoothStep(
                0f,
                1f,
                Mathf.InverseLerp(0.38f, 0.88f, blend));
            Vector3 rightButtLocal = buttBodySideRightGrip
                ? GetShotgunButtBodySideRightGripPoint(analysis)
                : analysis.SupportPoint;
            Vector3 rightLocal = Vector3.Lerp(
                analysis.HandlePoint,
                rightButtLocal,
                rightMove);
            rightTarget = item.TransformPoint(rightLocal);

            Vector3 leftLocal = Vector3.Lerp(
                analysis.ForwardSupportPoint,
                analysis.HandlePoint,
                leftMove);
            Vector3 characterLeft = GetCharacterLeftDirection(root);
            Vector3 itemPalmUp = -item.TransformDirection(
                analysis.Geometry.TriggerDirectionAxis);
            Vector3 leftSurfaceTarget = item.TransformPoint(leftLocal);
            if (buttBodySideRightGrip)
            {
                float longitudinalSeparation = Vector3.Distance(
                    rightTarget,
                    leftSurfaceTarget);
                float lateralSeparation = Mathf.Sqrt(Mathf.Max(
                    0f,
                    ShotgunButtRegripClearanceArcMeters *
                    ShotgunButtRegripClearanceArcMeters -
                    longitudinalSeparation * longitudinalSeparation));
                rightTarget += root.right * lateralSeparation;
            }
            float leftSurfaceArc = Mathf.Sin(leftMove * Mathf.PI);
            leftTarget = leftSurfaceTarget -
                         characterLeft * (leftSurfaceArc * 0.025f);

            rightPalmDirection = Vector3.Slerp(
                characterLeft,
                itemPalmUp,
                rightMove).normalized;
            leftPalmDirection = Vector3.Slerp(
                itemPalmUp,
                -characterLeft,
                leftMove).normalized;
        }

        private static Vector3 GetShotgunButtBodySideRightGripPoint(
            ShotgunGripAnalysis analysis)
        {
            return Vector3.Lerp(
                analysis.SupportPoint,
                analysis.ForwardSupportPoint,
                ShotgunButtBodySideGripProgress);
        }

        private static void MoveShotgunRightPalmToFixedItemGrip(
            Transform root,
            Transform rightHand,
            Transform item,
            Vector3 rightPalmLocal,
            Vector3 requestedPalm,
            Vector3 itemLocalScale,
            ref Quaternion previousArmLocalRotation,
            ref Quaternion previousForeArmLocalRotation,
            ref Quaternion previousHandLocalRotation,
            ref bool hasPreviousRotation)
        {
            Vector3 itemWorldPosition = item.position;
            Quaternion itemWorldRotation = item.rotation;
            Transform rightArm = FindRequired(root, RightArmPath);
            Transform rightForeArm = FindRequired(root, RightForeArmPath);
            Quaternion desiredHandWorldRotation = rightHand.rotation;
            Vector3 requestedHand = rightHand.position +
                requestedPalm - rightHand.TransformPoint(rightPalmLocal);
            item.SetParent(root, true);
            SolveShotgunRightArmIkContinuous(
                root,
                rightArm,
                rightForeArm,
                rightHand,
                requestedHand,
                desiredHandWorldRotation,
                ref previousArmLocalRotation,
                ref previousForeArmLocalRotation,
                ref previousHandLocalRotation,
                ref hasPreviousRotation);
            item.SetParent(rightHand, true);
            item.position = itemWorldPosition;
            item.rotation = itemWorldRotation;
            item.localScale = itemLocalScale;
        }

        private static void SolveShotgunRightArmIkContinuous(
            Transform root,
            Transform arm,
            Transform foreArm,
            Transform hand,
            Vector3 requestedTarget,
            Quaternion desiredHandWorldRotation,
            ref Quaternion previousArmLocalRotation,
            ref Quaternion previousForeArmLocalRotation,
            ref Quaternion previousHandLocalRotation,
            ref bool hasPreviousRotation)
        {
            Quaternion sourceArmLocalRotation = arm.localRotation;
            Quaternion sourceForeArmLocalRotation = foreArm.localRotation;
            Quaternion sourceHandLocalRotation = hand.localRotation;
            Vector3 armPosition = arm.position;
            float upperLength = Vector3.Distance(
                armPosition,
                foreArm.position);
            float lowerLength = Vector3.Distance(
                foreArm.position,
                hand.position);
            float minimumReach = Mathf.Abs(upperLength - lowerLength) + 0.0001f;
            float maximumReach = upperLength + lowerLength - 0.0001f;
            Vector3 targetVector = requestedTarget - armPosition;
            Vector3 targetDirection = targetVector.sqrMagnitude > 0.0000001f
                ? targetVector.normalized
                : (hand.position - armPosition).normalized;
            float reach = Mathf.Clamp(
                targetVector.magnitude,
                minimumReach,
                maximumReach);
            Vector3 clampedTarget = armPosition + targetDirection * reach;
            Vector3 defaultPole = foreArm.position + root.right * 0.22f -
                                  root.forward * 0.12f;
            Vector3 baseBendDirection = Vector3.ProjectOnPlane(
                defaultPole - armPosition,
                targetDirection);
            if (baseBendDirection.sqrMagnitude < 0.0000001f)
            {
                baseBendDirection = Vector3.ProjectOnPlane(
                    foreArm.position - armPosition,
                    targetDirection);
            }
            if (baseBendDirection.sqrMagnitude < 0.0000001f)
            {
                baseBendDirection = Vector3.Cross(
                    targetDirection,
                    root.up);
            }
            baseBendDirection.Normalize();

            float along =
                (upperLength * upperLength + reach * reach -
                 lowerLength * lowerLength) / (2f * reach);
            float perpendicular = Mathf.Sqrt(Mathf.Max(
                0f,
                upperLength * upperLength - along * along));
            float bestScore = float.PositiveInfinity;
            Quaternion bestArmLocalRotation = sourceArmLocalRotation;
            Quaternion bestForeArmLocalRotation = sourceForeArmLocalRotation;
            Quaternion bestHandLocalRotation = sourceHandLocalRotation;
            for (int sample = 0; sample < 72; sample++)
            {
                float bendDegrees = -180f + sample * 5f;
                arm.localRotation = sourceArmLocalRotation;
                foreArm.localRotation = sourceForeArmLocalRotation;
                hand.rotation = desiredHandWorldRotation;
                Vector3 bendDirection = Quaternion.AngleAxis(
                    bendDegrees,
                    targetDirection) * baseBendDirection;
                Vector3 elbowTarget = armPosition +
                    targetDirection * along +
                    bendDirection * perpendicular;
                arm.rotation = Quaternion.FromToRotation(
                    foreArm.position - armPosition,
                    elbowTarget - armPosition) * arm.rotation;
                foreArm.rotation = Quaternion.FromToRotation(
                    hand.position - foreArm.position,
                    clampedTarget - foreArm.position) * foreArm.rotation;
                hand.rotation = desiredHandWorldRotation;

                float sourceScore = Mathf.Max(
                    Quaternion.Angle(
                        sourceArmLocalRotation,
                        arm.localRotation),
                    Quaternion.Angle(
                        sourceForeArmLocalRotation,
                        foreArm.localRotation));
                float continuityScore = hasPreviousRotation
                    ? Mathf.Max(
                        Quaternion.Angle(
                            previousArmLocalRotation,
                            arm.localRotation),
                        Mathf.Max(
                            Quaternion.Angle(
                                previousForeArmLocalRotation,
                                foreArm.localRotation),
                            Quaternion.Angle(
                                previousHandLocalRotation,
                                hand.localRotation)))
                    : sourceScore;
                float score = hasPreviousRotation
                    ? continuityScore * 4f + sourceScore * 0.15f
                    : sourceScore;
                if (score >= bestScore)
                {
                    continue;
                }

                bestScore = score;
                bestArmLocalRotation = arm.localRotation;
                bestForeArmLocalRotation = foreArm.localRotation;
                bestHandLocalRotation = hand.localRotation;
            }

            arm.localRotation = bestArmLocalRotation;
            foreArm.localRotation = bestForeArmLocalRotation;
            hand.localRotation = bestHandLocalRotation;
            previousArmLocalRotation = bestArmLocalRotation;
            previousForeArmLocalRotation = bestForeArmLocalRotation;
            previousHandLocalRotation = bestHandLocalRotation;
            hasPreviousRotation = true;
        }

        private static AnimationClip CreateShotgunIdleTimelineBase(
            AnimationClip source,
            string clipName)
        {
            AnimationClip generated = new AnimationClip
            {
                name = clipName,
                frameRate = ShotgunButtClipFrameRate,
                wrapMode = WrapMode.Loop,
                legacy = false
            };
            int frameCount = Mathf.RoundToInt(
                ShotgunButtClipSeconds * ShotgunButtClipFrameRate);
            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetCurveBindings(source))
            {
                AnimationCurve sourceCurve =
                    AnimationUtility.GetEditorCurve(source, binding);
                bool lowerBody = binding.path.StartsWith(
                        LeftUpLegPath,
                        StringComparison.Ordinal) ||
                    binding.path.StartsWith(
                        RightUpLegPath,
                        StringComparison.Ordinal);
                if (lowerBody)
                {
                    continue;
                }

                List<Keyframe> keys = new List<Keyframe>();
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = frame / ShotgunButtClipFrameRate;
                    float sourceTime = source.length > 0.0001f
                        ? Mathf.Clamp01(time / ShotgunButtClipSeconds) *
                          source.length
                        : 0f;
                    keys.Add(new Keyframe(time, sourceCurve.Evaluate(sourceTime)));
                }

                AnimationUtility.SetEditorCurve(
                    generated,
                    binding,
                    new AnimationCurve(keys.ToArray()));
            }

            return generated;
        }

        private static void ConfigureShotgunNormalWorldPose(
            Transform root,
            Vector3 rightPalm,
            Transform item,
            ShotgunGripAnalysis analysis,
            out Vector3 position,
            out Quaternion rotation)
        {
            rotation = AlignShotgunAxes(
                analysis.Geometry.StockToMuzzleAxis,
                analysis.Geometry.TriggerDirectionAxis,
                root.forward,
                -root.up);
            item.localScale = Vector3.one *
                (ShotgunDesignLengthMeters / analysis.Geometry.SourceLength);
            position = rightPalm -
                rotation * Vector3.Scale(
                    analysis.HandlePoint,
                    item.lossyScale);
            item.position = position;
            item.rotation = rotation;
        }

        private static void ConfigureShotgunButtWorldPose(
            Transform root,
            Vector3 rightPalm,
            Transform item,
            ShotgunGripAnalysis analysis,
            ShotgunTorsoClearanceProfile torsoProfile,
            out Vector3 position,
            out Quaternion rotation,
            float maximumLateralShiftMeters = 0.40f)
        {
            Vector3 stockHorizontal =
                (root.forward * Mathf.Cos(
                     ShotgunButtOutwardYawDegrees * Mathf.Deg2Rad) -
                 root.right * Mathf.Sin(
                     ShotgunButtOutwardYawDegrees * Mathf.Deg2Rad)).normalized;
            Vector3 stockDirection =
                stockHorizontal * Mathf.Cos(ShotgunButtStockDownDegrees * Mathf.Deg2Rad) -
                root.up * Mathf.Sin(ShotgunButtStockDownDegrees * Mathf.Deg2Rad);
            rotation = AlignShotgunAxes(
                -analysis.Geometry.StockToMuzzleAxis,
                analysis.Geometry.TriggerDirectionAxis,
                stockDirection,
                -root.up);
            item.localScale = Vector3.one *
                (ShotgunDesignLengthMeters / analysis.Geometry.SourceLength);
            position = rightPalm -
                rotation * Vector3.Scale(
                    analysis.SupportPoint,
                    item.lossyScale);
            ResolveShotgunLateralClearanceForPose(
                root,
                item,
                analysis,
                torsoProfile,
                ref position,
                rotation,
                maximumLateralShiftMeters);
            item.position = position;
            item.rotation = rotation;
        }

        private static void ResolveShotgunClearanceForPose(
            Transform root,
            Transform item,
            ShotgunGripAnalysis analysis,
            ShotgunTorsoClearanceProfile clearanceProfile,
            ref Vector3 position,
            Quaternion rotation,
            float maximumLateralShiftMeters)
        {
            Vector3 posePosition = position;
            Quaternion poseRotation = rotation;
            Vector3[] posedVertices = analysis.Geometry.LocalVertices
                .Select(vertex =>
                    posePosition +
                    poseRotation * Vector3.Scale(vertex, item.lossyScale) -
                    root.position)
                .ToArray();
            float bestLateralShift = 0f;
            float bestForwardShift = float.PositiveInfinity;
            float bestDistanceSquared = float.PositiveInfinity;
            const float lateralStepMeters = 0.01f;
            int lateralSteps = Mathf.RoundToInt(
                maximumLateralShiftMeters / lateralStepMeters);
            for (int lateralStep = 0; lateralStep <= lateralSteps; lateralStep++)
            {
                float lateralShift = lateralStep * lateralStepMeters;
                float forwardShift = 0f;
                foreach (Vector3 fromRoot in posedVertices)
                {
                    float lateral = Vector3.Dot(fromRoot, root.right) + lateralShift;
                    float vertical = Vector3.Dot(fromRoot, root.up);
                    if (!clearanceProfile.TryGetFront(
                            lateral,
                            vertical,
                            out float localTorsoFront))
                    {
                        continue;
                    }

                    float weaponForward = Vector3.Dot(fromRoot, root.forward);
                    forwardShift = Mathf.Max(
                        forwardShift,
                        localTorsoFront + ShotgunTorsoClearanceMeters - weaponForward);
                }

                forwardShift = Mathf.Max(0f, forwardShift);
                float distanceSquared = lateralShift * lateralShift +
                                        forwardShift * forwardShift;
                if (distanceSquared + 0.0000001f >= bestDistanceSquared)
                {
                    continue;
                }

                bestDistanceSquared = distanceSquared;
                bestLateralShift = lateralShift;
                bestForwardShift = forwardShift;
            }

            position += root.right * bestLateralShift +
                        root.forward * bestForwardShift;
        }

        private static void ResolveShotgunReachableHeldPose(
            Transform root,
            Transform item,
            ShotgunGripAnalysis analysis,
            ShotgunTorsoClearanceProfile clearanceProfile,
            Vector3 rightPalm,
            Vector3 leftPalm,
            Vector3 rightGripOffset,
            Vector3 leftGripOffset,
            bool constrainLeft,
            float preferredForwardAdvanceMeters,
            ref Vector3 position,
            Quaternion rotation)
        {
            Vector3 rightAnchor = rightPalm - rightGripOffset;
            position = rightAnchor;
            if (constrainLeft)
            {
                Vector3 leftAnchor = leftPalm - leftGripOffset;
                position = (rightAnchor + leftAnchor) * 0.5f;
            }

            position += root.forward * preferredForwardAdvanceMeters;
            for (int iteration = 0; iteration < 4; iteration++)
            {
                ResolveShotgunClearanceForPose(
                    root,
                    item,
                    analysis,
                    clearanceProfile,
                    ref position,
                    rotation,
                    0.36f);
                Vector3 rightCorrection = GetShotgunArmReachCorrection(
                    root,
                    true,
                    rightPalm,
                    position + rightGripOffset);
                position += rightCorrection * 0.95f;

                Vector3 leftCorrection = Vector3.zero;
                if (constrainLeft)
                {
                    // Project the already right-reachable pose into the left
                    // arm's reach next. Averaging both corrections halved this
                    // dominant left-arm correction even when the right arm
                    // needed no movement at all.
                    leftCorrection = GetShotgunArmReachCorrection(
                        root,
                        false,
                        leftPalm,
                        position + leftGripOffset);
                    position += leftCorrection * 0.95f;
                }

                if (rightCorrection.sqrMagnitude <= 0.000001f &&
                    leftCorrection.sqrMagnitude <= 0.000001f)
                {
                    break;
                }
            }

            // Finish with reach-only alternating projections. Running only a
            // single right-then-left projection let the final left correction
            // push the reverse Exit pose back outside the right arm's reach.
            // Both reach regions are convex, so these inexpensive projections
            // converge to their common reachable pose when one exists.
            for (int iteration = 0; iteration < 12; iteration++)
            {
                Vector3 rightCorrection = GetShotgunArmReachCorrection(
                    root,
                    true,
                    rightPalm,
                    position + rightGripOffset);
                position += rightCorrection * 0.98f;
                Vector3 leftCorrection = Vector3.zero;
                if (constrainLeft)
                {
                    leftCorrection = GetShotgunArmReachCorrection(
                        root,
                        false,
                        leftPalm,
                        position + leftGripOffset);
                    position += leftCorrection * 0.98f;
                }

                if (rightCorrection.sqrMagnitude <= 0.0000001f &&
                    leftCorrection.sqrMagnitude <= 0.0000001f)
                {
                    break;
                }
            }
        }

        private static Vector3 GetShotgunArmReachCorrection(
            Transform root,
            bool right,
            Vector3 currentPalm,
            Vector3 requestedPalm)
        {
            Transform upper = FindRequired(
                root,
                right ? RightArmPath : LeftArmPath);
            Transform lower = FindRequired(
                root,
                right ? RightForeArmPath : LeftForeArmPath);
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            float maximumPalmReach =
                Vector3.Distance(upper.position, lower.position) +
                Vector3.Distance(lower.position, hand.position) +
                Vector3.Distance(hand.position, currentPalm) -
                0.01f;
            Vector3 shoulderToTarget = requestedPalm - upper.position;
            float overreach = shoulderToTarget.magnitude - maximumPalmReach;
            if (overreach <= 0f || shoulderToTarget.sqrMagnitude <= 0.000001f)
            {
                return Vector3.zero;
            }

            return -shoulderToTarget.normalized * overreach;
        }

        private static void ResolveShotgunLateralClearanceForPose(
            Transform root,
            Transform item,
            ShotgunGripAnalysis analysis,
            ShotgunTorsoClearanceProfile clearanceProfile,
            ref Vector3 position,
            Quaternion rotation,
            float maximumLateralShiftMeters =
                ShotgunStowMaximumLateralShiftMeters)
        {
            Vector3 posePosition = position;
            Vector3[] posedVertices = analysis.Geometry.LocalVertices
                .Select(vertex =>
                    posePosition +
                    rotation * Vector3.Scale(vertex, item.lossyScale) -
                    root.position)
                .ToArray();
            const float lateralStepMeters = 0.01f;
            int lateralSteps = Mathf.RoundToInt(
                maximumLateralShiftMeters /
                lateralStepMeters);
            for (int lateralStep = 0;
                 lateralStep <= lateralSteps;
                 lateralStep++)
            {
                float lateralShift = lateralStep * lateralStepMeters;
                bool intersects = false;
                foreach (Vector3 fromRoot in posedVertices)
                {
                    float lateral =
                        Vector3.Dot(fromRoot, root.right) + lateralShift;
                    float vertical = Vector3.Dot(fromRoot, root.up);
                    if (!clearanceProfile.TryGetDepthRange(
                            lateral,
                            vertical,
                            out float back,
                            out float front))
                    {
                        continue;
                    }

                    float weaponForward = Vector3.Dot(
                        fromRoot,
                        root.forward);
                    if (weaponForward >=
                            back - ShotgunTorsoClearanceMeters &&
                        weaponForward <=
                            front + ShotgunTorsoClearanceMeters)
                    {
                        intersects = true;
                        break;
                    }
                }

                if (intersects)
                {
                    continue;
                }

                position += root.right * lateralShift;
                return;
            }

            // If the authored Stow arc cannot clear to the character's right
            // within arm reach, keep the weapon in front of the measured body
            // surface rather than allowing it to pass through the torso.
            ResolveShotgunClearanceForPose(
                root,
                item,
                analysis,
                clearanceProfile,
                ref position,
                rotation,
                maximumLateralShiftMeters);
        }

        private static void ApplyShotgunPalmIk(
            Transform root,
            bool right,
            Vector3 palmLocal,
            Vector3 requestedPalm,
            Vector3 desiredPalmDirection,
            bool distributeWristTwist = true,
            float additionalElbowPoleBackMeters = 0f,
            Vector3? palmReferenceAxisLocal = null,
            bool alignPalmRotation = true)
        {
            string armPath = right ? RightArmPath : LeftArmPath;
            string foreArmPath = right ? RightForeArmPath : LeftForeArmPath;
            string handPath = right ? RightHandPath : LeftHandPath;
            Transform arm = FindRequired(root, armPath);
            Transform foreArm = FindRequired(root, foreArmPath);
            Transform hand = FindRequired(root, handPath);
            Quaternion originalHandRotation = hand.rotation;
            Vector3 pole = foreArm.position +
                (right ? root.right : -root.right) * 0.22f -
                root.forward * (0.12f + additionalElbowPoleBackMeters);
            for (int iteration = 0; iteration < 5; iteration++)
            {
                Vector3 requestedHand = hand.position +
                    requestedPalm - hand.TransformPoint(palmLocal);
                SolveTwoBoneIk(
                    arm,
                    foreArm,
                    hand,
                    requestedHand,
                    pole);
            }

            // Apply palm roll once after the positional solve. Repeating this
            // inside every IK iteration accumulated visible mesh twist.
            if (alignPalmRotation && distributeWristTwist)
            {
                RotateForearmAndHandForPalmFacingDirection(
                    arm,
                    foreArm,
                    hand,
                    desiredPalmDirection,
                    palmReferenceAxisLocal);
            }
            else if (alignPalmRotation)
            {
                RotateHandForPalmFacingDirection(
                    foreArm,
                    hand,
                    desiredPalmDirection);
            }

            // Palm roll rotates the weighted palm centre around the wrist.
            // Re-solve only the position while preserving that world rotation,
            // so the visible palm stays on the requested weapon surface.
            Quaternion preservedHandRotation = alignPalmRotation
                ? hand.rotation
                : originalHandRotation;
            for (int iteration = 0; iteration < 3; iteration++)
            {
                Vector3 requestedHand = hand.position +
                    requestedPalm - hand.TransformPoint(palmLocal);
                SolveTwoBoneIk(
                    arm,
                    foreArm,
                    hand,
                    requestedHand,
                    pole);
                hand.rotation = preservedHandRotation;
            }
        }

        private static float GetShotgunLeftSupportWeight(
            string targetName,
            float time,
            float duration)
        {
            float normalized = duration > 0.0001f
                ? Mathf.Clamp01(time / duration)
                : 0f;
            if (string.Equals(targetName, ShotgunDrawTargetName, StringComparison.Ordinal))
            {
                return Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.34f, 0.54f, normalized));
            }

            if (string.Equals(targetName, ShotgunStowTargetName, StringComparison.Ordinal))
            {
                return 1f - Mathf.SmoothStep(
                    0f,
                    1f,
                    Mathf.InverseLerp(0.16f, 0.42f, normalized));
            }

            return 1f;
        }

        private static void BakeShotgunFixedLeftHandAttachment(
            AnimationClip destination,
            Transform template,
            ShotgunGripAnalysis analysis,
            bool reloadSupportHold,
            bool preserveItemDirection = false)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name = destination.name + "LeftHandAttachmentBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            try
            {
                Transform root = workObject.transform;
                float holdStart = reloadSupportHold
                    ? GetShotgunReloadSupportHoldStartTime(destination.length)
                    : 0f;
                Animator animator = RequireAnimator(root);
                using (AnimationClipPoseSampler sampler =
                       new AnimationClipPoseSampler(animator, destination))
                {
                    sampler.Sample(holdStart);
                }
                Transform item = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                Transform leftForeArm = FindRequired(root, LeftForeArmPath);
                Transform leftHand = FindRequired(root, LeftHandPath);
                Vector3 leftPalmLocal = leftHand.InverseTransformPoint(
                    CalculateLeftPalmSample(root).Center);
                Vector3 heldPalmItemLocal = reloadSupportHold
                    ? item.InverseTransformPoint(
                        CalculateLeftPalmSample(root).Center)
                    : analysis.HandlePoint;
                Vector3 heldRightPalmItemLocal = item.InverseTransformPoint(
                    CalculateRightPalmSample(root).Center);
                Quaternion heldHandItemRotation = Quaternion.Inverse(
                    item.rotation) * leftHand.rotation;
                Vector3 desiredHeldPalm = item.TransformPoint(
                    heldPalmItemLocal);
                Vector3 heldLeftWristItemLocal = item.InverseTransformPoint(
                    leftHand.position +
                    desiredHeldPalm -
                    leftHand.TransformPoint(leftPalmLocal));
                Vector3 heldElbowRootLocal = root.InverseTransformPoint(
                    leftForeArm.position);
                string[] adjustedPaths =
                {
                    LeftShoulderPath,
                    LeftArmPath,
                    LeftForeArmPath,
                    LeftHandPath
                };
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(
                        destination.length * destination.frameRate));
                const int correctionPassCount = 4;
                for (int correctionPass = 0;
                     correctionPass < correctionPassCount;
                     correctionPass++)
                {
                    Dictionary<string, TransformCurveTrack> tracks =
                        adjustedPaths.ToDictionary(
                            path => path,
                            path => new TransformCurveTrack(path),
                            StringComparer.Ordinal);
                    TransformCurveTrack itemTrack = new TransformCurveTrack(
                        RightHandPath + "/" + ShotgunHandInstanceName);
                    Quaternion previousLeftArmRotation = Quaternion.identity;
                    Quaternion previousLeftForeArmRotation = Quaternion.identity;
                    Quaternion previousLeftForeArmWorldRotation =
                        Quaternion.identity;
                    Quaternion previousLeftHandRotation = Quaternion.identity;
                    Vector3 previousLeftElbowRootPosition = Vector3.zero;
                    bool hasPreviousLeftArmRotation = false;
                    Quaternion previousItemRootRotation = Quaternion.identity;
                    bool hasPreviousItemRotation = false;
                    using (AnimationClipPoseSampler sampler =
                           new AnimationClipPoseSampler(animator, destination))
                    {
                        for (int frame = 0; frame <= frameCount; frame++)
                        {
                            float time = Mathf.Min(
                                destination.length,
                                frame / Mathf.Max(
                                    1f,
                                    destination.frameRate));
                            float sampleTime = frame == frameCount
                                ? Mathf.Max(
                                    0f,
                                    destination.length -
                                    1f / Mathf.Max(
                                        1f,
                                        destination.frameRate))
                                : time;
                            sampler.Sample(sampleTime);
                            item = FindRequired(
                                root,
                                RightHandPath + "/" +
                                ShotgunHandInstanceName);
                            if (!reloadSupportHold ||
                                time + 0.0001f >= holdStart)
                            {
                                if (preserveItemDirection)
                                {
                                    KeepShotgunDirectionFixedAtRightPalm(
                                        root,
                                        item,
                                        heldRightPalmItemLocal,
                                        heldLeftWristItemLocal,
                                        ref previousItemRootRotation,
                                        ref hasPreviousItemRotation);
                                }
                                else
                                {
                                    KeepShotgunLeftGripWithinReach(
                                        root,
                                        item,
                                        heldRightPalmItemLocal,
                                        heldLeftWristItemLocal,
                                        ref previousItemRootRotation,
                                        ref hasPreviousItemRotation);
                                }
                                ApplyShotgunLeftPalmIkWithFixedItemPose(
                                    root,
                                    leftPalmLocal,
                                    item.TransformPoint(heldPalmItemLocal),
                                    item.rotation * heldHandItemRotation,
                                    root.TransformPoint(heldElbowRootLocal),
                                    ref previousLeftArmRotation,
                                    ref previousLeftForeArmRotation,
                                    ref previousLeftHandRotation,
                                    ref previousLeftForeArmWorldRotation,
                                    ref previousLeftElbowRootPosition,
                                    ref hasPreviousLeftArmRotation);
                            }
                            else
                            {
                                Transform currentLeftArm = FindRequired(
                                    root,
                                    LeftArmPath);
                                Transform currentLeftForeArm = FindRequired(
                                    root,
                                    LeftForeArmPath);
                                Transform currentLeftHand = FindRequired(
                                    root,
                                    LeftHandPath);
                                previousLeftArmRotation =
                                    currentLeftArm.localRotation;
                                previousLeftForeArmRotation =
                                    currentLeftForeArm.localRotation;
                                previousLeftForeArmWorldRotation =
                                    currentLeftForeArm.rotation;
                                previousLeftHandRotation =
                                    currentLeftHand.localRotation;
                                previousLeftElbowRootPosition =
                                    root.InverseTransformPoint(
                                        currentLeftForeArm.position);
                                hasPreviousLeftArmRotation = true;
                                previousItemRootRotation = Quaternion.Inverse(
                                    root.rotation) * item.rotation;
                                hasPreviousItemRotation = true;
                            }

                            foreach (string path in adjustedPaths)
                            {
                                tracks[path].Add(
                                    time,
                                    FindRequired(root, path));
                            }
                            itemTrack.Add(time, item);
                        }
                    }

                    foreach (EditorCurveBinding binding in AnimationUtility
                                 .GetCurveBindings(destination)
                                 .Where(binding =>
                                     adjustedPaths.Contains(
                                         binding.path,
                                         StringComparer.Ordinal) &&
                                     IsTransformRotationProperty(
                                         binding.propertyName))
                                 .ToArray())
                    {
                        AnimationUtility.SetEditorCurve(
                            destination,
                            binding,
                            null);
                    }

                    foreach (TransformCurveTrack track in tracks.Values)
                    {
                        SetRotationTrackCurves(destination, track);
                    }
                    SetTransformTrackCurves(destination, itemTrack);
                    destination.EnsureQuaternionContinuity();
                    EditorUtility.SetDirty(destination);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void KeepShotgunDirectionFixedAtRightPalm(
            Transform root,
            Transform item,
            Vector3 heldRightPalmItemLocal,
            Vector3 heldLeftWristItemLocal,
            ref Quaternion heldItemRootRotation,
            ref bool hasHeldItemRootRotation)
        {
            if (!hasHeldItemRootRotation)
            {
                heldItemRootRotation = Quaternion.Inverse(root.rotation) *
                                       item.rotation;
                hasHeldItemRootRotation = true;
            }

            item.rotation = root.rotation * heldItemRootRotation;
            Vector3 rightPalm = CalculateRightPalmSample(root).Center;
            item.position += rightPalm -
                item.TransformPoint(heldRightPalmItemLocal);
            Vector3 leftWristTarget = item.TransformPoint(
                heldLeftWristItemLocal);
            AimShotgunLeftShoulderForFixedTargetReach(
                root,
                leftWristTarget);
        }

        private static void AimShotgunButtStrikeShoulderTowardGrip(
            Transform root,
            bool right,
            Vector3 wristTarget)
        {
            Transform shoulder = FindRequired(
                root,
                right ? RightShoulderPath : LeftShoulderPath);
            Transform arm = FindRequired(
                root,
                right ? RightArmPath : LeftArmPath);
            Transform foreArm = FindRequired(
                root,
                right ? RightForeArmPath : LeftForeArmPath);
            Transform hand = FindRequired(
                root,
                right ? RightHandPath : LeftHandPath);
            float minimumReach = Mathf.Abs(
                Vector3.Distance(arm.position, foreArm.position) -
                Vector3.Distance(foreArm.position, hand.position)) +
                0.0005f;
            float maximumReach =
                Vector3.Distance(arm.position, foreArm.position) +
                Vector3.Distance(foreArm.position, hand.position) -
                0.0005f;
            float currentReach = Vector3.Distance(
                arm.position,
                wristTarget);
            if (currentReach >= minimumReach &&
                currentReach <= maximumReach)
            {
                return;
            }

            Vector3 currentDirection = arm.position - shoulder.position;
            Vector3 shoulderToTarget = wristTarget - shoulder.position;
            Vector3 targetDirection = currentReach > maximumReach
                ? shoulderToTarget
                : -shoulderToTarget;
            if (currentDirection.sqrMagnitude <= 0.000001f ||
                targetDirection.sqrMagnitude <= 0.000001f)
            {
                return;
            }

            Quaternion aimedRotation = Quaternion.FromToRotation(
                currentDirection,
                targetDirection) * shoulder.rotation;
            shoulder.rotation = Quaternion.RotateTowards(
                shoulder.rotation,
                aimedRotation,
                85f);
        }

        private static void AimShotgunRightShoulderForFixedTargetReach(
            Transform root,
            Vector3 wristTarget)
        {
            Transform shoulder = FindRequired(root, RightShoulderPath);
            Transform arm = FindRequired(root, RightArmPath);
            Transform foreArm = FindRequired(root, RightForeArmPath);
            Transform hand = FindRequired(root, RightHandPath);
            float maximumWristReach =
                Vector3.Distance(arm.position, foreArm.position) +
                Vector3.Distance(foreArm.position, hand.position) -
                0.01f - ShotgunLeftGripReachReserveMeters;
            maximumWristReach = Mathf.Max(0.05f, maximumWristReach);
            if (Vector3.Distance(arm.position, wristTarget) <=
                maximumWristReach)
            {
                return;
            }

            Vector3 currentDirection = arm.position - shoulder.position;
            Vector3 targetDirection = wristTarget - shoulder.position;
            if (currentDirection.sqrMagnitude <= 0.000001f ||
                targetDirection.sqrMagnitude <= 0.000001f)
            {
                return;
            }

            Quaternion baseRotation = shoulder.rotation;
            Quaternion aimedRotation = Quaternion.FromToRotation(
                currentDirection,
                targetDirection) * baseRotation;
            Quaternion maximumRotation = Quaternion.RotateTowards(
                baseRotation,
                aimedRotation,
                55f);
            shoulder.rotation = maximumRotation;
            if (Vector3.Distance(
                    FindRequired(root, RightArmPath).position,
                    wristTarget) > maximumWristReach)
            {
                shoulder.rotation = baseRotation;
                return;
            }

            float lower = 0f;
            float upper = 1f;
            for (int iteration = 0; iteration < 12; iteration++)
            {
                float midpoint = (lower + upper) * 0.5f;
                shoulder.rotation = Quaternion.Slerp(
                    baseRotation,
                    maximumRotation,
                    midpoint);
                bool reaches = Vector3.Distance(
                    FindRequired(root, RightArmPath).position,
                    wristTarget) <= maximumWristReach;
                if (reaches)
                {
                    upper = midpoint;
                }
                else
                {
                    lower = midpoint;
                }
            }

            shoulder.rotation = Quaternion.Slerp(
                baseRotation,
                maximumRotation,
                upper);
        }

        private static void AimShotgunLeftShoulderForFixedTargetReach(
            Transform root,
            Vector3 wristTarget)
        {
            Transform shoulder = FindRequired(root, LeftShoulderPath);
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Transform hand = FindRequired(root, LeftHandPath);
            float maximumWristReach =
                Vector3.Distance(arm.position, foreArm.position) +
                Vector3.Distance(foreArm.position, hand.position) -
                0.01f - ShotgunLeftGripReachReserveMeters;
            maximumWristReach = Mathf.Max(0.05f, maximumWristReach);
            if (Vector3.Distance(arm.position, wristTarget) <=
                maximumWristReach)
            {
                return;
            }

            Vector3 currentDirection = arm.position - shoulder.position;
            Vector3 targetDirection = wristTarget - shoulder.position;
            if (currentDirection.sqrMagnitude <= 0.000001f ||
                targetDirection.sqrMagnitude <= 0.000001f)
            {
                return;
            }

            Quaternion baseRotation = shoulder.rotation;
            Quaternion aimedRotation = Quaternion.FromToRotation(
                currentDirection,
                targetDirection) * baseRotation;
            Quaternion maximumRotation = Quaternion.RotateTowards(
                baseRotation,
                aimedRotation,
                55f);
            shoulder.rotation = maximumRotation;
            if (Vector3.Distance(
                    FindRequired(root, LeftArmPath).position,
                    wristTarget) > maximumWristReach)
            {
                shoulder.rotation = baseRotation;
                return;
            }

            float lower = 0f;
            float upper = 1f;
            for (int iteration = 0; iteration < 12; iteration++)
            {
                float midpoint = (lower + upper) * 0.5f;
                shoulder.rotation = Quaternion.Slerp(
                    baseRotation,
                    maximumRotation,
                    midpoint);
                bool reaches = Vector3.Distance(
                    FindRequired(root, LeftArmPath).position,
                    wristTarget) <= maximumWristReach;
                if (reaches)
                {
                    upper = midpoint;
                }
                else
                {
                    lower = midpoint;
                }
            }

            shoulder.rotation = Quaternion.Slerp(
                baseRotation,
                maximumRotation,
                upper);
        }

        private static void KeepShotgunLeftGripWithinReach(
            Transform root,
            Transform item,
            Vector3 heldRightPalmItemLocal,
            Vector3 heldLeftWristItemLocal,
            ref Quaternion previousItemRootRotation,
            ref bool hasPreviousItemRotation)
        {
            Transform leftArm = FindRequired(root, LeftArmPath);
            Transform leftForeArm = FindRequired(root, LeftForeArmPath);
            Transform leftHand = FindRequired(root, LeftHandPath);
            Vector3 rightPalm = CalculateRightPalmSample(root).Center;
            if (hasPreviousItemRotation)
            {
                Quaternion previousWorldRotation =
                    root.rotation * previousItemRootRotation;
                item.rotation = Quaternion.RotateTowards(
                    previousWorldRotation,
                    item.rotation,
                    ShotgunLeftGripMaximumItemStepDegrees);
            }
            item.position += rightPalm -
                item.TransformPoint(heldRightPalmItemLocal);
            Vector3 currentLeftTarget = item.TransformPoint(
                heldLeftWristItemLocal);
            float maximumWristReach =
                Vector3.Distance(leftArm.position, leftForeArm.position) +
                Vector3.Distance(leftForeArm.position, leftHand.position) -
                0.01f;
            maximumWristReach = Mathf.Max(
                0.05f,
                maximumWristReach -
                ShotgunLeftGripReachReserveMeters);
            Vector3 shoulderToTarget = currentLeftTarget - leftArm.position;
            if (shoulderToTarget.magnitude <= maximumWristReach)
            {
                previousItemRootRotation = Quaternion.Inverse(
                    root.rotation) * item.rotation;
                hasPreviousItemRotation = true;
                return;
            }

            Vector3 anchorToShoulder = leftArm.position - rightPalm;
            Vector3 anchorToTarget = currentLeftTarget - rightPalm;
            float anchorDistance = anchorToShoulder.magnitude;
            float gripDistance = anchorToTarget.magnitude;
            if (anchorDistance <= 0.0001f || gripDistance <= 0.0001f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike has no usable two-hand grip span.");
            }

            float closestReach = Mathf.Abs(anchorDistance - gripDistance);
            if (closestReach > maximumWristReach)
            {
                AimShotgunLeftShoulderForGripReach(
                    root,
                    rightPalm,
                    gripDistance,
                    maximumWristReach);
                leftArm = FindRequired(root, LeftArmPath);
                leftForeArm = FindRequired(root, LeftForeArmPath);
                leftHand = FindRequired(root, LeftHandPath);
                anchorToShoulder = leftArm.position - rightPalm;
                anchorDistance = anchorToShoulder.magnitude;
                maximumWristReach =
                    Vector3.Distance(
                        leftArm.position,
                        leftForeArm.position) +
                    Vector3.Distance(
                        leftForeArm.position,
                        leftHand.position) - 0.01f -
                    ShotgunLeftGripReachReserveMeters;
                maximumWristReach = Mathf.Max(
                    0.05f,
                    maximumWristReach);
                closestReach = Mathf.Abs(
                    anchorDistance - gripDistance);
                if (closestReach > maximumWristReach + 0.0001f)
                {
                    throw new InvalidOperationException(
                        "Shotgun left-hand grip cannot enter arm reach while preserving the right-palm contact and natural shoulder length. Remaining gap=" +
                        Num(closestReach - maximumWristReach) + ".");
                }
            }

            float allowedCosine = Mathf.Clamp(
                (anchorDistance * anchorDistance +
                 gripDistance * gripDistance -
                 maximumWristReach * maximumWristReach) /
                (2f * anchorDistance * gripDistance),
                -1f,
                1f);
            float allowedAngle = Mathf.Acos(allowedCosine);
            Vector3 towardShoulder = anchorToShoulder / anchorDistance;
            Vector3 currentDirection = anchorToTarget / gripDistance;
            float currentAngle = Mathf.Acos(Mathf.Clamp(
                Vector3.Dot(towardShoulder, currentDirection),
                -1f,
                1f));
            if (currentAngle <= allowedAngle)
            {
                previousItemRootRotation = Quaternion.Inverse(
                    root.rotation) * item.rotation;
                hasPreviousItemRotation = true;
                return;
            }

            Vector3 reachableDirection = Vector3.Slerp(
                towardShoulder,
                currentDirection,
                allowedAngle / Mathf.Max(currentAngle, 0.0001f));
            Quaternion reachableRotation = Quaternion.FromToRotation(
                currentDirection,
                reachableDirection) * item.rotation;
            item.rotation = reachableRotation;
            item.position = rightPalm -
                item.rotation * Vector3.Scale(
                    heldRightPalmItemLocal,
                    item.lossyScale);
            previousItemRootRotation = Quaternion.Inverse(
                root.rotation) * item.rotation;
            hasPreviousItemRotation = true;
        }

        private static void AimShotgunLeftShoulderForGripReach(
            Transform root,
            Vector3 rightPalm,
            float gripDistance,
            float maximumWristReach)
        {
            Transform shoulder = FindRequired(root, LeftShoulderPath);
            Transform arm = FindRequired(root, LeftArmPath);
            Vector3 currentDirection = arm.position - shoulder.position;
            Vector3 shoulderToAnchor = rightPalm - shoulder.position;
            if (currentDirection.sqrMagnitude <= 0.000001f ||
                shoulderToAnchor.sqrMagnitude <= 0.000001f)
            {
                return;
            }

            float currentAnchorDistance = Vector3.Distance(
                arm.position,
                rightPalm);
            bool anchorTooFar = currentAnchorDistance >
                gripDistance + maximumWristReach;
            Vector3 requestedDirection = anchorTooFar
                ? shoulderToAnchor
                : -shoulderToAnchor;
            Quaternion baseRotation = shoulder.rotation;
            Quaternion fullyAimedRotation = Quaternion.FromToRotation(
                currentDirection,
                requestedDirection) * baseRotation;
            Quaternion maximumRotation = Quaternion.RotateTowards(
                baseRotation,
                fullyAimedRotation,
                55f);
            shoulder.rotation = maximumRotation;
            float maximumRotationDistance = Vector3.Distance(
                FindRequired(root, LeftArmPath).position,
                rightPalm);
            bool maximumRotationReaches = Mathf.Abs(
                maximumRotationDistance - gripDistance) <=
                maximumWristReach;
            if (!maximumRotationReaches)
            {
                return;
            }

            float lower = 0f;
            float upper = 1f;
            for (int iteration = 0; iteration < 12; iteration++)
            {
                float midpoint = (lower + upper) * 0.5f;
                shoulder.rotation = Quaternion.Slerp(
                    baseRotation,
                    maximumRotation,
                    midpoint);
                float anchorDistance = Vector3.Distance(
                    FindRequired(root, LeftArmPath).position,
                    rightPalm);
                bool reaches = Mathf.Abs(
                    anchorDistance - gripDistance) <=
                    maximumWristReach;
                if (reaches)
                {
                    upper = midpoint;
                }
                else
                {
                    lower = midpoint;
                }
            }

            shoulder.rotation = Quaternion.Slerp(
                baseRotation,
                maximumRotation,
                upper);
        }

        private static void ApplyShotgunRightPalmIkWithContinuousFixedItemPose(
            Transform root,
            Vector3 palmLocal,
            Vector3 requestedPalm,
            Quaternion requestedHandRotation,
            Vector3 elbowPole,
            ref Quaternion previousArmLocalRotation,
            ref Quaternion previousForeArmLocalRotation,
            ref Quaternion previousHandLocalRotation,
            ref Quaternion previousForeArmWorldRotation,
            ref Vector3 previousElbowRootPosition,
            ref bool hasPreviousRotation)
        {
            Transform arm = FindRequired(root, RightArmPath);
            Transform foreArm = FindRequired(root, RightForeArmPath);
            Transform hand = FindRequired(root, RightHandPath);
            hand.rotation = requestedHandRotation;
            Vector3 requestedHand = hand.position +
                requestedPalm - hand.TransformPoint(palmLocal);
            Quaternion sourceArmLocalRotation = arm.localRotation;
            Quaternion sourceForeArmLocalRotation = foreArm.localRotation;
            Quaternion sourceHandLocalRotation = hand.localRotation;
            Vector3 armPosition = arm.position;
            float upperLength = Vector3.Distance(
                armPosition,
                foreArm.position);
            float lowerLength = Vector3.Distance(
                foreArm.position,
                hand.position);
            float minimumReach = Mathf.Abs(
                upperLength - lowerLength) + 0.0001f;
            float maximumReach = upperLength + lowerLength - 0.0001f;
            Vector3 targetVector = requestedHand - armPosition;
            Vector3 targetDirection = targetVector.sqrMagnitude > 0.0000001f
                ? targetVector.normalized
                : (hand.position - armPosition).normalized;
            float reach = Mathf.Clamp(
                targetVector.magnitude,
                minimumReach,
                maximumReach);
            Vector3 clampedTarget = armPosition + targetDirection * reach;
            Vector3 continuousElbowPole = hasPreviousRotation
                ? root.TransformPoint(previousElbowRootPosition)
                : elbowPole;
            Vector3 baseBendDirection = Vector3.ProjectOnPlane(
                continuousElbowPole - armPosition,
                targetDirection);
            if (baseBendDirection.sqrMagnitude < 0.0000001f)
            {
                baseBendDirection = Vector3.ProjectOnPlane(
                    foreArm.position - armPosition,
                    targetDirection);
            }
            if (baseBendDirection.sqrMagnitude < 0.0000001f)
            {
                baseBendDirection = Vector3.Cross(
                    targetDirection,
                    root.up);
            }
            baseBendDirection.Normalize();

            float along =
                (upperLength * upperLength + reach * reach -
                 lowerLength * lowerLength) / (2f * reach);
            float perpendicular = Mathf.Sqrt(Mathf.Max(
                0f,
                upperLength * upperLength - along * along));
            float bestScore = float.PositiveInfinity;
            Quaternion bestArmLocalRotation = sourceArmLocalRotation;
            Quaternion bestForeArmLocalRotation =
                sourceForeArmLocalRotation;
            Quaternion bestHandLocalRotation = sourceHandLocalRotation;
            for (int sample = 0; sample < 72; sample++)
            {
                float bendDegrees = -180f + sample * 5f;
                arm.localRotation = sourceArmLocalRotation;
                foreArm.localRotation = sourceForeArmLocalRotation;
                hand.rotation = requestedHandRotation;
                Vector3 bendDirection = Quaternion.AngleAxis(
                    bendDegrees,
                    targetDirection) * baseBendDirection;
                Vector3 elbowTarget = armPosition +
                    targetDirection * along +
                    bendDirection * perpendicular;
                arm.rotation = Quaternion.FromToRotation(
                    foreArm.position - armPosition,
                    elbowTarget - armPosition) * arm.rotation;
                foreArm.rotation = Quaternion.FromToRotation(
                    hand.position - foreArm.position,
                    clampedTarget - foreArm.position) * foreArm.rotation;
                hand.rotation = requestedHandRotation;

                float sourceScore = Mathf.Max(
                    Quaternion.Angle(
                        sourceArmLocalRotation,
                        arm.localRotation),
                    Quaternion.Angle(
                        sourceForeArmLocalRotation,
                        foreArm.localRotation));
                float continuityScore = hasPreviousRotation
                    ? Mathf.Max(
                        Quaternion.Angle(
                            previousArmLocalRotation,
                            arm.localRotation),
                        Mathf.Max(
                            Quaternion.Angle(
                                previousForeArmLocalRotation,
                                foreArm.localRotation),
                            Quaternion.Angle(
                                previousHandLocalRotation,
                                hand.localRotation)))
                    : sourceScore;
                float elbowContinuityScore = hasPreviousRotation
                    ? Vector3.Distance(
                          root.TransformPoint(
                              previousElbowRootPosition),
                          foreArm.position) /
                      Mathf.Max(upperLength, 0.0001f) * 180f
                    : sourceScore;
                float score = hasPreviousRotation
                    ? Mathf.Max(
                          continuityScore,
                          elbowContinuityScore) * 8f +
                      sourceScore * 0.05f
                    : sourceScore;
                if (score >= bestScore)
                {
                    continue;
                }

                bestScore = score;
                bestArmLocalRotation = arm.localRotation;
                bestForeArmLocalRotation = foreArm.localRotation;
                bestHandLocalRotation = hand.localRotation;
            }

            arm.localRotation = bestArmLocalRotation;
            foreArm.localRotation = bestForeArmLocalRotation;
            hand.localRotation = bestHandLocalRotation;
            if (hasPreviousRotation)
            {
                Quaternion baseForeArmWorldRotation = foreArm.rotation;
                Vector3 foreArmAxis = hand.position - foreArm.position;
                if (foreArmAxis.sqrMagnitude > 0.000001f)
                {
                    foreArmAxis.Normalize();
                    float bestTwistScore = float.PositiveInfinity;
                    Quaternion continuousForeArmLocalRotation =
                        foreArm.localRotation;
                    Quaternion continuousHandLocalRotation =
                        hand.localRotation;
                    for (int sample = 0; sample < 360; sample++)
                    {
                        float twistDegrees = -180f + sample;
                        foreArm.rotation = Quaternion.AngleAxis(
                            twistDegrees,
                            foreArmAxis) * baseForeArmWorldRotation;
                        hand.rotation = requestedHandRotation;
                        float twistScore = Quaternion.Angle(
                                               previousForeArmWorldRotation,
                                               foreArm.rotation) * 8f +
                                           Quaternion.Angle(
                                               sourceForeArmLocalRotation,
                                               foreArm.localRotation) * 0.05f;
                        if (twistScore >= bestTwistScore)
                        {
                            continue;
                        }

                        bestTwistScore = twistScore;
                        continuousForeArmLocalRotation =
                            foreArm.localRotation;
                        continuousHandLocalRotation = hand.localRotation;
                    }

                    foreArm.localRotation =
                        continuousForeArmLocalRotation;
                    hand.localRotation = continuousHandLocalRotation;
                }
            }
            for (int iteration = 0; iteration < 3; iteration++)
            {
                hand.rotation = requestedHandRotation;
                Vector3 correctedHandPosition = hand.position +
                    requestedPalm - hand.TransformPoint(palmLocal);
                SolveTwoBoneIk(
                    arm,
                    foreArm,
                    hand,
                    correctedHandPosition,
                    foreArm.position);
            }
            hand.rotation = requestedHandRotation;
            previousArmLocalRotation = arm.localRotation;
            previousForeArmLocalRotation = foreArm.localRotation;
            previousHandLocalRotation = hand.localRotation;
            previousForeArmWorldRotation = foreArm.rotation;
            previousElbowRootPosition = root.InverseTransformPoint(
                foreArm.position);
            hasPreviousRotation = true;
        }

        private static void ApplyShotgunLeftPalmIkWithFixedItemPose(
            Transform root,
            Vector3 palmLocal,
            Vector3 requestedPalm,
            Quaternion requestedHandRotation,
            Vector3 elbowPole,
            ref Quaternion previousArmLocalRotation,
            ref Quaternion previousForeArmLocalRotation,
            ref Quaternion previousHandLocalRotation,
            ref Quaternion previousForeArmWorldRotation,
            ref Vector3 previousElbowRootPosition,
            ref bool hasPreviousRotation)
        {
            Transform arm = FindRequired(root, LeftArmPath);
            Transform foreArm = FindRequired(root, LeftForeArmPath);
            Transform hand = FindRequired(root, LeftHandPath);
            hand.rotation = requestedHandRotation;
            Vector3 requestedHand = hand.position +
                requestedPalm - hand.TransformPoint(palmLocal);
            Quaternion sourceArmLocalRotation = arm.localRotation;
            Quaternion sourceForeArmLocalRotation = foreArm.localRotation;
            Quaternion sourceHandLocalRotation = hand.localRotation;
            Vector3 armPosition = arm.position;
            float upperLength = Vector3.Distance(
                armPosition,
                foreArm.position);
            float lowerLength = Vector3.Distance(
                foreArm.position,
                hand.position);
            float minimumReach = Mathf.Abs(
                upperLength - lowerLength) + 0.0001f;
            float maximumReach = upperLength + lowerLength - 0.0001f;
            Vector3 targetVector = requestedHand - armPosition;
            Vector3 targetDirection = targetVector.sqrMagnitude > 0.0000001f
                ? targetVector.normalized
                : (hand.position - armPosition).normalized;
            float reach = Mathf.Clamp(
                targetVector.magnitude,
                minimumReach,
                maximumReach);
            Vector3 clampedTarget = armPosition + targetDirection * reach;
            Vector3 baseBendDirection = Vector3.ProjectOnPlane(
                elbowPole - armPosition,
                targetDirection);
            if (baseBendDirection.sqrMagnitude < 0.0000001f)
            {
                baseBendDirection = Vector3.ProjectOnPlane(
                    foreArm.position - armPosition,
                    targetDirection);
            }
            if (baseBendDirection.sqrMagnitude < 0.0000001f)
            {
                baseBendDirection = Vector3.Cross(
                    targetDirection,
                    root.up);
            }
            baseBendDirection.Normalize();

            float along =
                (upperLength * upperLength + reach * reach -
                 lowerLength * lowerLength) / (2f * reach);
            float perpendicular = Mathf.Sqrt(Mathf.Max(
                0f,
                upperLength * upperLength - along * along));
            float bestScore = float.PositiveInfinity;
            Quaternion bestArmLocalRotation = sourceArmLocalRotation;
            Quaternion bestForeArmLocalRotation =
                sourceForeArmLocalRotation;
            Quaternion bestHandLocalRotation = sourceHandLocalRotation;
            for (int sample = 0; sample < 72; sample++)
            {
                float bendDegrees = -180f + sample * 5f;
                arm.localRotation = sourceArmLocalRotation;
                foreArm.localRotation = sourceForeArmLocalRotation;
                hand.rotation = requestedHandRotation;
                Vector3 bendDirection = Quaternion.AngleAxis(
                    bendDegrees,
                    targetDirection) * baseBendDirection;
                Vector3 elbowTarget = armPosition +
                    targetDirection * along +
                    bendDirection * perpendicular;
                arm.rotation = Quaternion.FromToRotation(
                    foreArm.position - armPosition,
                    elbowTarget - armPosition) * arm.rotation;
                foreArm.rotation = Quaternion.FromToRotation(
                    hand.position - foreArm.position,
                    clampedTarget - foreArm.position) * foreArm.rotation;
                hand.rotation = requestedHandRotation;

                float sourceScore = Mathf.Max(
                    Quaternion.Angle(
                        sourceArmLocalRotation,
                        arm.localRotation),
                    Quaternion.Angle(
                        sourceForeArmLocalRotation,
                        foreArm.localRotation));
                float continuityScore = hasPreviousRotation
                    ? Mathf.Max(
                        Quaternion.Angle(
                            previousArmLocalRotation,
                            arm.localRotation),
                        Mathf.Max(
                            Quaternion.Angle(
                                previousForeArmLocalRotation,
                                foreArm.localRotation),
                            Quaternion.Angle(
                                previousHandLocalRotation,
                                hand.localRotation)))
                    : sourceScore;
                float elbowContinuityScore = hasPreviousRotation
                    ? Vector3.Distance(
                          root.TransformPoint(
                              previousElbowRootPosition),
                          foreArm.position) /
                      Mathf.Max(upperLength, 0.0001f) * 180f
                    : sourceScore;
                float score = hasPreviousRotation
                    ? Mathf.Max(
                          continuityScore,
                          elbowContinuityScore) * 8f +
                      sourceScore * 0.05f
                    : sourceScore;
                if (score >= bestScore)
                {
                    continue;
                }

                bestScore = score;
                bestArmLocalRotation = arm.localRotation;
                bestForeArmLocalRotation = foreArm.localRotation;
                bestHandLocalRotation = hand.localRotation;
            }

            arm.localRotation = bestArmLocalRotation;
            foreArm.localRotation = bestForeArmLocalRotation;
            hand.localRotation = bestHandLocalRotation;
            if (hasPreviousRotation)
            {
                Quaternion baseForeArmWorldRotation = foreArm.rotation;
                Vector3 foreArmAxis = hand.position - foreArm.position;
                if (foreArmAxis.sqrMagnitude > 0.000001f)
                {
                    foreArmAxis.Normalize();
                    float bestTwistScore = float.PositiveInfinity;
                    Quaternion continuousForeArmLocalRotation =
                        foreArm.localRotation;
                    Quaternion continuousHandLocalRotation =
                        hand.localRotation;
                    for (int sample = 0; sample < 360; sample++)
                    {
                        float twistDegrees = -180f + sample;
                        foreArm.rotation = Quaternion.AngleAxis(
                            twistDegrees,
                            foreArmAxis) * baseForeArmWorldRotation;
                        hand.rotation = requestedHandRotation;
                        float twistScore = Quaternion.Angle(
                                               previousForeArmWorldRotation,
                                               foreArm.rotation) * 8f +
                                           Quaternion.Angle(
                                               sourceForeArmLocalRotation,
                                               foreArm.localRotation) * 0.05f;
                        if (twistScore >= bestTwistScore)
                        {
                            continue;
                        }

                        bestTwistScore = twistScore;
                        continuousForeArmLocalRotation =
                            foreArm.localRotation;
                        continuousHandLocalRotation = hand.localRotation;
                    }

                    foreArm.localRotation =
                        continuousForeArmLocalRotation;
                    hand.localRotation = continuousHandLocalRotation;
                }
            }
            previousArmLocalRotation = bestArmLocalRotation;
            previousForeArmLocalRotation = foreArm.localRotation;
            previousHandLocalRotation = hand.localRotation;
            previousForeArmWorldRotation = foreArm.rotation;
            previousElbowRootPosition = root.InverseTransformPoint(
                foreArm.position);
            hasPreviousRotation = true;
        }

        private static float GetShotgunReloadSupportHoldStartTime(
            float duration)
        {
            return Mathf.Min(
                duration,
                Mathf.Max(0f, duration * ShotgunReloadStartNormalized) +
                ShotgunReloadPullSeconds +
                ShotgunReloadDetachedTravelSeconds);
        }

        private static float[] GetShotgunLeftHandAttachmentReviewPhases(
            string targetName,
            float duration)
        {
            if (!string.Equals(
                    targetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal))
            {
                return new[] { 0f, 0.34f, 0.50f, 0.68f, 0.99f };
            }

            float safeDuration = Mathf.Max(0.0001f, duration);
            float pullStart = Mathf.Max(
                0f,
                duration * ShotgunReloadStartNormalized);
            float pullEnd = Mathf.Min(
                duration,
                pullStart + ShotgunReloadPullSeconds);
            float returnEnd = Mathf.Min(
                duration,
                pullEnd + ShotgunReloadDetachedTravelSeconds);
            return new[]
            {
                Mathf.Clamp01(pullStart / safeDuration),
                Mathf.Clamp01(pullEnd / safeDuration),
                Mathf.Clamp01(((pullEnd + returnEnd) * 0.5f) / safeDuration),
                Mathf.Clamp01(returnEnd / safeDuration),
                0.99f
            };
        }

        private static float GetShotgunSupportPalmOffsetMeters(string targetName)
        {
            return string.Equals(
                       targetName,
                       ShotgunIdleTargetName,
                       StringComparison.Ordinal) ||
                   string.Equals(
                       targetName,
                       ShotgunStowTargetName,
                       StringComparison.Ordinal) ||
                   string.Equals(
                       targetName,
                       ShotgunFireTargetName,
                       StringComparison.Ordinal)
                ? ShotgunSupportPalmSurfaceOffsetMeters
                : ShotgunPalmSurfaceOffsetMeters;
        }

        private static float GetShotgunReloadDetachedTravelProgress(
            float time,
            float duration)
        {
            float startTime = Mathf.Max(
                0f,
                duration * ShotgunReloadStartNormalized);
            float travelStart = startTime + ShotgunReloadPullSeconds;
            return Mathf.SmoothStep(
                0f,
                1f,
                Mathf.InverseLerp(
                    travelStart,
                    travelStart + ShotgunReloadDetachedTravelSeconds,
                    time));
        }

        private static void GetShotgunReloadLeftGripTarget(
            Transform item,
            ShotgunGripAnalysis analysis,
            float time,
            float duration,
            out Vector3 palmTarget,
            out Vector3 palmDirection)
        {
            float scale = Mathf.Max(
                0.000001f,
                Mathf.Abs(item.lossyScale.x));
            Vector3 actionLocal = analysis.ReloadActionPoint -
                analysis.Geometry.StockToMuzzleAxis.normalized *
                (GetShotgunReloadPullMeters(time, duration) / scale);
            Vector3 triggerDirection = item.TransformDirection(
                    analysis.Geometry.TriggerDirectionAxis)
                .normalized;
            Vector3 actionSurfaceNormal = -triggerDirection;
            Vector3 supportSurfaceNormal = triggerDirection;
            Vector3 actionTarget = item.TransformPoint(actionLocal) +
                                   actionSurfaceNormal *
                                   ShotgunPalmSurfaceOffsetMeters;
            Vector3 supportTarget = item.TransformPoint(
                                        analysis.ForwardSupportPoint) +
                                    supportSurfaceNormal *
                                    ShotgunSupportPalmSurfaceOffsetMeters;
            float travelProgress = GetShotgunReloadDetachedTravelProgress(
                time,
                duration);
            palmTarget = Vector3.Lerp(
                actionTarget,
                supportTarget,
                travelProgress) +
                actionSurfaceNormal *
                (Mathf.Sin(travelProgress * Mathf.PI) *
                 ShotgunReloadDetachedArcMeters);
            Vector3 itemLongAxis = item.TransformDirection(
                    analysis.Geometry.StockToMuzzleAxis)
                .normalized;
            palmDirection = Quaternion.AngleAxis(
                    180f * travelProgress,
                    itemLongAxis) *
                -actionSurfaceNormal;
        }

        private static float GetShotgunReloadPullMeters(float time, float duration)
        {
            float startTime = Mathf.Max(
                0f,
                duration * ShotgunReloadStartNormalized);
            float pull = Mathf.SmoothStep(
                0f,
                1f,
                Mathf.InverseLerp(
                    startTime,
                    startTime + ShotgunReloadPullSeconds,
                    time));
            return ShotgunReloadPullDistanceMeters * pull;
        }

        private static float GetShotgunButtStrikeImpactWeight(
            float time,
            float duration)
        {
            float phase = duration > 0.0001f
                ? Mathf.Clamp01(time / duration)
                : 0f;
            float advance = Mathf.SmoothStep(
                0f,
                1f,
                Mathf.InverseLerp(0.25f, 0.50f, phase));
            float recover = 1f - Mathf.SmoothStep(
                0f,
                1f,
                Mathf.InverseLerp(0.50f, 0.75f, phase));
            return Mathf.Min(advance, recover);
        }

        private static void SetShotgunItemScaleCurves(
            AnimationClip clip,
            string path,
            Vector3 scale,
            float duration)
        {
            SetTransformCurve(
                clip,
                path,
                "m_LocalScale.x",
                new[] { new Keyframe(0f, scale.x), new Keyframe(duration, scale.x) });
            SetTransformCurve(
                clip,
                path,
                "m_LocalScale.y",
                new[] { new Keyframe(0f, scale.y), new Keyframe(duration, scale.y) });
            SetTransformCurve(
                clip,
                path,
                "m_LocalScale.z",
                new[] { new Keyframe(0f, scale.z), new Keyframe(duration, scale.z) });
        }

        private sealed class ShotgunTorsoClearanceProfile
        {
            private const float CellSizeMeters = 0.04f;
            private readonly Dictionary<Vector2Int, float> frontByCell =
                new Dictionary<Vector2Int, float>();
            private readonly Dictionary<Vector2Int, float> backByCell =
                new Dictionary<Vector2Int, float>();

            internal int Count => frontByCell.Count;

            internal void Add(float lateral, float vertical, float forward)
            {
                Vector2Int cell = ToCell(lateral, vertical);
                if (!frontByCell.TryGetValue(cell, out float current) || forward > current)
                {
                    frontByCell[cell] = forward;
                }

                if (!backByCell.TryGetValue(cell, out current) || forward < current)
                {
                    backByCell[cell] = forward;
                }
            }

            internal bool TryGetFront(float lateral, float vertical, out float front)
            {
                Vector2Int center = ToCell(lateral, vertical);
                front = float.NegativeInfinity;
                for (int x = -1; x <= 1; x++)
                {
                    for (int y = -1; y <= 1; y++)
                    {
                        if (frontByCell.TryGetValue(
                                new Vector2Int(center.x + x, center.y + y),
                                out float candidate))
                        {
                            front = Mathf.Max(front, candidate);
                        }
                    }
                }

                return !float.IsNegativeInfinity(front);
            }

            internal bool TryGetDepthRange(
                float lateral,
                float vertical,
                out float back,
                out float front)
            {
                Vector2Int center = ToCell(lateral, vertical);
                back = float.PositiveInfinity;
                front = float.NegativeInfinity;
                for (int x = -1; x <= 1; x++)
                {
                    for (int y = -1; y <= 1; y++)
                    {
                        Vector2Int cell = new Vector2Int(
                            center.x + x,
                            center.y + y);
                        if (frontByCell.TryGetValue(
                                cell,
                                out float candidateFront))
                        {
                            front = Mathf.Max(front, candidateFront);
                        }

                        if (backByCell.TryGetValue(
                                cell,
                                out float candidateBack))
                        {
                            back = Mathf.Min(back, candidateBack);
                        }
                    }
                }

                return !float.IsPositiveInfinity(back) &&
                       !float.IsNegativeInfinity(front);
            }

            private static Vector2Int ToCell(float lateral, float vertical)
            {
                return new Vector2Int(
                    Mathf.RoundToInt(lateral / CellSizeMeters),
                    Mathf.RoundToInt(vertical / CellSizeMeters));
            }
        }

        private static ShotgunTorsoClearanceProfile MeasureShotgunTorsoClearanceProfile(
            Transform root,
            bool includeRightArm = false)
        {
            Transform spine = FindRequired(root, SpinePath);
            ShotgunTorsoClearanceProfile profile =
                new ShotgunTorsoClearanceProfile();
            foreach (SkinnedMeshRenderer renderer in
                     root.GetComponentsInChildren<SkinnedMeshRenderer>(true))
            {
                Mesh source = renderer.sharedMesh;
                if (source == null || source.boneWeights.Length != source.vertexCount)
                {
                    continue;
                }

                Mesh baked = new Mesh();
                try
                {
                    renderer.BakeMesh(baked, true);
                    Vector3[] vertices = baked.vertices;
                    BoneWeight[] weights = source.boneWeights;
                    for (int index = 0; index < vertices.Length; index++)
                    {
                        float torsoWeight = BoneWeightForSuffixes(
                            weights[index],
                            renderer.bones,
                            "Hips",
                            "Spine02",
                            "Spine01",
                            "Spine",
                            "LeftShoulder",
                            "RightShoulder",
                            "Neck");
                        float rightArmWeight = includeRightArm
                            ? BoneWeightForSuffixes(
                                weights[index],
                                renderer.bones,
                                "RightArm",
                                "RightForeArm")
                            : 0f;
                        if (Mathf.Max(torsoWeight, rightArmWeight) < 0.20f)
                        {
                            continue;
                        }

                        Vector3 world = renderer.transform.TransformPoint(vertices[index]);
                        if (Mathf.Abs(Vector3.Dot(world - spine.position, root.up)) > 0.55f)
                        {
                            continue;
                        }

                        Vector3 fromRoot = world - root.position;
                        profile.Add(
                            Vector3.Dot(fromRoot, root.right),
                            Vector3.Dot(fromRoot, root.up),
                            Vector3.Dot(fromRoot, root.forward));
                    }
                }
                finally
                {
                    UnityEngine.Object.DestroyImmediate(baked);
                }
            }

            if (profile.Count == 0)
            {
                throw new InvalidOperationException(
                    "Player torso surface could not be measured for Shotgun clearance.");
            }

            return profile;
        }

        private static int ApplyConfirmedShotgunPerformanceFix(
            Scene scene,
            ShotgunPerformanceMetrics performance)
        {
            HashSet<string> measuredPaths = new HashSet<string>(
                performance.additionalShadowLightPaths ?? Array.Empty<string>(),
                StringComparer.Ordinal);
            Light[] measuredLights = scene.GetRootGameObjects()
                .SelectMany(root => root.GetComponentsInChildren<Light>(true))
                .Where(light => measuredPaths.Contains(
                    GetShotgunSceneHierarchyPath(light.transform)))
                .ToArray();
            if (measuredLights.Length != performance.additionalShadowLightCount ||
                measuredPaths.Count != performance.additionalShadowLightCount)
            {
                throw new InvalidOperationException(
                    "The measured additional-shadow light set changed before the performance fix. Expected=" +
                    performance.additionalShadowLightCount.ToString(CultureInfo.InvariantCulture) +
                    ", Actual=" +
                    measuredLights.Length.ToString(CultureInfo.InvariantCulture) + ".");
            }

            foreach (Light light in measuredLights)
            {
                if (light.shadows == LightShadows.None)
                {
                    continue;
                }

                light.shadows = LightShadows.None;
                EditorUtility.SetDirty(light);
            }

            return measuredLights.Count(light => light.shadows == LightShadows.None);
        }

        private static string GetShotgunSceneHierarchyPath(Transform value)
        {
            List<string> parts = new List<string>();
            Transform current = value;
            while (current != null)
            {
                parts.Add(current.name);
                current = current.parent;
            }

            parts.Reverse();
            return string.Join("/", parts);
        }

        private static void ApplyCorrectedShotgunButtBinding(
            Transform idleTarget,
            AnimationClip idleClip,
            GameObject shotgunAsset,
            ShotgunGripAnalysis analysis,
            ShotgunGripBinding grip)
        {
            GameObject clone = UnityEngine.Object.Instantiate(idleTarget.gameObject);
            clone.name = "ShotgunCorrectedButtBindingAnalysis";
            clone.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(clone);
            try
            {
                idleClip.SampleAnimation(clone, 0f);
                Transform root = clone.transform;
                Transform rightHand = FindRequired(root, RightHandPath);
                Vector3 rightPalm = CalculateRightPalmSample(root).Center;
                Vector3 leftPalm = CalculateLeftPalmSample(root).Center;
                GameObject itemObject = UnityEngine.Object.Instantiate(shotgunAsset);
                itemObject.name = ShotgunHandInstanceName;
                itemObject.hideFlags = HideFlags.HideAndDontSave;
                itemObject.transform.SetParent(rightHand, false);
                Transform item = itemObject.transform;
                ConfigureShotgunButtWorldPose(
                    root,
                    rightPalm,
                    item,
                    analysis,
                    MeasureShotgunTorsoClearanceProfile(root),
                    out Vector3 _,
                    out Quaternion _);
                grip.ButtLocalPosition = item.localPosition;
                grip.ButtLocalRotation = item.localRotation;
                grip.ButtLocalScale = item.localScale;
                grip.ButtStockForwardDot = Vector3.Dot(
                    -item.TransformDirection(
                        analysis.Geometry.StockToMuzzleAxis).normalized,
                    root.forward);
                grip.ButtRightPalmDistance = Vector3.Distance(
                    rightPalm,
                    item.TransformPoint(analysis.SupportPoint));
                grip.ButtLeftPalmDistance = Vector3.Distance(
                    leftPalm,
                    item.TransformPoint(analysis.HandlePoint));
                UnityEngine.Object.DestroyImmediate(itemObject);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(clone);
            }
        }

        internal static void CaptureShotgunAnimationCorrectionsPlayMode()
        {
            int stage = SessionState.GetInt(
                ShotgunCorrectionMusketCaptureStageKey,
                0);
            try
            {
                if (stage == 0)
                {
                    int shotgunCaptureStage = SessionState.GetInt(
                        ShotgunAnimationCaptureStageKey,
                        0);
                    if (shotgunCaptureStage != 0 ||
                        !ShotgunCorrectionReviewIsCurrent())
                    {
                        CaptureShotgunAnimationSetPlayMode();
                        return;
                    }

                    if (EditorApplication.isPlayingOrWillChangePlaymode)
                    {
                        throw new InvalidOperationException(
                            "Musket_Reload correction review must start in Edit Mode.");
                    }

                    SessionState.SetInt(
                        ShotgunCorrectionMusketCaptureStageKey,
                        1);
                    EditorApplication.EnterPlaymode();
                    Debug.Log(
                        "[PlayerShotgunCorrection] Entering Play Mode for direct Musket_Reload palm review.");
                    return;
                }

                if (stage == 1)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Musket_Reload correction capture start requires Play Mode.");
                    }

                    MusketAnimationSetPlayModeCapture
                        .StartReloadCorrectionReview();
                    SessionState.SetInt(
                        ShotgunCorrectionMusketCaptureStageKey,
                        2);
                    Debug.Log(
                        "[PlayerShotgunCorrection] Began actual two-loop Musket_Reload palm capture.");
                    return;
                }

                if (stage == 2)
                {
                    if (MusketAnimationSetPlayModeCapture.Failure != null)
                    {
                        throw new InvalidOperationException(
                            "Musket_Reload correction Play Mode capture failed.",
                            MusketAnimationSetPlayModeCapture.Failure);
                    }

                    if (!MusketAnimationSetPlayModeCapture.IsComplete)
                    {
                        Debug.Log(
                            "[PlayerShotgunCorrection] Musket_Reload capture is still running. " +
                            MusketAnimationSetPlayModeCapture.Status);
                        return;
                    }

                    SessionState.SetInt(
                        ShotgunCorrectionMusketCaptureStageKey,
                        3);
                    Debug.Log(
                        "[PlayerShotgunCorrection] Musket_Reload two-loop capture completed; run once more to exit Play Mode.");
                    return;
                }

                if (stage == 3)
                {
                    SessionState.EraseInt(
                        ShotgunCorrectionMusketCaptureStageKey);
                    EditorApplication.ExitPlaymode();
                    Debug.Log(
                        "[PlayerShotgunCorrection] Exiting Play Mode after Musket_Reload correction review.");
                    return;
                }

                throw new InvalidOperationException(
                    "Musket_Reload correction capture stage is invalid: " +
                    stage.ToString(CultureInfo.InvariantCulture) + ".");
            }
            catch
            {
                SessionState.EraseInt(
                    ShotgunCorrectionMusketCaptureStageKey);
                MusketAnimationSetPlayModeCapture.Stop();
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                throw;
            }
        }

        internal static void CaptureShotgunAnimationCorrectionsFinal()
        {
            MusketAnimationReviewMetrics musketReloadReview =
                ReadJson<MusketAnimationReviewMetrics>(
                    MusketReloadCorrectionReviewMetricsPath);
            if (!musketReloadReview.passedNumericChecks ||
                musketReloadReview.targets == null ||
                musketReloadReview.targets.Length != 1 ||
                !string.Equals(
                    musketReloadReview.targets[0].target,
                    MusketReloadTargetName,
                    StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Musket_Reload direct correction review did not pass.");
            }

            CaptureShotgunAnimationSetFinal();
        }

        private static bool ShotgunCorrectionReviewIsCurrent()
        {
            string reviewPath = Path.GetFullPath(
                ShotgunAnimationReviewMetricsPath);
            string applyPath = Path.GetFullPath(
                ShotgunCorrectionApplyMetricsPath);
            if (!File.Exists(reviewPath) ||
                !File.Exists(applyPath) ||
                File.GetLastWriteTimeUtc(reviewPath) <
                File.GetLastWriteTimeUtc(applyPath))
            {
                return false;
            }

            ShotgunAnimationReviewMetrics review =
                ReadJson<ShotgunAnimationReviewMetrics>(
                    ShotgunAnimationReviewMetricsPath);
            return review.passedNumericChecks;
        }

        [MenuItem("Bellerophon/Player/Apply Shotgun Animation Set")]
        internal static void ApplyShotgunAnimationSet()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                SessionState.EraseInt(ShotgunAnimationCaptureStageKey);
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                Debug.Log(
                    "[PlayerShotgunAnimationSet] Exited Play Mode before apply; run apply again in Edit Mode.");
                return;
            }

            RequireHash(ShotgunAssetPath, ShotgunAssetHash, "Unity shotgun FBX");
            RequireHash(
                ShotgunDrawSourcePath,
                ShotgunDrawSourceHash,
                "Shotgun_Draw embedded Mixamo FBX");
            RequireHash(
                ShotgunStowSourcePath,
                ShotgunStowSourceHash,
                "Shotgun_Stow embedded Mixamo FBX");
            RequireHash(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeSourceHash,
                "Shotgun_ButtStrike embedded Mixamo FBX");
            ConfigureSourceImporter(ShotgunDrawSourcePath, ShotgunDrawTargetName);
            ConfigureSourceImporter(ShotgunStowSourcePath, ShotgunStowTargetName);
            ConfigureSourceImporter(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeTargetName);

            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp must be clean before Shotgun animation apply.");
            }

            Transform layout = RequireLayout(scene);
            ShotgunAnimationSpec[] specs = GetShotgunAnimationSpecs();
            Transform[] targets = specs
                .Select(spec => RequireTarget(layout, spec.TargetName))
                .ToArray();
            AnimationClip musketIdle = GetConnectedMusketAnimationClip(
                layout,
                MusketIdleTargetName);
            AnimationClip musketFire = GetConnectedMusketAnimationClip(
                layout,
                MusketHipFireTargetName);
            AnimationClip musketReload = GetConnectedMusketAnimationClip(
                layout,
                MusketReloadTargetName);
            AnimationClip draw = LoadSingleEmbeddedClip(
                ShotgunDrawSourcePath,
                ShotgunDrawTargetName);
            AnimationClip stow = LoadSingleEmbeddedClip(
                ShotgunStowSourcePath,
                ShotgunStowTargetName);
            AnimationClip strike = LoadSingleEmbeddedClip(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeTargetName);
            AnimationClip idle = CreateOrUpdateExactShotgunClipCopy(
                musketIdle,
                specs[1].ClipPath,
                ShotgunIdleTargetName);
            AnimationClip fire = CreateOrUpdateExactShotgunClipCopy(
                musketFire,
                specs[3].ClipPath,
                ShotgunFireTargetName);
            AnimationClip buttIdle = CreateOrUpdateExactShotgunClipCopy(
                musketIdle,
                specs[5].ClipPath,
                ShotgunButtModeIdleTargetName);
            AnimationClip reload = CreateOrUpdateExactShotgunClipCopy(
                musketReload,
                specs[8].ClipPath,
                ShotgunReloadTargetName);

            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            ShotgunGripBinding grip = AnalyzeShotgunGripBinding(
                targets[1],
                musketIdle,
                shotgunAsset,
                analysis);
            AnimationClip enter = CreateOrUpdateShotgunButtTransitionClip(
                targets[4],
                musketIdle,
                shotgunAsset,
                analysis,
                grip,
                specs[4].ClipPath,
                ShotgunButtModeEnterTargetName,
                false);
            AnimationClip exit = CreateOrUpdateShotgunButtTransitionClip(
                targets[7],
                musketIdle,
                shotgunAsset,
                analysis,
                grip,
                specs[7].ClipPath,
                ShotgunButtModeExitTargetName,
                true);
            AnimationClip[] clips =
            {
                draw,
                idle,
                stow,
                fire,
                enter,
                buttIdle,
                strike,
                exit,
                reload
            };
            AnimationClip[] exactSources =
            {
                draw,
                musketIdle,
                stow,
                musketFire,
                null,
                musketIdle,
                strike,
                null,
                musketReload
            };

            AnimatorController[] controllers = new AnimatorController[specs.Length];
            Animator[] animators = new Animator[specs.Length];
            Transform[] items = new Transform[specs.Length];
            for (int index = 0; index < specs.Length; index++)
            {
                bool butt = string.Equals(
                    specs[index].ItemMode,
                    "Butt",
                    StringComparison.Ordinal) ||
                    string.Equals(
                        specs[index].ItemMode,
                        "Exit",
                        StringComparison.Ordinal);
                items[index] = ReplaceShotgunHandItem(
                    targets[index],
                    shotgunAsset,
                    grip,
                    butt);
                controllers[index] =
                    CreateOrUpdateExactEmbeddedTakeController(
                        specs[index].ControllerPath,
                        specs[index].StateName,
                        clips[index]);
                animators[index] = ConfigureAnimator(
                    targets[index],
                    controllers[index]);
                animators[index].speed = 1f;
                EditorUtility.SetDirty(animators[index]);
            }

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            AssetDatabase.SaveAssets();

            ShotgunAnimationTargetApplyMetrics[] targetMetrics =
                new ShotgunAnimationTargetApplyMetrics[specs.Length];
            for (int index = 0; index < specs.Length; index++)
            {
                ShotgunAnimationSpec spec = specs[index];
                AnimationClip source = exactSources[index];
                bool custom = source == null;
                string sourceContentHash = custom
                    ? "custom-enter-exit-only"
                    : HashAnimationClipContent(source);
                string appliedContentHash = HashAnimationClipContent(clips[index]);
                bool exact = custom || string.Equals(
                    sourceContentHash,
                    appliedContentHash,
                    StringComparison.Ordinal);
                AnimationClipSettings settings =
                    AnimationUtility.GetAnimationClipSettings(clips[index]);
                ShotgunAnimationTargetApplyMetrics metrics =
                    new ShotgunAnimationTargetApplyMetrics
                    {
                        target = spec.TargetName,
                        sourceKind = spec.SourceKind,
                        sourcePath = GetShotgunSourcePath(spec, source),
                        sourceHash = GetShotgunSourceHash(spec),
                        clipPath = spec.ClipPath,
                        controllerPath = spec.ControllerPath,
                        stateName = spec.StateName,
                        itemMode = spec.ItemMode,
                        durationSeconds = clips[index].length,
                        frameRate = clips[index].frameRate,
                        floatCurveCount =
                            AnimationUtility.GetCurveBindings(clips[index]).Length,
                        sourceContentHash = sourceContentHash,
                        appliedContentHash = appliedContentHash,
                        sourceAnimationExact = exact,
                        clipLoops = settings.loopTime,
                        controllerUsesClipAtSpeedOne = StateUsesClip(
                            controllers[index],
                            spec.StateName,
                            clips[index]),
                        animatorSettingsCorrect = AnimatorMatches(
                            animators[index],
                            controllers[index]) &&
                            Mathf.Abs(animators[index].speed - 1f) <= 0.0001f,
                        itemParentedToRightHand = items[index].parent ==
                            FindRequired(targets[index], RightHandPath),
                        itemLocalPosition = items[index].localPosition,
                        itemLocalRotation = items[index].localRotation,
                        itemLocalScale = items[index].localScale
                    };
                metrics.passedNumericChecks =
                    metrics.sourceAnimationExact &&
                    metrics.clipLoops &&
                    metrics.controllerUsesClipAtSpeedOne &&
                    metrics.animatorSettingsCorrect &&
                    metrics.itemParentedToRightHand &&
                    (!custom ||
                     Mathf.Abs(metrics.durationSeconds -
                               ShotgunButtClipSeconds) <= 0.0001f);
                targetMetrics[index] = metrics;
            }

            ShotgunAnimationApplyMetrics apply =
                new ShotgunAnimationApplyMetrics
                {
                    targetSet = string.Join(", ", specs.Select(spec => spec.TargetName)),
                    shotgunAssetPath = ShotgunAssetPath,
                    shotgunAssetHash = HashFile(ShotgunAssetPath),
                    detectedStockToMuzzleAxis =
                        analysis.Geometry.StockToMuzzleAxis,
                    detectedTriggerDirectionAxis =
                        analysis.Geometry.TriggerDirectionAxis,
                    detectedHandlePoint = analysis.HandlePoint,
                    detectedSupportPoint = analysis.SupportPoint,
                    detectedGripSpan = analysis.GripSpan,
                    normalLocalPosition = grip.NormalLocalPosition,
                    normalLocalRotation = grip.NormalLocalRotation,
                    normalLocalScale = grip.NormalLocalScale,
                    buttLocalPosition = grip.ButtLocalPosition,
                    buttLocalRotation = grip.ButtLocalRotation,
                    buttLocalScale = grip.ButtLocalScale,
                    transitionSeconds = ShotgunButtTransitionSeconds,
                    holdSeconds = ShotgunButtHoldSeconds,
                    normalMuzzleForwardDot = grip.NormalMuzzleForwardDot,
                    buttStockForwardDot = grip.ButtStockForwardDot,
                    normalRightPalmDistanceMeters =
                        grip.NormalRightPalmDistance,
                    normalLeftPalmDistanceMeters = grip.NormalLeftPalmDistance,
                    buttRightPalmDistanceMeters = grip.ButtRightPalmDistance,
                    buttLeftPalmDistanceMeters = grip.ButtLeftPalmDistance,
                    targets = targetMetrics,
                    allExactSourcesPreserved = targetMetrics.All(
                        metrics => metrics.sourceAnimationExact),
                    allItemsParentedToRightHand = targetMetrics.All(
                        metrics => metrics.itemParentedToRightHand),
                    allAnimatorsAtSpeedOne = targetMetrics.All(
                        metrics => metrics.animatorSettingsCorrect),
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            apply.passedNumericChecks =
                string.Equals(
                    apply.shotgunAssetHash,
                    ShotgunAssetHash,
                    StringComparison.OrdinalIgnoreCase) &&
                apply.targets.Length == 9 &&
                apply.targets.All(metrics => metrics.passedNumericChecks) &&
                apply.allExactSourcesPreserved &&
                apply.allItemsParentedToRightHand &&
                apply.allAnimatorsAtSpeedOne &&
                apply.normalMuzzleForwardDot >= 0.98f &&
                apply.buttStockForwardDot >= 0.98f &&
                apply.normalRightPalmDistanceMeters <= 0.005f &&
                apply.normalLeftPalmDistanceMeters <= 0.35f &&
                apply.buttRightPalmDistanceMeters <= 0.005f &&
                apply.buttLeftPalmDistanceMeters <= 0.35f;
            WriteJson(ShotgunAnimationApplyMetricsPath, apply);
            if (!apply.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun animation apply support checks failed. " +
                    JsonUtility.ToJson(apply));
            }

            SessionState.EraseInt(ShotgunAnimationCaptureStageKey);
            Debug.Log(
                "[PlayerShotgunAnimationSet] Applied all nine Shotgun targets. " +
                "Draw/Stow/ButtStrike use their exact embedded Mixamo Takes; " +
                "Idle/Fire/ButtIdle/Reload use exact copies of the currently connected Musket clips; " +
                "only ButtMode Enter/Exit contain generated 1.0s transition plus 0.5s hold curves.");
        }

        private static ShotgunAnimationSpec[] GetShotgunAnimationSpecs()
        {
            return new[]
            {
                CreateShotgunAnimationSpec(ShotgunDrawTargetName, "EmbeddedMixamo", "Normal"),
                CreateShotgunAnimationSpec(ShotgunIdleTargetName, "MusketIdleExactCopy", "Normal"),
                CreateShotgunAnimationSpec(ShotgunStowTargetName, "EmbeddedMixamo", "Normal"),
                CreateShotgunAnimationSpec(ShotgunFireTargetName, "MusketHipFireExactCopy", "Normal"),
                CreateShotgunAnimationSpec(ShotgunButtModeEnterTargetName, "CustomApprovedTransition", "Enter"),
                CreateShotgunAnimationSpec(ShotgunButtModeIdleTargetName, "MusketIdleExactCopy", "Butt"),
                CreateShotgunAnimationSpec(ShotgunButtStrikeTargetName, "EmbeddedMixamo", "Butt"),
                CreateShotgunAnimationSpec(ShotgunButtModeExitTargetName, "CustomApprovedTransition", "Exit"),
                CreateShotgunAnimationSpec(ShotgunReloadTargetName, "MusketReloadExactCopy", "Normal")
            };
        }

        private static ShotgunAnimationSpec[]
            GetShotgunRightHandEdgeCorrectionSpecs()
        {
            return GetShotgunAnimationSpecs()
                .Where(spec => !string.Equals(
                    spec.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal))
                .ToArray();
        }

        private static ShotgunAnimationSpec[]
            GetShotgunButtModeHandSpacingSpecs()
        {
            return GetShotgunAnimationSpecs()
                .Where(spec =>
                    string.Equals(
                        spec.TargetName,
                        ShotgunButtModeEnterTargetName,
                        StringComparison.Ordinal) ||
                    string.Equals(
                        spec.TargetName,
                        ShotgunButtModeIdleTargetName,
                        StringComparison.Ordinal) ||
                    string.Equals(
                        spec.TargetName,
                        ShotgunButtStrikeTargetName,
                        StringComparison.Ordinal) ||
                    string.Equals(
                        spec.TargetName,
                        ShotgunButtModeExitTargetName,
                        StringComparison.Ordinal))
                .ToArray();
        }

        private static ShotgunAnimationSpec[]
            GetShotgunReloadAndButtStrikeLeftHandSpecs()
        {
            ShotgunAnimationSpec[] specs = GetShotgunAnimationSpecs();
            return new[]
            {
                specs.Single(spec => string.Equals(
                    spec.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal)),
                specs.Single(spec => string.Equals(
                    spec.TargetName,
                    ShotgunButtStrikeTargetName,
                    StringComparison.Ordinal))
            };
        }

        private static ShotgunAnimationSpec CreateShotgunAnimationSpec(
            string targetName,
            string sourceKind,
            string itemMode)
        {
            string assetBase = ShotgunAnimationDirectory + "/" + targetName;
            bool embedded = string.Equals(
                sourceKind,
                "EmbeddedMixamo",
                StringComparison.Ordinal);
            return new ShotgunAnimationSpec
            {
                TargetName = targetName,
                StateName = targetName + "Loop",
                ControllerPath = assetBase + ".controller",
                ClipPath = embedded
                    ? GetShotgunEmbeddedSourcePath(targetName)
                    : assetBase + ".anim",
                SourceKind = sourceKind,
                ItemMode = itemMode
            };
        }

        private static string GetShotgunEmbeddedSourcePath(string targetName)
        {
            if (string.Equals(targetName, ShotgunDrawTargetName, StringComparison.Ordinal))
            {
                return ShotgunDrawSourcePath;
            }

            if (string.Equals(targetName, ShotgunStowTargetName, StringComparison.Ordinal))
            {
                return ShotgunStowSourcePath;
            }

            if (string.Equals(targetName, ShotgunButtStrikeTargetName, StringComparison.Ordinal))
            {
                return ShotgunButtStrikeSourcePath;
            }

            throw new InvalidOperationException(
                targetName + " has no approved embedded Shotgun source.");
        }

        private static AnimationClip GetConnectedMusketAnimationClip(
            Transform layout,
            string targetName)
        {
            Animator animator = RequireAnimator(RequireTarget(layout, targetName));
            AnimatorController controller =
                animator.runtimeAnimatorController as AnimatorController ??
                throw new InvalidOperationException(
                    targetName + " does not use an AnimatorController.");
            if (controller.layers.Length != 1)
            {
                throw new InvalidOperationException(
                    targetName + " must expose one connected animation layer.");
            }

            AnimationClip clip = controller.layers[0].stateMachine.defaultState
                ?.motion as AnimationClip;
            return clip ?? throw new InvalidOperationException(
                targetName + " has no connected default AnimationClip.");
        }

        private static AnimationClip CreateOrUpdateExactShotgunClipCopy(
            AnimationClip source,
            string path,
            string name)
        {
            AnimationClip generated = new AnimationClip();
            EditorUtility.CopySerialized(source, generated);
            generated.name = name;
            AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, path);
                existing = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, existing);
                UnityEngine.Object.DestroyImmediate(generated);
                existing.name = name;
                EditorUtility.SetDirty(existing);
            }

            AssetDatabase.SaveAssets();
            return existing;
        }

        private static ShotgunGripAnalysis AnalyzeShotgunGrip(
            GameObject shotgunAsset)
        {
            MusketGeometryAnalysis geometry = AnalyzeMusketGeometry(shotgunAsset);
            Vector3 heightAxis = geometry.TriggerDirectionAxis.normalized;
            Vector3 stock = geometry.LocalStockPoint;
            Vector3 longAxis = geometry.StockToMuzzleAxis.normalized;
            List<Vector3> barrel = geometry.LocalVertices
                .Where(vertex =>
                {
                    float ratio = Vector3.Dot(vertex - stock, longAxis) /
                                  geometry.SourceLength;
                    return ratio >= 0.62f && ratio <= 0.88f;
                })
                .ToList();
            List<Vector3> handleRegion = geometry.LocalVertices
                .Where(vertex =>
                {
                    float ratio = Vector3.Dot(vertex - stock, longAxis) /
                                  geometry.SourceLength;
                    return ratio >= 0.20f && ratio <= 0.46f;
                })
                .ToList();
            if (barrel.Count < 4 || handleRegion.Count < 4)
            {
                throw new InvalidOperationException(
                    "Shotgun mesh does not expose usable barrel and handle regions.");
            }

            float barrelHeight = barrel.Average(vertex =>
                Vector3.Dot(vertex, heightAxis));
            float positiveExtent = handleRegion.Max(vertex =>
                Vector3.Dot(vertex, heightAxis)) - barrelHeight;
            float negativeExtent = barrelHeight - handleRegion.Min(vertex =>
                Vector3.Dot(vertex, heightAxis));
            if (negativeExtent > positiveExtent)
            {
                heightAxis = -heightAxis;
            }

            // Direct inspection of the fixed-hash shotgun mesh confirmed that the
            // generic extent heuristic selects the receiver-top side. The actual
            // trigger and trigger guard extend on the opposite side.
            heightAxis = -heightAxis;
            geometry.TriggerDirectionAxis = heightAxis;
            Vector3 handlePoint = FindShotgunUndersideCenter(
                geometry,
                0.25f,
                0.39f);
            Vector3 supportPoint = FindShotgunUndersideCenter(
                geometry,
                0.42f,
                0.55f);
            Vector3 forwardSupportPoint = FindShotgunUndersideCenter(
                geometry,
                0.55f,
                0.66f);
            Vector3 reloadActionPoint = FindShotgunTopsideCenter(
                geometry,
                0.40f,
                0.52f);
            float gripSpan = Vector3.Distance(handlePoint, supportPoint);
            if (gripSpan <= Mathf.Max(
                    0.000001f,
                    geometry.SourceLength * 0.05f))
            {
                throw new InvalidOperationException(
                    "Shotgun handle-to-support geometry span is too small.");
            }

            return new ShotgunGripAnalysis
            {
                Geometry = geometry,
                HandlePoint = handlePoint,
                SupportPoint = supportPoint,
                ForwardSupportPoint = forwardSupportPoint,
                ReloadActionPoint = reloadActionPoint,
                GripSpan = gripSpan
            };
        }

        private static Vector3 FindShotgunUndersideCenter(
            MusketGeometryAnalysis geometry,
            float minimumRatio,
            float maximumRatio)
        {
            Vector3 stock = geometry.LocalStockPoint;
            Vector3 longAxis = geometry.StockToMuzzleAxis.normalized;
            Vector3 triggerAxis = geometry.TriggerDirectionAxis.normalized;
            List<Vector3> slice = geometry.LocalVertices
                .Where(vertex =>
                {
                    float ratio = Vector3.Dot(vertex - stock, longAxis) /
                                  geometry.SourceLength;
                    return ratio >= minimumRatio && ratio <= maximumRatio;
                })
                .ToList();
            if (slice.Count < 4)
            {
                throw new InvalidOperationException(
                    "Shotgun grip slice has insufficient vertices.");
            }

            float minimum = slice.Min(vertex => Vector3.Dot(vertex, triggerAxis));
            float maximum = slice.Max(vertex => Vector3.Dot(vertex, triggerAxis));
            float threshold = Mathf.Lerp(minimum, maximum, 0.68f);
            Vector3[] underside = slice
                .Where(vertex => Vector3.Dot(vertex, triggerAxis) >= threshold)
                .ToArray();
            if (underside.Length == 0)
            {
                throw new InvalidOperationException(
                    "Shotgun grip slice has no underside surface vertices.");
            }

            Vector3 sum = Vector3.zero;
            foreach (Vector3 vertex in underside)
            {
                sum += vertex;
            }

            return sum / underside.Length;
        }

        private static Vector3 FindShotgunTopsideCenter(
            MusketGeometryAnalysis geometry,
            float minimumRatio,
            float maximumRatio)
        {
            Vector3 stock = geometry.LocalStockPoint;
            Vector3 longAxis = geometry.StockToMuzzleAxis.normalized;
            Vector3 triggerAxis = geometry.TriggerDirectionAxis.normalized;
            List<Vector3> slice = geometry.LocalVertices
                .Where(vertex =>
                {
                    float ratio = Vector3.Dot(vertex - stock, longAxis) /
                                  geometry.SourceLength;
                    return ratio >= minimumRatio && ratio <= maximumRatio;
                })
                .ToList();
            if (slice.Count < 4)
            {
                throw new InvalidOperationException(
                    "Shotgun action slice has insufficient vertices.");
            }

            float minimum = slice.Min(vertex => Vector3.Dot(vertex, triggerAxis));
            float maximum = slice.Max(vertex => Vector3.Dot(vertex, triggerAxis));
            float threshold = Mathf.Lerp(minimum, maximum, 0.32f);
            Vector3[] topside = slice
                .Where(vertex => Vector3.Dot(vertex, triggerAxis) <= threshold)
                .ToArray();
            if (topside.Length == 0)
            {
                throw new InvalidOperationException(
                    "Shotgun action slice has no topside surface vertices.");
            }

            Vector3 sum = Vector3.zero;
            foreach (Vector3 vertex in topside)
            {
                sum += vertex;
            }

            return sum / topside.Length;
        }

        private static ShotgunGripBinding AnalyzeShotgunGripBinding(
            Transform idleTarget,
            AnimationClip idleClip,
            GameObject shotgunAsset,
            ShotgunGripAnalysis analysis)
        {
            GameObject clone = UnityEngine.Object.Instantiate(idleTarget.gameObject);
            clone.name = "ShotgunGripBindingAnalysis";
            clone.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(clone);
            try
            {
                idleClip.SampleAnimation(clone, 0f);
                Transform root = clone.transform;
                Transform rightHand = FindRequired(root, RightHandPath);
                RightHandPalmSample rightPalm = CalculateRightPalmSample(root);
                RightHandPalmSample leftPalm = CalculateLeftPalmSample(root);
                Vector3 handVector = leftPalm.Center - rightPalm.Center;
                float handSpan = handVector.magnitude;
                if (handSpan <= 0.1f)
                {
                    throw new InvalidOperationException(
                        "Shotgun_Idle hands do not define a usable two-hand span.");
                }

                float scale = ShotgunDesignLengthMeters /
                              analysis.Geometry.SourceLength;
                Quaternion normalWorldRotation = AlignShotgunAxes(
                    analysis.SupportPoint - analysis.HandlePoint,
                    analysis.Geometry.TriggerDirectionAxis,
                    root.forward,
                    -root.up);
                Quaternion buttWorldRotation = AlignShotgunAxes(
                    analysis.HandlePoint - analysis.SupportPoint,
                    analysis.Geometry.TriggerDirectionAxis,
                    root.forward,
                    -root.up);
                GameObject item = UnityEngine.Object.Instantiate(shotgunAsset);
                item.name = ShotgunHandInstanceName;
                item.hideFlags = HideFlags.HideAndDontSave;
                item.transform.SetParent(rightHand, false);
                item.transform.localScale = Vector3.one * scale;

                item.transform.rotation = normalWorldRotation;
                item.transform.position = rightPalm.Center -
                    normalWorldRotation * (analysis.HandlePoint * scale);
                Vector3 normalPosition = item.transform.localPosition;
                Quaternion normalRotation = item.transform.localRotation;
                Vector3 normalScale = item.transform.localScale;
                float normalRight = Vector3.Distance(
                    rightPalm.Center,
                    item.transform.TransformPoint(analysis.HandlePoint));
                float normalLeft = Vector3.Distance(
                    leftPalm.Center,
                    item.transform.TransformPoint(analysis.SupportPoint));
                float normalForward = Vector3.Dot(
                    item.transform.TransformDirection(
                        analysis.Geometry.StockToMuzzleAxis).normalized,
                    root.forward);

                item.transform.rotation = buttWorldRotation;
                item.transform.position = rightPalm.Center -
                    buttWorldRotation * (analysis.SupportPoint * scale);
                Vector3 buttPosition = item.transform.localPosition;
                Quaternion buttRotation = item.transform.localRotation;
                Vector3 buttScale = item.transform.localScale;
                float buttRight = Vector3.Distance(
                    rightPalm.Center,
                    item.transform.TransformPoint(analysis.SupportPoint));
                float buttLeft = Vector3.Distance(
                    leftPalm.Center,
                    item.transform.TransformPoint(analysis.HandlePoint));
                float buttStockForward = Vector3.Dot(
                    -item.transform.TransformDirection(
                        analysis.Geometry.StockToMuzzleAxis).normalized,
                    root.forward);
                UnityEngine.Object.DestroyImmediate(item);
                return new ShotgunGripBinding
                {
                    NormalLocalPosition = normalPosition,
                    NormalLocalRotation = normalRotation,
                    NormalLocalScale = normalScale,
                    ButtLocalPosition = buttPosition,
                    ButtLocalRotation = buttRotation,
                    ButtLocalScale = buttScale,
                    NormalMuzzleForwardDot = normalForward,
                    ButtStockForwardDot = buttStockForward,
                    NormalRightPalmDistance = normalRight,
                    NormalLeftPalmDistance = normalLeft,
                    ButtRightPalmDistance = buttRight,
                    ButtLeftPalmDistance = buttLeft
                };
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(clone);
            }
        }

        private static Quaternion AlignShotgunAxes(
            Vector3 localPrimary,
            Vector3 localSecondary,
            Vector3 worldPrimary,
            Vector3 worldSecondary)
        {
            Vector3 localForward = localPrimary.normalized;
            Vector3 localUp = Vector3.ProjectOnPlane(
                localSecondary,
                localForward).normalized;
            Vector3 worldForward = worldPrimary.normalized;
            Vector3 worldUp = Vector3.ProjectOnPlane(
                worldSecondary,
                worldForward).normalized;
            if (localForward.sqrMagnitude < 0.99f ||
                localUp.sqrMagnitude < 0.99f ||
                worldForward.sqrMagnitude < 0.99f ||
                worldUp.sqrMagnitude < 0.99f)
            {
                throw new InvalidOperationException(
                    "Shotgun grip axes cannot define a stable orientation.");
            }

            return Quaternion.LookRotation(worldForward, worldUp) *
                   Quaternion.Inverse(
                       Quaternion.LookRotation(localForward, localUp));
        }

        private static Transform ReplaceShotgunHandItem(
            Transform target,
            GameObject shotgunAsset,
            ShotgunGripBinding grip,
            bool butt)
        {
            Transform rightHand = FindRequired(target, RightHandPath);
            Transform existing = rightHand.Find(ShotgunHandInstanceName);
            if (existing != null)
            {
                UnityEngine.Object.DestroyImmediate(existing.gameObject);
            }

            GameObject instance = PrefabUtility.InstantiatePrefab(
                shotgunAsset,
                rightHand) as GameObject ??
                throw new InvalidOperationException(
                    target.name + " shotgun instance could not be created.");
            instance.name = ShotgunHandInstanceName;
            instance.transform.localPosition = butt
                ? grip.ButtLocalPosition
                : grip.NormalLocalPosition;
            instance.transform.localRotation = butt
                ? grip.ButtLocalRotation
                : grip.NormalLocalRotation;
            instance.transform.localScale = butt
                ? grip.ButtLocalScale
                : grip.NormalLocalScale;
            EditorUtility.SetDirty(instance);
            return instance.transform;
        }

        private static AnimationClip CreateOrUpdateShotgunButtTransitionClip(
            Transform template,
            AnimationClip idleSource,
            GameObject shotgunAsset,
            ShotgunGripAnalysis analysis,
            ShotgunGripBinding grip,
            string path,
            string clipName,
            bool reverse)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(template.gameObject);
            workObject.name = clipName + "BakeWork";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                AnimationClip generated = CreateShotgunConstantIdleBase(
                    idleSource,
                    clipName);
                Transform root = workObject.transform;
                idleSource.SampleAnimation(workObject, 0f);
                Transform rightHand = FindRequired(root, RightHandPath);
                Transform leftUpper = FindRequired(root, LeftArmPath);
                Transform leftLower = FindRequired(root, LeftForeArmPath);
                Transform leftHand = FindRequired(root, LeftHandPath);
                RightHandPalmSample initialLeftPalm =
                    CalculateLeftPalmSample(root);
                Vector3 leftPalmLocal = leftHand.InverseTransformPoint(
                    initialLeftPalm.Center);
                GameObject item = UnityEngine.Object.Instantiate(shotgunAsset);
                item.name = ShotgunHandInstanceName;
                item.hideFlags = HideFlags.HideAndDontSave;
                item.transform.SetParent(rightHand, false);
                TransformCurveTrack leftUpperTrack =
                    new TransformCurveTrack(LeftArmPath);
                TransformCurveTrack leftLowerTrack =
                    new TransformCurveTrack(LeftForeArmPath);
                TransformCurveTrack leftHandTrack =
                    new TransformCurveTrack(LeftHandPath);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                int frameCount = Mathf.RoundToInt(
                    ShotgunButtClipSeconds * ShotgunButtClipFrameRate);
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = frame / ShotgunButtClipFrameRate;
                    idleSource.SampleAnimation(workObject, 0f);
                    float raw = Mathf.Clamp01(
                        time / ShotgunButtTransitionSeconds);
                    float smooth = raw * raw * (3f - 2f * raw);
                    float blend = reverse ? 1f - smooth : smooth;
                    item.transform.localPosition = Vector3.Lerp(
                        grip.NormalLocalPosition,
                        grip.ButtLocalPosition,
                        blend);
                    item.transform.localRotation = Quaternion.Slerp(
                        grip.NormalLocalRotation,
                        grip.ButtLocalRotation,
                        blend);
                    item.transform.localScale = Vector3.Lerp(
                        grip.NormalLocalScale,
                        grip.ButtLocalScale,
                        blend);
                    Vector3 leftGripLocal = Vector3.Lerp(
                        analysis.SupportPoint,
                        analysis.HandlePoint,
                        blend);
                    Vector3 requestedPalm = item.transform.TransformPoint(
                        leftGripLocal);
                    for (int iteration = 0; iteration < 4; iteration++)
                    {
                        Vector3 requestedHand = requestedPalm -
                            leftHand.TransformVector(leftPalmLocal);
                        SolveTwoBoneIk(
                            leftUpper,
                            leftLower,
                            leftHand,
                            requestedHand,
                            leftLower.position - root.forward * 0.25f);
                    }

                    leftUpperTrack.Add(time, leftUpper);
                    leftLowerTrack.Add(time, leftLower);
                    leftHandTrack.Add(time, leftHand);
                    itemTrack.Add(time, item.transform);
                }

                SetTransformTrackCurves(generated, leftUpperTrack);
                SetTransformTrackCurves(generated, leftLowerTrack);
                SetTransformTrackCurves(generated, leftHandTrack);
                SetTransformTrackCurves(generated, itemTrack);
                SetTransformCurve(
                    generated,
                    itemTrack.Path,
                    "m_LocalScale.x",
                    new[]
                    {
                        new Keyframe(0f, grip.NormalLocalScale.x),
                        new Keyframe(
                            ShotgunButtClipSeconds,
                            grip.NormalLocalScale.x)
                    });
                SetTransformCurve(
                    generated,
                    itemTrack.Path,
                    "m_LocalScale.y",
                    new[]
                    {
                        new Keyframe(0f, grip.NormalLocalScale.y),
                        new Keyframe(
                            ShotgunButtClipSeconds,
                            grip.NormalLocalScale.y)
                    });
                SetTransformCurve(
                    generated,
                    itemTrack.Path,
                    "m_LocalScale.z",
                    new[]
                    {
                        new Keyframe(0f, grip.NormalLocalScale.z),
                        new Keyframe(
                            ShotgunButtClipSeconds,
                            grip.NormalLocalScale.z)
                    });
                generated.EnsureQuaternionContinuity();
                AnimationClipSettings settings =
                    AnimationUtility.GetAnimationClipSettings(generated);
                settings.loopTime = true;
                settings.loopBlend = false;
                AnimationUtility.SetAnimationClipSettings(generated, settings);
                AnimationClip existing =
                    AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
                if (existing == null)
                {
                    AssetDatabase.CreateAsset(generated, path);
                    existing = generated;
                }
                else
                {
                    EditorUtility.CopySerialized(generated, existing);
                    UnityEngine.Object.DestroyImmediate(generated);
                    existing.name = clipName;
                    EditorUtility.SetDirty(existing);
                }

                UnityEngine.Object.DestroyImmediate(item);
                AssetDatabase.SaveAssets();
                return existing;
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static AnimationClip CreateShotgunConstantIdleBase(
            AnimationClip source,
            string clipName)
        {
            AnimationClip generated = new AnimationClip
            {
                name = clipName,
                frameRate = ShotgunButtClipFrameRate,
                wrapMode = WrapMode.Loop,
                legacy = false
            };
            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetCurveBindings(source))
            {
                AnimationCurve sourceCurve =
                    AnimationUtility.GetEditorCurve(source, binding);
                float value = sourceCurve.Evaluate(0f);
                AnimationCurve constant = new AnimationCurve(
                    new Keyframe(0f, value),
                    new Keyframe(ShotgunButtClipSeconds, value));
                AnimationUtility.SetEditorCurve(generated, binding, constant);
            }

            return generated;
        }

        private static string HashAnimationClipContent(AnimationClip clip)
        {
            StringBuilder data = new StringBuilder();
            data.Append(clip.length.ToString("R", CultureInfo.InvariantCulture))
                .Append('|')
                .Append(clip.frameRate.ToString("R", CultureInfo.InvariantCulture))
                .AppendLine();
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(clip);
            data.Append(settings.loopTime).Append('|')
                .Append(settings.loopBlend).AppendLine();
            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetCurveBindings(clip)
                         .OrderBy(item => item.path, StringComparer.Ordinal)
                         .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                data.Append(binding.path).Append('|')
                    .Append(binding.propertyName).Append('|')
                    .Append(binding.type.FullName).AppendLine();
                AnimationCurve curve =
                    AnimationUtility.GetEditorCurve(clip, binding);
                foreach (Keyframe key in curve.keys)
                {
                    data.Append(key.time.ToString("R", CultureInfo.InvariantCulture))
                        .Append('|')
                        .Append(key.value.ToString("R", CultureInfo.InvariantCulture))
                        .Append('|')
                        .Append(key.inTangent.ToString("R", CultureInfo.InvariantCulture))
                        .Append('|')
                        .Append(key.outTangent.ToString("R", CultureInfo.InvariantCulture))
                        .AppendLine();
                }
            }

            using (SHA256 sha = SHA256.Create())
            {
                return BitConverter.ToString(
                        sha.ComputeHash(Encoding.UTF8.GetBytes(data.ToString())))
                    .Replace("-", string.Empty);
            }
        }

        private static string GetShotgunSourcePath(
            ShotgunAnimationSpec spec,
            AnimationClip source)
        {
            if (string.Equals(spec.SourceKind, "EmbeddedMixamo", StringComparison.Ordinal))
            {
                return spec.ClipPath;
            }

            if (source != null)
            {
                return AssetDatabase.GetAssetPath(source);
            }

            return "사용자 승인 ButtMode Enter/Exit 전환";
        }

        private static string GetShotgunSourceHash(ShotgunAnimationSpec spec)
        {
            if (string.Equals(spec.TargetName, ShotgunDrawTargetName, StringComparison.Ordinal))
            {
                return ShotgunDrawSourceHash;
            }

            if (string.Equals(spec.TargetName, ShotgunStowTargetName, StringComparison.Ordinal))
            {
                return ShotgunStowSourceHash;
            }

            if (string.Equals(spec.TargetName, ShotgunButtStrikeTargetName, StringComparison.Ordinal))
            {
                return ShotgunButtStrikeSourceHash;
            }

            return "not-applicable";
        }

        [MenuItem("Bellerophon/Player/Capture Shotgun Animation Set Play Mode")]
        internal static void CaptureShotgunAnimationSetPlayMode()
        {
            int stage = SessionState.GetInt(
                ShotgunAnimationCaptureStageKey,
                0);
            try
            {
                if (stage == 0)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode)
                    {
                        throw new InvalidOperationException(
                            "Shotgun animation review must start in Edit Mode.");
                    }

                    Scene scene = RequireScene();
                    if (scene.isDirty)
                    {
                        throw new InvalidOperationException(
                            "CargoRunMvp must be clean before Shotgun animation review.");
                    }

                    ShotgunAnimationApplyMetrics apply =
                        ReadJson<ShotgunAnimationApplyMetrics>(
                            ShotgunAnimationApplyMetricsPath);
                    if (!apply.passedNumericChecks)
                    {
                        throw new InvalidOperationException(
                            "Shotgun animation apply metrics did not pass.");
                    }

                    SessionState.SetInt(ShotgunAnimationCaptureStageKey, 1);
                    EditorApplication.EnterPlaymode();
                    Debug.Log(
                        "[PlayerShotgunAnimationSet] Entering Play Mode for direct two-loop review.");
                    return;
                }

                if (stage == 1)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun animation capture start requires Play Mode.");
                    }

                    ShotgunAnimationSetPlayModeCapture.Start();
                    SessionState.SetInt(ShotgunAnimationCaptureStageKey, 2);
                    Debug.Log(
                        "[PlayerShotgunAnimationSet] Began sequential actual Play Mode capture for every target.");
                    return;
                }

                if (stage == 2)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun animation capture polling requires Play Mode.");
                    }

                    if (ShotgunAnimationSetPlayModeCapture.Failure != null)
                    {
                        throw new InvalidOperationException(
                            "Shotgun animation Play Mode capture failed.",
                            ShotgunAnimationSetPlayModeCapture.Failure);
                    }

                    if (!ShotgunAnimationSetPlayModeCapture.IsComplete)
                    {
                        Debug.Log(
                            "[PlayerShotgunAnimationSet] Capture is still running. " +
                            ShotgunAnimationSetPlayModeCapture.Status);
                        return;
                    }

                    SessionState.SetInt(ShotgunAnimationCaptureStageKey, 3);
                    Debug.Log(
                        "[PlayerShotgunAnimationSet] Two-loop capture completed; run once more to exit Play Mode.");
                    return;
                }

                if (stage == 3)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun animation review exit requires Play Mode.");
                    }

                    SessionState.EraseInt(ShotgunAnimationCaptureStageKey);
                    EditorApplication.ExitPlaymode();
                    Debug.Log(
                        "[PlayerShotgunAnimationSet] Exiting Play Mode after direct review capture.");
                    return;
                }

                throw new InvalidOperationException(
                    "Shotgun animation capture stage is invalid: " +
                    stage.ToString(CultureInfo.InvariantCulture) + ".");
            }
            catch
            {
                SessionState.EraseInt(ShotgunAnimationCaptureStageKey);
                ShotgunAnimationSetPlayModeCapture.Stop();
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                throw;
            }
        }

        [MenuItem("Bellerophon/Player/Apply Shotgun ButtStrike Weapon Grip Only")]
        internal static void ApplyShotgunButtStrikeWeaponGripOnly()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike weapon-only correction must be applied in Edit Mode.");
            }

            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp must be clean before the Shotgun_ButtStrike weapon-only correction.");
            }

            RequireHash(
                ShotgunButtStrikeOriginalPath,
                ShotgunButtStrikeSourceHash,
                "Shotgun_ButtStrike original Mixamo FBX");
            RequireHash(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeSourceHash,
                "Shotgun_ButtStrike Unity Mixamo FBX");
            RequireHash(
                ShotgunAssetPath,
                ShotgunAssetHash,
                "Shotgun model FBX");
            Dictionary<string, string> otherAssetsBefore =
                HashOtherShotgunAnimationAssets();
            AnimationClip source = LoadSingleEmbeddedClip(
                ShotgunButtStrikeSourcePath,
                ShotgunButtStrikeTargetName);
            if (!string.Equals(source.name, "mixamo.com", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike FBX must expose the exact mixamo.com Take.");
            }

            Transform target = RequireTarget(
                RequireLayout(scene),
                ShotgunButtStrikeTargetName);
            Transform item = FindRequired(
                target,
                RightHandPath + "/" + ShotgunHandInstanceName);
            if (item.parent != FindRequired(target, RightHandPath))
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike shotgun must remain parented to the right hand.");
            }

            GameObject shotgunAsset = AssetDatabase.LoadAssetAtPath<GameObject>(
                ShotgunAssetPath) ??
                throw new FileNotFoundException(
                    "Unity shotgun asset is missing.",
                    Path.GetFullPath(ShotgunAssetPath));
            ShotgunGripAnalysis analysis = AnalyzeShotgunGrip(shotgunAsset);
            ShotgunButtStrikeWeaponGripBakeResult bake =
                CreateOrUpdateShotgunButtStrikeWeaponGripClip(
                    target,
                    source,
                    analysis,
                    item.localScale);
            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(candidate => string.Equals(
                    candidate.TargetName,
                    ShotgunButtStrikeTargetName,
                    StringComparison.Ordinal));
            AnimatorController controller =
                CreateOrUpdateShotgunButtStrikeWeaponGripController(
                    spec.ControllerPath,
                    spec.StateName,
                    source,
                    bake.Clip);
            Animator animator = RequireAnimator(target);
            EditorCurveBinding[] weaponBindings =
                AnimationUtility.GetCurveBindings(bake.Clip);
            string itemPath = RightHandPath + "/" + ShotgunHandInstanceName;
            bool curvesAreWeaponPositionRotationOnly =
                weaponBindings.Length == 7 &&
                weaponBindings.All(binding =>
                    string.Equals(binding.path, itemPath, StringComparison.Ordinal) &&
                    (binding.propertyName.StartsWith(
                         "m_LocalPosition.",
                         StringComparison.Ordinal) ||
                     binding.propertyName.StartsWith(
                         "m_LocalRotation.",
                         StringComparison.Ordinal))) &&
                AnimationUtility.GetObjectReferenceCurveBindings(bake.Clip).Length == 0 &&
                AnimationUtility.GetAnimationEvents(bake.Clip).Length == 0;
            AnimatorControllerLayer[] layers = controller.layers;
            bool baseLayerExact = layers.Length == 2 &&
                LayerStateUsesClip(layers[0], spec.StateName, source);
            bool weaponLayerExact = layers.Length == 2 &&
                LayerStateUsesClip(
                    layers[1],
                    ShotgunButtStrikeWeaponGripStateName,
                    bake.Clip) &&
                layers[1].blendingMode == AnimatorLayerBlendingMode.Override &&
                Mathf.Abs(layers[1].defaultWeight - 1f) <= 0.0001f;
            bool otherAssetsUnchanged = DictionariesEqual(
                otherAssetsBefore,
                HashOtherShotgunAnimationAssets());
            ShotgunButtStrikeWeaponGripApplyMetrics metrics =
                new ShotgunButtStrikeWeaponGripApplyMetrics
                {
                    sourcePath = ShotgunButtStrikeSourcePath,
                    sourceHash = HashFile(ShotgunButtStrikeSourcePath),
                    sourceTake = source.name,
                    weaponClipPath = ShotgunButtStrikeWeaponGripClipPath,
                    controllerPath = spec.ControllerPath,
                    framesBaked = bake.FramesBaked,
                    weaponFloatCurveCount = weaponBindings.Length,
                    durationSeconds = bake.Clip.length,
                    frameRate = bake.Clip.frameRate,
                    minimumSupportRatioFromStock =
                        bake.MinimumSupportRatioFromStock,
                    maximumSupportRatioFromStock =
                        bake.MaximumSupportRatioFromStock,
                    maximumRightPalmGripDistanceMeters =
                        bake.MaximumRightPalmGripDistanceMeters,
                    maximumLeftPalmSupportDistanceMeters =
                        bake.MaximumLeftPalmSupportDistanceMeters,
                    maximumScaleDifference = bake.MaximumScaleDifference,
                    weaponClipContainsOnlyPositionRotation =
                        curvesAreWeaponPositionRotationOnly,
                    weaponClipLoops = AnimationUtility
                        .GetAnimationClipSettings(bake.Clip).loopTime,
                    baseLayerUsesExactMixamoAtSpeedOne = baseLayerExact,
                    weaponLayerUsesGripClipAtSpeedOne = weaponLayerExact,
                    animatorSettingsCorrect =
                        AnimatorMatches(animator, controller) &&
                        Mathf.Abs(animator.speed - 1f) <= 0.0001f &&
                        !animator.applyRootMotion,
                    sourceHashesMatch =
                        string.Equals(
                            HashFile(ShotgunButtStrikeOriginalPath),
                            ShotgunButtStrikeSourceHash,
                            StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(
                            HashFile(ShotgunButtStrikeSourcePath),
                            ShotgunButtStrikeSourceHash,
                            StringComparison.OrdinalIgnoreCase),
                    otherEightShotgunAssetsUnchanged = otherAssetsUnchanged,
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                metrics.framesBaked >= 2 &&
                metrics.weaponFloatCurveCount == 7 &&
                Mathf.Abs(metrics.durationSeconds - source.length) <= 0.0001f &&
                Mathf.Abs(metrics.frameRate - source.frameRate) <= 0.0001f &&
                metrics.minimumSupportRatioFromStock >= 0.50f &&
                metrics.maximumSupportRatioFromStock <= 0.93f &&
                metrics.maximumRightPalmGripDistanceMeters <= 0.001f &&
                metrics.maximumLeftPalmSupportDistanceMeters <= 0.03f &&
                metrics.maximumScaleDifference <= 0.0001f &&
                metrics.weaponClipContainsOnlyPositionRotation &&
                metrics.weaponClipLoops &&
                metrics.baseLayerUsesExactMixamoAtSpeedOne &&
                metrics.weaponLayerUsesGripClipAtSpeedOne &&
                metrics.animatorSettingsCorrect &&
                metrics.sourceHashesMatch &&
                metrics.otherEightShotgunAssetsUnchanged;
            WriteJson(ShotgunButtStrikeWeaponGripApplyMetricsPath, metrics);
            AssetDatabase.SaveAssets();
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike weapon-only apply checks failed. " +
                    JsonUtility.ToJson(metrics));
            }

            SessionState.EraseInt(
                ShotgunButtStrikeWeaponGripCaptureStageKey);
            Debug.Log(
                "[PlayerShotgunButtStrikeWeaponGrip] Preserved the exact Mixamo base Take and added only seven Shotgun_Hand_Item position/rotation curves for continuous right-handle and left-front-underbarrel contact.");
        }

        private static ShotgunButtStrikeWeaponGripBakeResult
            CreateOrUpdateShotgunButtStrikeWeaponGripClip(
                Transform template,
                AnimationClip source,
                ShotgunGripAnalysis analysis,
                Vector3 fixedItemLocalScale)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name = "ShotgunButtStrikeWeaponGripBake";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                Transform item = FindRequired(
                    root,
                    RightHandPath + "/" + ShotgunHandInstanceName);
                TransformCurveTrack itemTrack = new TransformCurveTrack(
                    RightHandPath + "/" + ShotgunHandInstanceName);
                ShotgunButtStrikeWeaponGripBakeResult result =
                    new ShotgunButtStrikeWeaponGripBakeResult();
                int frameCount = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / Mathf.Max(1f, source.frameRate));
                    source.SampleAnimation(workObject, time);
                    item.localScale = fixedItemLocalScale;
                    Vector3 rightPalm = CalculateRightPalmSample(root).Center;
                    Vector3 leftPalm = CalculateLeftPalmSample(root).Center;
                    GetShotgunButtStrikeWeaponGripLocalTargets(
                        analysis,
                        item,
                        Vector3.Distance(rightPalm, leftPalm),
                        out Vector3 handleLocal,
                        out Vector3 supportLocal,
                        out float supportRatio);
                    Vector3 worldPrimary = leftPalm - rightPalm;
                    Vector3 worldSecondary = Vector3.ProjectOnPlane(
                        -root.up,
                        worldPrimary.normalized);
                    if (worldSecondary.sqrMagnitude < 0.01f)
                    {
                        worldSecondary = Vector3.ProjectOnPlane(
                            root.forward,
                            worldPrimary.normalized);
                    }
                    if (worldSecondary.sqrMagnitude < 0.01f)
                    {
                        worldSecondary = Vector3.ProjectOnPlane(
                            root.right,
                            worldPrimary.normalized);
                    }

                    item.rotation = AlignShotgunAxes(
                        supportLocal - handleLocal,
                        analysis.Geometry.TriggerDirectionAxis,
                        worldPrimary,
                        worldSecondary);
                    item.position += rightPalm - item.TransformPoint(handleLocal);
                    result.MaximumRightPalmGripDistanceMeters = Mathf.Max(
                        result.MaximumRightPalmGripDistanceMeters,
                        Vector3.Distance(
                            rightPalm,
                            item.TransformPoint(handleLocal)));
                    result.MaximumLeftPalmSupportDistanceMeters = Mathf.Max(
                        result.MaximumLeftPalmSupportDistanceMeters,
                        Vector3.Distance(
                            leftPalm,
                            item.TransformPoint(supportLocal)));
                    result.MaximumScaleDifference = Mathf.Max(
                        result.MaximumScaleDifference,
                        Vector3.Distance(
                            item.localScale,
                            fixedItemLocalScale));
                    result.MinimumSupportRatioFromStock = Mathf.Min(
                        result.MinimumSupportRatioFromStock,
                        supportRatio);
                    result.MaximumSupportRatioFromStock = Mathf.Max(
                        result.MaximumSupportRatioFromStock,
                        supportRatio);
                    itemTrack.Add(time, item);
                }

                AnimationClip generated = new AnimationClip
                {
                    name = "Shotgun_ButtStrike_WeaponGripOnly",
                    frameRate = source.frameRate,
                    wrapMode = WrapMode.Loop,
                    legacy = false
                };
                SetTransformTrackCurves(generated, itemTrack);
                generated.EnsureQuaternionContinuity();
                AnimationClipSettings settings =
                    AnimationUtility.GetAnimationClipSettings(generated);
                settings.startTime = 0f;
                settings.stopTime = source.length;
                settings.loopTime = true;
                settings.loopBlend = false;
                AnimationUtility.SetAnimationClipSettings(generated, settings);
                AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    ShotgunButtStrikeWeaponGripClipPath);
                if (existing == null)
                {
                    AssetDatabase.CreateAsset(
                        generated,
                        ShotgunButtStrikeWeaponGripClipPath);
                    existing = generated;
                }
                else
                {
                    EditorUtility.CopySerialized(generated, existing);
                    UnityEngine.Object.DestroyImmediate(generated);
                    existing.name = "Shotgun_ButtStrike_WeaponGripOnly";
                    EditorUtility.SetDirty(existing);
                }

                AssetDatabase.SaveAssets();
                result.Clip = existing;
                result.FramesBaked = frameCount + 1;
                return result;
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void GetShotgunButtStrikeWeaponGripLocalTargets(
            ShotgunGripAnalysis analysis,
            Transform item,
            float handSpanMeters,
            out Vector3 handleLocal,
            out Vector3 supportLocal,
            out float supportRatioFromStock)
        {
            Vector3 longAxis = analysis.Geometry.StockToMuzzleAxis.normalized;
            handleLocal = analysis.HandlePoint;
            Vector3 referenceSupport = analysis.ForwardSupportPoint;
            Vector3 crossOffset = Vector3.ProjectOnPlane(
                referenceSupport - handleLocal,
                longAxis);
            float axialWorldScale = item.TransformVector(longAxis).magnitude;
            float crossWorldLength = item.TransformVector(crossOffset).magnitude;
            if (axialWorldScale <= 0.000001f ||
                handSpanMeters <= crossWorldLength + 0.000001f)
            {
                throw new InvalidOperationException(
                    "Shotgun_ButtStrike hand span cannot define a stable handle-to-underbarrel grip.");
            }

            float requestedAxialLocal = Mathf.Sqrt(
                handSpanMeters * handSpanMeters -
                crossWorldLength * crossWorldLength) /
                axialWorldScale;
            float handleCoordinate = Vector3.Dot(
                handleLocal - analysis.Geometry.LocalStockPoint,
                longAxis);
            float minimumCoordinate = analysis.Geometry.SourceLength * 0.55f;
            float maximumCoordinate = analysis.Geometry.SourceLength * 0.93f;
            float supportCoordinate = Mathf.Clamp(
                handleCoordinate + requestedAxialLocal,
                minimumCoordinate,
                maximumCoordinate);
            supportLocal = handleLocal + crossOffset +
                longAxis * (supportCoordinate - handleCoordinate);
            supportRatioFromStock = supportCoordinate /
                analysis.Geometry.SourceLength;
        }

        private static Dictionary<string, string>
            HashOtherShotgunAnimationAssets()
        {
            return HashOtherShotgunAnimationAssetsExcept(
                ShotgunButtStrikeTargetName);
        }

        private static Dictionary<string, string>
            HashOtherShotgunAnimationAssetsExcept(string excludedTargetName)
        {
            return GetShotgunAnimationSpecs()
                .Where(spec => !string.Equals(
                    spec.TargetName,
                    excludedTargetName,
                    StringComparison.Ordinal))
                .SelectMany(spec => new[] { spec.ControllerPath, spec.ClipPath })
                .Distinct(StringComparer.Ordinal)
                .Where(path => File.Exists(Path.GetFullPath(path)))
                .ToDictionary(
                    path => path,
                    HashFile,
                    StringComparer.Ordinal);
        }

        [MenuItem("Bellerophon/Player/Capture Shotgun ButtStrike Exact Source Play Mode")]
        internal static void CaptureShotgunButtStrikeExactSourcePlayMode()
        {
            int stage = SessionState.GetInt(
                ShotgunButtStrikeExactCaptureStageKey,
                0);
            try
            {
                if (stage == 0)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike exact-source review must start in Edit Mode.");
                    }

                    Scene scene = RequireScene();
                    if (scene.isDirty)
                    {
                        throw new InvalidOperationException(
                            "CargoRunMvp must be clean before Shotgun_ButtStrike exact-source review.");
                    }

                    RequireHash(
                        ShotgunButtStrikeOriginalPath,
                        ShotgunButtStrikeSourceHash,
                        "Shotgun_ButtStrike original Mixamo FBX");
                    RequireHash(
                        ShotgunButtStrikeSourcePath,
                        ShotgunButtStrikeSourceHash,
                        "Shotgun_ButtStrike Unity Mixamo FBX");
                    AnimationClip source = LoadSingleEmbeddedClip(
                        ShotgunButtStrikeSourcePath,
                        ShotgunButtStrikeTargetName);
                    if (!string.Equals(source.name, "mixamo.com", StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike FBX must expose the exact mixamo.com Take.");
                    }

                    AnimationClipSettings settings =
                        AnimationUtility.GetAnimationClipSettings(source);
                    Transform target = RequireTarget(
                        RequireLayout(scene),
                        ShotgunButtStrikeTargetName);
                    Animator animator = RequireAnimator(target);
                    AnimatorController controller =
                        AssetDatabase.LoadAssetAtPath<AnimatorController>(
                            GetShotgunAnimationSpecs()
                                .Single(spec => string.Equals(
                                    spec.TargetName,
                                    ShotgunButtStrikeTargetName,
                                    StringComparison.Ordinal))
                                .ControllerPath) ??
                        throw new FileNotFoundException(
                            "Shotgun_ButtStrike controller is missing.");
                    if (!settings.loopTime ||
                        !StateUsesClip(
                            controller,
                            GetShotgunAnimationSpecs()
                                .Single(spec => string.Equals(
                                    spec.TargetName,
                                    ShotgunButtStrikeTargetName,
                                    StringComparison.Ordinal))
                                .StateName,
                            source) ||
                        !AnimatorMatches(animator, controller) ||
                        Mathf.Abs(animator.speed - 1f) > 0.0001f ||
                        animator.applyRootMotion)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike is not connected directly to the looping embedded mixamo.com Take at speed 1.");
                    }

                    SessionState.SetInt(
                        ShotgunButtStrikeExactCaptureStageKey,
                        1);
                    EditorApplication.EnterPlaymode();
                    Debug.Log(
                        "[PlayerShotgunButtStrikeExactSource] Entering Play Mode for an unmodified two-loop review.");
                    return;
                }

                if (stage == 1)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike exact-source capture requires Play Mode.");
                    }

                    ShotgunAnimationSetPlayModeCapture.StartExactButtStrike();
                    SessionState.SetInt(
                        ShotgunButtStrikeExactCaptureStageKey,
                        2);
                    Debug.Log(
                        "[PlayerShotgunButtStrikeExactSource] Began actual speed-1 capture for two loops.");
                    return;
                }

                if (stage == 2)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike exact-source capture polling requires Play Mode.");
                    }

                    if (ShotgunAnimationSetPlayModeCapture.Failure != null)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike exact-source Play Mode capture failed.",
                            ShotgunAnimationSetPlayModeCapture.Failure);
                    }

                    if (!ShotgunAnimationSetPlayModeCapture.IsComplete)
                    {
                        Debug.Log(
                            "[PlayerShotgunButtStrikeExactSource] Capture is still running. " +
                            ShotgunAnimationSetPlayModeCapture.Status);
                        return;
                    }

                    SessionState.SetInt(
                        ShotgunButtStrikeExactCaptureStageKey,
                        3);
                    Debug.Log(
                        "[PlayerShotgunButtStrikeExactSource] Two-loop capture completed; run once more to exit Play Mode.");
                    return;
                }

                if (stage == 3)
                {
                    SessionState.EraseInt(
                        ShotgunButtStrikeExactCaptureStageKey);
                    EditorApplication.ExitPlaymode();
                    Debug.Log(
                        "[PlayerShotgunButtStrikeExactSource] Exiting Play Mode after direct review capture.");
                    return;
                }

                throw new InvalidOperationException(
                    "Shotgun_ButtStrike exact-source review stage is invalid: " +
                    stage.ToString(CultureInfo.InvariantCulture) + ".");
            }
            catch
            {
                SessionState.EraseInt(
                    ShotgunButtStrikeExactCaptureStageKey);
                ShotgunAnimationSetPlayModeCapture.Stop();
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                throw;
            }
        }

