                    AnimatorController controller =
                        AssetDatabase.LoadAssetAtPath<AnimatorController>(
                            spec.ControllerPath) ??
                        throw new FileNotFoundException(
                            "Shotgun_ButtStrike controller is missing.");
                    AnimatorControllerLayer[] layers = controller.layers;
                    Transform target = RequireTarget(
                        RequireLayout(scene),
                        ShotgunButtStrikeTargetName);
                    Animator animator = RequireAnimator(target);
                    if (layers.Length != 2 ||
                        !LayerStateUsesClip(layers[0], spec.StateName, source) ||
                        !LayerStateUsesClip(
                            layers[1],
                            ShotgunButtStrikeWeaponGripStateName,
                            weaponClip) ||
                        layers[1].blendingMode !=
                            AnimatorLayerBlendingMode.Override ||
                        Mathf.Abs(layers[1].defaultWeight - 1f) > 0.0001f ||
                        !AnimatorMatches(animator, controller) ||
                        Mathf.Abs(animator.speed - 1f) > 0.0001f ||
                        animator.applyRootMotion ||
                        !AnimationUtility.GetAnimationClipSettings(source).loopTime ||
                        !AnimationUtility.GetAnimationClipSettings(weaponClip).loopTime)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike does not have the exact looping Mixamo base plus the full-weight weapon-only layer at speed 1.");
                    }

                    SessionState.SetInt(
                        ShotgunButtStrikeWeaponGripCaptureStageKey,
                        1);
                    EditorApplication.EnterPlaymode();
                    Debug.Log(
                        "[PlayerShotgunButtStrikeWeaponGrip] Entering Play Mode for a two-loop direct grip review.");
                    return;
                }

                if (stage == 1)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike weapon-grip capture requires Play Mode.");
                    }

                    ShotgunAnimationSetPlayModeCapture.StartWeaponGripOnly();
                    SessionState.SetInt(
                        ShotgunButtStrikeWeaponGripCaptureStageKey,
                        2);
                    Debug.Log(
                        "[PlayerShotgunButtStrikeWeaponGrip] Began actual speed-1 capture for two loops.");
                    return;
                }

                if (stage == 2)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike weapon-grip capture polling requires Play Mode.");
                    }

                    if (ShotgunAnimationSetPlayModeCapture.Failure != null)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike weapon-grip Play Mode capture failed.",
                            ShotgunAnimationSetPlayModeCapture.Failure);
                    }

                    if (!ShotgunAnimationSetPlayModeCapture.IsComplete)
                    {
                        Debug.Log(
                            "[PlayerShotgunButtStrikeWeaponGrip] Capture is still running. " +
                            ShotgunAnimationSetPlayModeCapture.Status);
                        return;
                    }

                    SessionState.SetInt(
                        ShotgunButtStrikeWeaponGripCaptureStageKey,
                        3);
                    Debug.Log(
                        "[PlayerShotgunButtStrikeWeaponGrip] Two-loop capture and support checks completed; run once more to exit Play Mode.");
                    return;
                }

                if (stage == 3)
                {
                    if (!EditorApplication.isPlaying)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike weapon-grip review exit requires Play Mode.");
                    }

                    SessionState.SetInt(
                        ShotgunButtStrikeWeaponGripCaptureStageKey,
                        4);
                    EditorApplication.ExitPlaymode();
                    Debug.Log(
                        "[PlayerShotgunButtStrikeWeaponGrip] Exiting Play Mode after the direct review capture.");
                    return;
                }

                if (stage == 4)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike final reviewed capture must be saved in Edit Mode.");
                    }

                    ShotgunAnimationReviewMetrics review =
                        ReadJson<ShotgunAnimationReviewMetrics>(
                            ShotgunButtStrikeWeaponGripReviewMetricsPath);
                    if (!review.passedNumericChecks ||
                        !review.actualPlayModeObserved ||
                        review.targets == null ||
                        review.targets.Length != 1 ||
                        !review.targets[0].weaponTransformOnly)
                    {
                        throw new InvalidOperationException(
                            "Shotgun_ButtStrike weapon-grip review did not pass before final capture.");
                    }

                    CopyReviewedContact(
                        ShotgunButtStrikeWeaponGripContactPath,
                        ShotgunButtStrikeWeaponGripFinalPath);
                    SessionState.EraseInt(
                        ShotgunButtStrikeWeaponGripCaptureStageKey);
                    Debug.Log(
                        "[PlayerShotgunButtStrikeWeaponGrip] Saved the single final representative image from the passed direct Play Mode review.");
                    return;
                }

                throw new InvalidOperationException(
                    "Shotgun_ButtStrike weapon-grip review stage is invalid: " +
                    stage.ToString(CultureInfo.InvariantCulture) + ".");
            }
            catch
            {
                SessionState.EraseInt(
                    ShotgunButtStrikeWeaponGripCaptureStageKey);
                ShotgunAnimationSetPlayModeCapture.Stop();
                if (EditorApplication.isPlaying)
                {
                    EditorApplication.ExitPlaymode();
                }

                throw;
            }
        }

        [MenuItem("Bellerophon/Player/Capture Shotgun Reload Wrist Detach Return Play Mode")]
        internal static void CaptureShotgunReloadWristDetachReturnPlayMode()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload wrist deformation review must run in Edit Mode.");
            }

            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp must be clean before the Shotgun_Reload wrist deformation review.");
            }

            ShotgunReloadWristDeformApplyRecord apply =
                ReadJson<ShotgunReloadWristDeformApplyRecord>(
                    ShotgunReloadWristDeformApplyPath);
            if (!apply.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload wrist deformation apply invariants did not pass.");
            }

            ShotgunAnimationSpec spec = GetShotgunAnimationSpecs()
                .Single(candidate => string.Equals(
                    candidate.TargetName,
                    ShotgunReloadTargetName,
                    StringComparison.Ordinal));
            string clipHash = HashFile(ShotgunReloadWristReturnClipPath);
            string controllerHash = HashFile(spec.ControllerPath);
            bool assetsMatchApply =
                string.Equals(
                    clipHash,
                    apply.reloadClipHashAfter,
                    StringComparison.Ordinal) &&
                string.Equals(
                    controllerHash,
                    apply.controllerHashAfter,
                    StringComparison.Ordinal);
            if (!assetsMatchApply)
            {
                throw new InvalidOperationException(
                    "Shotgun_Reload clip or controller changed after the deformation-only apply step.");
            }

            Transform target = RequireTarget(
                RequireLayout(scene),
                ShotgunReloadTargetName);
            GameObject reviewObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            reviewObject.name = "ShotgunReloadWristDeformDirectReview";
            reviewObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(reviewObject);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ShotgunReloadWristReturnClipPath) ??
                throw new FileNotFoundException(
                    "Shotgun_Reload clip is missing for direct review.",
                    Path.GetFullPath(ShotgunReloadWristReturnClipPath));

            List<byte[]> closeFront = new List<byte[]>();
            List<byte[]> closeSide = new List<byte[]>();
            List<byte[]> fullFront = new List<byte[]>();
            float maximumPositionDifference = 0f;
            float maximumRotationDifference = 0f;
            float maximumScaleDifference = 0f;
            try
            {
                Transform reviewRoot = reviewObject.transform;
                Transform reviewShoulder = FindRequired(
                    reviewRoot,
                    LeftShoulderPath);
                Transform reviewArm = FindRequired(reviewRoot, LeftArmPath);
                Transform reviewForeArm = FindRequired(
                    reviewRoot,
                    LeftForeArmPath);
                Transform reviewHand = FindRequired(reviewRoot, LeftHandPath);
                Transform reviewHelper = reviewForeArm.Find(
                    ShotgunReloadWristDeformBoneName) ??
                    throw new InvalidOperationException(
                        "Shotgun_Reload deformation helper is missing from the review instance.");
                if (reviewHand.parent != reviewForeArm ||
                    reviewHand.IsChildOf(reviewHelper))
                {
                    throw new InvalidOperationException(
                        "Shotgun_Reload left-hand hierarchy changed; the deformation helper must remain a sibling.");
                }

                ShotgunReloadWristTwistDeformer deformer =
                    reviewObject.GetComponent<
                        ShotgunReloadWristTwistDeformer>() ??
                    throw new InvalidOperationException(
                        "Shotgun_Reload deformation driver is missing from the review instance.");
                foreach (SkinnedMeshRenderer reviewRenderer in reviewObject
                             .GetComponentsInChildren<SkinnedMeshRenderer>(true))
                {
                    reviewRenderer.updateWhenOffscreen = true;
                }

                using (CaptureEnvironment environment =
                       new CaptureEnvironment(reviewRoot))
                {
                    for (int phaseIndex = 0; phaseIndex <= 8; phaseIndex++)
                    {
                        float phase = phaseIndex / 8f;
                        float time = phaseIndex == 8
                            ? 0f
                            : clip.length * phase;
                        clip.SampleAnimation(reviewObject, time);
                        Dictionary<Transform, LocalTransformState> before =
                            CaptureLocalTransformStates(
                                reviewShoulder,
                                reviewArm,
                                reviewForeArm,
                                reviewHand);
                        deformer.EvaluateNow();
                        MeasureLocalTransformDifferences(
                            before,
                            out float positionDifference,
                            out float rotationDifference,
                            out float scaleDifference);
                        maximumPositionDifference = Mathf.Max(
                            maximumPositionDifference,
                            positionDifference);
                        maximumRotationDifference = Mathf.Max(
                            maximumRotationDifference,
                            rotationDifference);
                        maximumScaleDifference = Mathf.Max(
                            maximumScaleDifference,
                            scaleDifference);

                        Vector3 wristCenter = Vector3.Lerp(
                            reviewForeArm.position,
                            reviewHand.position,
                            0.92f);
                        environment.ConfigureView(
                            reviewRoot,
                            wristCenter,
                            0.20f);
                        closeFront.Add(environment.CaptureFront());
                        closeSide.Add(environment.CaptureSide());
                        environment.ConfigureView(reviewRoot, 1.05f, 1.18f);
                        fullFront.Add(environment.CaptureFront());
                    }
                }

                ComposeRows(
                    new[] { closeFront, closeSide, fullFront },
                    ShotgunReloadWristDeformReviewPath);
                AssetDatabase.ImportAsset(
                    ShotgunReloadWristDeformReviewPath,
                    ImportAssetOptions.ForceUpdate);
                ShotgunReloadWristDeformReviewRecord review =
                    new ShotgunReloadWristDeformReviewRecord
                    {
                        target = ShotgunReloadTargetName,
                        contactSheetPath =
                            ShotgunReloadWristDeformReviewPath,
                        sampledIntervals = 8,
                        loopStartRepeatedAsFinalColumn = true,
                        maximumExistingBonePositionDifferenceMeters =
                            maximumPositionDifference,
                        maximumExistingBoneRotationDifferenceDegrees =
                            maximumRotationDifference,
                        maximumExistingBoneScaleDifference =
                            maximumScaleDifference,
                        reloadClipHash = clipHash,
                        controllerHash = controllerHash,
                        clipAndControllerMatchApplyRecord = assetsMatchApply,
                        componentWritesOnlyHelperBone =
                            maximumPositionDifference <= 0.000001f &&
                            maximumRotationDifference <= 0.0001f &&
                            maximumScaleDifference <= 0.000001f,
                        validationPriority =
                            "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                    };
                review.passedNumericChecks =
                    review.clipAndControllerMatchApplyRecord &&
                    review.componentWritesOnlyHelperBone &&
                    closeFront.Count == 9 &&
                    closeSide.Count == 9 &&
                    fullFront.Count == 9;
                WriteJson(
                    ShotgunReloadWristDeformReviewMetricsPath,
                    review);
                AssetDatabase.ImportAsset(
                    ShotgunReloadWristDeformReviewMetricsPath,
                    ImportAssetOptions.ForceUpdate);
                AssetDatabase.SaveAssets();
                if (!review.passedNumericChecks)
                {
                    throw new InvalidOperationException(
                        "Shotgun_Reload deformation-only review invariants failed.");
                }

                Debug.Log(
                    "[PlayerShotgunReloadWristDeform] Captured one direct three-view contact sheet across eight equal animation intervals plus the repeated loop start. Existing left-arm bone differences remained zero.");
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(reviewObject);
            }
        }

