                Mathf.Abs(
                    metrics.measuredPeakForwardTiltDegrees -
                    StickAttackForwardAttackingPeakForwardTiltDegrees) <= 0.1f &&
                Mathf.Abs(
                    metrics.measuredFinalForwardTiltDegrees -
                    StickAttackForwardAttackingFinalForwardTiltDegrees) <= 0.1f &&
                metrics.finalStickTiltsForward &&
                metrics.maximumLeftPalmCharacterRightAngleDegrees <= 0.5f &&
                metrics.maximumStickAxisDirectionStepDegrees <= 45f &&
                metrics.nonCorrectedBodyPositionDifferenceMax <=
                    PositionTolerance &&
                metrics.nonCorrectedBodyRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.endHoldBodyPositionDifferenceMax <=
                    PositionTolerance &&
                metrics.endHoldBodyRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.endHoldStickPositionDifferenceMax <= 0.000001f &&
                metrics.endHoldStickRotationDifferenceDegreesMax <= 0.001f &&
                metrics.leftForeArmCorrectionAndSourceLeftHandPosePreserved &&
                metrics.sourceEventsUnchanged &&
                metrics.controllerUsesGeneratedClip &&
                metrics.generatedClipLoops &&
                metrics.animatorSettingsCorrect &&
                metrics.actualPlayModeVideoExists &&
                metrics.actualPlayModeOverviewExists &&
                metrics.actualPlayModeRuntimeSamplesExist;
            return metrics;
        }

        private static void
            MeasureStickAttackForwardAttackingCorrectionMotion(
                Transform template,
                AnimationClip source,
                AnimationClip generated,
                out float leftPalmAngleMax,
                out float stickRotationStepMax,
                out float stickRotationCumulativeTravel,
                out float nonCorrectedPositionDifferenceMax,
                out float nonCorrectedRotationDifferenceMax,
                out float holdBodyPositionDifferenceMax,
                out float holdBodyRotationDifferenceMax,
                out float holdStickPositionDifferenceMax,
                out float holdStickRotationDifferenceMax,
                out int alignmentStartFrame,
                out int peakForwardTiltFrame,
                out int alignmentCompleteFrame)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject generatedObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            generatedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            DisableAnimators(generatedObject);
            try
            {
                Transform sourceRoot = sourceObject.transform;
                Transform generatedRoot = generatedObject.transform;
                string stickPath = RightHandPath + "/" + StickInstanceName;
                string[] nonCorrectedPaths = sourceRoot
                    .GetComponentsInChildren<Transform>(true)
                    .Select(item => AnimationUtility.CalculateTransformPath(
                        item,
                        sourceRoot))
                    .Where(path =>
                        (string.Equals(path, "Armature", StringComparison.Ordinal) ||
                         path.StartsWith("Armature/", StringComparison.Ordinal)) &&
                        !string.Equals(path, LeftForeArmPath, StringComparison.Ordinal) &&
                        !string.Equals(path, stickPath, StringComparison.Ordinal) &&
                        !path.StartsWith(stickPath + "/", StringComparison.Ordinal))
                    .ToArray();
                int sourceIntervals = Mathf.RoundToInt(
                    source.length * source.frameRate);
                alignmentCompleteFrame = Mathf.Max(
                    1,
                    sourceIntervals -
                    StickAttackForwardAttackingFinalAlignmentLeadFrames);
                alignmentStartFrame =
                    FindStickAttackForwardAttackingDescentStartFrame(
                        sourceObject,
                        source,
                        alignmentCompleteFrame);
                peakForwardTiltFrame =
                    FindStickAttackForwardAttackingPeakDescentFrame(
                        sourceObject,
                        source,
                        alignmentStartFrame,
                        alignmentCompleteFrame);
                leftPalmAngleMax = 0f;
                stickRotationStepMax = 0f;
                stickRotationCumulativeTravel = 0f;
                nonCorrectedPositionDifferenceMax = 0f;
                nonCorrectedRotationDifferenceMax = 0f;
                StickGripPlacement stickPlacement =
                    DescribeExistingStickGrip(generatedRoot);
                Vector3 previousStickAxisDirection = Vector3.zero;
                bool hasPreviousStickAxisDirection = false;
                for (int frame = 0; frame <= sourceIntervals; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / source.frameRate);
                    source.SampleAnimation(sourceObject, time);
                    generated.SampleAnimation(generatedObject, time);
                    MeasurePoseDifferenceForPaths(
                        CapturePose(sourceRoot),
                        CapturePose(generatedRoot),
                        nonCorrectedPaths,
                        out float positionDifference,
                        out float rotationDifference);
                    nonCorrectedPositionDifferenceMax = Mathf.Max(
                        nonCorrectedPositionDifferenceMax,
                        positionDifference);
                    nonCorrectedRotationDifferenceMax = Mathf.Max(
                        nonCorrectedRotationDifferenceMax,
                        rotationDifference);
                    Transform leftHand = FindRequired(
                        generatedRoot,
                        LeftHandPath);
                    Transform leftForeArm = FindRequired(
                        generatedRoot,
                        LeftForeArmPath);
                    Vector3 foreArmAxis =
                        (leftHand.position - leftForeArm.position).normalized;
                    Vector3 palmProjected = Vector3.ProjectOnPlane(
                        leftHand.right,
                        foreArmAxis);
                    Vector3 requestedProjected = Vector3.ProjectOnPlane(
                        generatedRoot.right,
                        foreArmAxis);
                    if (palmProjected.sqrMagnitude < 0.0000001f ||
                        requestedProjected.sqrMagnitude < 0.0000001f)
                    {
                        throw new InvalidOperationException(
                            "Stick_Attack_Forward left palm-right validation projection is degenerate.");
                    }
                    leftPalmAngleMax = Mathf.Max(
                        leftPalmAngleMax,
                        Vector3.Angle(
                            palmProjected,
                            requestedProjected));
                    Transform stick = FindRequired(generatedRoot, stickPath);
                    Vector3 stickAxisDirection = stick.TransformDirection(
                        stickPlacement.LongLocalAxis).normalized;
                    if (hasPreviousStickAxisDirection &&
                        Vector3.Dot(
                            stickAxisDirection,
                            previousStickAxisDirection) < 0f)
                    {
                        stickAxisDirection = -stickAxisDirection;
                    }

                    if (hasPreviousStickAxisDirection)
                    {
                        float step = Vector3.Angle(
                            previousStickAxisDirection,
                            stickAxisDirection);
                        stickRotationStepMax = Mathf.Max(
                            stickRotationStepMax,
                            step);
                        stickRotationCumulativeTravel += step;
                    }

                    previousStickAxisDirection = stickAxisDirection;
                    hasPreviousStickAxisDirection = true;
                }

                MeasureArmatureTransformCurveHold(
                    generated,
                    stickPath,
                    source.length,
                    generated.length,
                    out holdBodyPositionDifferenceMax,
                    out holdBodyRotationDifferenceMax);
                MeasureTransformCurveHold(
                    generated,
                    stickPath,
                    source.length,
                    generated.length,
                    out holdStickPositionDifferenceMax,
                    out holdStickRotationDifferenceMax);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(generatedObject);
            }
        }

        private static int CountTransformRotationCurves(
            AnimationClip clip,
            string path)
        {
            return AnimationUtility.GetCurveBindings(clip).Count(binding =>
                binding.type == typeof(Transform) &&
                string.Equals(binding.path, path, StringComparison.Ordinal) &&
                binding.propertyName.StartsWith(
                    "m_LocalRotation.",
                    StringComparison.Ordinal));
        }

        private static float
            MeasureStickAttackForwardAttackingStickTiltAtFrame(
                Transform template,
                AnimationClip generated,
                int frame)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                StickGripPlacement placement = DescribeExistingStickGrip(root);
                generated.SampleAnimation(
                    workObject,
                    Mathf.Clamp(
                        frame / generated.frameRate,
                        0f,
                        generated.length));
                Vector3 direction = placement.Instance.TransformDirection(
                    placement.LongLocalAxis).normalized;
                if (Vector3.Dot(direction, root.up) < 0f)
                {
                    direction = -direction;
                }

                return Vector3.Angle(root.up, direction);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void MeasureArmatureTransformCurveHold(
            AnimationClip clip,
            string excludedRootPath,
            float holdStartTime,
            float holdEndTime,
            out float positionDifferenceMax,
            out float rotationDifferenceMax)
        {
            positionDifferenceMax = 0f;
            rotationDifferenceMax = 0f;
            string[] paths = AnimationUtility.GetCurveBindings(clip)
                .Where(binding =>
                    binding.type == typeof(Transform) &&
                    (string.Equals(
                         binding.path,
                         "Armature",
                         StringComparison.Ordinal) ||
                     binding.path.StartsWith(
                         "Armature/",
                         StringComparison.Ordinal)) &&
                    !string.Equals(
                        binding.path,
                        excludedRootPath,
                        StringComparison.Ordinal) &&
                    !binding.path.StartsWith(
                        excludedRootPath + "/",
                        StringComparison.Ordinal))
                .Select(binding => binding.path)
                .Distinct()
                .ToArray();
            bool measuredAny = false;
            foreach (string path in paths)
            {
                AnimationCurve[] positionCurves =
                {
                    FindTransformCurve(clip, path, "m_LocalPosition.x"),
                    FindTransformCurve(clip, path, "m_LocalPosition.y"),
                    FindTransformCurve(clip, path, "m_LocalPosition.z")
                };
                if (positionCurves.All(curve => curve != null))
                {
                    measuredAny = true;
                    Vector3 start = new Vector3(
                        positionCurves[0].Evaluate(holdStartTime),
                        positionCurves[1].Evaluate(holdStartTime),
                        positionCurves[2].Evaluate(holdStartTime));
                    for (int frame = 1;
                         frame <= Mathf.Max(
                             1,
                             Mathf.RoundToInt(
                                 (holdEndTime - holdStartTime) *
                                 clip.frameRate));
                         frame++)
                    {
                        float time = Mathf.Lerp(
                            holdStartTime,
                            holdEndTime,
                            frame / (float)Mathf.Max(
                                1,
                                Mathf.RoundToInt(
                                    (holdEndTime - holdStartTime) *
                                    clip.frameRate)));
                        Vector3 current = new Vector3(
                            positionCurves[0].Evaluate(time),
                            positionCurves[1].Evaluate(time),
                            positionCurves[2].Evaluate(time));
                        positionDifferenceMax = Mathf.Max(
                            positionDifferenceMax,
                            Vector3.Distance(start, current));
                    }
                }

                AnimationCurve[] rotationCurves =
                {
                    FindTransformCurve(clip, path, "m_LocalRotation.x"),
                    FindTransformCurve(clip, path, "m_LocalRotation.y"),
                    FindTransformCurve(clip, path, "m_LocalRotation.z"),
                    FindTransformCurve(clip, path, "m_LocalRotation.w")
                };
                if (rotationCurves.All(curve => curve != null))
                {
                    measuredAny = true;
                    Quaternion start = new Quaternion(
                        rotationCurves[0].Evaluate(holdStartTime),
                        rotationCurves[1].Evaluate(holdStartTime),
                        rotationCurves[2].Evaluate(holdStartTime),
                        rotationCurves[3].Evaluate(holdStartTime)).normalized;
                    int intervals = Mathf.Max(
                        1,
                        Mathf.RoundToInt(
                            (holdEndTime - holdStartTime) * clip.frameRate));
                    for (int frame = 1; frame <= intervals; frame++)
                    {
                        float time = Mathf.Lerp(
                            holdStartTime,
                            holdEndTime,
                            frame / (float)intervals);
                        Quaternion current = new Quaternion(
                            rotationCurves[0].Evaluate(time),
                            rotationCurves[1].Evaluate(time),
                            rotationCurves[2].Evaluate(time),
                            rotationCurves[3].Evaluate(time)).normalized;
                        rotationDifferenceMax = Mathf.Max(
                            rotationDifferenceMax,
                            Quaternion.Angle(start, current));
                    }
                }
            }

            if (!measuredAny)
            {
                throw new InvalidOperationException(
                    "No Armature transform curves were available for the Stick_Attack_Forward hold check.");
            }
        }

        private static AnimationCurve FindTransformCurve(
            AnimationClip clip,
            string path,
            string propertyName)
        {
            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetCurveBindings(clip))
            {
                if (binding.type == typeof(Transform) &&
                    string.Equals(
                        binding.path,
                        path,
                        StringComparison.Ordinal) &&
                    string.Equals(
                        binding.propertyName,
                        propertyName,
                        StringComparison.Ordinal))
                {
                    return AnimationUtility.GetEditorCurve(clip, binding);
                }
            }

            return null;
        }

        private static void MeasureTransformCurveHold(
            AnimationClip clip,
            string path,
            float holdStartTime,
            float holdEndTime,
            out float positionDifferenceMax,
            out float rotationDifferenceMax)
        {
            AnimationCurve positionX = RequireTransformCurve(
                clip,
                path,
                "m_LocalPosition.x");
            AnimationCurve positionY = RequireTransformCurve(
                clip,
                path,
                "m_LocalPosition.y");
            AnimationCurve positionZ = RequireTransformCurve(
                clip,
                path,
                "m_LocalPosition.z");
            AnimationCurve rotationX = RequireTransformCurve(
                clip,
                path,
                "m_LocalRotation.x");
            AnimationCurve rotationY = RequireTransformCurve(
                clip,
                path,
                "m_LocalRotation.y");
            AnimationCurve rotationZ = RequireTransformCurve(
                clip,
                path,
                "m_LocalRotation.z");
            AnimationCurve rotationW = RequireTransformCurve(
                clip,
                path,
                "m_LocalRotation.w");
            Vector3 startPosition = new Vector3(
                positionX.Evaluate(holdStartTime),
                positionY.Evaluate(holdStartTime),
                positionZ.Evaluate(holdStartTime));
            Quaternion startRotation = new Quaternion(
                rotationX.Evaluate(holdStartTime),
                rotationY.Evaluate(holdStartTime),
                rotationZ.Evaluate(holdStartTime),
                rotationW.Evaluate(holdStartTime)).normalized;
            positionDifferenceMax = 0f;
            rotationDifferenceMax = 0f;
            int intervals = Mathf.Max(
                1,
                Mathf.RoundToInt(
                    (holdEndTime - holdStartTime) * clip.frameRate));
            for (int frame = 1; frame <= intervals; frame++)
            {
                float time = Mathf.Lerp(
                    holdStartTime,
                    holdEndTime,
                    frame / (float)intervals);
                Vector3 position = new Vector3(
                    positionX.Evaluate(time),
                    positionY.Evaluate(time),
                    positionZ.Evaluate(time));
                Quaternion rotation = new Quaternion(
                    rotationX.Evaluate(time),
                    rotationY.Evaluate(time),
                    rotationZ.Evaluate(time),
                    rotationW.Evaluate(time)).normalized;
                positionDifferenceMax = Mathf.Max(
                    positionDifferenceMax,
                    Vector3.Distance(startPosition, position));
                rotationDifferenceMax = Mathf.Max(
                    rotationDifferenceMax,
                    Quaternion.Angle(startRotation, rotation));
            }
        }

        private static AnimationCurve RequireTransformCurve(
            AnimationClip clip,
            string path,
            string propertyName)
        {
            EditorCurveBinding binding = AnimationUtility
                .GetCurveBindings(clip)
                .FirstOrDefault(candidate =>
                    candidate.type == typeof(Transform) &&
                    string.Equals(
                        candidate.path,
                        path,
                        StringComparison.Ordinal) &&
                    string.Equals(
                        candidate.propertyName,
                        propertyName,
                        StringComparison.Ordinal));
            AnimationCurve curve = AnimationUtility.GetEditorCurve(
                clip,
                binding);
            if (curve == null)
            {
                throw new InvalidOperationException(
                    "Required Stick_Attack_Forward correction curve is missing: " +
                    path + ":" + propertyName + ".");
            }

            return curve;
        }

        private static StickAttackForwardAttackingMetrics
            MeasureStickAttackForwardAttackingMetrics()
        {
            Scene scene = RequireScene();
            Transform target = RequireTarget(
                RequireLayout(scene),
                StickAttackForwardTargetName);
            AnimationClip source = LoadSingleEmbeddedClip(
                StickAttackForwardAttackingSourcePath,
                "stick attacking");
            AnimationClip generated = LoadClip(
                StickAttackForwardAttackingClipPath);
            Animator animator = RequireAnimator(target);
            AnimatorController controller =
                animator.runtimeAnimatorController as AnimatorController;
            if (controller == null)
            {
                throw new InvalidOperationException(
                    "Stick_Attack_Forward attacking controller is missing.");
            }

            MeasureStickAttackForwardAttackingBodyDifference(
                target,
                source,
                generated,
                out float sourcePositionDifference,
                out float sourceRotationDifference,
                out float holdPositionDifference,
                out float holdRotationDifference);
            MeasureStickAttackForwardAttackingFinalStick(
                target,
                source,
                generated,
                out float measuredTilt,
                out bool tiltsForward,
                out float rightHandToShaft,
                out float leftHandToShaft,
                out float holdStickPositionDifference,
                out float holdStickRotationDifference);
            string stickPath = RightHandPath + "/" + StickInstanceName;
            EditorCurveBinding[] generatedBindings =
                AnimationUtility.GetCurveBindings(generated);
            EditorCurveBinding[] stickPositionBindings = generatedBindings
                .Where(binding =>
                    string.Equals(
                        binding.path,
                        stickPath,
                        StringComparison.Ordinal) &&
                    binding.propertyName.StartsWith(
                        "m_LocalPosition.",
                        StringComparison.Ordinal))
                .ToArray();
            EditorCurveBinding[] stickRotationBindings = generatedBindings
                .Where(binding =>
                    string.Equals(
                        binding.path,
                        stickPath,
                        StringComparison.Ordinal) &&
                    binding.propertyName.StartsWith(
                        "m_LocalRotation.",
                        StringComparison.Ordinal))
                .ToArray();
            HashSet<EditorCurveBinding> sourceBindings =
                new HashSet<EditorCurveBinding>(
                    AnimationUtility.GetCurveBindings(source));
            EditorCurveBinding[] addedBindings = generatedBindings
                .Where(binding => !sourceBindings.Contains(binding))
                .ToArray();
            bool onlyStickTransformCurvesAdded =
                addedBindings.Length == 7 &&
                addedBindings.All(binding =>
                    string.Equals(
                        binding.path,
                        stickPath,
                        StringComparison.Ordinal) &&
                    (binding.propertyName.StartsWith(
                         "m_LocalPosition.",
                         StringComparison.Ordinal) ||
                     binding.propertyName.StartsWith(
                         "m_LocalRotation.",
                         StringComparison.Ordinal)));
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            StickAttackForwardAttackingMetrics metrics =
                new StickAttackForwardAttackingMetrics
                {
                    attackOriginalHash = HashFile(
                        StickAttackForwardAttackingOriginalPath),
                    attackSourceHash = HashFile(
                        StickAttackForwardAttackingSourcePath),
                    stickSourceHash = HashFile(StickSourceModelPath),
                    stickAssetHash = HashFile(StickAssetPath),
                    sourceEmbeddedTake = source.name,
                    sourceDurationSeconds = source.length,
                    sourceFrameRate = source.frameRate,
                    endHoldDurationSeconds = generated.length -
                        source.length,
                    generatedDurationSeconds = generated.length,
                    generatedFrameRate = generated.frameRate,
                    configuredFinalForwardTiltDegrees =
                        StickAttackForwardAttackingFinalForwardTiltDegrees,
                    measuredFinalForwardTiltDegrees = measuredTilt,
                    finalStickTiltsForward = tiltsForward,
                    sourceBodyPosePositionDifferenceMax =
                        sourcePositionDifference,
                    sourceBodyPoseRotationDifferenceDegreesMax =
                        sourceRotationDifference,
                    holdBodyPositionDifferenceMax = holdPositionDifference,
                    holdBodyRotationDifferenceDegreesMax =
                        holdRotationDifference,
                    endHoldStickPositionDifferenceMax =
                        holdStickPositionDifference,
                    endHoldStickRotationDifferenceDegreesMax =
                        holdStickRotationDifference,
                    finalRightHandToShaftMeters = rightHandToShaft,
                    finalLeftHandToShaftMeters = leftHandToShaft,
                    stickPositionCurveCount =
                        stickPositionBindings.Length,
                    stickRotationCurveCount =
                        stickRotationBindings.Length,
                    onlyStickTransformCurvesAdded =
                        onlyStickTransformCurvesAdded,
                    sourceEventsUnchanged = AnimationEventsExact(
                        source,
                        generated),
                    controllerUsesGeneratedClip =
                        StickAttackForwardAttackingControllerIsExact(
                            controller,
                            generated),
                    generatedClipLoops = settings.loopTime,
                    animatorSettingsCorrect = AnimatorMatches(
                        animator,
                        controller),
                    reviewContactSheetExists = File.Exists(
                        Path.GetFullPath(
                            StickAttackForwardAttackingReviewPath)),
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                string.Equals(
                    metrics.attackOriginalHash,
                    StickAttackForwardAttackingSourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.attackOriginalHash,
                    metrics.attackSourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.stickSourceHash,
                    metrics.stickAssetHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.sourceEmbeddedTake,
                    "mixamo.com",
                    StringComparison.Ordinal) &&
                Mathf.Abs(metrics.sourceFrameRate - 30f) <= 0.0001f &&
                Mathf.Abs(
                    metrics.endHoldDurationSeconds -
                    StickAttackForwardAttackingEndHoldSeconds) <=
                    0.0001f &&
                Mathf.Abs(
                    metrics.generatedDurationSeconds -
                    (metrics.sourceDurationSeconds +
                     StickAttackForwardAttackingEndHoldSeconds)) <=
                    0.0001f &&
                Mathf.Abs(
                    metrics.generatedFrameRate -
                    metrics.sourceFrameRate) <= 0.0001f &&
                Mathf.Abs(
                    metrics.measuredFinalForwardTiltDegrees -
                    StickAttackForwardAttackingFinalForwardTiltDegrees) <=
                    0.1f &&
                metrics.finalStickTiltsForward &&
                metrics.sourceBodyPosePositionDifferenceMax <=
                    PositionTolerance &&
                metrics.sourceBodyPoseRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.holdBodyPositionDifferenceMax <=
                    PositionTolerance &&
                metrics.holdBodyRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.endHoldStickPositionDifferenceMax <= 0.000001f &&
                metrics.endHoldStickRotationDifferenceDegreesMax <= 0.001f &&
                metrics.finalRightHandToShaftMeters <= 0.06f &&
                metrics.finalLeftHandToShaftMeters <= 0.06f &&
                metrics.stickPositionCurveCount == 3 &&
                metrics.stickRotationCurveCount == 4 &&
                metrics.onlyStickTransformCurvesAdded &&
                metrics.sourceEventsUnchanged &&
                metrics.controllerUsesGeneratedClip &&
                metrics.generatedClipLoops &&
                metrics.animatorSettingsCorrect &&
                metrics.reviewContactSheetExists;
            return metrics;
        }

        private static void MeasureStickAttackForwardAttackingBodyDifference(
            Transform template,
            AnimationClip source,
            AnimationClip generated,
            out float sourcePositionDifferenceMax,
            out float sourceRotationDifferenceMax,
            out float holdPositionDifferenceMax,
            out float holdRotationDifferenceMax)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject generatedObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            generatedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            DisableAnimators(generatedObject);
            string stickPath = RightHandPath + "/" + StickInstanceName;
            string[] paths = GetStickGripTwoHandArmaturePaths(
                    sourceObject.transform)
                .Where(path =>
                    !string.Equals(
                        path,
                        stickPath,
                        StringComparison.Ordinal) &&
                    !path.StartsWith(
                        stickPath + "/",
                        StringComparison.Ordinal))
                .ToArray();
            sourcePositionDifferenceMax = 0f;
            sourceRotationDifferenceMax = 0f;
            holdPositionDifferenceMax = 0f;
            holdRotationDifferenceMax = 0f;
            try
            {
                int sourceIntervals = Mathf.RoundToInt(
                    source.length * source.frameRate);
                for (int frame = 0; frame <= sourceIntervals; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / source.frameRate);
                    source.SampleAnimation(sourceObject, time);
                    generated.SampleAnimation(generatedObject, time);
                    MeasurePoseDifferenceForPaths(
                        CapturePose(sourceObject.transform),
                        CapturePose(generatedObject.transform),
                        paths,
                        out float positionDifference,
                        out float rotationDifference);
                    sourcePositionDifferenceMax = Mathf.Max(
                        sourcePositionDifferenceMax,
                        positionDifference);
                    sourceRotationDifferenceMax = Mathf.Max(
                        sourceRotationDifferenceMax,
                        rotationDifference);
                }

                source.SampleAnimation(sourceObject, source.length);
                PoseSnapshot finalSourcePose = CapturePose(
                    sourceObject.transform);
                int holdIntervals = Mathf.RoundToInt(
                    StickAttackForwardAttackingEndHoldSeconds *
                    generated.frameRate);
                for (int frame = 0; frame <= holdIntervals; frame++)
                {
                    float time = source.length +
                        frame / generated.frameRate;
                    generated.SampleAnimation(
                        generatedObject,
                        Mathf.Min(generated.length, time));
                    MeasurePoseDifferenceForPaths(
                        finalSourcePose,
                        CapturePose(generatedObject.transform),
                        paths,
                        out float positionDifference,
                        out float rotationDifference);
                    holdPositionDifferenceMax = Mathf.Max(
                        holdPositionDifferenceMax,
                        positionDifference);
                    holdRotationDifferenceMax = Mathf.Max(
                        holdRotationDifferenceMax,
                        rotationDifference);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(generatedObject);
            }
        }

        private static void MeasureStickAttackForwardAttackingFinalStick(
            Transform template,
            AnimationClip source,
            AnimationClip generated,
            out float measuredTiltDegrees,
            out bool tiltsForward,
            out float rightHandToShaft,
            out float leftHandToShaft,
            out float holdPositionDifferenceMax,
            out float holdRotationDifferenceMax)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                generated.SampleAnimation(workObject, source.length);
                StickGripPlacement placement = DescribeExistingStickGrip(root);
                Transform stick = placement.Instance;
                Vector3 holdLocalPosition = stick.localPosition;
                Quaternion holdLocalRotation = stick.localRotation;
                Vector3 direction = stick.TransformDirection(
                    placement.LongLocalAxis).normalized;
                if (Vector3.Dot(direction, root.up) < 0f)
                {
                    direction = -direction;
                }

                measuredTiltDegrees = Vector3.Angle(root.up, direction);
                tiltsForward = Vector3.Dot(direction, root.forward) > 0f;
                Vector3 shaftPoint = stick.TransformPoint(
                    placement.LocalGripPoint);
                Vector3 rightPalm = CalculateRightPalmSample(root).Center;
                Vector3 leftPalm = CalculateLeftPalmSample(root).Center;
                rightHandToShaft = DistancePointToLine(
                    rightPalm,
                    shaftPoint,
                    direction);
                leftHandToShaft = DistancePointToLine(
                    leftPalm,
                    shaftPoint,
                    direction);
                holdPositionDifferenceMax = 0f;
                holdRotationDifferenceMax = 0f;
                int holdIntervals = Mathf.RoundToInt(
                    StickAttackForwardAttackingEndHoldSeconds *
                    generated.frameRate);
                for (int frame = 1; frame <= holdIntervals; frame++)
                {
                    generated.SampleAnimation(
                        workObject,
                        source.length + frame / generated.frameRate);
                    stick = DescribeExistingStickGrip(root).Instance;
                    holdPositionDifferenceMax = Mathf.Max(
                        holdPositionDifferenceMax,
                        Vector3.Distance(
                            holdLocalPosition,
                            stick.localPosition));
                    holdRotationDifferenceMax = Mathf.Max(
                        holdRotationDifferenceMax,
                        Quaternion.Angle(
                            holdLocalRotation,
                            stick.localRotation));
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static float DistancePointToLine(
            Vector3 point,
            Vector3 linePoint,
            Vector3 lineDirection)
        {
            return Vector3.Cross(
                point - linePoint,
                lineDirection.normalized).magnitude;
        }

        private static bool AnimationEventsExact(
            AnimationClip source,
            AnimationClip generated)
        {
            AnimationEvent[] sourceEvents =
                AnimationUtility.GetAnimationEvents(source);
            AnimationEvent[] generatedEvents =
                AnimationUtility.GetAnimationEvents(generated);
            if (sourceEvents.Length != generatedEvents.Length)
            {
                return false;
            }

            for (int index = 0; index < sourceEvents.Length; index++)
            {
                AnimationEvent first = sourceEvents[index];
                AnimationEvent second = generatedEvents[index];
                if (Mathf.Abs(first.time - second.time) > 0.000001f ||
                    !string.Equals(
                        first.functionName,
                        second.functionName,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        first.stringParameter,
                        second.stringParameter,
                        StringComparison.Ordinal) ||
                    Mathf.Abs(
                        first.floatParameter -
                        second.floatParameter) > 0.000001f ||
                    first.intParameter != second.intParameter ||
                    first.objectReferenceParameter !=
                    second.objectReferenceParameter ||
                    first.messageOptions != second.messageOptions)
                {
                    return false;
                }
            }

            return true;
        }

        private static bool StickAttackForwardAttackingControllerIsExact(
            AnimatorController controller,
            AnimationClip clip)
        {
            if (controller.layers.Length != 1)
            {
                return false;
            }

            AnimatorStateMachine stateMachine =
                controller.layers[0].stateMachine;
            AnimatorState[] states = stateMachine.states
                .Select(child => child.state)
                .ToArray();
            return states.Length == 1 &&
                string.Equals(
                    states[0].name,
                    StickAttackForwardAttackingStateName,
                    StringComparison.Ordinal) &&
                stateMachine.defaultState == states[0] &&
                states[0].motion == clip &&
                Mathf.Abs(states[0].speed - 1f) <= 0.0001f &&
                !states[0].mirror &&
                Mathf.Abs(states[0].cycleOffset) <= 0.0001f;
        }

        private static void CaptureStickAttackForwardTrimDirectReview()
        {
            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(
                layout,
                StickAttackForwardTargetName);
            AnimationClip source = LoadSingleEmbeddedClip(
                StickAttackForwardSourcePath,
                "stick forward attack");
            AnimationClip trimmed = LoadClip(
                StickAttackForwardTrimmedClipPath);
            GameObject sourceObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            GameObject appliedObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            sourceObject.name = "StickAttackForwardSourceTrimReview";
            appliedObject.name = "StickAttackForwardAppliedTrimReview";
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            appliedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            DisableAnimators(appliedObject);
            const int columns = 30;
            List<List<byte[]>> rows = new List<List<byte[]>>();
            try
            {
                List<byte[]> sourceFront = new List<byte[]>();
                List<byte[]> sourceSide = new List<byte[]>();
                List<byte[]> appliedFront = new List<byte[]>();
                List<byte[]> appliedSide = new List<byte[]>();
                CaptureStickAttackForwardFrameRange(
                    sourceObject.transform,
                    source,
                    0,
                    StickAttackForwardStopFrame,
                    false,
                    sourceFront,
                    sourceSide);
                CaptureStickAttackForwardFrameRange(
                    appliedObject.transform,
                    trimmed,
                    0,
                    StickAttackForwardStopFrame,
                    false,
                    appliedFront,
                    appliedSide);
                AppendExactComparisonRows(
                    rows,
                    sourceFront,
                    appliedFront,
                    sourceSide,
                    appliedSide,
                    columns);

                int descentStart =
                    FindStickAttackForwardDescentStartFrame(
                        sourceObject.transform,
                        source);
                List<byte[]> sourceCloseFront = new List<byte[]>();
                List<byte[]> sourceCloseSide = new List<byte[]>();
                List<byte[]> appliedCloseFront = new List<byte[]>();
                List<byte[]> appliedCloseSide = new List<byte[]>();
                CaptureStickAttackForwardFrameRange(
                    sourceObject.transform,
                    source,
                    descentStart,
                    StickAttackForwardStopFrame,
                    true,
                    sourceCloseFront,
                    sourceCloseSide);
                CaptureStickAttackForwardFrameRange(
                    appliedObject.transform,
                    trimmed,
                    descentStart,
                    StickAttackForwardStopFrame,
                    true,
                    appliedCloseFront,
                    appliedCloseSide);
                rows.Add(CreatePaddedFrameRow(
                    sourceCloseFront,
                    0,
                    columns));
                rows.Add(CreatePaddedFrameRow(
                    appliedCloseFront,
                    0,
                    columns));
                rows.Add(CreatePaddedFrameRow(
                    sourceCloseSide,
                    0,
                    columns));
                rows.Add(CreatePaddedFrameRow(
                    appliedCloseSide,
                    0,
                    columns));

                int[] loopFrames =
                {
                    StickAttackForwardStopFrame - 2,
                    StickAttackForwardStopFrame - 1,
                    StickAttackForwardStopFrame,
                    0,
                    1,
                    2
                };
                List<byte[]> loopFront = new List<byte[]>();
                List<byte[]> loopSide = new List<byte[]>();
                CaptureStickAttackForwardSelectedFrames(
                    appliedObject.transform,
                    trimmed,
                    loopFrames,
                    loopFront,
                    loopSide);
                rows.Add(CreatePaddedFrameRow(loopFront, 0, columns));
                rows.Add(CreatePaddedFrameRow(loopSide, 0, columns));
                ComposeScaledRows(
                    rows,
                    StickAttackForwardTrimReviewPath,
                    160,
                    200);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(appliedObject);
            }
        }

        private static void CaptureStickAttackForwardFrameRange(
            Transform subject,
            AnimationClip clip,
            int startFrame,
            int endFrame,
            bool closeView,
            ICollection<byte[]> frontFrames,
            ICollection<byte[]> sideFrames)
        {
            using (CaptureEnvironment environment =
                   new CaptureEnvironment(subject))
            {
                for (int frame = startFrame; frame <= endFrame; frame++)
                {
                    float time = Mathf.Min(
                        StickAttackForwardStopTime,
                        frame / StickAttackForwardFrameRate);
                    clip.SampleAnimation(subject.gameObject, time);
                    if (closeView)
                    {
                        Transform hand = FindRequired(subject, RightHandPath);
                        StickGripPlacement stick = DescribeExistingStickGrip(
                            subject);
                        Vector3 center = Vector3.Lerp(
                            hand.position,
                            stick.Instance.TransformPoint(
                                stick.LocalBounds.center),
                            0.55f);
                        environment.ConfigureView(subject, center, 0.82f);
                    }
                    else
                    {
                        environment.ConfigureView(subject, 1.05f, 1.35f);
                    }

                    frontFrames.Add(environment.CaptureFront());
                    sideFrames.Add(environment.CaptureSide());
                }
            }
        }

        private static void CaptureStickAttackForwardSelectedFrames(
            Transform subject,
            AnimationClip clip,
            IEnumerable<int> frames,
            ICollection<byte[]> frontFrames,
            ICollection<byte[]> sideFrames)
        {
            using (CaptureEnvironment environment =
                   new CaptureEnvironment(subject))
            {
                foreach (int frame in frames)
                {
                    float time = Mathf.Clamp(
                        frame / StickAttackForwardFrameRate,
                        0f,
                        StickAttackForwardStopTime);
                    clip.SampleAnimation(subject.gameObject, time);
                    environment.ConfigureView(subject, 1.05f, 1.35f);
                    frontFrames.Add(environment.CaptureFront());
                    sideFrames.Add(environment.CaptureSide());
                }
            }
        }

        private static StickAttackForwardTrimMetrics
            MeasureStickAttackForwardTrimMetrics()
        {
            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(
                layout,
                StickAttackForwardTargetName);
            Transform carryTarget = RequireTarget(
                layout,
                StickCarryTargetName);
            AnimationClip source = LoadSingleEmbeddedClip(
                StickAttackForwardSourcePath,
                "stick forward attack");
            AnimationClip trimmed = LoadClip(
                StickAttackForwardTrimmedClipPath);
            Animator animator = RequireAnimator(target);
            AnimatorController controller =
                animator.runtimeAnimatorController as AnimatorController;
            if (controller == null)
            {
                throw new InvalidOperationException(
                    "Stick_Attack_Forward trimmed controller is missing.");
            }

            MeasureStickAttackForwardTrimBodyPoseDifference(
                target,
                source,
                trimmed,
                out float bodyPositionDifference,
                out float bodyRotationDifference);
            Quaternion carryRotation = DescribeExistingStickGrip(carryTarget)
                .Instance.localRotation;
            string stickPath = RightHandPath + "/" + StickInstanceName;
            EditorCurveBinding[] stickRotationBindings = AnimationUtility
                .GetCurveBindings(trimmed)
                .Where(binding =>
                    string.Equals(
                        binding.path,
                        stickPath,
                        StringComparison.Ordinal) &&
                    binding.propertyName.StartsWith(
                        "m_LocalRotation.",
                        StringComparison.Ordinal))
                .ToArray();
            Quaternion startRotation = EvaluateStickLocalRotation(
                trimmed,
                stickPath,
                0f,
                carryRotation);
            Quaternion stopRotation = EvaluateStickLocalRotation(
                trimmed,
                stickPath,
                StickAttackForwardStopTime,
                carryRotation);
            float peakRotation = 0f;
            for (int frame = 0;
                 frame <= StickAttackForwardStopFrame;
                 frame++)
            {
                Quaternion rotation = EvaluateStickLocalRotation(
                    trimmed,
                    stickPath,
                    frame / StickAttackForwardFrameRate,
                    carryRotation);
                peakRotation = Mathf.Max(
                    peakRotation,
                    Quaternion.Angle(carryRotation, rotation));
            }

            HashSet<EditorCurveBinding> sourceBindings =
                new HashSet<EditorCurveBinding>(
                    AnimationUtility.GetCurveBindings(source));
            EditorCurveBinding[] addedBindings = AnimationUtility
                .GetCurveBindings(trimmed)
                .Where(binding => !sourceBindings.Contains(binding))
                .ToArray();
            bool onlyStickRotationCurvesAdded =
                addedBindings.Length == 4 &&
                addedBindings.All(binding =>
                    string.Equals(
                        binding.path,
                        stickPath,
                        StringComparison.Ordinal) &&
                    binding.propertyName.StartsWith(
                        "m_LocalRotation.",
                        StringComparison.Ordinal));
            bool noKeysAfterStop = AnimationUtility
                .GetCurveBindings(trimmed)
                .All(binding => AnimationUtility.GetEditorCurve(trimmed, binding)
                    .keys.All(key =>
                        key.time <= StickAttackForwardStopTime + 0.0001f)) &&
                AnimationUtility.GetObjectReferenceCurveBindings(trimmed)
                    .All(binding => AnimationUtility
                        .GetObjectReferenceCurve(trimmed, binding)
                        .All(key =>
                            key.time <=
                            StickAttackForwardStopTime + 0.0001f)) &&
                AnimationUtility.GetAnimationEvents(trimmed)
                    .All(animationEvent =>
                        animationEvent.time <=
                        StickAttackForwardStopTime + 0.0001f);
            int descentStart = MeasureStickAttackForwardDescentStartFrame(
                target,
                source);
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(trimmed);
            StickAttackForwardTrimMetrics metrics =
                new StickAttackForwardTrimMetrics
                {
                    attackOriginalHash = HashFile(
                        StickAttackForwardOriginalPath),
                    attackSourceHash = HashFile(
                        StickAttackForwardSourcePath),
                    sourceEmbeddedTake = source.name,
                    sourceDurationSeconds = source.length,
                    sourceFrameRate = source.frameRate,
                    stopFrame = StickAttackForwardStopFrame,
                    stopTimeSeconds = StickAttackForwardStopTime,
                    removedDurationSeconds = source.length -
                        StickAttackForwardStopTime,
                    trimmedDurationSeconds = trimmed.length,
                    trimmedFrameRate = trimmed.frameRate,
                    rightHandDescentStartFrame = descentStart,
                    configuredPeakForwardTiltDegrees =
                        StickAttackForwardPeakForwardTiltDegrees,
                    measuredPeakStickRotationFromCarryDegrees = peakRotation,
                    startStickRotationFromCarryDegrees = Quaternion.Angle(
                        carryRotation,
                        startRotation),
                    stopStickRotationFromCarryDegrees = Quaternion.Angle(
                        carryRotation,
                        stopRotation),
                    sourceBodyPosePositionDifferenceMax =
                        bodyPositionDifference,
                    sourceBodyPoseRotationDifferenceDegreesMax =
                        bodyRotationDifference,
                    stickRotationCurveCount = stickRotationBindings.Length,
                    onlyStickRotationCurvesAdded =
                        onlyStickRotationCurvesAdded,
                    noKeysAfterStopTime = noKeysAfterStop,
                    controllerUsesTrimmedClip =
                        StickAttackForwardTrimControllerIsExact(
                            controller,
                            trimmed),
                    trimmedClipLoops = settings.loopTime,
                    animatorSettingsCorrect = AnimatorMatches(
                        animator,
                        controller),
                    reviewContactSheetExists = File.Exists(
                        Path.GetFullPath(
                            StickAttackForwardTrimReviewPath)),
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                string.Equals(
                    metrics.attackOriginalHash,
                    StickAttackForwardSourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.attackOriginalHash,
                    metrics.attackSourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.sourceEmbeddedTake,
                    "mixamo.com",
                    StringComparison.Ordinal) &&
                Mathf.Abs(
                    metrics.sourceFrameRate -
                    StickAttackForwardFrameRate) <= 0.0001f &&
                metrics.stopFrame == StickAttackForwardStopFrame &&
                Mathf.Abs(
                    metrics.trimmedDurationSeconds -
                    StickAttackForwardStopTime) <= 0.0001f &&
                Mathf.Abs(
                    metrics.trimmedFrameRate -
                    StickAttackForwardFrameRate) <= 0.0001f &&
                metrics.rightHandDescentStartFrame <
                    StickAttackForwardStopFrame - 1 &&
                metrics.sourceBodyPosePositionDifferenceMax <=
                    PositionTolerance &&
                metrics.sourceBodyPoseRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.stickRotationCurveCount == 4 &&
                metrics.onlyStickRotationCurvesAdded &&
                metrics.noKeysAfterStopTime &&
                metrics.measuredPeakStickRotationFromCarryDegrees >= 20f &&
                metrics.measuredPeakStickRotationFromCarryDegrees <= 25f &&
                metrics.startStickRotationFromCarryDegrees <= 0.01f &&
                metrics.stopStickRotationFromCarryDegrees <= 0.01f &&
                metrics.controllerUsesTrimmedClip &&
                metrics.trimmedClipLoops &&
                metrics.animatorSettingsCorrect &&
                metrics.reviewContactSheetExists;
            return metrics;
        }

        private static int MeasureStickAttackForwardDescentStartFrame(
            Transform template,
            AnimationClip source)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                return FindStickAttackForwardDescentStartFrame(
                    workObject.transform,
                    source);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void MeasureStickAttackForwardTrimBodyPoseDifference(
            Transform template,
            AnimationClip source,
            AnimationClip trimmed,
            out float positionDifferenceMax,
            out float rotationDifferenceMax)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject trimmedObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            trimmedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            DisableAnimators(trimmedObject);
            string stickPath = RightHandPath + "/" + StickInstanceName;
            string[] paths = GetStickGripTwoHandArmaturePaths(
                    sourceObject.transform)
                .Where(path =>
                    !string.Equals(
                        path,
                        stickPath,
                        StringComparison.Ordinal) &&
                    !path.StartsWith(
                        stickPath + "/",
                        StringComparison.Ordinal))
                .ToArray();
            positionDifferenceMax = 0f;
            rotationDifferenceMax = 0f;
            try
            {
                for (int frame = 0;
                     frame <= StickAttackForwardStopFrame;
                     frame++)
                {
                    float time = frame / StickAttackForwardFrameRate;
                    source.SampleAnimation(sourceObject, time);
                    trimmed.SampleAnimation(trimmedObject, time);
                    MeasurePoseDifferenceForPaths(
                        CapturePose(sourceObject.transform),
                        CapturePose(trimmedObject.transform),
                        paths,
                        out float positionDifference,
                        out float rotationDifference);
                    positionDifferenceMax = Mathf.Max(
                        positionDifferenceMax,
                        positionDifference);
                    rotationDifferenceMax = Mathf.Max(
                        rotationDifferenceMax,
                        rotationDifference);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(trimmedObject);
            }
        }

        private static Quaternion EvaluateStickLocalRotation(
            AnimationClip clip,
            string path,
            float time,
            Quaternion fallback)
        {
            AnimationCurve x = AnimationUtility.GetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    path,
                    typeof(Transform),
                    "m_LocalRotation.x"));
            AnimationCurve y = AnimationUtility.GetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    path,
                    typeof(Transform),
                    "m_LocalRotation.y"));
            AnimationCurve z = AnimationUtility.GetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    path,
                    typeof(Transform),
                    "m_LocalRotation.z"));
            AnimationCurve w = AnimationUtility.GetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    path,
                    typeof(Transform),
                    "m_LocalRotation.w"));
            if (x == null || y == null || z == null || w == null)
            {
                return fallback;
            }

            return new Quaternion(
                x.Evaluate(time),
                y.Evaluate(time),
                z.Evaluate(time),
                w.Evaluate(time)).normalized;
        }

        private static bool StickAttackForwardTrimControllerIsExact(
            AnimatorController controller,
            AnimationClip clip)
        {
            if (controller.layers.Length != 1)
            {
                return false;
            }

            AnimatorStateMachine stateMachine =
                controller.layers[0].stateMachine;
            AnimatorState[] states = stateMachine.states
                .Select(child => child.state)
                .ToArray();
            return states.Length == 1 &&
                string.Equals(
                    states[0].name,
                    StickAttackForwardTrimmedStateName,
                    StringComparison.Ordinal) &&
                stateMachine.defaultState == states[0] &&
                states[0].motion == clip &&
                Mathf.Abs(states[0].speed - 1f) <= 0.0001f &&
                !states[0].mirror &&
                Mathf.Abs(states[0].cycleOffset) <= 0.0001f;
        }

        private static void CaptureStickAttackForwardAndGripOneHandDirectReview()
        {
            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform attackTarget = RequireTarget(
                layout,
                StickAttackForwardTargetName);
            Transform oneHandTarget = RequireTarget(
                layout,
                StickGripOneHandTargetName);
            Animator attackAnimator = RequireAnimator(attackTarget);
            Animator oneHandAnimator = RequireAnimator(oneHandTarget);
            AnimationClip attackClip = LoadSingleEmbeddedClip(
                StickAttackForwardSourcePath,
                "stick forward attack");
            AnimationClip twoHandAttackReady = LoadClip(
                StickGripTwoHandAdjustedAttackReadyClipPath);
            AnimationClip twoHandTransition = LoadClip(
                StickGripTwoHandTransitionClipPath);
            AnimationClip twoHandCarry = LoadClip(
                StickGripTwoHandCarryClipPath);
            const int columns = 40;
            const float reviewFrameRate = 30f;
            int attackIntervals = Mathf.Max(
                1,
                Mathf.CeilToInt(attackClip.length * reviewFrameRate));
            int reverseIntervals = Mathf.RoundToInt(
                StickGripTwoHandSequenceDurationSeconds * reviewFrameRate);
            GameObject attackSourceObject = UnityEngine.Object.Instantiate(
                attackTarget.gameObject);
            GameObject reverseSourceObject = UnityEngine.Object.Instantiate(
                oneHandTarget.gameObject);
            attackSourceObject.name = "StickAttackForwardExactSourceReview";
            reverseSourceObject.name = "StickGripOneHandReverseSourceReview";
            attackSourceObject.hideFlags = HideFlags.HideAndDontSave;
            reverseSourceObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(attackSourceObject);
            DisableAnimators(reverseSourceObject);
            List<List<byte[]>> rows = new List<List<byte[]>>();
            try
            {
                List<byte[]> attackSourceFront = new List<byte[]>();
                List<byte[]> attackSourceSide = new List<byte[]>();
                List<byte[]> attackAppliedFront = new List<byte[]>();
                List<byte[]> attackAppliedSide = new List<byte[]>();
                CaptureExactSequenceFrames(
                    attackSourceObject.transform,
                    attackIntervals,
                    attackClip.length,
                    time => attackClip.SampleAnimation(
                        attackSourceObject,
                        time),
                    attackSourceFront,
                    attackSourceSide);
                CaptureExactSequenceFrames(
                    attackTarget,
                    attackIntervals,
                    attackClip.length,
                    time => SampleAnimator(
                        attackAnimator,
                        StickAttackForwardStateName,
                        attackClip.length <= 0f
                            ? 0f
                            : time / attackClip.length),
                    attackAppliedFront,
                    attackAppliedSide);
                AppendExactComparisonRows(
                    rows,
                    attackSourceFront,
                    attackAppliedFront,
                    attackSourceSide,
                    attackAppliedSide,
                    columns);

                List<byte[]> reverseSourceFront = new List<byte[]>();
                List<byte[]> reverseSourceSide = new List<byte[]>();
                List<byte[]> reverseAppliedFront = new List<byte[]>();
                List<byte[]> reverseAppliedSide = new List<byte[]>();
                CaptureExactSequenceFrames(
                    reverseSourceObject.transform,
                    reverseIntervals,
                    StickGripTwoHandSequenceDurationSeconds,
                    time => SampleCurrentStickGripTwoHandClipsExact(
                        reverseSourceObject,
                        twoHandCarry,
                        twoHandTransition,
                        twoHandAttackReady,
                        StickGripTwoHandSequenceDurationSeconds - time),
                    reverseSourceFront,
                    reverseSourceSide);
                CaptureExactSequenceFrames(
                    oneHandTarget,
                    reverseIntervals,
                    StickGripTwoHandSequenceDurationSeconds,
                    time => SampleStickGripOneHandReverseSequence(
                        oneHandAnimator,
                        time),
                    reverseAppliedFront,
                    reverseAppliedSide);
                AppendExactComparisonRows(
                    rows,
                    reverseSourceFront,
                    reverseAppliedFront,
                    reverseSourceSide,
                    reverseAppliedSide,
                    columns);
                ComposeScaledRows(
                    rows,
                    StickAttackForwardGripOneHandReviewPath,
                    200,
                    250);
            }
            finally
            {
                attackAnimator.Rebind();
                attackAnimator.Update(0f);
                oneHandAnimator.Rebind();
                oneHandAnimator.Update(0f);
                UnityEngine.Object.DestroyImmediate(attackSourceObject);
                UnityEngine.Object.DestroyImmediate(reverseSourceObject);
            }
        }

        private static void CaptureExactSequenceFrames(
            Transform subject,
            int frameIntervals,
            float duration,
            Action<float> sample,
            ICollection<byte[]> frontFrames,
            ICollection<byte[]> sideFrames)
        {
            using (CaptureEnvironment environment =
                   new CaptureEnvironment(subject))
            {
                for (int frame = 0; frame <= frameIntervals; frame++)
                {
                    float time = Mathf.Min(
                        duration,
                        frame / 30f);
                    sample(time);
                    environment.ConfigureView(subject, 1.05f, 1.35f);
                    frontFrames.Add(environment.CaptureFront());
                    sideFrames.Add(environment.CaptureSide());
                }
            }
        }

        private static void AppendExactComparisonRows(
            ICollection<List<byte[]>> outputRows,
            IReadOnlyList<byte[]> referenceFront,
            IReadOnlyList<byte[]> appliedFront,
            IReadOnlyList<byte[]> referenceSide,
            IReadOnlyList<byte[]> appliedSide,
            int columns)
        {
            if (referenceFront.Count == 0 ||
                referenceFront.Count != appliedFront.Count ||
                referenceFront.Count != referenceSide.Count ||
                referenceFront.Count != appliedSide.Count)
            {
                throw new InvalidOperationException(
                    "Exact stick comparison frame counts differ.");
            }

            int pageCount = Mathf.CeilToInt(
                referenceFront.Count / (float)columns);
            for (int page = 0; page < pageCount; page++)
            {
                int start = page * columns;
                outputRows.Add(CreatePaddedFrameRow(
                    referenceFront,
                    start,
                    columns));
                outputRows.Add(CreatePaddedFrameRow(
                    appliedFront,
                    start,
                    columns));
                outputRows.Add(CreatePaddedFrameRow(
                    referenceSide,
                    start,
                    columns));
                outputRows.Add(CreatePaddedFrameRow(
                    appliedSide,
                    start,
                    columns));
            }
        }

        private static List<byte[]> CreatePaddedFrameRow(
            IReadOnlyList<byte[]> frames,
            int start,
            int columns)
        {
            List<byte[]> row = frames
                .Skip(start)
                .Take(columns)
                .ToList();
            while (row.Count < columns)
            {
                row.Add(row[row.Count - 1]);
            }

            return row;
        }

        private static void ComposeScaledRows(
            IReadOnlyList<List<byte[]>> rows,
            string outputPath,
            int panelWidth,
            int panelHeight)
        {
            if (rows.Count == 0 ||
                rows.Any(row => row.Count != rows[0].Count) ||
                panelWidth <= 0 ||
                panelHeight <= 0)
            {
                throw new InvalidOperationException(
                    "Scaled stick comparison rows are invalid.");
            }

            int columns = rows[0].Count;
            Texture2D composite = new Texture2D(
                panelWidth * columns,
                panelHeight * rows.Count,
                TextureFormat.RGB24,
                false);
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                for (int row = 0; row < rows.Count; row++)
                {
                    for (int column = 0; column < columns; column++)
                    {
                        Texture2D source = new Texture2D(
                            CaptureWidth,
                            CaptureHeight,
                            TextureFormat.RGB24,
                            false);
                        RenderTexture scaled = RenderTexture.GetTemporary(
                            panelWidth,
                            panelHeight,
                            0,
                            RenderTextureFormat.ARGB32);
                        Texture2D panel = new Texture2D(
                            panelWidth,
                            panelHeight,
                            TextureFormat.RGB24,
                            false);
                        try
                        {
                            if (!source.LoadImage(rows[row][column]))
                            {
                                throw new InvalidOperationException(
                                    "Scaled stick comparison frame could not be decoded.");
                            }

                            scaled.filterMode = FilterMode.Bilinear;
                            Graphics.Blit(source, scaled);
                            RenderTexture.active = scaled;
                            panel.ReadPixels(
                                new Rect(0f, 0f, panelWidth, panelHeight),
                                0,
                                0,
                                false);
                            panel.Apply(false, false);
                            composite.SetPixels(
                                column * panelWidth,
                                (rows.Count - row - 1) * panelHeight,
                                panelWidth,
                                panelHeight,
                                panel.GetPixels());
                        }
                        finally
                        {
                            UnityEngine.Object.DestroyImmediate(source);
                            UnityEngine.Object.DestroyImmediate(panel);
                            RenderTexture.ReleaseTemporary(scaled);
                        }
                    }
                }

                composite.Apply(false, false);
                string absoluteOutput = Path.GetFullPath(outputPath);
                Directory.CreateDirectory(
                    Path.GetDirectoryName(absoluteOutput) ??
                    throw new InvalidOperationException(
                        "Scaled stick comparison output directory is unavailable."));
                File.WriteAllBytes(absoluteOutput, composite.EncodeToPNG());
            }
            finally
            {
                RenderTexture.active = previousActive;
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void SampleCurrentStickGripTwoHandClipsExact(
            GameObject target,
            AnimationClip carryClip,
            AnimationClip transitionClip,
            AnimationClip attackReadyClip,
            float sequenceTime)
        {
            float time = Mathf.Clamp(
                sequenceTime,
                0f,
                StickGripTwoHandSequenceDurationSeconds);
            if (time < StickGripTwoHandCarryDurationSeconds)
            {
                carryClip.SampleAnimation(target, time);
                return;
            }

            if (time <
                StickGripTwoHandCarryDurationSeconds +
                StickGripTwoHandTransitionDurationSeconds)
            {
                transitionClip.SampleAnimation(
                    target,
                    time - StickGripTwoHandCarryDurationSeconds);
                return;
            }

            attackReadyClip.SampleAnimation(
                target,
                time - StickGripTwoHandCarryDurationSeconds -
                StickGripTwoHandTransitionDurationSeconds);
        }

        private static void SampleStickGripOneHandReverseSequence(
            Animator animator,
            float sequenceTime)
        {
            float time = Mathf.Clamp(
                sequenceTime,
                0f,
                StickGripTwoHandSequenceDurationSeconds);
            if (time <= StickGripTwoHandAttackReadyDurationSeconds)
            {
                SampleAnimator(
                    animator,
                    StickGripOneHandAttackReadyReverseStateName,
                    time / StickGripTwoHandAttackReadyDurationSeconds);
                return;
            }

            time -= StickGripTwoHandAttackReadyDurationSeconds;
            if (time <= StickGripTwoHandTransitionDurationSeconds)
            {
                SampleAnimator(
                    animator,
                    StickGripOneHandTransitionReverseStateName,
                    time / StickGripTwoHandTransitionDurationSeconds);
                return;
            }

            time -= StickGripTwoHandTransitionDurationSeconds;
            SampleAnimator(
                animator,
                StickGripOneHandCarryReverseStateName,
                time / StickGripTwoHandCarryDurationSeconds);
        }

        private static StickAttackForwardGripOneHandMetrics
            MeasureStickAttackForwardAndGripOneHandMetrics()
        {
            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp changed after the stick attack and reverse apply.");
            }

            Transform layout = RequireLayout(scene);
            Transform stickCarryTarget = RequireTarget(
                layout,
                StickCarryTargetName);
            Transform attackTarget = RequireTarget(
                layout,
                StickAttackForwardTargetName);
            Transform oneHandTarget = RequireTarget(
                layout,
                StickGripOneHandTargetName);
            Animator attackAnimator = RequireAnimator(attackTarget);
            Animator reverseAnimator = RequireAnimator(oneHandTarget);
            AnimationClip attackClip = LoadSingleEmbeddedClip(
                StickAttackForwardSourcePath,
                "stick forward attack");
            AnimationClip twoHandAttackReady = LoadClip(
                StickGripTwoHandAdjustedAttackReadyClipPath);
            AnimationClip twoHandTransition = LoadClip(
                StickGripTwoHandTransitionClipPath);
            AnimationClip twoHandCarry = LoadClip(
                StickGripTwoHandCarryClipPath);
            AnimationClip reversedAttack = LoadClip(
                StickGripOneHandAttackReadyReverseClipPath);
            AnimationClip reversedTransition = LoadClip(
                StickGripOneHandTransitionReverseClipPath);
            AnimationClip reversedCarry = LoadClip(
                StickGripOneHandCarryReverseClipPath);
            AnimatorController attackController =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    StickAttackForwardControllerPath) ??
                throw new InvalidOperationException(
                    "Stick_Attack_Forward controller is missing.");
            AnimatorController reverseController =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    StickGripOneHandControllerPath) ??
                throw new InvalidOperationException(
                    "Stick_Grip_OneHand controller is missing.");

            MeasureStickAttackForwardPoseDifference(
                attackTarget,
                attackController,
                attackClip,
                out float attackPositionDifference,
                out float attackRotationDifference);
            MeasureStickGripOneHandReversePoseDifference(
                oneHandTarget,
                twoHandCarry,
                twoHandTransition,
                twoHandAttackReady,
                reversedAttack,
                reversedTransition,
                reversedCarry,
                out float reversePositionDifference,
                out float reverseRotationDifference,
                out string reverseMaximumRotationPath,
                out float reverseMaximumRotationTime);
            StickAttackForwardGripOneHandMetrics metrics =
                new StickAttackForwardGripOneHandMetrics
                {
                    stickSourceHash = HashFile(StickSourceModelPath),
                    stickAssetHash = HashFile(StickAssetPath),
                    attackOriginalHash = HashFile(
                        StickAttackForwardOriginalPath),
                    attackSourceHash = HashFile(
                        StickAttackForwardSourcePath),
                    attackEmbeddedTake = attackClip.name,
                    attackDurationSeconds = attackClip.length,
                    attackFrameRate = attackClip.frameRate,
                    attackControllerUsesExactEmbeddedTake = StateUsesClip(
                        attackController,
                        StickAttackForwardStateName,
                        attackClip),
                    attackEmbeddedTakeLoops = AnimationUtility
                        .GetAnimationClipSettings(attackClip).loopTime,
                    attackPosePositionDifferenceMax =
                        attackPositionDifference,
                    attackPoseRotationDifferenceDegreesMax =
                        attackRotationDifference,
                    reversedAttackDurationSeconds = reversedAttack.length,
                    reversedTransitionDurationSeconds =
                        reversedTransition.length,
                    reversedCarryDurationSeconds = reversedCarry.length,
                    reversedSequenceDurationSeconds =
                        reversedAttack.length + reversedTransition.length +
                        reversedCarry.length,
                    reversePosePositionDifferenceMax =
                        reversePositionDifference,
                    reversePoseRotationDifferenceDegreesMax =
                        reverseRotationDifference,
                    reverseMaximumRotationPath =
                        reverseMaximumRotationPath,
                    reverseMaximumRotationTimeSeconds =
                        reverseMaximumRotationTime,
                    reverseControllerSequenceExact =
                        StickGripOneHandControllerIsExact(
                            reverseController,
                            reversedAttack,
                            reversedTransition,
                            reversedCarry),
                    attackAnimatorSettingsCorrect = AnimatorMatches(
                        attackAnimator,
                        attackController),
                    reverseAnimatorSettingsCorrect = AnimatorMatches(
                        reverseAnimator,
                        reverseController),
                    attackStickTransformExact = StickTransformMatchesCarry(
                        stickCarryTarget,
                        attackTarget),
                    reverseStickTransformExact = StickTransformMatchesCarry(
                        stickCarryTarget,
                        oneHandTarget),
                    reviewContactSheetExists = File.Exists(
                        Path.GetFullPath(
                            StickAttackForwardGripOneHandReviewPath)),
                    validationPriority =
                        "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
                };
            metrics.passedNumericChecks =
                string.Equals(
                    metrics.stickSourceHash,
                    metrics.stickAssetHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.attackOriginalHash,
                    StickAttackForwardSourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.attackOriginalHash,
                    metrics.attackSourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                metrics.attackControllerUsesExactEmbeddedTake &&
                metrics.attackEmbeddedTakeLoops &&
                metrics.attackPosePositionDifferenceMax <=
                    PositionTolerance &&
                metrics.attackPoseRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                Mathf.Abs(
                    metrics.reversedAttackDurationSeconds -
                    StickGripTwoHandAttackReadyDurationSeconds) <= 0.0001f &&
                Mathf.Abs(
                    metrics.reversedTransitionDurationSeconds -
                    StickGripTwoHandTransitionDurationSeconds) <= 0.0001f &&
                Mathf.Abs(
                    metrics.reversedCarryDurationSeconds -
                    StickGripTwoHandCarryDurationSeconds) <= 0.0001f &&
                Mathf.Abs(
                    metrics.reversedSequenceDurationSeconds -
                    StickGripTwoHandSequenceDurationSeconds) <= 0.0001f &&
                metrics.reversePosePositionDifferenceMax <=
                    PositionTolerance &&
                metrics.reversePoseRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.reverseControllerSequenceExact &&
                metrics.attackAnimatorSettingsCorrect &&
                metrics.reverseAnimatorSettingsCorrect &&
                metrics.attackStickTransformExact &&
                metrics.reverseStickTransformExact &&
                metrics.reviewContactSheetExists;
            return metrics;
        }

        private static void MeasureStickAttackForwardPoseDifference(
            Transform template,
            AnimatorController controller,
            AnimationClip source,
            out float positionDifferenceMax,
            out float rotationDifferenceMax)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject appliedObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            appliedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            Animator appliedAnimator = RequireAnimator(
                appliedObject.transform);
            appliedAnimator.runtimeAnimatorController = controller;
            string[] paths = GetStickGripTwoHandArmaturePaths(
                sourceObject.transform);
            positionDifferenceMax = 0f;
            rotationDifferenceMax = 0f;
            try
            {
                int frameIntervals = Mathf.Max(
                    1,
                    Mathf.CeilToInt(source.length * 30f));
                for (int frame = 0; frame <= frameIntervals; frame++)
                {
                    float time = Mathf.Min(source.length, frame / 30f);
                    source.SampleAnimation(sourceObject, time);
                    SampleAnimator(
                        appliedAnimator,
                        StickAttackForwardStateName,
                        source.length <= 0f ? 0f : time / source.length);
                    MeasurePoseDifferenceForPaths(
                        CapturePose(sourceObject.transform),
                        CapturePose(appliedObject.transform),
                        paths,
                        out float positionDifference,
                        out float rotationDifference);
                    positionDifferenceMax = Mathf.Max(
                        positionDifferenceMax,
                        positionDifference);
                    rotationDifferenceMax = Mathf.Max(
                        rotationDifferenceMax,
                        rotationDifference);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(appliedObject);
            }
        }

        private static void MeasureStickGripOneHandReversePoseDifference(
            Transform template,
            AnimationClip sourceCarry,
            AnimationClip sourceTransition,
            AnimationClip sourceAttackReady,
            AnimationClip reversedAttackReady,
            AnimationClip reversedTransition,
            AnimationClip reversedCarry,
            out float positionDifferenceMax,
            out float rotationDifferenceMax,
            out string maximumRotationPath,
            out float maximumRotationTime)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject reversedObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            reversedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            DisableAnimators(reversedObject);
            string[] paths = GetStickGripTwoHandArmaturePaths(
                sourceObject.transform);
            positionDifferenceMax = 0f;
            rotationDifferenceMax = 0f;
            maximumRotationPath = string.Empty;
            maximumRotationTime = 0f;
            try
            {
                int frameIntervals = Mathf.RoundToInt(
                    StickGripTwoHandSequenceDurationSeconds * 30f);
                for (int frame = 0; frame <= frameIntervals; frame++)
                {
                    float reversedTime = frame / 30f;
                    SampleCurrentStickGripTwoHandClipsExact(
                        sourceObject,
                        sourceCarry,
                        sourceTransition,
                        sourceAttackReady,
                        StickGripTwoHandSequenceDurationSeconds -
                            reversedTime);
                    SampleStickGripOneHandReversedClipsExact(
                        reversedObject,
                        reversedAttackReady,
                        reversedTransition,
                        reversedCarry,
                        reversedTime);
                    PoseSnapshot sourcePose = CapturePose(
                        sourceObject.transform);
                    PoseSnapshot reversedPose = CapturePose(
                        reversedObject.transform);
                    foreach (string path in paths)
                    {
                        float positionDifference = Vector3.Distance(
                            sourcePose.Positions[path],
                            reversedPose.Positions[path]);
                        float rotationDifference = Quaternion.Angle(
                            sourcePose.Rotations[path],
                            reversedPose.Rotations[path]);
                        positionDifferenceMax = Mathf.Max(
                            positionDifferenceMax,
                            positionDifference);
                        if (rotationDifference > rotationDifferenceMax)
                        {
                            rotationDifferenceMax = rotationDifference;
                            maximumRotationPath = path;
                            maximumRotationTime = reversedTime;
                        }
                    }
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(reversedObject);
            }
        }

        private static void SampleStickGripOneHandReversedClipsExact(
            GameObject target,
            AnimationClip attackReverse,
            AnimationClip transitionReverse,
            AnimationClip carryReverse,
            float sequenceTime)
        {
            float time = Mathf.Clamp(
                sequenceTime,
                0f,
                StickGripTwoHandSequenceDurationSeconds);
            if (time <= StickGripTwoHandAttackReadyDurationSeconds)
            {
                attackReverse.SampleAnimation(target, time);
                return;
            }

            time -= StickGripTwoHandAttackReadyDurationSeconds;
            if (time <= StickGripTwoHandTransitionDurationSeconds)
            {
                transitionReverse.SampleAnimation(target, time);
                return;
            }

            time -= StickGripTwoHandTransitionDurationSeconds;
            carryReverse.SampleAnimation(target, time);
        }

        private static bool StickTransformMatchesCarry(
            Transform stickCarryTarget,
            Transform target)
        {
            StickGripPlacement source = DescribeExistingStickGrip(
                stickCarryTarget);
            StickGripPlacement applied = DescribeExistingStickGrip(target);
            return applied.Instance.parent == FindRequired(target, RightHandPath) &&
                Vector3.Distance(
                    source.Instance.localPosition,
                    applied.Instance.localPosition) <= 0.000001f &&
                Quaternion.Angle(
                    source.Instance.localRotation,
                    applied.Instance.localRotation) <= 0.0001f &&
                Vector3.Distance(
                    source.Instance.localScale,
                    applied.Instance.localScale) <= 0.000001f;
        }

        private static bool StickGripOneHandControllerIsExact(
            AnimatorController controller,
            AnimationClip attackReverse,
            AnimationClip transitionReverse,
            AnimationClip carryReverse)
        {
            if (controller.layers.Length != 1)
            {
                return false;
            }

            AnimatorStateMachine stateMachine =
                controller.layers[0].stateMachine;
            Dictionary<string, AnimatorState> states = stateMachine.states
                .Select(child => child.state)
                .ToDictionary(state => state.name, StringComparer.Ordinal);
            if (states.Count != 3 ||
                !states.TryGetValue(
                    StickGripOneHandAttackReadyReverseStateName,
                    out AnimatorState attackState) ||
                !states.TryGetValue(
                    StickGripOneHandTransitionReverseStateName,
                    out AnimatorState transitionState) ||
                !states.TryGetValue(
                    StickGripOneHandCarryReverseStateName,
                    out AnimatorState carryState))
            {
                return false;
            }

            return stateMachine.defaultState == attackState &&
                StickGripTwoHandStateIsExact(
                    attackState,
                    attackReverse) &&
                StickGripTwoHandStateIsExact(
                    transitionState,
                    transitionReverse) &&
                StickGripTwoHandStateIsExact(carryState, carryReverse) &&
                StickGripTwoHandTransitionIsExact(
                    attackState,
                    transitionState,
                    1f) &&
                StickGripTwoHandTransitionIsExact(
                    transitionState,
                    carryState,
                    1f) &&
                StickGripTwoHandTransitionIsExact(
                    carryState,
                    attackState,
                    1f);
        }

        private static void CaptureStickGripTwoHandDirectReview()
        {
            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, StickGripTwoHandTargetName);
            Animator targetAnimator = RequireAnimator(target);
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    StickGripTwoHandControllerPath) ??
                throw new InvalidOperationException(
                    "Stick_Grip_TwoHand controller is missing for direct review.");
            if (!AnimatorMatches(targetAnimator, controller))
            {
                throw new InvalidOperationException(
                    "Stick_Grip_TwoHand does not use the applied controller.");
            }

            AnimationClip adjustedAttackReadyClip = LoadClip(
                StickGripTwoHandAdjustedAttackReadyClipPath);
            const int sequenceFrames = 45;
            const int columns = 10;
            int pageCount = Mathf.CeilToInt(sequenceFrames / (float)columns);
            List<List<byte[]>> rows = Enumerable.Range(0, pageCount * 2)
                .Select(_ => new List<byte[]>())
                .ToList();
            try
            {
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    for (int frame = 0; frame < sequenceFrames; frame++)
                    {
                        float sequenceTime =
                            StickGripTwoHandCarryDurationSeconds +
                            frame / 30f;
                        SampleStickGripTwoHandSequence(
                            targetAnimator,
                            adjustedAttackReadyClip,
                            sequenceTime);
                        Transform rightHand = FindRequired(
                            target,
                            RightHandPath);
                        Transform leftHand = FindRequired(
                            target,
                            LeftHandPath);
                        Vector3 center =
                            (rightHand.position + leftHand.position) * 0.5f;
                        environment.ConfigureView(target, center, 0.72f);
                        int rowOffset = frame / columns * 2;
                        rows[rowOffset].Add(environment.CaptureFront());
                        rows[rowOffset + 1].Add(environment.CaptureSide());
                    }
                }

                foreach (List<byte[]> row in rows)
                {
                    while (row.Count < columns)
                    {
                        row.Add(row[row.Count - 1]);
                    }
                }

                ComposeRows(rows, StickGripTwoHandReviewPath);
            }
            finally
            {
                targetAnimator.Rebind();
                targetAnimator.Update(0f);
            }
        }

        private static void CaptureStickGripTwoHandTwoViewRows(
            Transform subject,
            Action<float> sample,
            IReadOnlyList<List<byte[]>> rows,
            int rowOffset)
        {
            using (CaptureEnvironment environment = new CaptureEnvironment(subject))
            {
                const int phases = 8;
                for (int phaseIndex = 0; phaseIndex < phases; phaseIndex++)
                {
                    float phase = phaseIndex / (float)(phases - 1);
                    sample(phase);
                    environment.ConfigureView(subject, 1.05f, 1.35f);
                    rows[rowOffset].Add(environment.CaptureFront());
                    rows[rowOffset + 1].Add(environment.CaptureSide());
                }
            }
        }

        private static void CaptureStickGripTwoHandHandRows(
            Transform subject,
            Action<float> sample,
            IReadOnlyList<List<byte[]>> rows,
            int rowOffset)
        {
            using (CaptureEnvironment environment = new CaptureEnvironment(subject))
            {
                const int phases = 8;
                for (int phaseIndex = 0; phaseIndex < phases; phaseIndex++)
                {
                    float phase = phaseIndex / (float)(phases - 1);
                    sample(phase);
                    Transform rightHand = FindRequired(subject, RightHandPath);
                    Transform leftHand = FindRequired(subject, LeftHandPath);
                    Vector3 center = (rightHand.position + leftHand.position) * 0.5f;
                    environment.ConfigureView(subject, center, 0.72f);
                    rows[rowOffset].Add(environment.CaptureFront());
                    rows[rowOffset + 1].Add(environment.CaptureSide());
                }
            }
        }

        private static void SampleStickGripTwoHandSequence(
            Animator animator,
            AnimationClip attackReadyClip,
            float sequenceTime)
        {
            float time = Mathf.Repeat(
                sequenceTime,
                StickGripTwoHandSequenceDurationSeconds);
            if (time < StickGripTwoHandCarryDurationSeconds)
            {
                SampleAnimator(
                    animator,
                    StickGripTwoHandCarryStateName,
                    time / StickGripTwoHandCarryDurationSeconds);
                return;
            }

            time -= StickGripTwoHandCarryDurationSeconds;
            if (time < StickGripTwoHandTransitionDurationSeconds)
            {
                SampleAnimator(
                    animator,
                    StickGripTwoHandTransitionStateName,
                    time / StickGripTwoHandTransitionDurationSeconds);
                return;
            }

            time -= StickGripTwoHandTransitionDurationSeconds;
            SampleAnimator(
                animator,
                StickGripTwoHandAttackReadyStateName,
                time / attackReadyClip.length);
        }

        private static StickGripTwoHandMetrics
            MeasureStickGripTwoHandSequenceMetrics()
        {
            Scene scene = RequireScene();
            if (scene.isDirty)
            {
                throw new InvalidOperationException(
                    "CargoRunMvp changed after Stick_Grip_TwoHand apply.");
            }

            Transform layout = RequireLayout(scene);
            Transform sourceTarget = RequireTarget(layout, StickCarryTargetName);
            Transform target = RequireTarget(layout, StickGripTwoHandTargetName);
            Animator sourceAnimator = RequireAnimator(sourceTarget);
            Animator targetAnimator = RequireAnimator(target);
            AnimatorController sourceController =
                sourceAnimator.runtimeAnimatorController as AnimatorController ??
                throw new InvalidOperationException(
                    "Stick_Carry controller is unavailable for support checks.");
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    StickGripTwoHandControllerPath) ??
                throw new InvalidOperationException(
                    "Stick_Grip_TwoHand controller is missing.");
            AnimationClip baseClip = RequireDefaultLayerClip(
                sourceController,
                0,
                AlignmentBaseStateName);
            AnimationClip armClip = RequireDefaultLayerClip(
                sourceController,
                1,
                StickCarryStateName);
            AnimationClip carryClip = LoadClip(StickGripTwoHandCarryClipPath);
            AnimationClip transitionClip = LoadClip(
                StickGripTwoHandTransitionClipPath);
            AnimationClip attackReadyClip = LoadSingleEmbeddedClip(
                StickGripTwoHandSourcePath,
                "stick two-hand attack-ready");
            AnimationClip adjustedAttackReadyClip = LoadClip(
                StickGripTwoHandAdjustedAttackReadyClipPath);

            MeasureStickGripTwoHandCarryPoseDifference(
                target,
                sourceTarget,
                sourceAnimator,
                baseClip,
                armClip,
                carryClip,
                out float carryPositionDifference,
                out float carryRotationDifference);
            MeasureStickGripTwoHandTransitionEndpoints(
                target,
                carryClip,
                transitionClip,
                adjustedAttackReadyClip,
                out float transitionStartPositionDifference,
                out float transitionStartRotationDifference,
                out float transitionEndPositionDifference,
                out float transitionEndRotationDifference);

            MeasureStickGripTwoHandAdjustedAttackReady(
                target,
                attackReadyClip,
                adjustedAttackReadyClip,
                out float minimumLeftHandForwardSeparation,
                out float maximumLeftHandReachError,
                out float nonLeftPosePositionDifference,
                out float nonLeftPoseRotationDifference);
            string[] modifiedTransformPaths =
                GetStickGripTwoHandModifiedTransformPaths(
                    attackReadyClip,
                    adjustedAttackReadyClip);
            bool onlyLeftArmAndForeArmRotationCurvesChanged =
                AnimationMatchesExceptStickGripTwoHandArmRotations(
                    attackReadyClip,
                    adjustedAttackReadyClip) &&
                modifiedTransformPaths.Length > 0 &&
                modifiedTransformPaths.All(
                    IsStickGripTwoHandAdjustedArmPath);
            bool leftShoulderCurvesExact = StickGripTwoHandPathCurvesExact(
                attackReadyClip,
                adjustedAttackReadyClip,
                LeftShoulderPath);
            bool leftHandCurvesExact = StickGripTwoHandPathCurvesExact(
                attackReadyClip,
                adjustedAttackReadyClip,
                LeftHandPath);
            bool nonLeftPoseExact =
                nonLeftPosePositionDifference <= PositionTolerance &&
                nonLeftPoseRotationDifference <= RotationTolerance;

            bool controllerSequenceExact = StickGripTwoHandControllerIsExact(
                controller,
                carryClip,
                transitionClip,
                adjustedAttackReadyClip,
                out bool controllerUsesAdjustedAttackReadyClip);
            StickGripPlacement sourceStick = DescribeExistingStickGrip(
                sourceTarget);
            StickGripPlacement targetStick = DescribeExistingStickGrip(target);
            Transform targetHand = FindRequired(target, RightHandPath);
            bool stickTransformExact =
                targetStick.Instance.parent == targetHand &&
                Vector3.Distance(
                    sourceStick.Instance.localPosition,
                    targetStick.Instance.localPosition) <= 0.000001f &&
                Quaternion.Angle(
                    sourceStick.Instance.localRotation,
                    targetStick.Instance.localRotation) <= 0.0001f &&
                Vector3.Distance(
                    sourceStick.Instance.localScale,
                    targetStick.Instance.localScale) <= 0.000001f;
            StickGripTwoHandMetrics metrics = new StickGripTwoHandMetrics
            {
                sourceTarget = StickCarryTargetName,
                target = StickGripTwoHandTargetName,
                stickSourcePath = StickSourceModelPath,
                stickAssetPath = StickAssetPath,
                stickSourceHash = HashFile(StickSourceModelPath),
                stickAssetHash = HashFile(StickAssetPath),
                attackReadyOriginalPath = StickGripTwoHandOriginalPath,
                attackReadySourcePath = StickGripTwoHandSourcePath,
                attackReadyOriginalHash = HashFile(
                    StickGripTwoHandOriginalPath),
                attackReadySourceHash = HashFile(
                    StickGripTwoHandSourcePath),
                embeddedTake = attackReadyClip.name,
                embeddedTakeDurationSeconds = attackReadyClip.length,
                embeddedTakeFrameRate = attackReadyClip.frameRate,
                carryDurationSeconds = carryClip.length,
                transitionDurationSeconds = transitionClip.length,
                attackReadySegmentDurationSeconds =
                    StickGripTwoHandAttackReadyDurationSeconds,
                totalSequenceDurationSeconds =
                    StickGripTwoHandSequenceDurationSeconds,
                carryPosePositionDifferenceMax = carryPositionDifference,
                carryPoseRotationDifferenceDegreesMax = carryRotationDifference,
                transitionStartPositionDifferenceMax =
                    transitionStartPositionDifference,
                transitionStartRotationDifferenceDegreesMax =
                    transitionStartRotationDifference,
                transitionEndPositionDifferenceMax =
                    transitionEndPositionDifference,
                transitionEndRotationDifferenceDegreesMax =
                    transitionEndRotationDifference,
                adjustedAttackReadyClipPath =
                    StickGripTwoHandAdjustedAttackReadyClipPath,
                minimumLeftHandForwardSeparationMeters =
                    minimumLeftHandForwardSeparation,
                maximumLeftHandReachErrorMeters =
                    maximumLeftHandReachError,
                modifiedTransformPaths = modifiedTransformPaths,
                onlyLeftArmAndForeArmRotationCurvesChanged =
                    onlyLeftArmAndForeArmRotationCurvesChanged,
                leftShoulderCurvesExact = leftShoulderCurvesExact,
                leftHandCurvesExact = leftHandCurvesExact,
                nonLeftPoseExact = nonLeftPoseExact,
                nonLeftPosePositionDifferenceMax =
                    nonLeftPosePositionDifference,
                nonLeftPoseRotationDifferenceDegreesMax =
                    nonLeftPoseRotationDifference,
                controllerUsesAdjustedAttackReadyClip =
                    controllerUsesAdjustedAttackReadyClip,
                controllerSequenceExact = controllerSequenceExact,
                animatorSettingsCorrect = AnimatorMatches(
                    targetAnimator,
                    controller),
                stickParentPath = RightHandPath,
                sourceStickLocalPosition = sourceStick.Instance.localPosition,
                sourceStickLocalRotation = sourceStick.Instance.localRotation,
                sourceStickLocalScale = sourceStick.Instance.localScale,
                targetStickLocalPosition = targetStick.Instance.localPosition,
                targetStickLocalRotation = targetStick.Instance.localRotation,
                targetStickLocalScale = targetStick.Instance.localScale,
                stickParentAndLocalTransformExact = stickTransformExact,
                reviewContactSheetExists = File.Exists(
                    Path.GetFullPath(StickGripTwoHandReviewPath)),
                validationPriority =
                    "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
            };
            metrics.passedNumericChecks =
                string.Equals(
                    metrics.stickSourceHash,
                    metrics.stickAssetHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.attackReadyOriginalHash,
                    StickGripTwoHandSourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    metrics.attackReadyOriginalHash,
                    metrics.attackReadySourceHash,
                    StringComparison.OrdinalIgnoreCase) &&
                metrics.embeddedTakeDurationSeconds + 0.0001f >=
                    StickGripTwoHandAttackReadyDurationSeconds &&
                Mathf.Abs(
                    metrics.carryDurationSeconds -
                    StickGripTwoHandCarryDurationSeconds) <= 0.0001f &&
                Mathf.Abs(
                    metrics.transitionDurationSeconds -
                    StickGripTwoHandTransitionDurationSeconds) <= 0.0001f &&
                Mathf.Abs(
                    metrics.totalSequenceDurationSeconds - 2f) <= 0.0001f &&
                metrics.carryPosePositionDifferenceMax <= PositionTolerance &&
                metrics.carryPoseRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.transitionStartPositionDifferenceMax <=
                    PositionTolerance &&
                metrics.transitionStartRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.transitionEndPositionDifferenceMax <=
                    PositionTolerance &&
                metrics.transitionEndRotationDifferenceDegreesMax <=
                    RotationTolerance &&
                metrics.minimumLeftHandForwardSeparationMeters + 0.0001f >=
                    StickGripTwoHandLeftHandForwardClearanceMeters &&
                metrics.maximumLeftHandReachErrorMeters <= PositionTolerance &&
                metrics.onlyLeftArmAndForeArmRotationCurvesChanged &&
                metrics.leftShoulderCurvesExact &&
                metrics.leftHandCurvesExact &&
                metrics.nonLeftPoseExact &&
                metrics.controllerUsesAdjustedAttackReadyClip &&
                metrics.controllerSequenceExact &&
                metrics.animatorSettingsCorrect &&
                metrics.stickParentAndLocalTransformExact &&
                metrics.reviewContactSheetExists;
            return metrics;
        }

        private static void MeasureStickGripTwoHandAdjustedAttackReady(
            Transform target,
            AnimationClip sourceClip,
            AnimationClip adjustedClip,
            out float minimumLeftHandForwardSeparation,
            out float maximumLeftHandReachError,
            out float nonLeftPosePositionDifferenceMax,
            out float nonLeftPoseRotationDifferenceMax)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            GameObject adjustedObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            sourceObject.name = "StickGripTwoHandSourceAttackReadyMeasure";
            adjustedObject.name = "StickGripTwoHandAdjustedAttackReadyMeasure";
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            adjustedObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            DisableAnimators(adjustedObject);
            minimumLeftHandForwardSeparation = float.PositiveInfinity;
            maximumLeftHandReachError = 0f;
            nonLeftPosePositionDifferenceMax = 0f;
            nonLeftPoseRotationDifferenceMax = 0f;
            int frameIntervals = Mathf.Max(
                1,
                Mathf.RoundToInt(
                    StickGripTwoHandAttackReadyDurationSeconds *
                    adjustedClip.frameRate));
            try
            {
                for (int frame = 0; frame <= frameIntervals; frame++)
                {
                    float time = StickGripTwoHandAttackReadyDurationSeconds *
                        frame / frameIntervals;
                    sourceClip.SampleAnimation(sourceObject, time);
                    adjustedClip.SampleAnimation(adjustedObject, time);
                    Transform sourceRoot = sourceObject.transform;
                    Transform adjustedRoot = adjustedObject.transform;
                    Transform sourceLeftHand = FindRequired(
                        sourceRoot,
                        LeftHandPath);
                    Transform sourceRightHand = FindRequired(
                        sourceRoot,
                        RightHandPath);
                    Transform adjustedLeftHand = FindRequired(
                        adjustedRoot,
                        LeftHandPath);
                    Transform adjustedRightHand = FindRequired(
                        adjustedRoot,
                        RightHandPath);
                    float sourceSeparation = Vector3.Dot(
                        sourceLeftHand.position - sourceRightHand.position,
                        sourceRoot.forward);
                    Vector3 requestedLeftHandPosition =
                        sourceLeftHand.position +
                        sourceRoot.forward * Mathf.Max(
                            0f,
                            StickGripTwoHandLeftHandForwardClearanceMeters -
                                sourceSeparation);
                    minimumLeftHandForwardSeparation = Mathf.Min(
                        minimumLeftHandForwardSeparation,
                        Vector3.Dot(
                            adjustedLeftHand.position - adjustedRightHand.position,
                            adjustedRoot.forward));
                    maximumLeftHandReachError = Mathf.Max(
                        maximumLeftHandReachError,
                        Vector3.Distance(
                            requestedLeftHandPosition,
                            adjustedLeftHand.position));

                    PoseSnapshot sourcePose = CapturePose(sourceRoot);
                    PoseSnapshot adjustedPose = CapturePose(adjustedRoot);
                    string[] nonLeftPaths = sourcePose.Positions.Keys
                        .Where(path =>
                            (string.Equals(
                                 path,
                                 "Armature",
                                 StringComparison.Ordinal) ||
                             path.StartsWith(
                                 "Armature/",
                                 StringComparison.Ordinal)) &&
                            !IsStickGripTwoHandApprovedLeftChainPath(path))
                        .ToArray();
                    MeasurePoseDifferenceForPaths(
                        sourcePose,
                        adjustedPose,
                        nonLeftPaths,
                        out float positionDifference,
                        out float rotationDifference);
                    nonLeftPosePositionDifferenceMax = Mathf.Max(
                        nonLeftPosePositionDifferenceMax,
                        positionDifference);
                    nonLeftPoseRotationDifferenceMax = Mathf.Max(
                        nonLeftPoseRotationDifferenceMax,
                        rotationDifference);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(adjustedObject);
            }
        }

        private static void MeasureStickGripTwoHandCarryPoseDifference(
            Transform target,
            Transform sourceTarget,
            Animator sourceAnimator,
            AnimationClip baseClip,
            AnimationClip armClip,
            AnimationClip carryClip,
            out float positionDifferenceMax,
            out float rotationDifferenceMax)
        {
            GameObject actualObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            actualObject.name = "StickGripTwoHandCarryMeasure";
            actualObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(actualObject);
            positionDifferenceMax = 0f;
            rotationDifferenceMax = 0f;
            int frameIntervals = Mathf.Max(
                1,
                Mathf.RoundToInt(
                    StickGripTwoHandCarryDurationSeconds *
                    carryClip.frameRate));
            try
            {
                for (int frame = 0; frame <= frameIntervals; frame++)
                {
                    float time = StickGripTwoHandCarryDurationSeconds *
                        frame / frameIntervals;
                    SampleLayeredAnimator(
                        sourceAnimator,
                        StickCarryStateName,
                        time,
                        baseClip.length,
                        armClip.length);
                    carryClip.SampleAnimation(actualObject, time);
                    MeasureArmaturePoseDifference(
                        CapturePose(sourceTarget),
                        CapturePose(actualObject.transform),
                        out float positionDifference,
                        out float rotationDifference);
                    positionDifferenceMax = Mathf.Max(
                        positionDifferenceMax,
                        positionDifference);
                    rotationDifferenceMax = Mathf.Max(
                        rotationDifferenceMax,
                        rotationDifference);
                }
            }
            finally
            {
                sourceAnimator.Rebind();
                sourceAnimator.Update(0f);
                UnityEngine.Object.DestroyImmediate(actualObject);
            }
        }

        private static void MeasureStickGripTwoHandTransitionEndpoints(
            Transform target,
            AnimationClip carryClip,
            AnimationClip transitionClip,
            AnimationClip attackReadyClip,
            out float startPositionDifference,
            out float startRotationDifference,
            out float endPositionDifference,
            out float endRotationDifference)
        {
            GameObject carryObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            GameObject transitionStartObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            GameObject transitionEndObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            GameObject attackReadyObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            carryObject.hideFlags = HideFlags.HideAndDontSave;
            transitionStartObject.hideFlags = HideFlags.HideAndDontSave;
            transitionEndObject.hideFlags = HideFlags.HideAndDontSave;
            attackReadyObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(carryObject);
            DisableAnimators(transitionStartObject);
            DisableAnimators(transitionEndObject);
            DisableAnimators(attackReadyObject);
            try
            {
                carryClip.SampleAnimation(
                    carryObject,
                    StickGripTwoHandCarryDurationSeconds);
                transitionClip.SampleAnimation(transitionStartObject, 0f);
                transitionClip.SampleAnimation(
                    transitionEndObject,
                    StickGripTwoHandTransitionDurationSeconds);
                attackReadyClip.SampleAnimation(attackReadyObject, 0f);
                MeasureArmaturePoseDifference(
                    CapturePose(carryObject.transform),
                    CapturePose(transitionStartObject.transform),
                    out startPositionDifference,
                    out startRotationDifference);
                string[] sourceDrivenPaths = AnimationUtility
                    .GetCurveBindings(attackReadyClip)
                    .Where(binding =>
                        binding.type == typeof(Transform) &&
                        (binding.propertyName.StartsWith(
                             "m_LocalPosition.",
                             StringComparison.Ordinal) ||
                         binding.propertyName.StartsWith(
                             "m_LocalRotation.",
                             StringComparison.Ordinal)))
                    .Select(binding => binding.path)
                    .ToArray();
                MeasurePoseDifferenceForPaths(
                    CapturePose(transitionEndObject.transform),
                    CapturePose(attackReadyObject.transform),
                    sourceDrivenPaths,
                    out endPositionDifference,
                    out endRotationDifference);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(carryObject);
                UnityEngine.Object.DestroyImmediate(transitionStartObject);
                UnityEngine.Object.DestroyImmediate(transitionEndObject);
                UnityEngine.Object.DestroyImmediate(attackReadyObject);
            }
        }

        private static bool StickGripTwoHandControllerIsExact(
            AnimatorController controller,
            AnimationClip carryClip,
            AnimationClip transitionClip,
            AnimationClip attackReadyClip,
            out bool usesAdjustedAttackReadyClip)
        {
            usesAdjustedAttackReadyClip = false;
            if (controller.layers.Length != 1)
            {
                return false;
            }

            AnimatorStateMachine stateMachine =
                controller.layers[0].stateMachine;
            Dictionary<string, AnimatorState> states = stateMachine.states
                .Select(child => child.state)
                .ToDictionary(state => state.name, StringComparer.Ordinal);
            if (states.Count != 3 ||
                !states.TryGetValue(
                    StickGripTwoHandCarryStateName,
                    out AnimatorState carryState) ||
                !states.TryGetValue(
                    StickGripTwoHandTransitionStateName,
                    out AnimatorState transitionState) ||
                !states.TryGetValue(
                    StickGripTwoHandAttackReadyStateName,
                    out AnimatorState attackReadyState))
            {
                return false;
            }

            usesAdjustedAttackReadyClip =
                attackReadyState.motion == attackReadyClip &&
                Mathf.Abs(attackReadyState.speed - 1f) <= 0.0001f;
            return stateMachine.defaultState == carryState &&
                StickGripTwoHandStateIsExact(carryState, carryClip) &&
                StickGripTwoHandStateIsExact(
                    transitionState,
                    transitionClip) &&
                StickGripTwoHandStateIsExact(
                    attackReadyState,
                    attackReadyClip) &&
                StickGripTwoHandTransitionIsExact(
                    carryState,
                    transitionState,
                    1f) &&
                StickGripTwoHandTransitionIsExact(
                    transitionState,
                    attackReadyState,
                    1f) &&
                StickGripTwoHandTransitionIsExact(
                    attackReadyState,
                    carryState,
                    StickGripTwoHandAttackReadyDurationSeconds /
                        attackReadyClip.length);
        }

        private static bool StickGripTwoHandStateIsExact(
            AnimatorState state,
            AnimationClip clip)
        {
            return state.motion == clip &&
                Mathf.Abs(state.speed - 1f) <= 0.0001f &&
                !state.mirror &&
                Mathf.Abs(state.cycleOffset) <= 0.0001f;
        }

        private static bool StickGripTwoHandTransitionIsExact(
            AnimatorState source,
            AnimatorState destination,
            float exitTime)
        {
            AnimatorStateTransition[] transitions = source.transitions;
            if (transitions.Length != 1)
            {
                return false;
            }

            AnimatorStateTransition transition = transitions[0];
            return transition.destinationState == destination &&
                transition.hasExitTime &&
                Mathf.Abs(transition.exitTime - exitTime) <= 0.0001f &&
                transition.hasFixedDuration &&
                Mathf.Abs(transition.duration) <= 0.0001f &&
                Mathf.Abs(transition.offset) <= 0.0001f;
        }

        private sealed class AnimationClipPoseSampler : IDisposable
        {
            private readonly Animator animator;
            private readonly bool animatorEnabled;
            private readonly PlayableGraph graph;
            private readonly AnimationClipPlayable playable;

            internal AnimationClipPoseSampler(
                Animator targetAnimator,
                AnimationClip clip)
            {
                animator = targetAnimator;
                animatorEnabled = animator.enabled;
                animator.enabled = true;
                animator.Rebind();
                animator.Update(0f);
                graph = PlayableGraph.Create(
                    targetAnimator.name + "ClipPoseReview");
                graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);
                playable = AnimationClipPlayable.Create(graph, clip);
                playable.SetApplyFootIK(false);
                playable.SetApplyPlayableIK(false);
                AnimationPlayableOutput output = AnimationPlayableOutput.Create(
                    graph,
                    "ClipPose",
                    animator);
                output.SetSourcePlayable(playable);
                graph.Play();
            }

            internal void Sample(float time)
            {
                playable.SetTime(time);
                graph.Evaluate(0f);
            }

            public void Dispose()
            {
                if (graph.IsValid())
                {
                    graph.Destroy();
                }

                animator.enabled = animatorEnabled;
            }
        }

        private sealed class CaptureEnvironment : IDisposable
        {
            private readonly List<RendererState> hiddenRenderers;
            private readonly HashSet<Renderer> hiddenRendererSet;
            private readonly HashSet<Renderer> targetRenderers;
            private readonly GameObject frontCameraObject;
            private readonly GameObject sideCameraObject;
            private readonly GameObject palmCameraObject;
            private readonly GameObject lightObject;
            private readonly RenderTexture renderTexture;
            private readonly Texture2D frameTexture;
            private readonly RenderTexture previousActive;

            internal CaptureEnvironment(Transform target)
                : this(target, null, null)
            {
            }

            internal CaptureEnvironment(
                Transform target,
                Transform additionalTarget,
                Transform excludedTarget)
            {
                IEnumerable<Renderer> includedRenderers = target
                    .GetComponentsInChildren<Renderer>(true)
                    .Where(renderer => renderer.enabled);
                if (excludedTarget != null)
                {
                    HashSet<Renderer> excluded = new HashSet<Renderer>(
                        excludedTarget.GetComponentsInChildren<Renderer>(true));
                    includedRenderers = includedRenderers.Where(renderer =>
                        !excluded.Contains(renderer));
                }

                if (additionalTarget != null)
                {
                    includedRenderers = includedRenderers.Concat(
                        additionalTarget
                            .GetComponentsInChildren<Renderer>(true)
                            .Where(renderer => renderer.enabled));
                }

                Renderer[] targetRenderers = includedRenderers
                    .Distinct()
                    .ToArray();
                if (targetRenderers.Length == 0)
                {
                    throw new InvalidOperationException(
                        target.name + " has no enabled renderer.");
                }

                this.targetRenderers =
                    new HashSet<Renderer>(targetRenderers);
                hiddenRenderers = new List<RendererState>();
                hiddenRendererSet = new HashSet<Renderer>();

                frontCameraObject = CreateCameraObject(target.name + "FrontCamera");
                sideCameraObject = CreateCameraObject(target.name + "SideCamera");
                palmCameraObject = CreateCameraObject(target.name + "PalmCamera");
                ConfigureView(target, 1.05f, 1.35f);
                lightObject = new GameObject(target.name + "ReviewLight", typeof(Light));
                lightObject.hideFlags = HideFlags.HideAndDontSave;
                Light light = lightObject.GetComponent<Light>();
                light.type = LightType.Directional;
                light.intensity = 1.25f;
                light.color = new Color(1f, 0.96f, 0.9f);
                light.transform.rotation = Quaternion.LookRotation(
                    -target.forward - target.up * 0.65f,
                    target.up);
                renderTexture = new RenderTexture(
                    CaptureWidth,
                    CaptureHeight,
                    24,
                    RenderTextureFormat.ARGB32)
                {
                    antiAliasing = 2
                };
                renderTexture.Create();
                frameTexture = new Texture2D(
                    CaptureWidth,
                    CaptureHeight,
                    TextureFormat.RGB24,
                    false);
                previousActive = RenderTexture.active;
                HideNonTargetRenderers();
            }

            internal byte[] CaptureFront()
            {
                return CaptureFrame(frontCameraObject.GetComponent<Camera>());
            }

            internal byte[] CaptureSide()
            {
                return CaptureFrame(sideCameraObject.GetComponent<Camera>());
            }

            internal byte[] CapturePalmFromTorso()
            {
                return CaptureFrame(palmCameraObject.GetComponent<Camera>());
            }

            internal void ConfigureDarkMaterialReview()
            {
                Color neutralBackground = new Color(0.28f, 0.29f, 0.31f, 1f);
                frontCameraObject.GetComponent<Camera>().backgroundColor =
                    neutralBackground;
                sideCameraObject.GetComponent<Camera>().backgroundColor =
                    neutralBackground;
                palmCameraObject.GetComponent<Camera>().backgroundColor =
                    neutralBackground;
                Light reviewLight = lightObject.GetComponent<Light>();
                reviewLight.intensity = 3f;
                reviewLight.color = Color.white;
            }

            internal byte[] CaptureOppositeSide(
                Transform target,
                Vector3 center,
                float orthographicSize)
            {
                ConfigureFixedCamera(
                    palmCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    -target.right,
                    orthographicSize);
                return CaptureFrame(palmCameraObject.GetComponent<Camera>());
            }

            internal byte[] CaptureOblique(
                Transform target,
                Vector3 center,
                Vector3 viewDirection,
                float orthographicSize)
            {
                if (viewDirection.sqrMagnitude <= 0.000001f)
                {
                    throw new InvalidOperationException(
                        target.name + " has no usable oblique review direction.");
                }

                ConfigureFixedCamera(
                    palmCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    viewDirection.normalized,
                    orthographicSize);
                return CaptureFrame(palmCameraObject.GetComponent<Camera>());
            }

            internal void ConfigurePalmView(
                Transform target,
                Vector3 center,
                Vector3 torsoToHandViewDirection,
                float orthographicSize)
            {
                Vector3 direction = Vector3.ProjectOnPlane(
                    torsoToHandViewDirection,
                    Vector3.up).normalized;
                if (direction.sqrMagnitude < 0.99f)
                {
                    throw new InvalidOperationException(
                        target.name + " has no usable torso-side palm review direction.");
                }

                Camera camera = palmCameraObject.GetComponent<Camera>();
                camera.transform.position = center + direction * 0.12f;
                camera.transform.LookAt(center, target.up);
                camera.orthographicSize = orthographicSize;
                camera.nearClipPlane = 0.005f;
                camera.farClipPlane = 4f;
            }

            internal void ConfigureFirstPersonView(
                Vector3 cameraPosition,
                Vector3 lookTarget,
                Vector3 up,
                float fieldOfView)
            {
                Camera camera = palmCameraObject.GetComponent<Camera>();
                camera.orthographic = false;
                camera.transform.position = cameraPosition;
                camera.transform.LookAt(lookTarget, up);
                camera.fieldOfView = fieldOfView;
                camera.nearClipPlane = 0.015f;
                camera.farClipPlane = 12f;
            }

            internal void ConfigureView(
                Transform target,
                float centerHeight,
                float orthographicSize)
            {
                Vector3 center = target.position + target.up * centerHeight;
                ConfigureView(target, center, orthographicSize);
            }

            internal void ConfigureView(
                Transform target,
                Vector3 center,
                float orthographicSize)
            {
                ConfigureFixedCamera(
                    frontCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    target.forward,
                    orthographicSize);
                ConfigureFixedCamera(
                    sideCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    target.right,
                    orthographicSize);
            }

            internal void ConfigureBackView(
                Transform target,
                float centerHeight,
                float orthographicSize)
            {
                Vector3 center = target.position + target.up * centerHeight;
                ConfigureFixedCamera(
                    frontCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    -target.forward,
                    orthographicSize);
                ConfigureFixedCamera(
                    sideCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    target.right,
                    orthographicSize);
            }

            internal void ConfigureElevatedView(
                Transform target,
                Vector3 center,
                float orthographicSize)
            {
                ConfigureElevatedCamera(
                    frontCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    target.forward,
                    orthographicSize);
                ConfigureElevatedCamera(
                    sideCameraObject.GetComponent<Camera>(),
                    target,
                    center,
                    target.right,
                    orthographicSize);
            }

            internal void ConfigureTopView(
                Transform target,
                Vector3 center,
                float orthographicSize)
            {
                Camera camera = palmCameraObject.GetComponent<Camera>();
                camera.orthographic = true;
                camera.transform.position = center + target.up * 8f;
                camera.transform.LookAt(center, target.forward);
                camera.orthographicSize = orthographicSize;
                camera.nearClipPlane = 0.01f;
                camera.farClipPlane = 100f;
            }

            private byte[] CaptureFrame(Camera camera)
            {
                HideNonTargetRenderers();
                camera.targetTexture = renderTexture;
                camera.Render();
                RenderTexture.active = renderTexture;
                frameTexture.ReadPixels(
                    new Rect(0f, 0f, CaptureWidth, CaptureHeight),
                    0,
                    0,
                    false);
                frameTexture.Apply(false, false);
                byte[] png = frameTexture.EncodeToPNG();
                camera.targetTexture = null;
                return png;
            }

            private void HideNonTargetRenderers()
            {
                foreach (Renderer renderer in
                         Resources.FindObjectsOfTypeAll<Renderer>())
                {
                    if (renderer == null ||
                        !renderer.enabled ||
                        !renderer.gameObject.scene.IsValid() ||
                        targetRenderers.Contains(renderer))
                    {
                        continue;
                    }

                    if (hiddenRendererSet.Add(renderer))
                    {
                        hiddenRenderers.Add(new RendererState(renderer));
                    }

                    renderer.enabled = false;
                }
            }

            public void Dispose()
            {
                foreach (RendererState state in hiddenRenderers)
                {
                    state.Restore();
                }

                RenderTexture.active = previousActive;
                renderTexture.Release();
                UnityEngine.Object.DestroyImmediate(renderTexture);
                UnityEngine.Object.DestroyImmediate(frameTexture);
                UnityEngine.Object.DestroyImmediate(frontCameraObject);
                UnityEngine.Object.DestroyImmediate(sideCameraObject);
                UnityEngine.Object.DestroyImmediate(palmCameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

        private static GameObject CreateCameraObject(string name)
        {
            GameObject cameraObject = new GameObject(name, typeof(Camera));
            cameraObject.hideFlags = HideFlags.HideAndDontSave;
            Camera camera = cameraObject.GetComponent<Camera>();
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.055f, 0.065f, 0.08f, 1f);
            camera.allowHDR = false;
            camera.allowMSAA = true;
            camera.orthographic = true;
            camera.aspect = CaptureWidth / (float)CaptureHeight;
            camera.nearClipPlane = 0.01f;
            camera.farClipPlane = 100f;
            return cameraObject;
        }

        private static void ConfigureFixedCamera(
            Camera camera,
            Transform target,
            Vector3 center,
            Vector3 viewDirection,
            float orthographicSize)
        {
            Vector3 direction = Vector3.ProjectOnPlane(viewDirection, Vector3.up).normalized;
            if (direction.sqrMagnitude < 0.99f)
            {
                throw new InvalidOperationException(
                    target.name + " has no usable review direction.");
            }

            camera.transform.position = center + direction * 8f;
            camera.transform.LookAt(center, target.up);
            camera.orthographicSize = orthographicSize;
        }

        private static void ConfigureElevatedCamera(
            Camera camera,
            Transform target,
            Vector3 center,
            Vector3 viewDirection,
            float orthographicSize)
        {
            Vector3 direction = Vector3.ProjectOnPlane(
                viewDirection,
                Vector3.up).normalized;
            if (direction.sqrMagnitude < 0.99f)
            {
                throw new InvalidOperationException(
                    target.name + " has no usable elevated review direction.");
            }

            camera.transform.position =
                center + direction * 8f + target.up * 1.15f;
            camera.transform.LookAt(center, target.up);
            camera.orthographicSize = orthographicSize;
        }

        private static void MeasureThrowSourcePeak(
            Transform template,
            AnimationClip source,
            out int frameIntervals,
            out int peakFrame,
            out int peakCandidateCount)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(template.gameObject);
            sourceObject.name = "HandsThrowPeakMeasure";
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            try
            {
                frameIntervals = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                List<float> heights = new List<float>();
                for (int frame = 0; frame <= frameIntervals; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / source.frameRate);
                    source.SampleAnimation(sourceObject, time);
                    Transform rightHand = FindRequired(
                        sourceObject.transform,
                        RightHandPath);
                    heights.Add(Vector3.Dot(
                        rightHand.position - sourceObject.transform.position,
                        sourceObject.transform.up));
                }

                float peakHeight = heights.Max();
                peakFrame = heights.IndexOf(peakHeight);
                peakCandidateCount = heights.Count(height =>
                    Mathf.Abs(height - peakHeight) <= PositionTolerance);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
            }
        }

        private static void MeasureThrowSourceHeadHeightFrame(
            Transform template,
            AnimationClip source,
            out int frameIntervals,
            out int readyEndFrame,
            out float previousRightHandMinusHeadHeight,
            out float rightHandHeight,
            out float headHeight)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(template.gameObject);
            sourceObject.name = "HandsThrowHeadHeightMeasure";
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            try
            {
                frameIntervals = Mathf.Max(
                    1,
                    Mathf.RoundToInt(source.length * source.frameRate));
                readyEndFrame = -1;
                previousRightHandMinusHeadHeight = float.NaN;
                rightHandHeight = float.NaN;
                headHeight = float.NaN;
                float previousDifference = float.NaN;
                for (int frame = 0; frame <= frameIntervals; frame++)
                {
                    float time = Mathf.Min(
                        source.length,
                        frame / source.frameRate);
                    source.SampleAnimation(sourceObject, time);
                    Transform rightHand = FindRequired(
                        sourceObject.transform,
                        RightHandPath);
                    Transform head = FindRequired(
                        sourceObject.transform,
                        HeadPath);
                    float sampledRightHandHeight = Vector3.Dot(
                        rightHand.position - sourceObject.transform.position,
                        sourceObject.transform.up);
                    float sampledHeadHeight = Vector3.Dot(
                        head.position - sourceObject.transform.position,
                        sourceObject.transform.up);
                    float difference =
                        sampledRightHandHeight - sampledHeadHeight;
                    if (frame > 0 &&
                        previousDifference < 0f &&
                        difference >= 0f)
                    {
                        readyEndFrame = frame;
                        previousRightHandMinusHeadHeight = previousDifference;
                        rightHandHeight = sampledRightHandHeight;
                        headHeight = sampledHeadHeight;
                        break;
                    }

                    previousDifference = difference;
                }

                if (readyEndFrame < 0)
                {
                    throw new InvalidOperationException(
                        "Hands Throw source has no rising frame where the right hand first reaches Head height.");
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
            }
        }

        private static ThrowBreathingMeshBuildResult
            CreateOrUpdateThrowReadyBreathingMesh(
                Transform template,
                SkinnedMeshRenderer templateRenderer,
                AnimationClip baseClip,
                float readyEndTime,
                float expansionAtAnimatedWeight,
                float animatedWeight)
        {
            Mesh originalMesh = AssetDatabase.LoadAllAssetsAtPath(PlayerModelPath)
                .OfType<Mesh>()
                .OrderByDescending(mesh => mesh.vertexCount)
                .FirstOrDefault();
            if (originalMesh == null || originalMesh.vertexCount == 0)
            {
                throw new InvalidOperationException(
                    "Player FBX has no usable source mesh for Ready breathing.");
            }

            if (animatedWeight <= 0f || animatedWeight > 100f)
            {
                throw new InvalidOperationException(
                    "Ready breathing animated BlendShape weight is invalid.");
            }

            string rendererPath = AnimationUtility.CalculateTransformPath(
                templateRenderer.transform,
                template);
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name = "HandsThrowReadyBreathingMeshBuild";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            Mesh baseBake = new Mesh { name = "HandsThrowReadyBreathingBaseBake" };
            Mesh expandedBake = new Mesh { name = "HandsThrowReadyBreathingExpandedBake" };
            try
            {
                SkinnedMeshRenderer renderer = RequireRelativeSkinnedMeshRenderer(
                    workObject.transform,
                    rendererPath);
                renderer.sharedMesh = originalMesh;
                baseClip.SampleAnimation(workObject, readyEndTime);
                renderer.BakeMesh(baseBake, true);
                Vector3[] bakedVertices = baseBake.vertices;
                BoneWeight[] boneWeights = originalMesh.boneWeights;
                Matrix4x4[] bindPoses = originalMesh.bindposes;
                if (bakedVertices.Length != originalMesh.vertexCount ||
                    boneWeights.Length != originalMesh.vertexCount ||
                    bindPoses.Length != renderer.bones.Length)
                {
                    throw new InvalidOperationException(
                        "Ready breathing source mesh skinning data is unsupported.");
                }

                Transform root = workObject.transform;
                Transform spine = FindRequired(root, SpinePath);
                Transform solar = FindRequired(root, SolarPlexusPath);
                Transform leftShoulder = FindRequired(root, LeftShoulderPath);
                Transform rightShoulder = FindRequired(root, RightShoulderPath);
                float lowerHeight = Vector3.Dot(
                    solar.position - root.position,
                    root.up);
                float upperHeight = Vector3.Dot(
                    ((leftShoulder.position + rightShoulder.position) * 0.5f) -
                    root.position,
                    root.up);
                if (upperHeight <= lowerHeight)
                {
                    throw new InvalidOperationException(
                        "Ready breathing chest vertical range is invalid.");
                }

                Vector3[] worldDirections = new Vector3[originalMesh.vertexCount];
                float[] rawFades = new float[originalMesh.vertexCount];
                int[] regions = new int[originalMesh.vertexCount];
                float maximumRawFade = 0f;
                for (int vertex = 0; vertex < originalMesh.vertexCount; vertex++)
                {
                    string dominantBone = DominantBoneName(
                        boneWeights[vertex],
                        renderer.bones);
                    if (!string.Equals(dominantBone, "Spine02", StringComparison.Ordinal) &&
                        !string.Equals(dominantBone, "Spine01", StringComparison.Ordinal) &&
                        !string.Equals(dominantBone, "Spine", StringComparison.Ordinal))
                    {
                        continue;
                    }

                    Vector3 world = renderer.transform.TransformPoint(
                        bakedVertices[vertex]);
                    float height = Vector3.Dot(
                        world - root.position,
                        root.up);
                    if (height <= lowerHeight || height >= upperHeight)
                    {
                        continue;
                    }

                    Vector3 fromSpine = world - spine.position;
                    float lateral = Vector3.Dot(fromSpine, root.right);
                    float forward = Vector3.Dot(fromSpine, root.forward);
                    if (forward < 0f)
                    {
                        continue;
                    }

                    Vector3 horizontal =
                        root.right * lateral + root.forward * forward;
                    if (horizontal.sqrMagnitude <= 0.0000001f)
                    {
                        continue;
                    }

                    float verticalPhase = Mathf.InverseLerp(
                        lowerHeight,
                        upperHeight,
                        height);
                    float fade = Mathf.Sin(verticalPhase * Mathf.PI);
                    if (fade <= 0f)
                    {
                        continue;
                    }

                    worldDirections[vertex] = horizontal.normalized;
                    rawFades[vertex] = fade;
                    regions[vertex] = Mathf.Abs(lateral) <= Mathf.Abs(forward)
                        ? 1
                        : lateral < 0f
                            ? 2
                            : 3;
                    maximumRawFade = Mathf.Max(maximumRawFade, fade);
                }

                if (maximumRawFade <= 0f)
                {
                    throw new InvalidOperationException(
                        "Ready breathing mesh found no chest vertices.");
                }

                float fullWeightExpansion =
                    expansionAtAnimatedWeight * 100f / animatedWeight;
                Vector3[] deltaVertices = new Vector3[originalMesh.vertexCount];
                bool[] affected = new bool[originalMesh.vertexCount];
                int frontCount = 0;
                int leftCount = 0;
                int rightCount = 0;
                for (int vertex = 0; vertex < originalMesh.vertexCount; vertex++)
                {
                    if (rawFades[vertex] <= 0f)
                    {
                        continue;
                    }

                    Vector3 desiredWorldDelta = worldDirections[vertex] *
                        (fullWeightExpansion * rawFades[vertex] / maximumRawFade);
                    Vector3 desiredRendererLocal =
                        renderer.transform.InverseTransformVector(
                            desiredWorldDelta);
                    Matrix4x4 skinMatrix = CalculateWeightedSkinMatrix(
                        renderer,
                        bindPoses,
                        boneWeights[vertex]);
                    Vector3 bindDelta = skinMatrix.inverse.MultiplyVector(
                        desiredRendererLocal);
                    if (!IsFinite(bindDelta) || bindDelta.magnitude > 0.1f)
                    {
                        throw new InvalidOperationException(
                            "Ready breathing mesh produced an invalid chest delta.");
                    }

                    deltaVertices[vertex] = bindDelta;
                    affected[vertex] = true;
                    switch (regions[vertex])
                    {
                        case 1:
                            frontCount++;
                            break;
                        case 2:
                            leftCount++;
                            break;
                        case 3:
                            rightCount++;
                            break;
                    }
                }

                int affectedCount = affected.Count(value => value);
                if (affectedCount == 0 ||
                    frontCount == 0 ||
                    leftCount == 0 ||
                    rightCount == 0)
                {
                    throw new InvalidOperationException(
                        "Ready breathing mesh does not cover the front and both chest sides.");
                }

                Mesh generated = UnityEngine.Object.Instantiate(originalMesh);
                generated.name = "Hands_Throw_Ready_Breathing";
                generated.AddBlendShapeFrame(
                    ThrowReadyBreathingBlendShapeName,
                    100f,
                    deltaVertices,
                    new Vector3[originalMesh.vertexCount],
                    new Vector3[originalMesh.vertexCount]);
                generated.RecalculateBounds();
                Directory.CreateDirectory(Path.GetDirectoryName(
                    ThrowReadyBreathingMeshPath));
                Mesh breathingMesh = AssetDatabase.LoadAssetAtPath<Mesh>(
                    ThrowReadyBreathingMeshPath);
                if (breathingMesh == null)
                {
                    AssetDatabase.CreateAsset(
                        generated,
                        ThrowReadyBreathingMeshPath);
                    breathingMesh = generated;
                }
                else
                {
                    EditorUtility.CopySerialized(generated, breathingMesh);
                    UnityEngine.Object.DestroyImmediate(generated);
                    breathingMesh.name = "Hands_Throw_Ready_Breathing";
                    EditorUtility.SetDirty(breathingMesh);
                }

                AssetDatabase.SaveAssets();
                int blendShapeIndex = breathingMesh.GetBlendShapeIndex(
                    ThrowReadyBreathingBlendShapeName);
                if (blendShapeIndex < 0)
                {
                    throw new InvalidOperationException(
                        "Ready breathing mesh is missing its Breathing BlendShape.");
                }

                renderer.sharedMesh = breathingMesh;
                baseClip.SampleAnimation(workObject, readyEndTime);
                renderer.SetBlendShapeWeight(blendShapeIndex, 0f);
                renderer.BakeMesh(baseBake, true);
                renderer.SetBlendShapeWeight(blendShapeIndex, animatedWeight);
                renderer.BakeMesh(expandedBake, true);
                Vector3[] baseVertices = baseBake.vertices;
                Vector3[] expandedVertices = expandedBake.vertices;
                float maximumExpansion = 0f;
                for (int vertex = 0; vertex < baseVertices.Length; vertex++)
                {
                    maximumExpansion = Mathf.Max(
                        maximumExpansion,
                        Vector3.Distance(
                            renderer.transform.TransformPoint(baseVertices[vertex]),
                            renderer.transform.TransformPoint(expandedVertices[vertex])));
                }

                return new ThrowBreathingMeshBuildResult
                {
                    Mesh = breathingMesh,
                    RendererPath = rendererPath,
                    BlendShapeIndex = blendShapeIndex,
                    AffectedVertexCount = affectedCount,
                    FrontVertexCount = frontCount,
                    LeftSideVertexCount = leftCount,
                    RightSideVertexCount = rightCount,
                    MaximumExpansionAtThirtyPercentMeters = maximumExpansion
                };
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(baseBake);
                UnityEngine.Object.DestroyImmediate(expandedBake);
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static string DominantBoneName(
            BoneWeight weight,
            Transform[] bones)
        {
            int[] indices =
            {
                weight.boneIndex0,
                weight.boneIndex1,
                weight.boneIndex2,
                weight.boneIndex3
            };
            float[] values =
            {
                weight.weight0,
                weight.weight1,
                weight.weight2,
                weight.weight3
            };
            int best = 0;
            for (int index = 1; index < values.Length; index++)
            {
                if (values[index] > values[best])
                {
                    best = index;
                }
            }

            int boneIndex = indices[best];
            return boneIndex >= 0 && boneIndex < bones.Length && bones[boneIndex] != null
                ? bones[boneIndex].name
                : string.Empty;
        }

        private static AnimationClip CreateOrUpdateThrowReadyClip(
            AnimationClip source,
            Transform template,
            string rendererPath,
            float readyEndTime,
            float holdDuration,
            float breathingFrequency,
            float breathingMaximumWeight,
            float requestedBodyDrop,
            out ThrowBreathingMotionBuildResult motionBuild)
        {
            float holdEndTime = readyEndTime + holdDuration;
            AnimationClip generated = new AnimationClip();
            EditorUtility.CopySerialized(source, generated);
            generated.name = "Hands_Throw_Ready_MixamoHeadHeightBreathing";
            generated.frameRate = source.frameRate;
            generated.wrapMode = WrapMode.Loop;
            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetCurveBindings(source))
            {
                AnimationCurve sourceCurve =
                    AnimationUtility.GetEditorCurve(source, binding);
                AnimationCurve readyCurve = CreateThrowReadyCurve(
                    sourceCurve,
                    readyEndTime,
                    holdEndTime,
                    binding.path + "/" + binding.propertyName);
                AnimationUtility.SetEditorCurve(generated, binding, readyCurve);
            }

            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetObjectReferenceCurveBindings(source))
            {
                ObjectReferenceKeyframe[] sourceKeys =
                    AnimationUtility.GetObjectReferenceCurve(source, binding);
                List<ObjectReferenceKeyframe> readyKeys = sourceKeys
                    .Where(key => key.time <= readyEndTime + 0.0001f)
                    .ToList();
                ObjectReferenceKeyframe[] available = sourceKeys
                    .Where(key => key.time <= readyEndTime + 0.0001f)
                    .ToArray();
                UnityEngine.Object readyEndValue = available.Length > 0
                    ? available[available.Length - 1].value
                    : sourceKeys.Length > 0
                        ? sourceKeys[0].value
                        : null;
                if (!readyKeys.Any(key =>
                        Mathf.Abs(key.time - readyEndTime) <= 0.0001f))
                {
                    readyKeys.Add(new ObjectReferenceKeyframe
                    {
                        time = readyEndTime,
                        value = readyEndValue
                    });
                }

                readyKeys.Add(new ObjectReferenceKeyframe
                {
                    time = holdEndTime,
                    value = readyEndValue
                });
                AnimationUtility.SetObjectReferenceCurve(
                    generated,
                    binding,
                    readyKeys.OrderBy(key => key.time).ToArray());
            }

            AnimationEvent[] readyEvents = AnimationUtility
                .GetAnimationEvents(source)
                .Where(animationEvent =>
                    animationEvent.time <= readyEndTime + 0.0001f)
                .ToArray();
            AnimationUtility.SetAnimationEvents(generated, readyEvents);
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(source);
            settings.startTime = 0f;
            settings.stopTime = holdEndTime;
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            motionBuild = ApplyThrowReadyBreathingCurves(
                template,
                source,
                generated,
                rendererPath,
                readyEndTime,
                holdDuration,
                breathingFrequency,
                breathingMaximumWeight,
                requestedBodyDrop);
            AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrowReadyClipPath);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, ThrowReadyClipPath);
                existing = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, existing);
                UnityEngine.Object.DestroyImmediate(generated);
                existing.name = "Hands_Throw_Ready_MixamoHeadHeightBreathing";
                EditorUtility.SetDirty(existing);
            }

            AssetDatabase.SaveAssets();
            return existing;
        }

        private static ThrowBreathingMotionBuildResult
            ApplyThrowReadyBreathingCurves(
                Transform template,
                AnimationClip source,
                AnimationClip generated,
                string rendererPath,
                float readyEndTime,
                float holdDuration,
                float breathingFrequency,
                float breathingMaximumWeight,
                float requestedBodyDrop)
        {
            GameObject workObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            workObject.name = "HandsThrowReadyBreathingMotionBuild";
            workObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(workObject);
            try
            {
                Transform root = workObject.transform;
                SkinnedMeshRenderer renderer = RequireRelativeSkinnedMeshRenderer(
                    root,
                    rendererPath);
                int blendShapeIndex = renderer.sharedMesh != null
                    ? renderer.sharedMesh.GetBlendShapeIndex(
                        ThrowReadyBreathingBlendShapeName)
                    : -1;
                if (blendShapeIndex < 0)
                {
                    throw new InvalidOperationException(
                        "Ready breathing motion build is missing its state mesh BlendShape.");
                }

                int readyEndFrame = Mathf.RoundToInt(
                    readyEndTime * source.frameRate);
                int totalFrames = Mathf.RoundToInt(
                    (readyEndTime + holdDuration) * source.frameRate);
                source.SampleAnimation(workObject, readyEndTime);
                renderer.SetBlendShapeWeight(blendShapeIndex, 0f);
                Transform hips = FindRequired(root, HipsPath);
                Transform leftUpper = FindRequired(root, LeftUpLegPath);
                Transform leftLower = FindRequired(root, LeftLegPath);
                Transform leftFoot = FindRequired(root, LeftFootPath);
                Transform rightUpper = FindRequired(root, RightUpLegPath);
                Transform rightLower = FindRequired(root, RightLegPath);
                Transform rightFoot = FindRequired(root, RightFootPath);
                Vector3 baseHipsWorld = hips.position;
                Vector3 baseLeftKneeWorld = leftLower.position;
                Vector3 baseRightKneeWorld = rightLower.position;
                Vector3 baseLeftFootWorld = leftFoot.position;
                Vector3 baseRightFootWorld = rightFoot.position;
                Quaternion baseLeftFootRotation = leftFoot.rotation;
                Quaternion baseRightFootRotation = rightFoot.rotation;
                float baseLeftFlex = MeasureKneeFlexDegrees(
                    leftUpper,
                    leftLower,
                    leftFoot);
                float baseRightFlex = MeasureKneeFlexDegrees(
                    rightUpper,
                    rightLower,
                    rightFoot);

                TransformCurveTrack hipsTrack = new TransformCurveTrack(HipsPath);
                TransformCurveTrack leftUpperTrack =
                    new TransformCurveTrack(LeftUpLegPath);
                TransformCurveTrack leftLowerTrack =
                    new TransformCurveTrack(LeftLegPath);
                TransformCurveTrack leftFootTrack =
                    new TransformCurveTrack(LeftFootPath);
                TransformCurveTrack rightUpperTrack =
                    new TransformCurveTrack(RightUpLegPath);
                TransformCurveTrack rightLowerTrack =
                    new TransformCurveTrack(RightLegPath);
                TransformCurveTrack rightFootTrack =
                    new TransformCurveTrack(RightFootPath);
                List<Keyframe> breathingKeys = new List<Keyframe>();
                float maximumBodyDrop = 0f;
                float maximumFootDisplacement = 0f;
                float maximumLeftFlexIncrease = 0f;
                float maximumRightFlexIncrease = 0f;
                for (int frame = 0; frame <= totalFrames; frame++)
                {
                    float time = frame / source.frameRate;
                    float factor = 0f;
                    if (frame <= readyEndFrame)
                    {
                        source.SampleAnimation(workObject, time);
                    }
                    else
                    {
                        source.SampleAnimation(workObject, readyEndTime);
                        float holdTime = time - readyEndTime;
                        factor = 0.5f - 0.5f * Mathf.Cos(
                            2f * Mathf.PI * breathingFrequency * holdTime);
                        hips.position = baseHipsWorld -
                            root.up * (requestedBodyDrop * factor);
                        float leftError = SolveTwoBoneLeg(
                            root,
                            leftUpper,
                            leftLower,
                            leftFoot,
                            baseLeftFootWorld,
                            baseLeftFootRotation,
                            baseLeftKneeWorld);
                        float rightError = SolveTwoBoneLeg(
                            root,
                            rightUpper,
                            rightLower,
                            rightFoot,
                            baseRightFootWorld,
                            baseRightFootRotation,
                            baseRightKneeWorld);
                        maximumFootDisplacement = Mathf.Max(
                            maximumFootDisplacement,
                            leftError,
                            rightError);
                        maximumBodyDrop = Mathf.Max(
                            maximumBodyDrop,
                            Vector3.Dot(
                                baseHipsWorld - hips.position,
                                root.up));
                        maximumLeftFlexIncrease = Mathf.Max(
                            maximumLeftFlexIncrease,
                            MeasureKneeFlexDegrees(
                                leftUpper,
                                leftLower,
                                leftFoot) - baseLeftFlex);
                        maximumRightFlexIncrease = Mathf.Max(
                            maximumRightFlexIncrease,
                            MeasureKneeFlexDegrees(
                                rightUpper,
                                rightLower,
                                rightFoot) - baseRightFlex);
                    }

                    renderer.SetBlendShapeWeight(
                        blendShapeIndex,
                        factor * breathingMaximumWeight);
                    hipsTrack.Add(time, hips);
                    leftUpperTrack.Add(time, leftUpper);
                    leftLowerTrack.Add(time, leftLower);
                    leftFootTrack.Add(time, leftFoot);
                    rightUpperTrack.Add(time, rightUpper);
                    rightLowerTrack.Add(time, rightLower);
                    rightFootTrack.Add(time, rightFoot);
                    breathingKeys.Add(new Keyframe(
                        time,
                        factor * breathingMaximumWeight));
                }

                RemoveThrowReadyBreathingTransformCurves(generated);
                SetTransformTrackCurves(generated, hipsTrack);
                SetRotationTrackCurves(generated, leftUpperTrack);
                SetRotationTrackCurves(generated, leftLowerTrack);
                SetRotationTrackCurves(generated, leftFootTrack);
                SetRotationTrackCurves(generated, rightUpperTrack);
                SetRotationTrackCurves(generated, rightLowerTrack);
                SetRotationTrackCurves(generated, rightFootTrack);
                AnimationCurve breathingCurve = new AnimationCurve(
                    breathingKeys.ToArray());
                for (int key = 0; key < breathingCurve.length; key++)
                {
                    AnimationUtility.SetKeyLeftTangentMode(
                        breathingCurve,
                        key,
                        AnimationUtility.TangentMode.Linear);
                    AnimationUtility.SetKeyRightTangentMode(
                        breathingCurve,
                        key,
                        AnimationUtility.TangentMode.Linear);
                }

                AnimationUtility.SetEditorCurve(
                    generated,
                    EditorCurveBinding.FloatCurve(
                        rendererPath,
                        typeof(SkinnedMeshRenderer),
                        "blendShape." + ThrowReadyBreathingBlendShapeName),
                    breathingCurve);
                int trackKeyCount =
                    hipsTrack.PositionX.Count * 3 +
                    (hipsTrack.RotationX.Count +
                     leftUpperTrack.RotationX.Count +
                     leftLowerTrack.RotationX.Count +
                     leftFootTrack.RotationX.Count +
                     rightUpperTrack.RotationX.Count +
                     rightLowerTrack.RotationX.Count +
                     rightFootTrack.RotationX.Count) * 4 +
                    breathingCurve.length;
                return new ThrowBreathingMotionBuildResult
                {
                    BreathingCycleCount = Mathf.RoundToInt(
                        holdDuration * breathingFrequency),
                    CurveKeyCount = trackKeyCount,
                    MaximumBodyDropMeters = maximumBodyDrop,
                    MaximumFootDisplacementMeters = maximumFootDisplacement,
                    MinimumKneeFlexIncreaseDegrees = Mathf.Min(
                        maximumLeftFlexIncrease,
                        maximumRightFlexIncrease)
                };
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(workObject);
            }
        }

        private static void RemoveThrowReadyBreathingTransformCurves(
            AnimationClip clip)
        {
            HashSet<string> legPaths = new HashSet<string>(
                new[]
                {
                    LeftUpLegPath,
                    LeftLegPath,
                    LeftFootPath,
                    RightUpLegPath,
                    RightLegPath,
                    RightFootPath
                },
                StringComparer.Ordinal);
            EditorCurveBinding[] bindings = AnimationUtility.GetCurveBindings(clip)
                .Where(binding =>
                    (string.Equals(binding.path, HipsPath, StringComparison.Ordinal) &&
                     (binding.propertyName.StartsWith(
                          "m_LocalPosition.",
                          StringComparison.Ordinal) ||
                      IsTransformRotationProperty(binding.propertyName))) ||
                    (legPaths.Contains(binding.path) &&
                     IsTransformRotationProperty(binding.propertyName)))
                .ToArray();
            foreach (EditorCurveBinding binding in bindings)
            {
                AnimationUtility.SetEditorCurve(clip, binding, null);
            }
        }

        private static bool IsTransformRotationProperty(string property)
        {
            return property.StartsWith("m_LocalRotation.", StringComparison.Ordinal) ||
                   property.IndexOf("Euler", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static float SolveTwoBoneLeg(
            Transform characterRoot,
            Transform upper,
            Transform lower,
            Transform foot,
            Vector3 targetFootPosition,
            Quaternion targetFootRotation,
            Vector3 poleReference)
        {
            Vector3 hipPosition = upper.position;
            float upperLength = Vector3.Distance(upper.position, lower.position);
            float lowerLength = Vector3.Distance(lower.position, foot.position);
            Vector3 toTarget = targetFootPosition - hipPosition;
            float targetDistance = toTarget.magnitude;
            if (upperLength <= 0.00001f ||
                lowerLength <= 0.00001f ||
                targetDistance <= 0.00001f)
            {
                throw new InvalidOperationException(
                    "Ready breathing leg has invalid two-bone dimensions.");
            }

            Vector3 direction = toTarget / targetDistance;
            float solvedDistance = Mathf.Clamp(
                targetDistance,
                Mathf.Abs(upperLength - lowerLength) + 0.00001f,
                upperLength + lowerLength - 0.00001f);
            float along =
                (upperLength * upperLength - lowerLength * lowerLength +
                 solvedDistance * solvedDistance) /
                (2f * solvedDistance);
            float height = Mathf.Sqrt(Mathf.Max(
                0f,
                upperLength * upperLength - along * along));
            Vector3 linePoint = hipPosition + direction * Vector3.Dot(
                poleReference - hipPosition,
                direction);
            Vector3 poleDirection = poleReference - linePoint;
            if (poleDirection.sqrMagnitude <= 0.0000001f)
            {
                poleDirection = Vector3.ProjectOnPlane(
                    characterRoot.forward,
                    direction);
            }

            if (poleDirection.sqrMagnitude <= 0.0000001f)
            {
                poleDirection = Vector3.ProjectOnPlane(
                    characterRoot.right,
                    direction);
            }

            poleDirection.Normalize();
            Vector3 desiredKnee =
                hipPosition + direction * along + poleDirection * height;
            Vector3 currentUpperDirection = lower.position - upper.position;
            Vector3 desiredUpperDirection = desiredKnee - upper.position;
            upper.rotation = Quaternion.FromToRotation(
                currentUpperDirection,
                desiredUpperDirection) * upper.rotation;
            Vector3 currentLowerDirection = foot.position - lower.position;
            Vector3 desiredLowerDirection = targetFootPosition - lower.position;
            lower.rotation = Quaternion.FromToRotation(
                currentLowerDirection,
                desiredLowerDirection) * lower.rotation;
            foot.rotation = targetFootRotation;
            return Vector3.Distance(foot.position, targetFootPosition);
        }

        private static float MeasureKneeFlexDegrees(
            Transform upper,
            Transform lower,
            Transform foot)
        {
            float jointAngle = Vector3.Angle(
                upper.position - lower.position,
                foot.position - lower.position);
            return 180f - jointAngle;
        }

        private static AnimationCurve CreateThrowReadyCurve(
            AnimationCurve source,
            float readyEndTime,
            float holdEndTime,
            string label)
        {
            Keyframe[] sourceKeys = source.keys;
            List<Keyframe> readyKeys = sourceKeys
                .Where(key => key.time <= readyEndTime + 0.0001f)
                .ToList();
            int readyEndKeyIndex = readyKeys.FindIndex(key =>
                Mathf.Abs(key.time - readyEndTime) <= 0.0001f);
            if (readyEndKeyIndex < 0)
            {
                bool constantCurve = sourceKeys.Length <= 1 ||
                    sourceKeys.All(key =>
                        Mathf.Abs(key.value - sourceKeys[0].value) <= 0.000001f);
                if (!constantCurve)
                {
                    throw new InvalidOperationException(
                        "Hands Throw source curve has no exact key at the directly confirmed head-height frame: " +
                        label + ".");
                }

                readyKeys.Add(new Keyframe(
                    readyEndTime,
                    source.Evaluate(readyEndTime),
                    0f,
                    0f));
                readyEndKeyIndex = readyKeys.Count - 1;
            }

            Keyframe readyEndKey = readyKeys[readyEndKeyIndex];
            readyEndKey.time = readyEndTime;
            readyEndKey.outTangent = 0f;
            readyEndKey.outWeight = 0f;
            readyEndKey.weightedMode = (WeightedMode)(
                (int)readyEndKey.weightedMode & (int)WeightedMode.In);
            readyKeys[readyEndKeyIndex] = readyEndKey;
            Keyframe holdKey = readyEndKey;
            holdKey.time = holdEndTime;
            holdKey.inTangent = 0f;
            holdKey.outTangent = 0f;
            holdKey.inWeight = 0f;
            holdKey.outWeight = 0f;
            holdKey.weightedMode = WeightedMode.None;
            readyKeys.Add(holdKey);
            AnimationCurve result = new AnimationCurve(
                readyKeys.OrderBy(key => key.time).ToArray())
            {
                preWrapMode = source.preWrapMode,
                postWrapMode = WrapMode.Loop
            };
            return result;
        }

        private static void MeasureThrowReadyPrefixAndHold(
            Transform template,
            AnimationClip source,
            AnimationClip ready,
            int readyEndFrame,
            float holdDuration,
            out float prefixPositionDifference,
            out float prefixRotationDifference,
            out float holdPositionDifference,
            out float holdRotationDifference)
        {
            GameObject sourceObject = UnityEngine.Object.Instantiate(template.gameObject);
            GameObject readyObject = UnityEngine.Object.Instantiate(template.gameObject);
            sourceObject.name = "HandsThrowReadyPrefixSource";
            readyObject.name = "HandsThrowReadyPrefixResult";
            sourceObject.hideFlags = HideFlags.HideAndDontSave;
            readyObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(sourceObject);
            DisableAnimators(readyObject);
            try
            {
                prefixPositionDifference = 0f;
                prefixRotationDifference = 0f;
                holdPositionDifference = 0f;
                holdRotationDifference = 0f;
                for (int frame = 0; frame <= readyEndFrame; frame++)
                {
                    float time = frame / source.frameRate;
                    source.SampleAnimation(sourceObject, time);
                    ready.SampleAnimation(readyObject, time);
                    MeasureArmaturePoseDifference(
                        CapturePose(sourceObject.transform),
                        CapturePose(readyObject.transform),
                        out float positionDifference,
                        out float rotationDifference);
                    prefixPositionDifference = Mathf.Max(
                        prefixPositionDifference,
                        positionDifference);
                    prefixRotationDifference = Mathf.Max(
                        prefixRotationDifference,
                        rotationDifference);
                }

                float readyEndTime = readyEndFrame / source.frameRate;
                source.SampleAnimation(sourceObject, readyEndTime);
                PoseSnapshot readyEndPose = CapturePose(sourceObject.transform);
                int holdIntervals = Mathf.Max(
                    1,
                    Mathf.RoundToInt(holdDuration * ready.frameRate));
                for (int interval = 0; interval < holdIntervals; interval++)
                {
                    float time = readyEndTime +
                        holdDuration * interval / holdIntervals;
                    ready.SampleAnimation(readyObject, time);
                    MeasureArmaturePoseDifference(
                        readyEndPose,
                        CapturePose(readyObject.transform),
                        out float positionDifference,
                        out float rotationDifference);
                    holdPositionDifference = Mathf.Max(
                        holdPositionDifference,
                        positionDifference);
                    holdRotationDifference = Mathf.Max(
                        holdRotationDifference,
                        rotationDifference);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(sourceObject);
                UnityEngine.Object.DestroyImmediate(readyObject);
            }
        }

        private static bool ThrowReadyEventsMatchSourcePrefix(
            AnimationClip source,
            AnimationClip ready,
            float readyEndTime)
        {
            AnimationEvent[] sourceEvents = AnimationUtility
                .GetAnimationEvents(source)
                .Where(animationEvent =>
                    animationEvent.time <= readyEndTime + 0.0001f)
                .ToArray();
            AnimationEvent[] readyEvents = AnimationUtility.GetAnimationEvents(ready);
            if (sourceEvents.Length != readyEvents.Length)
            {
                return false;
            }

            for (int index = 0; index < sourceEvents.Length; index++)
            {
                AnimationEvent first = sourceEvents[index];
                AnimationEvent second = readyEvents[index];
                if (Mathf.Abs(first.time - second.time) > 0.00001f ||
                    !string.Equals(
                        first.functionName,
                        second.functionName,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        first.stringParameter,
                        second.stringParameter,
                        StringComparison.Ordinal) ||
                    Mathf.Abs(first.floatParameter - second.floatParameter) > 0.00001f ||
                    first.intParameter != second.intParameter ||
                    first.objectReferenceParameter != second.objectReferenceParameter)
                {
                    return false;
                }
            }

            return true;
        }

        private static AnimationClip CreateOrUpdateThrowCancelClip(
            Transform template,
            AnimationClip readyClip,
            AnimationClip idleClip,
            float readyEndTime,
            float initialHoldDuration,
            float finalIdleHoldDuration)
        {
            AnimationClip generated = new AnimationClip
            {
                name = "Hands_Throw_Cancel_MixamoReverse",
                frameRate = readyClip.frameRate,
                wrapMode = WrapMode.Loop,
                legacy = false
            };
            string[] transformPaths = AnimationUtility
                .GetCurveBindings(readyClip)
                .Concat(AnimationUtility.GetCurveBindings(idleClip))
                .Where(binding => binding.type == typeof(Transform))
                .Select(binding => binding.path)
                .Distinct(StringComparer.Ordinal)
                .OrderBy(path => path, StringComparer.Ordinal)
                .ToArray();
            if (transformPaths.Length == 0)
            {
                throw new InvalidOperationException(
                    "Hands Throw Ready has no Transform curves to copy into Cancel.");
            }

            GameObject readyObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject idleObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            readyObject.name = "HandsThrowCancelReadyFrameCopy";
            idleObject.name = "HandsThrowCancelIdleFrameZero";
            readyObject.hideFlags = HideFlags.HideAndDontSave;
            idleObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(readyObject);
            DisableAnimators(idleObject);
            try
            {
                Transform readyRoot = readyObject.transform;
                Transform idleRoot = idleObject.transform;
                Dictionary<string, TransformCurveTrack> tracks = transformPaths
                    .ToDictionary(
                        path => path,
                        path => new TransformCurveTrack(path),
                        StringComparer.Ordinal);
                int holdFrames = Mathf.RoundToInt(
                    initialHoldDuration * readyClip.frameRate);
                int reverseFrames = Mathf.RoundToInt(
                    readyEndTime * readyClip.frameRate);
                int finalHoldFrames = Mathf.RoundToInt(
                    finalIdleHoldDuration * readyClip.frameRate);
                idleClip.SampleAnimation(idleObject, 0f);
                for (int frame = 0; frame <= holdFrames; frame++)
                {
                    float time = frame / readyClip.frameRate;
                    readyClip.SampleAnimation(readyObject, readyEndTime);
                    foreach (string path in transformPaths)
                    {
                        Transform value = string.IsNullOrEmpty(path)
                            ? readyRoot
                            : FindRequired(readyRoot, path);
                        tracks[path].Add(time, value);
                    }
                }

                for (int frame = 1; frame <= reverseFrames; frame++)
                {
                    float offset = frame / readyClip.frameRate;
                    float time = initialHoldDuration + offset;
                    readyClip.SampleAnimation(
                        readyObject,
                        readyEndTime - offset);
                    BlendThrowCancelPoseTowardIdle(
                        readyRoot,
                        idleRoot,
                        transformPaths,
                        frame / (float)reverseFrames);
                    foreach (string path in transformPaths)
                    {
                        Transform value = string.IsNullOrEmpty(path)
                            ? readyRoot
                            : FindRequired(readyRoot, path);
                        tracks[path].Add(time, value);
                    }
                }

                float finalHoldStart = initialHoldDuration + readyEndTime;
                for (int frame = 1; frame <= finalHoldFrames; frame++)
                {
                    float time = finalHoldStart +
                        frame / readyClip.frameRate;
                    foreach (string path in transformPaths)
                    {
                        Transform value = string.IsNullOrEmpty(path)
                            ? idleRoot
                            : FindRequired(idleRoot, path);
                        tracks[path].Add(time, value);
                    }
                }

                foreach (TransformCurveTrack track in tracks.Values)
                {
                    SetTransformTrackCurves(generated, track);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(readyObject);
                UnityEngine.Object.DestroyImmediate(idleObject);
            }

            foreach (EditorCurveBinding binding in
                     AnimationUtility.GetObjectReferenceCurveBindings(readyClip))
            {
                ObjectReferenceKeyframe[] sourceKeys =
                    AnimationUtility.GetObjectReferenceCurve(
                        readyClip,
                        binding);
                AnimationUtility.SetObjectReferenceCurve(
                    generated,
                    binding,
                    CreateThrowCancelReverseObjectKeys(
                        sourceKeys,
                        readyEndTime,
                        initialHoldDuration,
                        binding.path + ":" + binding.propertyName));
            }

            AnimationEvent[] events = AnimationUtility
                .GetAnimationEvents(readyClip)
                .Where(animationEvent =>
                    animationEvent.time <= readyEndTime + 0.0001f)
                .Select(animationEvent =>
                {
                    AnimationEvent reversed = new AnimationEvent
                    {
                        time = initialHoldDuration +
                            (readyEndTime - animationEvent.time),
                        functionName = animationEvent.functionName,
                        stringParameter = animationEvent.stringParameter,
                        floatParameter = animationEvent.floatParameter,
                        intParameter = animationEvent.intParameter,
                        objectReferenceParameter =
                            animationEvent.objectReferenceParameter,
                        messageOptions = animationEvent.messageOptions
                    };
                    return reversed;
                })
                .OrderBy(animationEvent => animationEvent.time)
                .ToArray();
            AnimationUtility.SetAnimationEvents(generated, events);
            generated.EnsureQuaternionContinuity();
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(readyClip);
            settings.startTime = 0f;
            settings.stopTime = initialHoldDuration + readyEndTime +
                finalIdleHoldDuration;
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrowCancelClipPath);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, ThrowCancelClipPath);
                existing = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, existing);
                UnityEngine.Object.DestroyImmediate(generated);
                existing.name = "Hands_Throw_Cancel_MixamoReverse";
                EditorUtility.SetDirty(existing);
            }

            AssetDatabase.SaveAssets();
            return existing;
        }

        private static AnimationCurve CreateThrowCancelReverseCurve(
            AnimationCurve source,
            float readyEndTime,
            float initialHoldDuration,
            string label)
        {
            Keyframe[] sourceKeys = source.keys
                .Where(key => key.time <= readyEndTime + 0.0001f)
                .OrderBy(key => key.time)
                .ToArray();
            if (sourceKeys.Length == 0)
            {
                throw new InvalidOperationException(
                    "Hands Throw Cancel source curve has no Ready prefix keys: " +
                    label + ".");
            }

            int endIndex = Array.FindLastIndex(
                sourceKeys,
                key => Mathf.Abs(key.time - readyEndTime) <= 0.0001f);
            if (endIndex < 0)
            {
                throw new InvalidOperationException(
                    "Hands Throw Cancel source curve has no exact Ready frame 19 key: " +
                    label + ".");
            }

            Keyframe endpoint = sourceKeys[endIndex];
            Keyframe holdStart = endpoint;
            holdStart.time = 0f;
            holdStart.inTangent = 0f;
            holdStart.outTangent = 0f;
            holdStart.inWeight = 0f;
            holdStart.outWeight = 0f;
            holdStart.weightedMode = WeightedMode.None;
            List<Keyframe> result = new List<Keyframe> { holdStart };
            for (int index = endIndex; index >= 0; index--)
            {
                Keyframe sourceKey = sourceKeys[index];
                Keyframe reversed = sourceKey;
                reversed.time = initialHoldDuration +
                    (readyEndTime - sourceKey.time);
                reversed.inTangent = -sourceKey.outTangent;
                reversed.outTangent = -sourceKey.inTangent;
                reversed.inWeight = sourceKey.outWeight;
                reversed.outWeight = sourceKey.inWeight;
                reversed.weightedMode = ReverseWeightedMode(
                    sourceKey.weightedMode);
                if (index == endIndex)
                {
                    reversed.time = initialHoldDuration;
                    reversed.inTangent = 0f;
                    reversed.inWeight = 0f;
                    reversed.weightedMode = (WeightedMode)(
                        (int)reversed.weightedMode &
                        ~(int)WeightedMode.In);
                }

                result.Add(reversed);
            }

            return new AnimationCurve(result.ToArray());
        }

        private static WeightedMode ReverseWeightedMode(WeightedMode source)
        {
            WeightedMode result = WeightedMode.None;
            if (((int)source & (int)WeightedMode.In) != 0)
            {
                result = (WeightedMode)((int)result | (int)WeightedMode.Out);
            }

            if (((int)source & (int)WeightedMode.Out) != 0)
            {
                result = (WeightedMode)((int)result | (int)WeightedMode.In);
            }

            return result;
        }

        private static ObjectReferenceKeyframe[]
            CreateThrowCancelReverseObjectKeys(
                IReadOnlyList<ObjectReferenceKeyframe> sourceKeys,
                float readyEndTime,
                float initialHoldDuration,
                string label)
        {
            ObjectReferenceKeyframe[] prefix = sourceKeys
                .Where(key => key.time <= readyEndTime + 0.0001f)
                .OrderBy(key => key.time)
                .ToArray();
            if (prefix.Length == 0)
            {
                throw new InvalidOperationException(
                    "Hands Throw Cancel object curve has no Ready prefix keys: " +
                    label + ".");
            }

            UnityEngine.Object endpointValue = prefix[prefix.Length - 1].value;
            List<ObjectReferenceKeyframe> result =
                new List<ObjectReferenceKeyframe>
                {
                    new ObjectReferenceKeyframe
                    {
                        time = 0f,
                        value = endpointValue
                    },
                    new ObjectReferenceKeyframe
                    {
                        time = initialHoldDuration,
                        value = endpointValue
                    }
                };
            for (int index = prefix.Length - 1; index >= 0; index--)
            {
                ObjectReferenceKeyframe key = prefix[index];
                float reversedTime = initialHoldDuration +
                    (readyEndTime - key.time);
                if (Mathf.Abs(reversedTime - initialHoldDuration) <= 0.0001f)
                {
                    continue;
                }

                key.time = reversedTime;
                result.Add(key);
            }

            return result.OrderBy(key => key.time).ToArray();
        }

        private static string[] GetThrowCancelTransformPaths(
            AnimationClip readyClip,
            AnimationClip idleClip)
        {
            return AnimationUtility.GetCurveBindings(readyClip)
                .Concat(AnimationUtility.GetCurveBindings(idleClip))
                .Where(binding => binding.type == typeof(Transform))
                .Select(binding => binding.path)
                .Distinct(StringComparer.Ordinal)
                .OrderBy(path => path, StringComparer.Ordinal)
                .ToArray();
        }

        private static void BlendThrowCancelPoseTowardIdle(
            Transform readyRoot,
            Transform idleRoot,
            IReadOnlyList<string> transformPaths,
            float idleWeight)
        {
            float weight = Mathf.Clamp01(idleWeight);
            foreach (string path in transformPaths)
            {
                Transform readyValue = string.IsNullOrEmpty(path)
                    ? readyRoot
                    : FindRequired(readyRoot, path);
                Transform idleValue = string.IsNullOrEmpty(path)
                    ? idleRoot
                    : FindRequired(idleRoot, path);
                readyValue.localPosition = Vector3.Lerp(
                    readyValue.localPosition,
                    idleValue.localPosition,
                    weight);
                readyValue.localRotation = Quaternion.Slerp(
                    readyValue.localRotation,
                    idleValue.localRotation,
                    weight);
            }
        }

        private static void MeasureThrowCancelClipExact(
            Transform template,
            AnimationClip readyClip,
            AnimationClip idleClip,
            AnimationClip cancelClip,
            float readyEndTime,
            float initialHoldDuration,
            float finalIdleHoldDuration,
            out float holdPositionDifference,
            out float holdRotationDifference,
            out float reversePositionDifference,
            out float reverseRotationDifference,
            out float finalIdlePositionDifference,
            out float finalIdleRotationDifference,
            out float finalHoldPositionDifference,
            out float finalHoldRotationDifference)
        {
            GameObject readyObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject idleObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            GameObject cancelObject = UnityEngine.Object.Instantiate(
                template.gameObject);
            readyObject.name = "HandsThrowCancelReadyExpected";
            idleObject.name = "HandsThrowCancelIdleExpected";
            cancelObject.name = "HandsThrowCancelGenerated";
            readyObject.hideFlags = HideFlags.HideAndDontSave;
            idleObject.hideFlags = HideFlags.HideAndDontSave;
            cancelObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(readyObject);
            DisableAnimators(idleObject);
            DisableAnimators(cancelObject);
            try
            {
                string[] transformPaths = GetThrowCancelTransformPaths(
                    readyClip,
                    idleClip);
                idleClip.SampleAnimation(idleObject, 0f);
                cancelClip.SampleAnimation(cancelObject, 0f);
                PoseSnapshot holdBaseline = CapturePose(cancelObject.transform);
                holdPositionDifference = 0f;
                holdRotationDifference = 0f;
                int holdFrames = Mathf.RoundToInt(
                    initialHoldDuration * cancelClip.frameRate);
                for (int frame = 0; frame <= holdFrames; frame++)
                {
                    float time = frame / cancelClip.frameRate;
                    cancelClip.SampleAnimation(cancelObject, time);
                    MeasureArmaturePoseDifference(
                        holdBaseline,
                        CapturePose(cancelObject.transform),
                        out float positionDifference,
                        out float rotationDifference);
                    holdPositionDifference = Mathf.Max(
                        holdPositionDifference,
                        positionDifference);
                    holdRotationDifference = Mathf.Max(
                        holdRotationDifference,
                        rotationDifference);
                }

                reversePositionDifference = 0f;
                reverseRotationDifference = 0f;
                int reverseFrames = Mathf.RoundToInt(
                    readyEndTime * cancelClip.frameRate);
                for (int frame = 0; frame <= reverseFrames; frame++)
                {
                    float offset = frame / cancelClip.frameRate;
                    readyClip.SampleAnimation(
                        readyObject,
                        readyEndTime - offset);
                    BlendThrowCancelPoseTowardIdle(
                        readyObject.transform,
                        idleObject.transform,
                        transformPaths,
                        frame / (float)reverseFrames);
                    cancelClip.SampleAnimation(
                        cancelObject,
                        initialHoldDuration + offset);
                    MeasureArmaturePoseDifference(
                        CapturePose(readyObject.transform),
                        CapturePose(cancelObject.transform),
                        out float positionDifference,
                        out float rotationDifference);
                    reversePositionDifference = Mathf.Max(
                        reversePositionDifference,
                        positionDifference);
                    reverseRotationDifference = Mathf.Max(
                        reverseRotationDifference,
                        rotationDifference);
                }

                float finalHoldStart = initialHoldDuration + readyEndTime;
                cancelClip.SampleAnimation(cancelObject, finalHoldStart);
                PoseSnapshot idlePose = CapturePose(idleObject.transform);
                PoseSnapshot finalPose = CapturePose(cancelObject.transform);
                MeasureArmaturePoseDifference(
                    idlePose,
                    finalPose,
                    out finalIdlePositionDifference,
                    out finalIdleRotationDifference);
                finalHoldPositionDifference = 0f;
                finalHoldRotationDifference = 0f;
                int finalHoldFrames = Mathf.RoundToInt(
                    finalIdleHoldDuration * cancelClip.frameRate);
                for (int frame = 0; frame < finalHoldFrames; frame++)
                {
                    cancelClip.SampleAnimation(
                        cancelObject,
                        finalHoldStart + frame / cancelClip.frameRate);
                    MeasureArmaturePoseDifference(
                        idlePose,
                        CapturePose(cancelObject.transform),
                        out float positionDifference,
                        out float rotationDifference);
                    finalHoldPositionDifference = Mathf.Max(
                        finalHoldPositionDifference,
                        positionDifference);
                    finalHoldRotationDifference = Mathf.Max(
                        finalHoldRotationDifference,
                        rotationDifference);
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(readyObject);
                UnityEngine.Object.DestroyImmediate(idleObject);
                UnityEngine.Object.DestroyImmediate(cancelObject);
            }
        }

        private static void CapturePlayerHandsThrowCancelActualReview()
        {
            ThrowCancelApplyMetrics apply =
                ReadJson<ThrowCancelApplyMetrics>(
                    ThrowCancelApplyMetricsPath);
            if (!apply.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Hands Throw Cancel apply metrics did not pass.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform target = RequireTarget(layout, ThrowCancelTargetName);
            Transform idleReference = RequireTarget(
                layout,
                IdleReferenceTargetName);
            AnimationClip readyClip = LoadClip(ThrowReadyClipPath);
            AnimationClip idleClip = LoadClip(IdleClipPath);
            AnimationClip cancelClip = LoadClip(ThrowCancelClipPath);
            CaptureThrowCancelComparison(
                target,
                idleReference,
                readyClip,
                idleClip,
                cancelClip,
                apply.readyEndTimeSeconds,
                apply.initialHoldDurationSeconds,
                ThrowCancelReviewPath);
            TargetReviewMetrics runtime = CaptureTargetMetrics(
                target,
                cancelClip,
                ThrowCancelStateName,
                "Ready frame 19 hold 0.5s + linear Player_Idle frame 0 blend + Idle hold 0.5s");
            runtime.passedNumericChecks = TargetReviewPassed(runtime);
            MeasureThrowCancelRuntimeExpected(
                target,
                idleReference,
                readyClip,
                idleClip,
                cancelClip,
                apply.readyEndTimeSeconds,
                apply.initialHoldDurationSeconds,
                out float holdPositionDifference,
                out float holdRotationDifference,
                out float reversePositionDifference,
                out float reverseRotationDifference,
                out float finalIdlePositionDifference,
                out float finalIdleRotationDifference,
                out float finalHoldPositionDifference,
                out float finalHoldRotationDifference);
            ThrowCancelReviewMetrics metrics = new ThrowCancelReviewMetrics
            {
                target = ThrowCancelTargetName,
                phasesCaptured = 12,
                runtime = runtime,
                holdPositionDifferenceMax = holdPositionDifference,
                holdRotationDifferenceDegreesMax = holdRotationDifference,
                expectedReversePositionDifferenceMax =
                    reversePositionDifference,
                expectedReverseRotationDifferenceDegreesMax =
                    reverseRotationDifference,
                finalIdlePositionDifferenceMax = finalIdlePositionDifference,
                finalIdleRotationDifferenceDegreesMax =
                    finalIdleRotationDifference,
                finalHoldPositionDifferenceMax = finalHoldPositionDifference,
                finalHoldRotationDifferenceDegreesMax =
                    finalHoldRotationDifference,
                hasNoBlendShapeCurves = HasNoBlendShapeCurves(cancelClip),
                validationPriority =
                    "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
            };
            metrics.passedNumericChecks =
                metrics.phasesCaptured == 12 &&
                metrics.runtime.passedNumericChecks &&
                metrics.holdPositionDifferenceMax <= PositionTolerance &&
                metrics.holdRotationDifferenceDegreesMax <= RotationTolerance &&
                metrics.expectedReversePositionDifferenceMax <= PositionTolerance &&
                metrics.expectedReverseRotationDifferenceDegreesMax <= RotationTolerance &&
                metrics.finalIdlePositionDifferenceMax <= PositionTolerance &&
                metrics.finalIdleRotationDifferenceDegreesMax <= RotationTolerance &&
                metrics.finalHoldPositionDifferenceMax <= PositionTolerance &&
                metrics.finalHoldRotationDifferenceDegreesMax <= RotationTolerance &&
                metrics.hasNoBlendShapeCurves;
            WriteJson(ThrowCancelReviewMetricsPath, metrics);
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Hands Throw Cancel Play Mode support checks failed. " +
                    JsonUtility.ToJson(metrics));
            }

            Debug.Log(
                "[PlayerHandsThrowCancel] Captured static Ready hold, linear Idle blend, and final Idle hold in Play Mode. " +
                "Frames=" + runtime.framesSampled +
                ", RuntimePose=" +
                Num(runtime.sourcePosePositionDifferenceMax) + "/" +
                Num(runtime.sourcePoseRotationDifferenceDegreesMax) +
                ", Hold=" + Num(metrics.holdPositionDifferenceMax) +
                "/" + Num(metrics.holdRotationDifferenceDegreesMax) +
                ", Reverse=" +
                Num(metrics.expectedReversePositionDifferenceMax) + "/" +
                Num(metrics.expectedReverseRotationDifferenceDegreesMax) +
                ", FinalIdle=" +
                Num(metrics.finalIdlePositionDifferenceMax) + "/" +
                Num(metrics.finalIdleRotationDifferenceDegreesMax) +
                ", IdleHold=" +
                Num(metrics.finalHoldPositionDifferenceMax) + "/" +
                Num(metrics.finalHoldRotationDifferenceDegreesMax) +
                ", Breathing=False, Loops=2.");
        }

        private static void CaptureThrowCancelComparison(
            Transform target,
            Transform idleReference,
            AnimationClip readyClip,
            AnimationClip idleClip,
            AnimationClip cancelClip,
            float readyEndTime,
            float initialHoldDuration,
            string outputPath)
        {
            Animator animator = RequireAnimator(target);
            GameObject idleObject = UnityEngine.Object.Instantiate(
                idleReference.gameObject);
            idleObject.name = "HandsThrowCancelReviewIdleFrameZero";
            idleObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(idleObject);
            foreach (Renderer renderer in
                     idleObject.GetComponentsInChildren<Renderer>(true))
            {
                renderer.enabled = false;
            }

            idleClip.SampleAnimation(idleObject, 0f);
            string[] transformPaths = GetThrowCancelTransformPaths(
                readyClip,
                idleClip);
            List<List<byte[]>> rows = Enumerable.Range(0, 4)
                .Select(_ => new List<byte[]>())
                .ToList();
            try
            {
                using (CaptureEnvironment environment =
                       new CaptureEnvironment(target))
                {
                    for (int index = 0; index < 12; index++)
                    {
                        float cancelTime = cancelClip.length * index / 12f;
                        ApplyExpectedThrowCancelPose(
                            target.gameObject,
                            idleObject.transform,
                            readyClip,
                            transformPaths,
                            cancelTime,
                            readyEndTime,
                            initialHoldDuration);
                        environment.ConfigureView(target, 1.05f, 1.35f);
                        rows[0].Add(environment.CaptureFront());
                        rows[1].Add(environment.CaptureSide());
                        SampleAnimator(
                            animator,
                            ThrowCancelStateName,
                            cancelTime / cancelClip.length);
                        environment.ConfigureView(target, 1.05f, 1.35f);
                        rows[2].Add(environment.CaptureFront());
                        rows[3].Add(environment.CaptureSide());
                    }
                }

                ComposeRows(rows, outputPath);
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(idleObject);
                animator.Rebind();
                animator.Update(0f);
            }
        }

        private static void MeasureThrowCancelRuntimeExpected(
            Transform target,
            Transform idleReference,
            AnimationClip readyClip,
            AnimationClip idleClip,
            AnimationClip cancelClip,
            float readyEndTime,
            float initialHoldDuration,
            out float holdPositionDifference,
            out float holdRotationDifference,
            out float reversePositionDifference,
            out float reverseRotationDifference,
            out float finalIdlePositionDifference,
            out float finalIdleRotationDifference,
            out float finalHoldPositionDifference,
            out float finalHoldRotationDifference)
        {
            Animator animator = RequireAnimator(target);
            GameObject expectedObject = UnityEngine.Object.Instantiate(
                target.gameObject);
            GameObject idleObject = UnityEngine.Object.Instantiate(
                idleReference.gameObject);
            expectedObject.name = "HandsThrowCancelRuntimeExpected";
            idleObject.name = "HandsThrowCancelRuntimeIdleFrameZero";
            expectedObject.hideFlags = HideFlags.HideAndDontSave;
            idleObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(expectedObject);
            DisableAnimators(idleObject);
            try
            {
                idleClip.SampleAnimation(idleObject, 0f);
                string[] transformPaths = GetThrowCancelTransformPaths(
                    readyClip,
                    idleClip);
                SampleAnimator(animator, ThrowCancelStateName, 0f);
                PoseSnapshot holdBaseline = CapturePose(target);
                holdPositionDifference = 0f;
                holdRotationDifference = 0f;
                reversePositionDifference = 0f;
                reverseRotationDifference = 0f;
                finalHoldPositionDifference = 0f;
                finalHoldRotationDifference = 0f;
                float finalHoldStart = initialHoldDuration + readyEndTime;
                SampleAnimator(
                    animator,
                    ThrowCancelStateName,
                    finalHoldStart / cancelClip.length);
                MeasureArmaturePoseDifference(
                    CapturePose(idleObject.transform),
                    CapturePose(target),
                    out finalIdlePositionDifference,
                    out finalIdleRotationDifference);
                int framesPerLoop = Mathf.CeilToInt(
                    cancelClip.length * cancelClip.frameRate);
                for (int frame = 0; frame < framesPerLoop; frame++)
                {
                    float time = frame / cancelClip.frameRate;
                    ApplyExpectedThrowCancelPose(
                        expectedObject,
                        idleObject.transform,
                        readyClip,
                        transformPaths,
                        time,
                        readyEndTime,
                        initialHoldDuration);
                    SampleAnimator(
                        animator,
                        ThrowCancelStateName,
                        time / cancelClip.length);
                    PoseSnapshot actualPose = CapturePose(target);
                    MeasureArmaturePoseDifference(
                        CapturePose(expectedObject.transform),
                        actualPose,
                        out float positionDifference,
                        out float rotationDifference);
                    reversePositionDifference = Mathf.Max(
                        reversePositionDifference,
                        positionDifference);
                    reverseRotationDifference = Mathf.Max(
                        reverseRotationDifference,
                        rotationDifference);
                    if (time <= initialHoldDuration + 0.0001f)
                    {
                        MeasureArmaturePoseDifference(
                            holdBaseline,
                            actualPose,
                            out float holdPosition,
                            out float holdRotation);
                        holdPositionDifference = Mathf.Max(
                            holdPositionDifference,
                            holdPosition);
                        holdRotationDifference = Mathf.Max(
                            holdRotationDifference,
                            holdRotation);
                    }

                    if (time >= finalHoldStart - 0.0001f)
                    {
                        MeasureArmaturePoseDifference(
                            CapturePose(idleObject.transform),
                            actualPose,
                            out float finalPosition,
                            out float finalRotation);
                        finalHoldPositionDifference = Mathf.Max(
                            finalHoldPositionDifference,
                            finalPosition);
                        finalHoldRotationDifference = Mathf.Max(
                            finalHoldRotationDifference,
                            finalRotation);
                    }
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(expectedObject);
                UnityEngine.Object.DestroyImmediate(idleObject);
                animator.Rebind();
                animator.Update(0f);
            }
        }

        private static void ApplyExpectedThrowCancelPose(
            GameObject expectedObject,
            Transform idleRoot,
            AnimationClip readyClip,
            IReadOnlyList<string> transformPaths,
            float cancelTime,
            float readyEndTime,
            float initialHoldDuration)
        {
            if (cancelTime <= initialHoldDuration)
            {
                readyClip.SampleAnimation(expectedObject, readyEndTime);
                return;
            }

            float reverseTime = cancelTime - initialHoldDuration;
            readyClip.SampleAnimation(
                expectedObject,
                Mathf.Max(0f, readyEndTime - reverseTime));
            BlendThrowCancelPoseTowardIdle(
                expectedObject.transform,
                idleRoot,
                transformPaths,
                reverseTime >= readyEndTime
                    ? 1f
                    : reverseTime / readyEndTime);
        }

        private static void CapturePlayerHandsThrowMixamoActualReview()
        {
            ThrowApplyMetrics apply = ReadJson<ThrowApplyMetrics>(
                ThrowApplyMetricsPath);
            if (!apply.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Hands Throw Mixamo apply metrics did not pass.");
            }

            Scene scene = RequireScene();
            Transform layout = RequireLayout(scene);
            Transform readyTarget = RequireTarget(layout, ThrowReadyTargetName);
            Transform releaseTarget = RequireTarget(layout, ThrowReleaseTargetName);
            AnimationClip source = LoadSingleEmbeddedClip(
                ThrowSourcePath,
                "hands throw");
            AnimationClip readyClip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrowReadyClipPath);
            if (readyClip == null)
            {
                throw new InvalidOperationException(
                    "Hands Throw Ready head-height breathing clip is missing.");
            }

            CaptureThrowReviewComparison(
                readyTarget,
                readyClip,
                apply.readyEndTimeSeconds,
                apply.holdDurationSeconds,
                ThrowReviewPath);
            TargetReviewMetrics readyMetrics = CaptureTargetMetrics(
                readyTarget,
                readyClip,
                ThrowReadyStateName,
                source.name + " frames 0.." + apply.readyEndFrame +
                " + 3s breathing hold");
            TargetReviewMetrics releaseMetrics = CaptureTargetMetrics(
                releaseTarget,
                source,
                ThrowReleaseStateName,
                source.name + " full Take");
            readyMetrics.passedNumericChecks = TargetReviewPassed(readyMetrics);
            releaseMetrics.passedNumericChecks = TargetReviewPassed(releaseMetrics);
            MeasureThrowReadyPrefixAndHold(
                readyTarget,
                source,
                readyClip,
                apply.readyEndFrame,
                0f,
                out float prefixPositionDifference,
                out float prefixRotationDifference,
                out _,
                out _);
            ThrowBreathingRuntimeMetrics breathing =
                MeasureThrowBreathingRuntime(
                    readyTarget,
                    readyClip,
                    apply);
            ThrowReviewMetrics metrics = new ThrowReviewMetrics
            {
                targetSet = ThrowReadyTargetName + ", " + ThrowReleaseTargetName,
                phasesCapturedPerComparison = 12,
                ready = readyMetrics,
                release = releaseMetrics,
                readyPrefixPositionDifferenceMax = prefixPositionDifference,
                readyPrefixRotationDifferenceDegreesMax = prefixRotationDifference,
                breathing = breathing,
                validationPriority =
                    "1순위 직접 모델링·애니메이션 확인, 2순위 수치·스크립트 보조 검증"
            };
            metrics.passedNumericChecks =
                metrics.phasesCapturedPerComparison == 12 &&
                metrics.ready.passedNumericChecks &&
                metrics.release.passedNumericChecks &&
                metrics.readyPrefixPositionDifferenceMax <= PositionTolerance &&
                metrics.readyPrefixRotationDifferenceDegreesMax <= RotationTolerance &&
                metrics.breathing.passedNumericChecks;
            WriteJson(ThrowReviewMetricsPath, metrics);
            if (!metrics.passedNumericChecks)
            {
                throw new InvalidOperationException(
                    "Hands Throw Mixamo Play Mode support checks failed. " +
                    JsonUtility.ToJson(metrics));
            }

            Debug.Log(
                "[PlayerHandsThrow] Captured Ready 3-second breathing hold and unchanged Release in Play Mode. " +
                "ReadyFrames=" + readyMetrics.framesSampled +
                ", ReleaseFrames=" + releaseMetrics.framesSampled +
                ", ReadyPose=" +
                Num(readyMetrics.sourcePosePositionDifferenceMax) + "/" +
                Num(readyMetrics.sourcePoseRotationDifferenceDegreesMax) +
                ", Breath=" + Num(breathing.maximumBlendShapeWeight) +
                ", Drop=" + Num(breathing.measuredBodyDropMeters) +
                ", Feet=" + Num(Mathf.Max(
                    breathing.maximumLeftFootDisplacementMeters,
                    breathing.maximumRightFootDisplacementMeters)) +
                ", ReleasePose=" +
                Num(releaseMetrics.sourcePosePositionDifferenceMax) + "/" +
                Num(releaseMetrics.sourcePoseRotationDifferenceDegreesMax) +
                ", Loops=2.");
        }

        private static void CaptureThrowReviewComparison(
            Transform readyTarget,
            AnimationClip readyClip,
            float readyEndTime,
            float holdDuration,
            string outputPath)
        {
            GameObject baselineObject = UnityEngine.Object.Instantiate(
                readyTarget.gameObject);
            baselineObject.name = "HandsThrowBreathingReviewBaseline";
            baselineObject.hideFlags = HideFlags.HideAndDontSave;
            DisableAnimators(baselineObject);
            Animator readyAnimator = RequireAnimator(readyTarget);
            List<List<byte[]>> rows = Enumerable.Range(0, 8)
                .Select(_ => new List<byte[]>())
                .ToList();
            try
            {
                CaptureThrowBreathingFourViewRows(
                    baselineObject.transform,
                    _ => readyClip.SampleAnimation(
                        baselineObject,
                        readyEndTime),
                    rows,
                    0);
                CaptureThrowBreathingFourViewRows(
                    readyTarget,
                    phase =>
                    {
                        float holdTime = phase * holdDuration;
                        SampleAnimator(
                            readyAnimator,
                            ThrowReadyStateName,
                            (readyEndTime + holdTime) / readyClip.length);
                    },
                    rows,
                    4);
                ComposeRows(rows, outputPath);
            }
            finally
            {
                readyAnimator.Rebind();
                readyAnimator.Update(0f);
                UnityEngine.Object.DestroyImmediate(baselineObject);
            }
        }

        private static void CaptureThrowBreathingFourViewRows(
            Transform subject,
            Action<float> sample,
            IReadOnlyList<List<byte[]>> rows,
            int rowOffset)
        {
            using (CaptureEnvironment environment = new CaptureEnvironment(subject))
            {
                for (int phaseIndex = 0; phaseIndex < 12; phaseIndex++)
                {
                    float phase = phaseIndex / 12f;
                    sample(phase);
                    environment.ConfigureView(subject, 1.05f, 1.35f);
                    rows[rowOffset].Add(environment.CaptureFront());
                    rows[rowOffset + 1].Add(environment.CaptureSide());
                    Vector3 chestCenter =
                        (FindRequired(subject, SolarPlexusPath).position +
                         FindRequired(subject, SpinePath).position) * 0.5f;
                    environment.ConfigureView(subject, chestCenter, 0.48f);
                    rows[rowOffset + 2].Add(environment.CaptureFront());
                    Vector3 legCenter =
                        (FindRequired(subject, HipsPath).position +
                         FindRequired(subject, LeftFootPath).position +
                         FindRequired(subject, RightFootPath).position) / 3f;
                    environment.ConfigureView(subject, legCenter, 0.72f);
                    rows[rowOffset + 3].Add(environment.CaptureSide());
                }
            }
        }

        private static ThrowBreathingRuntimeMetrics MeasureThrowBreathingRuntime(
            Transform readyTarget,
            AnimationClip readyClip,
            ThrowApplyMetrics apply)
        {
            Animator animator = RequireAnimator(readyTarget);
            SkinnedMeshRenderer renderer =
                RequirePrimaryPlayerSkinnedMeshRenderer(readyTarget);
            int blendShapeIndex = renderer.sharedMesh != null
                ? renderer.sharedMesh.GetBlendShapeIndex(
                    ThrowReadyBreathingBlendShapeName)
                : -1;
            if (blendShapeIndex < 0)
            {
                throw new InvalidOperationException(
                    "Ready breathing runtime renderer is missing Breathing.");
            }

            SampleAnimator(
                animator,
                ThrowReadyStateName,
                apply.readyEndTimeSeconds / readyClip.length);
            Transform hips = FindRequired(readyTarget, HipsPath);
            Transform leftFoot = FindRequired(readyTarget, LeftFootPath);
            Transform rightFoot = FindRequired(readyTarget, RightFootPath);
            Vector3 baseHips = hips.position;
            Vector3 baseLeftFoot = leftFoot.position;
            Vector3 baseRightFoot = rightFoot.position;
            float maximumWeight = 0f;
            float maximumDrop = 0f;
            float maximumLeftFoot = 0f;
            float maximumRightFoot = 0f;
            int framesPerLoop = Mathf.RoundToInt(
                readyClip.length * readyClip.frameRate);
            // A looping Animator maps normalizedTime == 1 back to frame zero.
            // That pose is the requested return to the start, not part of the
            // three-second breathing hold whose foot contact is measured here.
            for (int frame = 0; frame < framesPerLoop; frame++)
            {
                float time = frame / readyClip.frameRate;
                if (time + 0.0001f < apply.readyEndTimeSeconds)
                {
                    continue;
                }

                SampleAnimator(
                    animator,
                    ThrowReadyStateName,
                    time / readyClip.length);
                maximumWeight = Mathf.Max(
                    maximumWeight,
                    renderer.GetBlendShapeWeight(blendShapeIndex));
                maximumDrop = Mathf.Max(
                    maximumDrop,
                    Vector3.Dot(
                        baseHips - hips.position,
                        readyTarget.up));
                maximumLeftFoot = Mathf.Max(
                    maximumLeftFoot,
                    Vector3.Distance(baseLeftFoot, leftFoot.position));
                maximumRightFoot = Mathf.Max(
                    maximumRightFoot,
                    Vector3.Distance(baseRightFoot, rightFoot.position));
            }

            int detectedPeaks = 0;
            for (int cycle = 0; cycle < 3; cycle++)
            {
                float peakTime =
                    apply.readyEndTimeSeconds + cycle + 0.5f;
                SampleAnimator(
                    animator,
                    ThrowReadyStateName,
                    peakTime / readyClip.length);
                if (Mathf.Abs(
                        renderer.GetBlendShapeWeight(blendShapeIndex) - 30f) <= 0.01f &&
                    Mathf.Abs(
                        Vector3.Dot(
                            baseHips - hips.position,
                            readyTarget.up) - 0.03f) <= 0.0005f)
                {
                    detectedPeaks++;
                }
            }

            ThrowBreathingRuntimeMetrics metrics =
                new ThrowBreathingRuntimeMetrics
                {
                    maximumBlendShapeWeight = maximumWeight,
                    measuredBodyDropMeters = maximumDrop,
                    maximumLeftFootDisplacementMeters = maximumLeftFoot,
                    maximumRightFootDisplacementMeters = maximumRightFoot,
                    detectedBreathingPeaks = detectedPeaks,
                    blendShapeCurveApplied = true
                };
            metrics.passedNumericChecks =
                Mathf.Abs(metrics.maximumBlendShapeWeight - 30f) <= 0.01f &&
                Mathf.Abs(metrics.measuredBodyDropMeters - 0.03f) <= 0.0005f &&
                metrics.maximumLeftFootDisplacementMeters <= 0.0005f &&
                metrics.maximumRightFootDisplacementMeters <= 0.0005f &&
                metrics.detectedBreathingPeaks == 3 &&
                metrics.blendShapeCurveApplied;
            animator.Rebind();
            animator.Update(0f);
            return metrics;
        }

        private static void CaptureThrowThreeViewRows(
            Transform subject,
            Action<float> sample,
            IReadOnlyList<List<byte[]>> rows,
            int rowOffset)
        {
            using (CaptureEnvironment environment = new CaptureEnvironment(subject))
            {
                for (int phaseIndex = 0; phaseIndex < 12; phaseIndex++)
                {
                    float phase = phaseIndex / 12f;
                    sample(phase);
                    environment.ConfigureView(subject, 1.05f, 1.35f);
                    rows[rowOffset].Add(environment.CaptureFront());
                    rows[rowOffset + 1].Add(environment.CaptureSide());
                    Vector3 armCenter =
                        (FindRequired(subject, RightArmPath).position +
                         FindRequired(subject, RightHandPath).position) * 0.5f;
                    environment.ConfigureView(subject, armCenter, 0.62f);
                    rows[rowOffset + 2].Add(environment.CaptureFront());
                }
            }
        }

        private static void ComposeRows(
            IReadOnlyList<List<byte[]>> rows,
            string outputPath)
        {
            if (rows.Count == 0 || rows.Any(row => row.Count != rows[0].Count))
            {
                throw new InvalidOperationException(
                    "Player Hands comparison rows have inconsistent frame counts.");
            }

            int columns = rows[0].Count;
            Texture2D composite = new Texture2D(
                CaptureWidth * columns,
                CaptureHeight * rows.Count,
                TextureFormat.RGB24,
                false);
            List<Texture2D> panels = new List<Texture2D>();
            try
            {
                for (int row = 0; row < rows.Count; row++)
                {
                    for (int column = 0; column < columns; column++)
                    {
                        Texture2D panel = new Texture2D(
                            CaptureWidth,
                            CaptureHeight,
                            TextureFormat.RGB24,
                            false);
                        if (!panel.LoadImage(rows[row][column]))
                        {
                            throw new InvalidOperationException(
                                "Player Hands comparison frame could not be decoded.");
                        }

                        panels.Add(panel);
                        composite.SetPixels(
                            column * CaptureWidth,
                            (rows.Count - row - 1) * CaptureHeight,
                            CaptureWidth,
                            CaptureHeight,
                            panel.GetPixels());
                    }
                }

                composite.Apply(false, false);
                string absoluteOutput = Path.GetFullPath(outputPath);
                Directory.CreateDirectory(
                    Path.GetDirectoryName(absoluteOutput) ??
                    throw new InvalidOperationException(
                        "Player Hands comparison output directory is unavailable."));
                File.WriteAllBytes(absoluteOutput, composite.EncodeToPNG());
            }
            finally
            {
                foreach (Texture2D panel in panels)
                {
                    UnityEngine.Object.DestroyImmediate(panel);
                }

                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void ComposeRowsBesideReference(
            IReadOnlyList<List<byte[]>> rows,
            string referencePath,
            string outputPath)
        {
            if (rows.Count == 0 || rows.Any(row => row.Count != rows[0].Count))
            {
                throw new InvalidOperationException(
                    "Shotgun V4 comparison rows have inconsistent frame counts.");
            }

            int columns = rows[0].Count;
            int appliedWidth = CaptureWidth * columns;
            int appliedHeight = CaptureHeight * rows.Count;
            Texture2D reference = new Texture2D(
                2,
                2,
                TextureFormat.RGB24,
                false);
            Texture2D composite = null;
            List<Texture2D> panels = new List<Texture2D>();
            try
            {
                string absoluteReference = Path.GetFullPath(referencePath);
                if (!reference.LoadImage(File.ReadAllBytes(absoluteReference)))
                {
                    throw new InvalidOperationException(
                        "Approved Shotgun V4 reference could not be decoded.");
                }

                if (reference.width != appliedWidth ||
                    reference.height != appliedHeight)
                {
                    throw new InvalidOperationException(
                        "Approved and applied Shotgun V4 review dimensions differ.");
                }

                composite = new Texture2D(
                    reference.width + appliedWidth,
                    appliedHeight,
                    TextureFormat.RGB24,
                    false);
                composite.SetPixels(0, 0, reference.width, reference.height,
                    reference.GetPixels());
                for (int row = 0; row < rows.Count; row++)
                {
                    for (int column = 0; column < columns; column++)
                    {
                        Texture2D panel = new Texture2D(
                            CaptureWidth,
                            CaptureHeight,
                            TextureFormat.RGB24,
                            false);
                        if (!panel.LoadImage(rows[row][column]))
                        {
                            throw new InvalidOperationException(
                                "Applied Shotgun V4 review frame could not be decoded.");
                        }

                        panels.Add(panel);
                        composite.SetPixels(
                            reference.width + column * CaptureWidth,
                            (rows.Count - row - 1) * CaptureHeight,
                            CaptureWidth,
                            CaptureHeight,
                            panel.GetPixels());
                    }
                }

                composite.Apply(false, false);
                string absoluteOutput = Path.GetFullPath(outputPath);
                Directory.CreateDirectory(
                    Path.GetDirectoryName(absoluteOutput) ??
                    throw new InvalidOperationException(
                        "Shotgun V4 comparison output directory is unavailable."));
                File.WriteAllBytes(absoluteOutput, composite.EncodeToPNG());
            }
            finally
            {
                foreach (Texture2D panel in panels)
                {
                    UnityEngine.Object.DestroyImmediate(panel);
                }

                UnityEngine.Object.DestroyImmediate(reference);
                if (composite != null)
                {
                    UnityEngine.Object.DestroyImmediate(composite);
                }
            }
        }

